  box-shadow: inset 0 0 0 1px var(--bd-glow), inset 0 1px 0 rgba(255, 255, 255, .05);
  color: var(--bd-metal);
}
.bd-req-ico .ico { width: 14px; height: 14px; }
.bd-req-head .bd-kicker {
  flex: 1 1 auto;
  min-width: 0;
  color: var(--bd-metal);
}
.bd-req-head .bd-kicker::before { display: none; }
.bd-req-chip {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px 4px;
  border-radius: var(--radius-pill);
