}
.bd-req-chip b { font-weight: 800; }
.bd-req-chip .ico {
  width: 11px;
  height: 11px;
  flex: none;
}
.bd-req-chip.is-met {
  color: var(--mint-ink);
  box-shadow: inset 0 0 0 1px rgba(110, 231, 183, .28);
