}
.bd-req-metric .ico { width: 11px; height: 11px; flex: none; }
.bd-req-metric-k { font-weight: 700; }
.bd-req-metric-v { font-weight: 800; color: var(--bd-metal); }
.bd-req-metric.is-met {
  color: var(--mint-ink);
  box-shadow: inset 0 0 0 1px rgba(110, 231, 183, .28);
}
.bd-req-metric.is-met .bd-req-metric-v { color: var(--mint-ink); }

.bd-req-copy {
