  border-radius: var(--radius-md);
  background:
    radial-gradient(92% 120% at 100% 0%, rgba(243, 212, 131, .075), transparent 62%),
    linear-gradient(180deg, rgba(255, 255, 255, .028), rgba(255, 255, 255, 0) 52%),
    rgba(16, 22, 36, .72);
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, .4),
