}
.bd-privilege-list {
  display: grid;
  gap: 6px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}
.bd-privilege {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  align-items: start;
  gap: 8px;
  min-width: 0;
  padding: 6px 7px 6px 6px;
  border-radius: 10px;
  background: rgba(0, 0, 0, .18);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, .045),
    inset 0 1px 0 rgba(255, 255, 255, .035);
}
.bd-privilege-ico {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background:
    radial-gradient(circle at 50% 30%, rgba(255, 246, 220, .16), rgba(243, 212, 131, .04) 60%, transparent 80%),
    rgba(0, 0, 0, .24);
  box-shadow:
    inset 0 0 0 1px rgba(243, 212, 131, .16),
    0 0 12px -8px rgba(243, 212, 131, .5);
  color: #F2D397;
}
.bd-privilege-ico .ico {
  width: 14px;
  height: 14px;
  filter: drop-shadow(0 0 5px rgba(243, 212, 131, .35));
}
.bd-privilege-text {
  min-width: 0;
  margin: 0;
  font-size: clamp(10.5px, 3.1vw, 11.5px);
  line-height: 1.5;
  font-weight: 500;
  color: #C7D2E0;
  text-align: start;
  overflow-wrap: break-word;
}

.bd-actions { flex: none; padding-top: 6px; }
.bd-cta {
  position: relative;
  isolation: isolate;
  width: 100%;
  min-height: 48px;
  padding: 11px 16px;
  border: 0;
  border-radius: 15px;
  appearance: none;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: .11em;
  text-transform: uppercase;
  color: var(--ink);
  cursor: pointer;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .08), rgba(255, 255, 255, 0) 40%),
    linear-gradient(180deg, #27344A 0%, #151D2C 100%);
  box-shadow:
    0 5px 0 #080C14,
    0 14px 22px -12px rgba(0, 0, 0, .85),
    inset 0 1px 0 rgba(255, 255, 255, .16),
    inset 0 -2px 0 rgba(0, 0, 0, .38);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast);
}
.bd-cta::before {
  content: '';
  position: absolute;
  inset: 0;
  padding: 1px;
  border-radius: inherit;
  background: linear-gradient(180deg, var(--bd-metal) 0%, rgba(255, 255, 255, .25) 36%, var(--bd-accent) 100%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask-composite: exclude;
  opacity: .8;
  pointer-events: none;
  z-index: 1;
}
.bd-cta .ico {
  position: relative;
  z-index: 2;
  width: 15px;
  height: 15px;
  filter: drop-shadow(0 0 6px var(--bd-glow));
}
.bd-cta #badge-cta-label { position: relative; z-index: 2; }
.bd-cta[data-mode="play"],
.bd-cta[data-mode="equip"] {
  color: var(--bd-metal);
  text-shadow: 0 0 12px var(--bd-glow);
  background:
    radial-gradient(80% 140% at 50% 120%, var(--bd-glow) 0%, rgba(0, 0, 0, 0) 65%),
    linear-gradient(180deg, #2A3850 0%, #141C2B 100%);
  box-shadow:
    0 5px 0 #080C14,
    0 16px 26px -14px var(--bd-glow),
    inset 0 1px 0 rgba(255, 255, 255, .18),
    inset 0 -2px 0 rgba(0, 0, 0, .38);
}
.bd-cta[data-mode="equip"] { color: var(--ink); }
.bd-cta:active:not([disabled]) {
  transform: translateY(3px);
  box-shadow:
    0 2px 0 #080C14,
    0 8px 14px -10px rgba(0, 0, 0, .8),
    inset 0 1px 0 rgba(255, 255, 255, .14);
}
.bd-cta:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 3px; }
.bd-cta[disabled] {
  cursor: default;
  color: #8FA0B8;
  opacity: .72;
}
/* the equipped state is a living seal, not a disabled key */
.bd-cta[data-mode="equipped"] {
  cursor: default;
  opacity: 1;
  color: #F4F1E3;
  background:
    radial-gradient(90% 150% at 50% 120%, rgba(16, 185, 129, .3) 0%, transparent 68%),
    linear-gradient(180deg, rgba(255, 255, 255, .06), rgba(255, 255, 255, 0) 42%),
    linear-gradient(180deg, #173A32 0%, #0B1E1A 62%, #060F0D 100%);
  box-shadow:
    0 5px 0 #04110E,
    0 16px 28px -16px rgba(16, 185, 129, .55),
    inset 0 1px 0 rgba(255, 246, 220, .22),
    inset 0 -2px 0 rgba(0, 0, 0, .5),
    inset 0 0 0 1px rgba(243, 212, 131, .24);
  text-shadow: 0 0 14px rgba(110, 231, 183, .38);
}
.bd-cta[data-mode="equipped"]::before {
  opacity: .9;
  background: linear-gradient(112deg, rgba(255, 246, 220, .62), rgba(243, 212, 131, .42) 34%, rgba(110, 231, 183, .48) 70%, rgba(255, 255, 255, .2));
}
.bd-cta[data-mode="equipped"]::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  border-radius: inherit;
  box-shadow:
    0 0 18px rgba(110, 231, 183, .35),
    0 0 26px -8px rgba(243, 212, 131, .35);
  opacity: .55;
  pointer-events: none;
  animation: bd-seal-glow 4.6s ease-in-out infinite;
}
.bd-cta[data-mode="equipped"] .ico {
  color: #F6E7B8;
  filter: drop-shadow(0 0 7px rgba(243, 212, 131, .55));
}
.bd-cta[data-mode="equipped"] #badge-cta-label {
  color: #F6F1DF;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .55);
}

html.reduced-motion .bd-hero-art,
html.reduced-motion .bd-aura,
html.reduced-motion .bd-hero-art::after,
html.reduced-motion .bd-privileges-live::before,
html.reduced-motion .bd-cta[data-mode="equipped"]::after { animation: none; }
@media (prefers-reduced-motion: reduce) {
  .bd-hero-art,
  .bd-aura,
  .bd-hero-art::after,
  .bd-privileges-live::before,
  .bd-cta[data-mode="equipped"]::after { animation: none; }
}

/* ---- Persian collector card: RTL prose, no tracking, room for descenders ---- */
.badge-sheet:lang(fa) :is(.bd-kicker, .bd-supply-label, .bd-state, .bd-cta, .bd-req-chip, .bd-req-metric) {
