}
.badge-sheet:lang(fa) :is(.bd-state, .bd-cta) { direction: rtl; }
.badge-sheet:lang(fa) .bd-supply-label { line-height: 1.5; }
.badge-sheet:lang(fa) .bd-req-head { direction: rtl; }
.badge-sheet:lang(fa) .bd-req::before { inset-inline-start: auto; inset-inline-end: 0; }
.badge-sheet:lang(fa) .bd-req-chip b {
  direction: ltr;
