  line-height: 1.4;
}
.badge-sheet:lang(fa) .bd-req-chips { direction: rtl; }
.badge-sheet:lang(fa) .bd-req-metric {
  padding-top: 2px;
  padding-bottom: 3px;
  line-height: 1.4;
}
.badge-sheet:lang(fa) :is(.bd-plaque-tag, .bd-privileges-live, .bd-privilege-text) {
  font-family: 'Vazirmatn', system-ui, -apple-system, sans-serif;
  letter-spacing: 0;
  text-transform: none;
}
/* the Persian plaque reads right-to-left as one phrase: «شماره 002 از 50 · نشان کمیاب» */
.badge-sheet:lang(fa) .bd-state[data-state="minted"] { direction: rtl; }
.badge-sheet:lang(fa) .bd-plaque-no {
  direction: rtl;
  unicode-bidi: isolate;
  letter-spacing: 0;
}
.badge-sheet:lang(fa) .bd-plaque-tag { direction: rtl; unicode-bidi: isolate; }
.badge-sheet:lang(fa) .bd-privileges { direction: rtl; }
.badge-sheet:lang(fa) .bd-privileges::before { inset-inline-start: auto; inset-inline-end: 0; }
.badge-sheet:lang(fa) .bd-privilege { direction: rtl; }
.badge-sheet:lang(fa) .bd-privilege-text { text-align: right; line-height: 1.7; }
.badge-sheet:lang(fa) .bd-supply-label { letter-spacing: 0; }

/* short phones: tighten the frame, never the type */
@media (max-height: 700px) {
  .sheet.badge-sheet {
    gap: 6px;
    padding-top: 8px;
