  .bd-supply-label { font-size: 8.5px; letter-spacing: .08em; }
  .bd-privilege { grid-template-columns: 26px minmax(0, 1fr); gap: 7px; padding: 6px; }
  .bd-privilege-ico { width: 26px; height: 26px; }
}

/* ---- the claimed cell is a door: glass button, gold only when the ledger has holders ---- */
button.bd-supply-cell {
  appearance: none;
  margin: 0;
  border: 0;
  font: inherit;
  color: inherit;
  text-align: center;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: transform var(--motion-fast), box-shadow var(--motion-fast), background var(--motion-fast);
}
.bd-supply-crown {
  position: absolute;
  top: 5px;
  inset-inline-end: 6px;
  display: grid;
  place-items: center;
  width: 12px;
  height: 12px;
  color: var(--gold-ink);
