.bd-supply-cell.is-claimed:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
/* an unpopulated registry keeps the cell neutral: the crown stays lit only for a real hall */
.bd-supply-cell.is-claimed[data-state="quiet"] { cursor: default; }
html.reduced-motion .bd-supply-cell.is-claimed { transition: none; }

/* ---- Hall of Owners: an obsidian registry plate with gold serial stamps ---- */
.sheet.owners-sheet {
  max-height: calc(92dvh - env(safe-area-inset-top));
  gap: 7px;
  padding: 10px max(14px, env(safe-area-inset-right)) calc(10px + env(safe-area-inset-bottom)) max(14px, env(safe-area-inset-left));
  overflow: hidden;
  --bo-accent: #22D3EE;
  --bo-metal: #A5F3FC;
}
.owners-sheet[data-accent="quantum"] { --bo-accent: #FBBF24; --bo-metal: #FDE68A; }
.owners-sheet[data-accent="frost"] { --bo-accent: #34D399; --bo-metal: #A7F3D0; }

.bo-head {
  flex: none;
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) 44px;
  align-items: start;
  gap: 6px;
}
.bo-head-id { min-width: 0; }
.bo-back, .bo-x {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 50%;
  appearance: none;
  font: inherit;
  color: #C6D2E4;
  background:
    radial-gradient(120% 130% at 50% 0%, rgba(255, 255, 255, .10), rgba(255, 255, 255, 0) 64%),
    rgba(9, 14, 24, .62);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  box-shadow:
    inset 0 0 0 1px rgba(245, 158, 11, .17),
    inset 0 1px 0 rgba(255, 255, 255, .10),
    0 2px 6px rgba(0, 0, 0, .42);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: transform var(--motion-fast), color var(--motion-fast);
}
.bo-back:active, .bo-x:active { transform: scale(.94); }
.bo-back:focus-visible, .bo-x:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.bo-back .ico { width: 18px; height: 18px; }
.bo-x { font-size: 22px; line-height: 1; }
.bo-title {
  margin: 0;
  text-align: center;
  font-size: 13px;
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #F6E4B4;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .55), 0 0 14px rgba(245, 158, 11, .18);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bo-sub {
  margin: 3px 0 0;
  text-align: center;
  font-size: 10px;
  line-height: 1.45;
  color: var(--ink-soft);
}
/* The honor under inspection wears its own gold-leaf cartouche: the sheet names the office
   first and the relic second, and the gem keeps the plate from reading as a plain caption. */
.bo-honor {
  flex: none;
  align-self: center;
  min-width: 0;
  max-width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin: 0;
  padding: 5px 12px 6px;
  border-radius: 999px;
  background:
    linear-gradient(180deg, rgba(253, 230, 138, .15), rgba(245, 158, 11, .04) 58%, rgba(0, 0, 0, .26)),
    rgba(12, 17, 28, .82);
  box-shadow:
    inset 0 0 0 1px rgba(245, 158, 11, .32),
    inset 0 1px 0 rgba(255, 255, 255, .12),
    0 1px 0 rgba(0, 0, 0, .4);
}
.bo-honor-gem {
  flex: none;
  width: 12px;
  height: 12px;
  color: var(--bo-metal);
  filter: drop-shadow(0 0 3px rgba(245, 158, 11, .45));
}
.bo-honor-name {
  min-width: 0;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--bo-metal);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bo-stage {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.bo-list {
  list-style: none;
  margin: 0;
  padding: 1px 1px 0 0;
  flex: 1 1 auto;
  min-height: 0;
  max-height: 55vh;
  display: flex;
  flex-direction: column;
  gap: 6px;
  scrollbar-width: thin;
  scrollbar-color: rgba(245, 158, 11, .34) transparent;
}
/* the app hides chrome everywhere; this registry earns a visible gold thread instead */
#badge-owners-modal .bo-list::-webkit-scrollbar { display: block; width: 5px; height: 5px; }
#badge-owners-modal .bo-list::-webkit-scrollbar-track { background: transparent; }
#badge-owners-modal .bo-list::-webkit-scrollbar-thumb { background: rgba(245, 158, 11, .34); border-radius: 99px; }
#badge-owners-modal .bo-list::-webkit-scrollbar-thumb:hover { background: rgba(245, 158, 11, .55); }

/* A pedestal, not a list item: deep obsidian glass under a hairline of gold. The row is a grid of
   three fixed roles — medallion, identity, deed — so a long Persian name can only ever ellipsize
   the middle column and never push the plate off a 320px phone. */
.bo-row {
  position: relative;
  flex: none;
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 64px;
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid rgba(255, 215, 0, .08);
  background:
    radial-gradient(120% 150% at 0% -24%, rgba(255, 214, 102, .04), rgba(255, 255, 255, 0) 58%),
    rgba(18, 24, 38, .75);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, .35);
  transition: border-color var(--motion-fast), box-shadow var(--motion-fast);
}
/* The player's own plate is a deed, not a rival: the gold hairline stays outside, an emerald ring
   sits just inside it, and the whole slab is lit from within. */
.bo-row.is-you {
  background:
    radial-gradient(130% 160% at 6% -26%, rgba(52, 211, 153, .16), rgba(255, 255, 255, 0) 60%),
    linear-gradient(180deg, rgba(16, 185, 129, .07), rgba(255, 255, 255, 0) 64%),
    rgba(16, 22, 34, .88);
  box-shadow:
    inset 0 0 0 1px rgba(52, 211, 153, .3),
    0 0 20px rgba(16, 185, 129, .08);
}
/* Serial one is the only plate the edition will never strike again: gold hairline, ambient burn. */
.bo-row.is-genesis {
  border-color: rgba(245, 158, 11, .45);
  box-shadow:
    inset 0 0 0 1px rgba(245, 158, 11, .22),
    inset 0 1px 0 rgba(255, 255, 255, .07),
    0 2px 10px rgba(0, 0, 0, .42);
}
.bo-row.is-you.is-genesis {
  box-shadow:
    inset 0 0 0 1px rgba(52, 211, 153, .3),
    inset 0 0 0 2px rgba(245, 158, 11, .1),
    0 0 20px rgba(16, 185, 129, .08);
}
/* The hall offers no live door while the challenge is parked: every plate keeps the same
   calm gold hairline, and no hover paints a target the player cannot press. */
.bo-row.is-genesis::after {
  content: "";
  position: absolute;
  inset-inline: 12px;
  inset-block-start: 0;
  height: 1px;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(253, 230, 138, .7), transparent);
}
/* `inset: 0`, never `-1px`: an absolutely positioned child that pokes past the scrollport is real
   horizontal overflow, and the burn below is a box-shadow that paints outside the box anyway. */
.bo-row.is-genesis::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  box-shadow: 0 0 20px rgba(245, 158, 11, .26);
  animation: bo-genesis-breathe 3.8s ease-in-out infinite;
}
@keyframes bo-genesis-breathe {
  0%, 100% { opacity: .4; }
  50% { opacity: 1; }
}
html.reduced-motion .bo-row.is-genesis::before { animation: none; opacity: .85; }

.bo-av {
  position: relative;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-family: var(--font-stat);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0;
  unicode-bidi: isolate;
  color: #F2E4BE;
  background: radial-gradient(125% 125% at 50% 14%, #33425E 0%, #151E2F 58%, #080E1B 100%);
  box-shadow:
    inset 0 0 0 1px rgba(245, 158, 11, .42),
    inset 0 1px 0 rgba(255, 255, 255, .18),
    inset 0 -1px 0 rgba(0, 0, 0, .55),
    0 2px 6px rgba(0, 0, 0, .48),
    0 0 0 1px rgba(255, 215, 0, .14);
}
/* the deed's medallion wears the same ring in the deed's own metal */
.bo-row.is-you .bo-av {
  box-shadow:
    inset 0 0 0 1px rgba(52, 211, 153, .55),
    inset 0 1px 0 rgba(255, 255, 255, .18),
    inset 0 -1px 0 rgba(0, 0, 0, .55),
    0 2px 6px rgba(0, 0, 0, .48),
    0 0 0 1px rgba(52, 211, 153, .22);
}
/* A real portrait sits inside the gold rim; the monogram stays underneath until it lands.
   An abspos <img> is a replaced element, so `inset` alone never stretches it: with `width: auto`
   it keeps its intrinsic size and a 1254px Telegram photo paints a 1254px dome over the ledger.
   The medallion must therefore state the box, not just the offsets. */
.bo-av-img {
  position: absolute;
  inset: 2px;
  width: calc(100% - 4px);
  height: calc(100% - 4px);
  max-width: calc(100% - 4px);
  max-height: calc(100% - 4px);
  object-fit: cover;
  display: block;
  border-radius: 50%;
  background: #0A1120;
}
.bo-av.has-photo { color: transparent; }
/* The founder's pip is a struck medal, not a sticker: the crown is stamped into gold, the way the
   serial plate beside it is. */
.bo-pin {
  position: absolute;
  inset-block-end: -3px;
  inset-inline-end: -3px;
  width: 16px;
  height: 16px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #2A1C05;
  background: linear-gradient(150deg, #FFF0B8 0%, #F5C542 48%, #B07410 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .82),
    inset 0 -1px 0 rgba(120, 74, 6, .4),
    0 1px 3px rgba(0, 0, 0, .62);
}
.bo-pin .ico { width: 9px; height: 9px; }

.bo-id { min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.bo-name {
  min-width: 0;
  font-size: 13px;
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: .005em;
  color: #EDF2FA;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .5);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* Each fact keeps its own direction, so an RTL sheet never reorders a handle or a mint stamp. */
.bo-meta {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 9.5px;
  line-height: 1.35;
  color: #7C8CA4;
  white-space: nowrap;
  overflow: hidden;
}
.bo-part { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bo-handle { unicode-bidi: isolate; color: #93A6C2; }
.bo-when { font-variant-numeric: tabular-nums; }
.bo-dot { flex: none; color: rgba(245, 158, 11, .55); }
.bo-row.is-you .bo-role { color: #86C9AE; }

.bo-right { min-width: 0; display: flex; flex-direction: column; align-items: flex-end; gap: 5px; }
/* The plaque is a struck gold ingot: `№ 001` is a code, so it reads LTR in every language and
   carries tabular figures. The brushed lines, the 1px top bevel and the letterpress shadow are
   what make it a plate of metal rather than a yellow sticker. */
.serial-plaque {
  position: relative;
  max-width: 100%;
  padding: 3px 10px;
  border-radius: 8px;
  border: 1px solid rgba(255, 224, 130, .5);
  direction: ltr;
  unicode-bidi: isolate;
  font-family: var(--font-stat);
  font-size: 10.5px;
  font-weight: 900;
  letter-spacing: .05em;
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1, "lnum" 1;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: #1A1300;
  background: linear-gradient(135deg, #FFE082 0%, #FFB300 50%, #FFA000 100%);
  box-shadow:
    inset 0 1px 1px rgba(255, 255, 255, .6),
    0 2px 8px rgba(255, 160, 0, .25);
  text-shadow: none;
}
.bo-row.is-genesis .serial-plaque {
  background: linear-gradient(135deg, #FFF3C4 0%, #F7C13C 52%, #D08A12 100%);
  box-shadow:
    inset 0 1px 1px rgba(255, 255, 255, .7),
    0 2px 10px rgba(245, 158, 11, .35);
}
/* The deed's own stamp: emerald set in gold, uppercase in Latin and plain in Persian. */
.bo-yours {
  max-width: 100%;
  padding: 3px 9px 4px;
  border-radius: 999px;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .04em;
  line-height: 1.35;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  unicode-bidi: isolate;
  color: #6EE7B7;
  background: rgba(5, 46, 32, .6);
  border: 1px solid rgba(52, 211, 153, .4);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .06);
  text-shadow: none;
}

.bo-note {
  flex: 1 1 auto;
  display: grid;
  place-items: center;
  padding: 20px 16px;
  text-align: center;
  font-size: 11.5px;
  line-height: 1.6;
  color: var(--ink-soft);
}
.bo-empty {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 14px 14px 18px;
  text-align: center;
}
.bo-empty-crest {
  width: 72px;
  height: 72px;
  display: grid;
  place-items: center;
  border-radius: 26%;
  opacity: .42;
  filter: saturate(.3) brightness(.9);
  background: linear-gradient(180deg, #263248 0%, #121A29 100%);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .08), 0 6px 16px rgba(0, 0, 0, .4);
}
.bo-empty-crest .badge-crest { width: 56px; height: 56px; display: block; }
.bo-empty-copy { margin: 0; max-width: 32ch; font-size: 11.5px; line-height: 1.6; color: var(--ink-soft); }
.bo-empty-first { margin: 0; max-width: 32ch; font-size: 12px; font-weight: 800; line-height: 1.6; color: var(--gold-ink); }

/* ---- the vault meter: how much of the edition is claimed, how much stays locked away ---- */
.bo-foot { flex: none; padding-top: 8px; border-top: 1px solid rgba(255, 215, 0, .1); }
.bo-vault { min-width: 0; display: flex; flex-direction: column; gap: 6px; }
.bo-vault-legend {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
}
.bo-vault-struck,
.bo-vault-held {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
/* The claimed count is the only glowing number on the screen: it is the one the player is counting. */
.bo-vault-struck {
  font-size: 11px;
  font-weight: 900;
  color: #FFD166;
  text-shadow: 0 0 12px rgba(255, 179, 0, .45);
}
.bo-vault-held { display: inline-flex; align-items: center; gap: 4px; color: var(--ink-soft); }
.bo-vault-lock { flex: none; width: 9px; height: 9px; color: #526079; }
/* the label sits in its own box, so a clipped count ellipsizes instead of losing its padlock */
.bo-vault-held > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* One continuous meter, not a segmented battery: the fill carries the claimed share. */
.bo-vault-track {
  position: relative;
  height: 6px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(10, 14, 22, .9);
  border: 1px solid rgba(255, 255, 255, .05);
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, .7);
}
.bo-vault-fill {
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  display: block;
  border-radius: 999px;
  background: linear-gradient(90deg, #FFB300, #F59E0B);
  box-shadow: 0 0 10px rgba(245, 158, 11, .4);
  transition: width var(--motion-med);
}
/* A drained vault is a closed book: the meter turns emerald, the same green the deed rows wear. */
.bo-vault[data-state="full"] .bo-vault-fill {
  background: linear-gradient(90deg, #34D399, #10B981);
  box-shadow: 0 0 10px rgba(16, 185, 129, .4);
}
.bo-vault[data-state="full"] .bo-vault-held { color: #4B6A5E; }
.bo-vault[data-state="full"] .bo-vault-lock { color: #3F5B50; }

/* ---- Persian registry: RTL columns, no tracking, room for descenders ---- */
.owners-sheet:lang(fa) :is(
  .bo-title, .bo-sub, .bo-honor-name, .bo-meta, .bo-role, .bo-when, .bo-yours, .bo-duel-t,
  .bo-shelter-tag, .bo-note, .bo-empty-copy, .bo-empty-first, .bo-vault-struck, .bo-vault-held
) {
  font-family: 'Vazirmatn', system-ui, -apple-system, sans-serif;
  letter-spacing: 0;
  text-transform: none;
}
.owners-sheet:lang(fa) :is(.bo-head, .bo-honor, .bo-id, .bo-right, .bo-duel, .bo-note, .bo-empty, .bo-foot, .bo-vault-legend) {
  direction: rtl;
  line-height: 1.6;
}
.owners-sheet:lang(fa) .bo-back .ico { transform: scaleX(-1); }
/* the plaque and the handle are codes, not prose: they keep their own Latin face and tracking */
.owners-sheet:lang(fa) :is(.serial-plaque, .bo-handle) { font-family: var(--font-stat); }

/* short phones: the registry keeps its rows, the frame gives way */
@media (max-height: 700px) {
  .sheet.owners-sheet { gap: 5px; padding-top: 8px; }
  .bo-head { grid-template-columns: 40px minmax(0, 1fr) 40px; }
  .bo-back, .bo-x { width: 40px; height: 40px; }
  .bo-title { font-size: 12.5px; letter-spacing: .08em; }
  .bo-row { min-height: 58px; padding: 7px 9px; gap: 8px; }
  .bo-av { width: 31px; height: 31px; font-size: 11px; }
  .bo-empty-crest { width: 62px; height: 62px; }
  .bo-empty-crest .badge-crest { width: 48px; height: 48px; }
}
@media (max-height: 600px) {
  .bo-list { max-height: 46vh; }
  .bo-sub { display: none; }
  .bo-empty { gap: 6px; padding: 8px 12px 12px; }
}
@media (min-height: 780px) {
  .sheet.owners-sheet { gap: 9px; }
  .bo-row { padding: 11px 13px; }
}
/* 320px: the plate and the duel key are the fixed cost, the name gives first */
@media (max-width: 360px) {
  .bo-row { grid-template-columns: 32px minmax(0, 1fr) auto; gap: 7px; padding: 7px 8px; min-height: 62px; }
  .bo-av { width: 32px; height: 32px; }
  .bo-pin { width: 14px; height: 14px; }
  .bo-title { font-size: 12px; letter-spacing: .07em; }
  .bo-name { font-size: 12px; }
  .bo-meta { gap: 4px; }
  .serial-plaque { font-size: 9.5px; padding: 3px 6px 4px; }
  .bo-yours { font-size: 8px; padding: 2px 6px 3px; }
  .bo-vault-legend { gap: 6px; font-size: 9px; letter-spacing: 0; }
  .bo-vault-struck { font-size: 10px; }
}

/* ---- the deed's two doors: a challenge on standby, or the shield that refuses one ----
   The challenge key is temporarily locked: it keeps its seat in the row, takes no tap, and never
   dispatches a RELIC_CHALLENGE_SEND. A guarded row prints its clock and shield instead, muted and
   inert. Both ride under the serial plate, never beside it: the row's third column is `auto`, so a
   second fixed width there is what would push a 320px phone into a sideways scroll. */
.bo-duel {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-height: 22px;
  max-width: 100%;
  padding: 0 9px 1px;
  border: 1px solid rgba(255, 255, 255, .08);
  border-radius: 999px;
  cursor: not-allowed;
  pointer-events: none;
  font: inherit;
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--ink-soft);
  background: rgba(25, 30, 42, .7);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .04);
  opacity: .92;
}
.bo-duel .ico {
  flex: none;
  width: 10px;
  height: 10px;
  color: var(--text-dim);
  filter: none;
}
.bo-duel-t {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* A shielded serial states its clock instead of offering a door: a dark obsidian pill with a
   hairline rim, the hour on LTR tabular figures, and the word SHIELD beside it. */
.bo-shelter {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 100%;
  min-height: 22px;
  padding: 2px 8px 3px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, .1);
  font-size: 8.5px;
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: .05em;
  white-space: nowrap;
  unicode-bidi: isolate;
  color: var(--ink-soft);
  background: rgba(12, 17, 26, .8);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .04);
}
.bo-shelter .ico { flex: none; width: 9px; height: 9px; color: #7C8FA8; }
.bo-shelter-t {
  font-family: var(--font-stat);
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1, "lnum" 1;
  unicode-bidi: isolate;
}
.bo-shelter-tag {
  font-size: 7.5px;
  font-weight: 900;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #64748B;
}
@media (max-width: 360px) {
  .bo-duel { padding: 0 6px 1px; gap: 3px; }
  .bo-shelter { font-size: 8.5px; padding: 2px 6px 3px; }
}

/* ---- "View All" drawer: the full catalogue as a quiet pick list ---- */
.badges-sheet .pick { max-height: none; }
.badge-pick-row {
  display: flex;
  align-items: center;
  gap: var(--s3);
  min-height: 54px;
  padding: var(--s1) var(--s2);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: transform var(--motion-fast), background var(--motion-fast);
}
.badge-pick-row:hover:not(:active) { transform: translateY(-1px); }
.badge-pick-row:active { transform: translateY(var(--press-y)); }
.badge-pick-row:focus-visible { outline: 3px solid var(--brand-2); outline-offset: -3px; }
.badge-pick-row .badge-chip { width: 36px; height: 36px; }
.badge-pick-row .badge-chip .ico { width: 16px; height: 16px; }
.badge-pick-txt { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.badge-pick-n {
  min-width: 0;
  font-size: var(--t-2);
  font-weight: 800;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.badge-pick-s {
  min-width: 0;
  font-size: var(--t-micro);
  font-weight: 700;
  color: var(--ink-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.badge-pick-row.is-unlocked .badge-pick-s { color: var(--mint-ink); }
.badge-pick-row.is-equipped .badge-pick-n { color: var(--honey-ink); }
.badge-pick-row .tick { width: 18px; height: 18px; flex: none; color: var(--honey-ink); visibility: hidden; }
.badge-pick-row.is-equipped .tick { visibility: visible; }

/* ---- profile responsive: zero horizontal scroll, targets stay >= 44px ---- */
@media (max-width: 380px) {
  .pf-hero.pf-hero-v2 { padding: var(--s3); }
  .pf-hero-top { gap: var(--s2); }
  .pf-avatar-wrap { --av: 60px; }
  .badge-rack { gap: 4px; padding: 6px 8px; }
  .badge-chip { width: 36px; height: 36px; }
  .badge-chip .ico { width: 16px; height: 16px; }
  .badge-lock .ico-lock { width: 13px; height: 13px; right: -4px; bottom: -4px; }
  .pf-id-card { min-height: 124px; padding: var(--s2); border-radius: 18px; }
  .pf-equipped-badge { max-width: 100%; }
  .pf-name-row { flex-wrap: wrap; }
}
@media (max-height: 700px) {
  .pf-hero.pf-hero-v2 { padding: var(--s3) var(--s4); }
  .pf-avatar-wrap { --av: 60px; }
}
html.reduced-motion .pf-xp-bar.bar i, html.reduced-motion .reward-badge { animation: none; transition: none; }



/* ==========================================================================
   THE 200 STARS CUP — the Telegram Stars championship, staged on one
   full-height clay card. The card's ladder reads two ways through the switch in
   its header: CHANNELS ranks the squads, and every channel card is a door into
   that channel's Top-10 roster; TOP PLAYERS lists the ten people the Stars
   actually land on.
   Dark Clay spec: canvas #10141D, card face #1C2433 lit from above, gold ink
   #FCD34D for the Stars. No backdrop-filter and no blur() anywhere on this
   screen or its sheet: every surface is opaque clay and every glow is a
   gradient fill.
   Geometry: a two-row hero header — the bare Star with its amber ambient glow beside
   the embossed silver wordmark, the round help key, and the inset bracket clock on
   the right; then the board switch stretched across the full card, its keys riding a
   recessed trench — over the Top-3 podium · two runners · the pinned squad row
   · CTA. The header stays at or under 60px, so the podium keeps its pixels. The
   podium band is the one flexible block; everything else is `flex: none`, so a short
   phone scrolls the stage instead of compressing a row.
   ========================================================================== */

/* ---- the stage: the card's height budget, never the page's ---- */
.screen.arena-screen { overflow: hidden; max-width: 100%; }
.arena-screen #arena-scroll {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 2px;                       /* room for the card's own extrusion */
  overflow-y: auto;                   /* a scroll of last resort on tiny phones */
  overflow-x: hidden;
  overscroll-behavior: contain;
  scrollbar-width: none;
}
.arena-screen #arena-scroll::-webkit-scrollbar { display: none; }

/* ---- the card: one slab, every section on the same rhythm ---- */
.stars-card {
  position: relative;
  flex: 1 1 auto;
  min-height: min-content;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: clamp(9px, 2vh, 16px);
  padding: clamp(10px, 1.7vh, 16px) clamp(11px, 3.2vw, 16px) clamp(9px, 1.5vh, 16px);
  border-radius: 20px;
  border-top: 1px solid rgba(255, 255, 255, .14);
  /* the crown of the card is lit: a warm wash lands on the championship lockup from
     above, the floor keeps a cool cyan breath, and the body stays clay between them */
  background:
    radial-gradient(126% 64% at 50% -8%, rgba(252, 211, 77, .19), rgba(252, 211, 77, 0) 62%),
    radial-gradient(88% 58% at 6% 100%, rgba(56, 189, 248, .1), rgba(56, 189, 248, 0) 60%),
    linear-gradient(180deg, #27334E 0%, #1C2433 62%, #1A2230 100%);
  background-color: #1C2433;
  box-shadow: var(--clay), var(--clay-ring), 0 0 36px -14px rgba(252, 211, 77, .5);
}

/* ---- hero header: two bands — the championship lockup, then the control strip ----
   Band one is the brand: the bare Star floating on the clay with its amber ambient
   glow, inline beside the big embossed platinum wordmark, the glass help key holding
   the right edge. Band two is one control strip: the two-way board switch on the left,
   the live bracket clock flush right.

   The clock used to share band one. On a 360px phone the card is only ~317px wide, so a
   serious wordmark, a three-register countdown and a 36px Star cannot fit one line — the
   title clips. Splitting them buys the wordmark its size AND gives the countdown the
   full height of its band, so both grew instead of both staying cramped.

   ONE PALETTE RULE HOLDS THE CARD TOGETHER. Gold is the colour of the live and the
   premium things — the Star's glow, the clock's numerals, the lit key's rim and bloom —
   while the wordmark itself is cool polished platinum. That keeps the biggest gold slab
   on the screen the PLAY FOR YOUR SQUAD key, where it belongs, instead of splitting the
   eye between the top of the card and the bottom. */
.stars-head {
  flex: none;
  display: flex;
  flex-direction: column;
  gap: 5px;
  min-width: 0;
}
/* Band two is one machined console, not two loose pills. The board switch holds the
   left of the capsule, the live chronograph the right, and a hairline seam divides them.
   Keeping the clock INSIDE the deck is what gives the labels room: at 360 the content
   band is only 317px, and the old separate clock capsule spent 8px on a gap plus its own
   padding and rim — leaving the switch 195px for two keys. Here the clock spends ~90px,
   the keys split the rest, and the header reads as one instrument instead of three
   controls stacked by accident. */
.stars-strip {
  position: relative;
  flex: none;
  display: flex;
  align-items: stretch;
  gap: 6px;
  height: 36px;
  min-width: 0;
  padding: 3px;
  border: 1px solid rgba(255, 255, 255, .08);
  border-radius: 999px;
  background:
    radial-gradient(130% 260% at 50% -70%, rgba(255, 255, 255, .13) 0%, rgba(255, 255, 255, 0) 58%),
    linear-gradient(180deg, rgba(7, 11, 20, .62) 0%, rgba(10, 16, 28, .46) 48%, rgba(23, 32, 51, .42) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .1),
    inset 0 -2px 5px rgba(2, 6, 16, .5),
    inset 0 0 14px rgba(2, 6, 16, .34),
    0 1px 0 rgba(255, 255, 255, .045);
}
/* the Star floats bare on the clay: the box, the rim and the jewel face are gone,
   and the PNG's own alpha carries the emblem. Its weight comes from a warm amber
   ambient drop-glow — light landing on the card, never a frame around it. */
.stars-emblem {
  position: relative;
  flex: none;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border: none;
  border-radius: 0;
  background: none;
  box-shadow: none;
}
/* the PNG is RGBA gold: `screen` lets the metal catch the clay light with no box */
.stars-emblem-img,
.stars-pod-star,
.stars-squad-star,
.stars-run-star,
.sr-notice-star,
.sr-pay-star {
  display: block;
  object-fit: contain;
  mix-blend-mode: screen;
}
/* full-bleed in its box; the amber ambient glow lives in the filter — three layers of
   it: a tight warm rim so the star's edges catch fire, a wide amber bloom so it lights
   the clay around it, and a dark cast shadow so it sits ON the card rather than in it */
.stars-emblem-img {
  position: relative;
  z-index: 1;
  width: 100%;
  height: 100%;
  filter:
    drop-shadow(0 0 6px rgba(255, 226, 150, .7))
    drop-shadow(0 0 17px rgba(245, 158, 11, .5))
    drop-shadow(0 5px 12px rgba(2, 6, 16, .6));
}
/* band one: the Star holds the left edge, the wordmark follows inline and takes every
   pixel it can, the help key closes the right. Height is the Star's, so the band grows
   with the emblem and shrinks with it on a short phone. */
.stars-titlebar { display: flex; align-items: center; gap: 9px; width: 100%; min-width: 0; }
/* the wordmark: heavy embossed platinum with tight tracking, sized to be the loudest
   thing on the card after the CTA. The gradient is the metal; the engraving is done with
   `drop-shadow` rather than `text-shadow`, because the fill is transparent and a
   text-shadow would simply show through it. */
.stars-name {
  margin: 0;
  flex: 1 1 auto;
  min-width: 0;
  font-size: 24px;
  font-weight: 900;
  letter-spacing: -.01em;
  line-height: 1;
  color: #F8FAFC;
  text-shadow: 0 1px 0 #05070C, 0 0 20px rgba(148, 178, 224, .28);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* guarded, because `color: transparent` without a working text clip would erase the
   championship's name — the fallback above is the plain lit silver */
@supports ((-webkit-background-clip: text) or (background-clip: text)) {
  .stars-name {
    /* five stops, not three: a blown highlight at the crown, the metal cooling through
       the middle, and a shadowed foot, which is what reads as a bevel at 24px */
    background-image: linear-gradient(180deg, #FFFFFF 0%, #F6FAFF 32%, #DCE6F6 56%, #AFC0DC 82%, #8093B3 100%);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    /* the engraving, done with a filter because a transparent fill would let a
       text-shadow show straight through the glyph: a crisp dark edge under the metal,
       a soft cast shadow, and a cool halo lifting it off the clay */
    filter:
      drop-shadow(0 1px 0 rgba(3, 5, 10, .95))
      drop-shadow(0 3px 6px rgba(2, 6, 16, .45))
      drop-shadow(0 0 14px rgba(150, 180, 230, .22));
    text-shadow: none;
  }
}
/* the round help key: a polished glass bead, not a hole in the band — a cool sheen
   landing on its upper left over a deep slate core, so it reads as something you can
   press. The "?" is bright silver, engraved into the glass with a dark shadow below
   it and a whisper of light above; the warm ring only arrives on hover/press, which
   keeps gold meaning "live" at rest. The 26px face carries a 50px invisible tap band. */
.stars-info {
  position: relative;
  flex: none;
  appearance: none;
  border: 0;
  padding: 0;
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  /* two paints: the glass catches the light top-left, the core stays cool and deep */
  background:
    radial-gradient(115% 115% at 30% 18%, rgba(255, 255, 255, .2) 0%, rgba(255, 255, 255, .05) 44%, rgba(255, 255, 255, 0) 70%),
    linear-gradient(180deg, #2E3A57 0%, #1A2233 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .2),
    inset 0 -2px 4px rgba(2, 6, 16, .55),
    inset 0 0 0 1px rgba(255, 255, 255, .055),
    0 2px 5px rgba(2, 6, 16, .45);
  color: #DCE4F1;
  font: inherit;
  font-size: 14px;
  font-weight: 900;
  line-height: 1;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: color var(--motion-fast), transform var(--motion-fast), box-shadow var(--motion-fast);
}
/* the glyph is cut into the bead rather than printed on it */
.stars-info > span {
  display: block;
  margin-top: -1px;
  text-shadow: 0 1px 0 rgba(4, 6, 12, .95), 0 -1px 0 rgba(255, 255, 255, .1), 0 0 10px rgba(148, 178, 224, .22);
}
/* the invisible tap band: generous up and down, flush at the RIGHT edge, and reaching
   further left instead. Two reasons. The key now CLOSES the band, so a symmetrical band
   would push 12px of scrollable overflow past the card's content box — which the layout
   audit reads, correctly, as a spill. And a measured target wants the width back: 28px
   plus a 20px left reach is a 48px target at every size, while the band never covers the
   wordmark's own space (nothing there is tappable). */
.stars-info::after { content: ""; position: absolute; inset: -12px 0 -12px -20px; border-radius: 50%; }
.stars-info:hover, .stars-info:active {
  color: #FDE68A;
  /* the bead warms from the inside out: a gold hairline and a soft amber halo */
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .22),
    inset 0 -2px 4px rgba(2, 6, 16, .55),
    inset 0 0 0 1px rgba(252, 211, 77, .34),
    0 0 13px -3px rgba(245, 158, 11, .8),
    0 2px 5px rgba(2, 6, 16, .45);
}
.stars-info:active { transform: translateY(1px) scale(.96); }
.stars-info:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
/* the switch zone: two equal keys under one travelling lit key. It is a bare child of
   the deck now — the deck itself owns the recess, the rim and the smoked glass, so the
   switch has no capsule of its own to fight with the clock's. */
.stars-tabs {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
/* the seam between the two zones: a lit hairline that dies at both ends, so the deck
   reads as one machined piece rather than two boxes butted together */
.stars-tabs::after {
  content: "";
  position: absolute;
  top: 4px;
  bottom: 4px;
  right: 0;
  width: 1px;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0) 0%, rgba(148, 178, 224, .2) 18%, rgba(148, 178, 224, .2) 82%, rgba(255, 255, 255, 0) 100%);
}
/* The lit key travels UNDER the labels. `position: absolute` is load-bearing: as a grid
   child it would occupy the first column, pushing "Top Players" onto a second row that
   spills out of the 36px deck — which is exactly how this control broke before. */
.stars-thumb {
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  width: 50%;
  border-radius: 999px;
  /* made like the rest of the card's metal: a glass sheen across its upper half, a cool
     slab body, a bright top edge, and warm gold tucked in at the rim and along the
     underside — enough to read as lit without becoming a second gold slab competing with
     the CTA. Its outer bloom warms the recess around it, so the live half reads live. */
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .26) 0%, rgba(255, 255, 255, .07) 46%, rgba(255, 255, 255, 0) 100%),
    linear-gradient(180deg, #4C608C 0%, #2E3A56 58%, #242D43 100%);
  box-shadow:
    0 3px 8px -2px rgba(2, 6, 16, .66),
    0 1px 0 rgba(255, 255, 255, .08),
    inset 0 1px 0 rgba(255, 255, 255, .34),
    inset 0 -10px 14px -12px rgba(245, 158, 11, .7),
    inset 0 0 0 1px rgba(252, 211, 77, .22),
    0 0 16px -7px rgba(245, 158, 11, .8);
  /* a spring on the slide: it settles rather than arrives */
  transition: transform .42s cubic-bezier(.22, 1, .36, 1);
}
.stars-tabs[data-active="players"] .stars-thumb { transform: translateX(100%); }
/* The keys are self-contained now. Every piece of native chrome is reset here rather
   than inherited from another screen's switch: an appearance, border or font-family
   left unpainted is what made the previous version render as two outlined system
   buttons. */
.stars-key {
  position: relative;
  z-index: 1;
  appearance: none;
  -webkit-appearance: none;
  border: 0;
  margin: 0;
  padding: 0 2px;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  border-radius: 999px;
  background: transparent;
  box-shadow: none;
  color: #8C9DB6;
  font: inherit;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .075em;
  text-transform: uppercase;
  white-space: nowrap;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: color var(--motion-fast), transform var(--motion-fast);
}
.stars-key-ico {
  flex: none;
  width: 13px;
  height: 13px;
  opacity: .72;
  transition: opacity var(--motion-fast), filter var(--motion-fast);
}
.stars-key-t { display: block; min-width: 0; }
/* the face is 28px inside the 36px deck; the band is what reaches 48px. Vertical only —
   the keys are flush, so a side band would let a neighbour steal the other's tap. */
.stars-key::after { content: ""; position: absolute; inset: -10px 0; }
.stars-key[aria-pressed="true"] {
  color: #FDE68A;
  /* the lit label sits IN the key: a dark seat under it, a warm bloom around it */
  text-shadow: 0 0 12px rgba(245, 158, 11, .46), 0 1px 0 #05070C;
}
.stars-key[aria-pressed="true"] .stars-key-ico {
  opacity: 1;
  filter: drop-shadow(0 0 5px rgba(245, 158, 11, .32));
}
.stars-key:active { transform: translateY(1px) scale(.985); }
.stars-key:focus-visible { outline: 2px solid rgba(252, 211, 77, .9); outline-offset: -2px; }
@media (hover: hover) {
  .stars-key:not([aria-pressed="true"]):hover { color: #DCE6F6; }
}
/* THE LIVE CHRONOGRAPH — engraved into the right end of the deck, not encased in a
   second capsule. What makes it read as an instrument is not a box: it is the monospaced
   tabular gold, the dimmed colons grouping the countdown into three registers, the warm
   halo the bead throws, and the fact that it is the only thing in the header that moves.
   The readout is still split into unit plates by src/compete.ts; the plates are stripped
   bare here so eight glyphs stay narrow enough to leave the switch two real keys. */
.stars-count {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 0;
  padding: 0 7px 0 2px;
  border: 0;
  border-radius: 0;
  background: radial-gradient(120% 170% at 16% 50%, rgba(245, 158, 11, .09) 0%, rgba(245, 158, 11, 0) 66%);
  box-shadow: none;
  color: #FDE68A;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
  font-size: 14px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0;
  white-space: nowrap;
  text-align: center;
  line-height: 1;
  text-shadow: 0 0 9px rgba(245, 158, 11, .42), 0 1px 0 #05070C;
}
/* the unit plate, stripped to a bare numeral: no window, no rim, no padding — the
   deck's glass is the only surface between the digits and the light */
.stars-count > b {
  display: block;
  padding: 0;
  background: none;
  box-shadow: none;
  font-weight: 900;
  line-height: 1;
}
.stars-count > b > span { line-height: 1; }
/* the same guarded metal the wordmark uses: a working text clip turns the numerals to
   polished gold, and a browser without one keeps the flat lit amber */
@supports ((-webkit-background-clip: text) or (background-clip: text)) {
  .stars-count > b > span {
    background-image: linear-gradient(180deg, #EFF6FF 0%, #FDE9A9 34%, #FBBF24 68%, #D99413 100%);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    /* the fill is transparent, so the glow has to come from the filter — a text-shadow
       would simply show through the glyph */
    text-shadow: none;
    filter: drop-shadow(0 0 4px rgba(245, 158, 11, .38));
  }
}
/* the colon: the real glyph at the digits' own size, so it lands on their baseline,
   dimmed to a separator rather than a third register */
.stars-count > i {
  display: block;
  margin: 0 1px;
  color: rgba(253, 230, 138, .38);
  font-size: 14px;
  font-style: normal;
  font-weight: 900;
  line-height: 1;
  text-shadow: none;
}
/* the states that are not a clock — `Bracket live` — are a word, not a readout; the
   micro-label treatment keeps them in the console's vocabulary */
.stars-count[data-shape="text"] {
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
}
/* the pulse bead — the same gold as the Star, one twentieth the size. It throws a ring
   on the beat, so the countdown reads as live from across the card. */
.stars-count::before {
  content: "";
  flex: none;
  width: 5px;
  height: 5px;
  margin: 0 5px 0 0;
  border-radius: 50%;
  background: radial-gradient(circle at 34% 30%, #FFFDF3 0%, #FBBF24 52%, #B45309 100%);
  animation: cup-clock 2s ease-out infinite;
}
/* the ring leaves the bead and dies: a live indicator, not a blinking dot */
@keyframes cup-clock {
  0% {
    opacity: 1;
    transform: scale(1);
    box-shadow: 0 0 6px rgba(251, 191, 36, .95), 0 0 12px rgba(245, 158, 11, .5), 0 0 0 0 rgba(245, 158, 11, .55);
  }
  60% {
    opacity: .72;
    transform: scale(.88);
    box-shadow: 0 0 6px rgba(251, 191, 36, .8), 0 0 12px rgba(245, 158, 11, .38), 0 0 0 6px rgba(245, 158, 11, 0);
  }
  100% {
    opacity: 1;
    transform: scale(1);
    box-shadow: 0 0 6px rgba(251, 191, 36, .95), 0 0 12px rgba(245, 158, 11, .5), 0 0 0 0 rgba(245, 158, 11, .55);
  }
}

/* ---- the channel icon: a clay squircle, not a ball — a channel is a place,
       not a player. Metal tints the body; every decorative corner tick is gone,
       so a board of channels reads as colours and letters, not badge noise. ---- */
.stars-ch-av {
  position: relative;
  flex: none;
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 13px;
  background:
    radial-gradient(52% 44% at 30% 22%, rgba(255, 255, 255, .34), rgba(255, 255, 255, 0) 72%),
    linear-gradient(180deg, #2E3A55 0%, #161E2D 100%);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, .1),
    inset 0 1px 0 rgba(255, 255, 255, .18),
    inset 0 -3px 5px rgba(0, 0, 0, .5),
    0 2px 0 #080C14;
  color: var(--ink);
  line-height: 1;
}
.stars-ch-t { font-size: 14px; font-weight: 900; letter-spacing: -.02em; }
/* the channel's real Telegram photo: a circular crop inside the crest well, ringed by
   a hairline of metal. It fades in over the call-sign monogram and removes itself on a
   hidden channel or an error, leaving the monogram as the one fallback. */
.stars-ch-av .stars-ch-photo {
  position: absolute;
  inset: 3px;
  z-index: 1;
  width: calc(100% - 6px);
  height: calc(100% - 6px);
  border-radius: 50%;
  object-fit: cover;
  object-position: center;
  clip-path: circle(50%);
  background: #0B1220;
  box-shadow:
    0 0 0 1px rgba(226, 232, 240, .42),
    0 0 0 2px rgba(4, 8, 16, .55),
    0 2px 5px rgba(0, 0, 0, .5);
  opacity: 0;
  transition: opacity .18s ease;
}
.stars-ch-av .stars-ch-photo.is-loaded { opacity: 1; }
.stars-ch-av.has-photo .stars-ch-t { opacity: 0; }
html.reduced-motion .stars-ch-photo { transition: none; }

/* ---- the Top-3 podium: three clay channel cards, the champion raised with the
       one gold rim. This band is the card's only flexible block, so it holds the
       celebration while the runners, the squad row and the CTA stay pinned. ---- */
.stars-podium {
  flex: 1 0 auto;
  min-width: 0;
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: end;                    /* the champion's extra height grows upward */
  align-content: end;                  /* the podium sits ON the runners — no void between */
  gap: 6px;
}
.stars-pod {
  position: relative;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 8px 5px 7px;
  border-radius: 16px;
  background: var(--clay-face);
  background-color: #1C2433;
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel);
  text-align: center;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: transform var(--motion-fast), box-shadow var(--motion-fast);
}
.stars-pod:active { transform: translateY(2px); }
.stars-pod:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
/* the champion stands ~24px taller, wears the screen's one gold rim, and is
   crowned by the board's only glyph — set into its own raised headroom, so the
   silver and bronze pedestals keep their breathing room */
.stars-pod[data-rank="1"] {
  padding-top: 21px;
  padding-bottom: 18px;
  box-shadow:
    var(--clay-drop), var(--clay-spec), var(--clay-bevel),
    inset 0 0 0 1.5px rgba(252, 211, 77, .5);
}
.stars-pod-crown {
  position: absolute;
  top: 4px;
  left: 50%;
  transform: translateX(-50%);
  width: 13px;
  height: 13px;
  color: #FCD34D;
  opacity: .95;
  filter: drop-shadow(0 1px 3px rgba(2, 6, 16, .7)) drop-shadow(0 0 7px rgba(245, 158, 11, .5));
  pointer-events: none;
}
/* podium order: silver on the left, the champion raised in the centre, bronze right */
.stars-pod[data-rank="2"] { order: 1; }
.stars-pod[data-rank="1"] { order: 2; }
.stars-pod[data-rank="3"] { order: 3; }
.stars-pod-rank {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: linear-gradient(180deg, #2A354C 0%, #161E2D 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .12), inset 0 0 0 1px rgba(255, 255, 255, .08), 0 2px 0 #080C14;
  color: var(--ink);
  font-size: 11.5px;
  font-weight: 900;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 1px 0 #05070C;
}
.stars-pod[data-metal="gold"] .stars-pod-rank {
  background: linear-gradient(180deg, #FDE68A 0%, #F59E0B 62%, #B45309 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .55), 0 2px 0 var(--gold-lip);
  color: #3B2405;
}
.stars-pod[data-metal="silver"] .stars-pod-rank {
  background: linear-gradient(180deg, #F1F5F9 0%, #94A3B8 62%, #475569 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .6), 0 2px 0 #334155;
  color: #16202E;
}
.stars-pod[data-metal="bronze"] .stars-pod-rank {
  background: linear-gradient(180deg, #FDBA74 0%, #EA580C 62%, #7C2D12 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .4), 0 2px 0 #7C2D12;
  color: #2A1005;
}
.stars-pod[data-metal="gold"] .stars-ch-av {
  background:
    radial-gradient(52% 44% at 30% 22%, rgba(255, 255, 255, .55), rgba(255, 255, 255, 0) 72%),
    linear-gradient(180deg, #FDE9A9 0%, #D97706 58%, #7C3A0B 100%);
  color: #432004;
}
.stars-pod[data-metal="silver"] .stars-ch-av {
  background:
    radial-gradient(52% 44% at 30% 22%, rgba(255, 255, 255, .6), rgba(255, 255, 255, 0) 72%),
    linear-gradient(180deg, #F8FAFC 0%, #94A3B8 58%, #334155 100%);
  color: #0F172A;
}
.stars-pod[data-metal="bronze"] .stars-ch-av {
  background:
    radial-gradient(52% 44% at 30% 22%, rgba(255, 255, 255, .45), rgba(255, 255, 255, 0) 72%),
    linear-gradient(180deg, #FED7AA 0%, #C2410C 58%, #5C1B08 100%);
  color: #FFF7ED;
}
.stars-pod-name {
  width: 100%;
  min-width: 0;
  max-width: 100%;
  font-size: var(--t-3);
  font-weight: 800;
  letter-spacing: -.02em;
  line-height: 1.18;
  color: var(--ink);
  text-align: center;
  /* a mixed Persian/English handle is one isolated paragraph that wraps to a second
     line before it is ever cut with an ellipsis */
  unicode-bidi: isolate;
  overflow-wrap: anywhere;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
}
.stars-pod[data-rank="1"] .stars-pod-name { color: #FEF3C7; }
.stars-pod-tiq {
  max-width: 100%;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .01em;
  line-height: 1.2;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.stars-pod-tiq b { color: var(--honey-ink); font-weight: 900; }
/* the Stars: on the channels board only the champion wears one, because only the
   #1 channel's Top 10 are paid; on the players board every place carries its own
   share of that same ladder. */
.stars-pod-prize {
  margin-top: 1px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 3px 8px 4px;
  border-radius: var(--radius-pill);
  /* translucent slate over a soft amber specular rim — no black box cutout */
  background: linear-gradient(180deg, rgba(42, 53, 76, .9) 0%, rgba(26, 35, 51, .9) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 -2px 3px rgba(0, 0, 0, .34),
    inset 0 0 0 1px rgba(245, 158, 11, .3),
    0 2px 0 #0B111C;
  color: #FDE68A;
  font-size: 10.5px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  text-shadow: 0 1px 0 #05070C;
}
.stars-pod-prize small { font-size: 8.5px; font-weight: 800; letter-spacing: .04em; opacity: .85; }
.stars-pod-star { flex: none; width: 15px; height: 15px; }
/* the players board: a person wears a lit ball with their nation on the corner,
   not a channel squircle. Same three metals, painted through the sphere's own
   custom properties. */
.stars-pod .stars-av { width: 38px; height: 38px; font-size: 13px; }
.stars-pod[data-metal="gold"] .stars-av {
  --av-hi: #FDE9A9; --av-mid: #D97706; --av-lo: #7C3A0B; --av-ink: #432004;
}
.stars-pod[data-metal="silver"] .stars-av {
  --av-hi: #F8FAFC; --av-mid: #94A3B8; --av-lo: #334155; --av-ink: #0F172A;
}
.stars-pod[data-metal="bronze"] .stars-av {
  --av-hi: #FED7AA; --av-mid: #C2410C; --av-lo: #5C1B08; --av-ink: #FFF7ED;
}
/* ---- empty rungs on the Cup podium: the stage stays whole while the field fills ----
   One squad is a normal championship, not a broken podium. The missing places hold
   frosted, dashed slots — muted squircle, dashed ring, lock glyph and a quiet label —
   so the champion sits inside a complete three-tier structure instead of floating. */
.stars-pod.is-awaiting {
  cursor: default;
  background:
    linear-gradient(180deg, rgba(148, 163, 184, .07) 0%, rgba(148, 163, 184, 0) 72%),
    rgba(20, 26, 38, .55);
  box-shadow:
    inset 0 0 0 1.5px rgba(148, 163, 184, .22),
    0 2px 0 #080C14;
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
}
.stars-pod.is-awaiting:active { transform: none; }
.stars-pod.is-awaiting .stars-pod-name { color: #7C8AA3; }
.stars-pod.is-awaiting .stars-pod-rank {
  background: linear-gradient(180deg, #232C3C 0%, #141A26 100%);
  box-shadow: inset 0 0 0 1px rgba(148, 163, 184, .18), 0 2px 0 #080C14;
  color: #6B7A93;
}
.stars-ch-av-awaiting {
  background: radial-gradient(circle at 32% 26%, rgba(148, 163, 184, .12) 0%, rgba(11, 16, 28, .9) 72%);
  box-shadow: inset 0 0 0 1.5px rgba(148, 163, 184, .3), 0 2px 0 #080C14;
  color: rgba(148, 163, 184, .82);
}
.stars-ch-av-awaiting::before {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 17px;
  border: 1px dashed rgba(148, 163, 184, .36);
  pointer-events: none;
}
.stars-awaiting-ico {
  width: 16px;
  height: 16px;
  opacity: .8;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, .5));
}
.stars-pod-name-awaiting {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .04em;
  line-height: 1.25;
  color: #7C8AA3;
  text-shadow: none;
}

/* ---- the runners: places four and five, each row a chevron-cued door ---- */
.stars-runners {
  flex: none;
  min-width: 0;
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.stars-run {
  flex: none;
  min-width: 0;
  min-height: 48px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 6px 10px 6px 9px;
  border-radius: 16px;
  background:
    radial-gradient(120% 140% at 0% 0%, rgba(252, 211, 77, .05), rgba(252, 211, 77, 0) 60%),
    var(--clay-face);
  background-color: #1C2433;
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: transform var(--motion-fast);
}
.stars-run:active { transform: translateY(2px); }
.stars-run:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
/* The board with no squads on it: one quiet row, never an empty slab. */
.stars-run.is-empty {
  justify-content: center;
  cursor: default;
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair);
  color: var(--ink-soft);
  font-size: 11px;
  font-weight: 700;
  text-align: center;
}
.stars-run.is-empty:active { transform: none; }
/* the place is a medal circle, never a #hashtag */
.stars-run-rank {
  flex: none;
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: linear-gradient(180deg, #2A354C 0%, #161E2D 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .12), inset 0 0 0 1px rgba(255, 255, 255, .08), 0 2px 0 #080C14;
  color: var(--ink);
  font-size: 12.5px;
  font-weight: 900;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 1px 0 #05070C;
}
.stars-ch-sm { width: 30px; height: 30px; border-radius: 11px; }
.stars-ch-sm .stars-ch-t { font-size: 12px; }
.stars-run-id { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.stars-run-nm {
  min-width: 0;
  unicode-bidi: isolate;
  font-size: var(--t-2);
  font-weight: 800;
  letter-spacing: -.02em;
  line-height: 1.2;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 1px 0 #05070C;
}
/* the players board's runner mark: the same ball, shrunk to the row's squircle */
.stars-run .stars-av { width: 30px; height: 30px; font-size: 11px; }
.stars-run .stars-av-flag { inset-inline-end: -3px; inset-block-end: -3px; }
.stars-run .stars-av-flag .fp { --fp-d: 15px; }
.stars-run .stars-av-flag .fp-img { box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .35), 0 0 0 2px #1C2433; }
/* the score rides a warm gold pill, not a bare muted run of digits */
.stars-run-tiq {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 4px 10px 5px;
  border-radius: var(--radius-pill);
  background: linear-gradient(180deg, rgba(252, 211, 77, .16) 0%, rgba(245, 158, 11, .1) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 0 0 1px rgba(245, 158, 11, .34),
    0 2px 0 #0B111C;
  color: #FDE68A;
  font-size: 10.5px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  text-shadow: 0 1px 0 #05070C;
}
.stars-run-tiq b { color: #FDE68A; font-weight: 900; }
/* a runner's own share of the pool, on the players board: the same warm pill,
   carried by the Star instead of the score */
.stars-run-pay {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 4px 8px 5px;
  border-radius: var(--radius-pill);
  background: linear-gradient(180deg, rgba(252, 211, 77, .2) 0%, rgba(245, 158, 11, .12) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 0 0 1px rgba(245, 158, 11, .4),
    0 2px 0 #0B111C;
  color: #FDE68A;
  font-size: 10.5px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  text-shadow: 0 1px 0 #05070C;
}
.stars-run-star { flex: none; width: 13px; height: 13px; }
/* a player is a place on the ladder, not a door: on the players board the cards
   keep their shape but stop pretending a tap opens something. */
.stars-card[data-view="players"] .stars-pod,
.stars-card[data-view="players"] .stars-run {
  cursor: default;
  -webkit-tap-highlight-color: transparent;
}
.stars-card[data-view="players"] .stars-pod:active,
.stars-card[data-view="players"] .stars-run:active { transform: none; }
/* the band's loading state keeps the real card shapes so the switch never jumps */
.stars-pod.is-skel, .stars-run.is-skel { cursor: default; justify-content: center; }
.stars-run.is-skel { min-height: 48px; }
.stars-pod.is-skel { min-height: 120px; }
.stars-pod.is-skel .skel, .stars-run.is-skel .skel { width: 60%; height: 12px; }
.stars-run-go, .stars-squad-go {
  flex: none;
  width: 15px;
  height: 15px;
  color: var(--ink-soft);
  opacity: .8;
}

/* ---- the pinned squad row: the channel you ride for, and where you sit in it ---- */
.stars-squad {
  flex: none;
  width: 100%;
  min-width: 0;
  min-height: 52px;
  appearance: none;
  border: 0;
  font: inherit;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 6px 11px 6px 9px;
  border-radius: 16px;
  /* the hero card of the field: a full golden clay rim, never a flat black slab */
  background:
    radial-gradient(120% 140% at 0% 0%, rgba(252, 211, 77, .16), rgba(252, 211, 77, 0) 62%),
    linear-gradient(180deg, #2A3651 0%, #1A2333 100%);
  box-shadow:
    var(--clay-drop), var(--clay-spec), var(--clay-bevel),
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 0 0 1.5px rgba(252, 211, 77, .5),
    0 0 22px -10px rgba(252, 211, 77, .5);
  transition: transform var(--motion-fast);
}
.stars-squad:active { transform: translateY(2px); }
.stars-squad:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 3px; }
.stars-squad-chip {
  flex: none;
  display: grid;
  place-items: center;
  padding: 5px 8px 6px;
  border-radius: var(--radius-pill);
  background: linear-gradient(180deg, #FDE68A 0%, #F59E0B 62%, #B45309 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .55), 0 2px 0 var(--gold-lip);
  color: #3B2405;
  font-size: 9.5px;
  font-weight: 900;
  letter-spacing: .05em;
  line-height: 1;
  white-space: nowrap;
}
.stars-squad-av { width: 34px; height: 34px; border-radius: 12px; }
.stars-squad-av .stars-ch-t { font-size: 13px; }
.stars-squad-txt { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.stars-squad-name {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: var(--t-2);
  font-weight: 900;
  letter-spacing: -.02em;
  line-height: 1.2;
  color: #FDE68A;
  font-variant-numeric: tabular-nums;
  unicode-bidi: isolate;
  text-shadow: 0 1px 0 #05070C;
}
/* the handle wraps to a second line under its own isolation, so a long bilingual
   squad name is never clipped to "Computer_Scien…" */
.stars-squad-handle {
  flex: 1 1 auto;
  min-width: 0;
  white-space: normal;
  unicode-bidi: isolate;
  overflow-wrap: anywhere;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
}
/* the squad's cup rank: a quiet slate pill beside the gold handle, so the two
   facts never run together in one ellipsised string */
.stars-squad-pos {
  flex: none;
  display: inline-flex;
  align-items: center;
  padding: 2px 6px 2.5px;
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, .07);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .1), inset 0 0 0 1px rgba(255, 255, 255, .07);
  color: var(--ink-soft);
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .04em;
  line-height: 1;
  text-shadow: none;
}
.stars-squad-note {
  min-width: 0;
  font-size: 9.5px;
  font-weight: 700;
  line-height: 1.25;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.stars-squad-note b { color: var(--honey-ink); font-weight: 900; }
/* the note runs prose, digits and metal on one baseline, so the Star stays inline */
.stars-squad-star { display: inline-block; width: 11px; height: 11px; vertical-align: -1px; }
.stars-squad.is-unbound .stars-squad-name { color: var(--ink); }
.stars-squad.is-unbound .stars-squad-chip {
  background: linear-gradient(180deg, #3B4B6B 0%, #232E44 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .14), 0 2px 0 #080C14;
  color: var(--ink-soft);
}

/* ---- the one loud key: 50px extruded clay, amber face on a dark lip ---- */
.stars-cta {
  --d: 5px;
  flex: none;
  width: 100%;
  min-height: 50px;
  appearance: none;
  border: 0;
  font: inherit;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 var(--s3);
  border-radius: 18px;
  background: linear-gradient(180deg, #FDE68A 0%, #FBBF24 46%, #D97706 100%);
  color: #3B2405;
  font-size: var(--t-2);
  font-weight: 900;
  letter-spacing: .04em;
  text-transform: uppercase;
  white-space: nowrap;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .6),
    inset 0 -2px 3px rgba(0, 0, 0, .26),
    inset 0 0 0 1px rgba(255, 255, 255, .22),
    0 var(--d) 0 var(--gold-lip),
    0 14px 26px -12px rgba(245, 158, 11, .62);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast);
}
.stars-cta .ico { width: 17px; height: 17px; }
.stars-cta:active { --d: 3px; transform: translateY(2px); }
.stars-cta:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 3px; }

/* ---- shorter and narrower phones: the card gives before the CTA does ----
   The four in-card gaps and the crown padding are where the bigger header is paid for:
   the championship lockup costs the head 13px more than the old one-line band, and the
   card's own rhythm hands exactly that back, so the CTA stays on the dock line. */
@media (max-height: 700px) {
  .stars-card { gap: clamp(6px, 1vh, 11px); padding-top: 8px; }
  .stars-pod { padding: 7px 5px 6px; gap: 3px; }
  .stars-pod[data-rank="1"] { padding-top: 19px; padding-bottom: 16px; }
}
@media (max-height: 620px) {
  .stars-pod .stars-ch-av, .stars-pod .stars-av { width: 34px; height: 34px; }
  .stars-pod-name { font-size: 11px; }
  .stars-pod-tiq { font-size: 9.5px; }
  .stars-pod-star { width: 14px; height: 14px; }
  /* the face drops to 44px here, so the band grows to keep the 48px target —
     2px each side fits inside the runners' own 4px gap */
  .stars-run { min-height: 44px; position: relative; }
  .stars-run::after { content: ""; position: absolute; inset: -2px 0; }
  .stars-runners { gap: 4px; }
}
/* the shortest phones: every fixed row gives a little, because the band cannot.
   The champion keeps the tallest pillar on the card but spends the one the
   runners and the key just took back. */
@media (max-height: 600px) {
  /* the 320s pay for the bigger lockup out of the card's own rhythm: everything that
     does not carry information gives back the 6px the taller header took */
  .stars-card { gap: 4px; padding-top: 5px; }
  /* the two header bands sit closer instead of the deck losing key height */
  .stars-head { gap: 3px; }
  .stars-emblem { width: 26px; height: 26px; }
  .stars-info { width: 22px; height: 22px; font-size: 12px; }
  .stars-name { font-size: 18px; }
  .stars-strip { height: 32px; }
  .stars-key { font-size: 9px; gap: 3px; }
  .stars-key-ico { width: 12px; height: 12px; }
  /* the face is 24px inside the 32px deck here, so the band carries 24px of it */
  .stars-key::after { inset: -12px 0; }
  .stars-count { font-size: 12px; padding-right: 5px; }
  .stars-count > i { font-size: 12px; }
  .stars-pod { padding: 6px 4px 5px; }
  .stars-pod[data-rank="1"] { padding-top: 13px; padding-bottom: 11px; }
  .stars-pod-prize { font-size: 10px; padding: 3px 6px 4px; }
  .stars-squad { min-height: 48px; }
  .stars-cta { min-height: 48px; }
}
/* short and narrow (320x568): the copy stays whole, the type steps down instead */
@media (max-width: 352px) {
  .stars-emblem { width: 26px; height: 26px; }
  .stars-info { width: 22px; height: 22px; font-size: 11.5px; }
  .stars-name { font-size: 18px; }
  .stars-strip { height: 32px; }
  .stars-key { font-size: 8.5px; letter-spacing: .055em; gap: 3px; }
  .stars-key-ico { width: 11px; height: 11px; }
  /* the face is 24px inside the 32px deck here, so the band carries 24px of it */
  .stars-key::after { inset: -12px 0; }
  .stars-pod { padding: 6px 4px 5px; }
  .stars-pod-tiq { font-size: 9px; }
  .stars-pod-prize { font-size: 10px; padding: 3px 6px 4px; }
  .stars-pod-star { width: 13px; height: 13px; }
  .stars-run-nm { font-size: 11px; }
  .stars-run-tiq { font-size: 9px; }
  .stars-run-pay { font-size: 9px; padding: 4px 6px 5px; }
  .stars-squad-chip { font-size: 8.5px; padding: 5px 6px 6px; }
  .stars-cta { letter-spacing: .02em; }
  /* the clock keeps its bead and its three registers, and pays for the deck's width in
     type: smaller numerals, tighter seam, and the switch beside it still reads */
  .stars-count { font-size: 11px; padding-right: 4px; }
  .stars-count > i { font-size: 11px; }
  .stars-count::before { width: 4px; height: 4px; margin-right: 4px; }
}
/* a tall phone: the celebration scales up rather than leaving slack above the key */
@media (min-height: 780px) {
  .stars-card { gap: 12px; padding: 18px 18px; border-radius: 24px; }
  .stars-name { font-size: 26px; }
  .stars-strip { height: 40px; }
  .stars-key { font-size: 11px; gap: 5px; }
  .stars-key-ico { width: 15px; height: 15px; }
  /* the face is 32px inside the 40px deck; 8px each side keeps the 48px target */
  .stars-key::after { inset: -8px 0; }
  .stars-count { font-size: 16px; }
  .stars-count > i { font-size: 16px; }
  .stars-pod { padding: 11px 8px 10px; gap: 4px; }
  .stars-pod[data-rank="1"] { padding-top: 25px; padding-bottom: 22px; }
  .stars-pod .stars-ch-av, .stars-pod .stars-av { width: 42px; height: 42px; }
  .stars-pod-star { width: 17px; height: 17px; }
  .stars-run { min-height: 52px; }
  .stars-cta { min-height: 56px; border-radius: 20px; font-size: var(--t-1); }
}
html.reduced-motion .stars-cta, html.reduced-motion .stars-pod, html.reduced-motion .stars-run, html.reduced-motion .stars-squad { transition: none; }
html.reduced-motion .stars-thumb { transition: none; }
html.reduced-motion .stars-count::before { animation: none; }

/* ==========================================================================
   THE CUP RULES SHEET — the three steps between a win and the Stars, opened by
   the round help key in the Cup header. Same dark-clay recipe as the roster:
   an opaque slate panel, engraved medallions, depth from inner shadow only
   (the shared .scrim behind it carries the app's one backdrop blur).
   ========================================================================== */
.rules-sheet {
  border-radius: 24px 24px 0 0;
  max-height: 85vh;
  max-height: 85dvh;
  gap: var(--s3);
  background: linear-gradient(180deg, #232E44 0%, #1C2433 46%);
  background-color: #1C2433;
  box-shadow:
    inset 0 1px 0 var(--hair-lit),
    inset 0 0 0 1px rgba(255, 255, 255, .06),
    0 -20px 44px -20px var(--shadow);
}
.rules-head { flex: none; display: flex; align-items: center; gap: var(--s2); min-width: 0; }
.rules-title { flex: 1 1 auto; min-width: 0; margin: 0; }
.rules-steps { list-style: none; margin: 0; padding: 0 2px 0 0; gap: 8px; }
.rules-step {
  flex: none;
  min-width: 0;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 16px;
  background:
    radial-gradient(120% 140% at 0% 0%, rgba(252, 211, 77, .06), rgba(252, 211, 77, 0) 62%),
    var(--clay-face);
  background-color: #1C2433;
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring);
}
.rules-num {
  flex: none;
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 10px;
  background: linear-gradient(180deg, #2E3A55 0%, #1A2333 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 -2px 3px rgba(0, 0, 0, .4),
    inset 0 0 0 1px rgba(252, 211, 77, .24);
  color: var(--honey-ink);
  font-size: 12px;
  font-weight: 900;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 1px 0 #05070C;
}
.rules-txt { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.rules-txt b { font-size: var(--t-2); font-weight: 900; letter-spacing: -.01em; color: var(--ink); }
.rules-txt small { font-size: var(--t-3); font-weight: 600; line-height: 1.42; color: var(--ink-soft); }
.rules-got { flex: none; margin-top: 2px; }

/* ==========================================================================
   CHANNEL ROSTER SHEET — the Top 10 behind one channel, and the Stars each of
   them projects to. Same dark-clay recipe as the mind sheet: an opaque slate
   panel, extruded keys, depth from inner shadow only. No backdrop-filter and no
   blur() anywhere in this block.
   ========================================================================== */

/* ---- the player sphere: inside a roster the entries are people again, so they
       wear a lit ball with their nation on the corner, not a channel squircle. ---- */
.stars-av {
  position: relative;
  flex: none;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background:
    radial-gradient(52% 46% at 32% 24%, rgba(255, 255, 255, .6), rgba(255, 255, 255, 0) 72%),
    radial-gradient(120% 120% at 30% 22%, var(--av-hi, #4E6285) 0%, var(--av-mid, #2A354C) 48%, var(--av-lo, #131A29) 100%);
  box-shadow:
    inset 0 -3px 5px rgba(0, 0, 0, .55),
    inset 0 1px 0 rgba(255, 255, 255, .2),
    0 2px 0 #080C14;
  color: var(--av-ink, #DBEAFE);
  font-size: 12.5px;
  font-weight: 900;
  letter-spacing: -.02em;
  line-height: 1;
}
.stars-av-t { display: block; }
/* the player's real Telegram portrait: a circular crop inside the metal ball, ringed by a
   hairline of metal. It fades in over the monogram and removes itself on an error or a hidden
   profile, so the initials are only ever the transient fallback — never the final face. */
.stars-av .stars-av-photo {
  position: absolute;
  inset: 3px;
  z-index: 1;
  width: calc(100% - 6px);
  height: calc(100% - 6px);
  border-radius: 50%;
  object-fit: cover;
  object-position: center;
  /* circle crop is explicit as well as rounded: a JPEG's square corners never
     leave a fringe against the metal ring */
  clip-path: circle(50%);
  background: #0B1220;
  box-shadow:
    0 0 0 1px rgba(226, 232, 240, .42),
    0 0 0 2px rgba(4, 8, 16, .55),
    0 2px 5px rgba(0, 0, 0, .5);
  opacity: 0;
  transition: opacity .18s ease;
}
.stars-av .stars-av-photo.is-loaded { opacity: 1; }
.stars-av.has-photo .stars-av-t { opacity: 0; }
html.reduced-motion .stars-av-photo { transition: none; }
.stars-av-flag {
  position: absolute;
  inset-inline-end: -4px;
  inset-block-end: -4px;
  /* the nation pin rides above the portrait, never under it */
  z-index: 2;
  display: inline-flex;
}
.stars-av-flag .fp { --fp-d: 16px; }
.stars-av-flag .fp-chip { border-radius: 50%; font-size: 7px; letter-spacing: 0; }
.stars-av-flag .fp-img { border-radius: 50%; box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .35), 0 0 0 2px #141B2A; }
/* an empty place on the players board: the same frosted slot as the channels board, cut as a
   ball so both tabs read as one stage with the same gap in it. */
.stars-av-awaiting {
  background: radial-gradient(circle at 32% 26%, rgba(148, 163, 184, .12) 0%, rgba(11, 16, 28, .9) 72%);
  box-shadow: inset 0 0 0 1.5px rgba(148, 163, 184, .3), 0 2px 0 #080C14;
  color: rgba(148, 163, 184, .82);
}
.stars-av-awaiting::before {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px dashed rgba(148, 163, 184, .36);
  pointer-events: none;
}

.roster-sheet {
  border-radius: 24px 24px 0 0;
  max-height: 85vh;
  max-height: 85dvh;
  gap: var(--s2);
  background: linear-gradient(180deg, #232E44 0%, #1C2433 46%);
  background-color: #1C2433;
  box-shadow:
    inset 0 1px 0 var(--hair-lit),
    inset 0 0 0 1px rgba(255, 255, 255, .06),
    0 -20px 44px -20px var(--shadow);
}
.roster-sheet[data-metal="gold"]   { --sr-aura: #F59E0B; }
.roster-sheet[data-metal="silver"] { --sr-aura: #94A3B8; }
.roster-sheet[data-metal="bronze"] { --sr-aura: #C2410C; }

.sr-head { flex: none; display: flex; align-items: center; gap: var(--s2); min-width: 0; }
.sr-marks { position: relative; flex: none; width: 50px; height: 50px; }
.sr-marks .stars-ch-av {
  position: absolute;
  inset: 0;
  width: auto;
  height: auto;
  border-radius: 16px;
  box-shadow:
    inset 0 0 0 2px var(--sr-aura, var(--brand-2)),
    inset 0 1px 0 rgba(255, 255, 255, .16),
    0 3px 0 #0A0F1A;
}
.sr-marks .stars-ch-t { font-size: 20px; }
/* the cup place rides the icon's top-left, where a badge belongs on a crest.
   It wears the channel's own metal, so a runner's sheet never opens in gold. */
.sr-rank {
  position: absolute;
  left: -6px;
  top: -6px;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: linear-gradient(180deg, #2A354C 0%, #161E2D 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .12),
    inset 0 0 0 1px rgba(255, 255, 255, .08),
    0 2px 0 #080C14, 0 0 0 2px #1C2433;
  color: var(--ink);
  font-size: 11.5px;
  font-weight: 900;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 1px 0 #05070C;
}
.roster-sheet[data-metal="gold"] .sr-rank {
  background: linear-gradient(180deg, #FDE68A 0%, #F59E0B 62%, #B45309 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .55), 0 2px 0 var(--gold-lip), 0 0 0 2px #1C2433;
  color: #3B2405;
  text-shadow: 0 1px 0 rgba(255, 255, 255, .3);
}
.roster-sheet[data-metal="silver"] .sr-rank {
  background: linear-gradient(180deg, #F1F5F9 0%, #94A3B8 62%, #475569 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .6), 0 2px 0 #334155, 0 0 0 2px #1C2433;
  color: #16202E;
}
.roster-sheet[data-metal="bronze"] .sr-rank {
  background: linear-gradient(180deg, #FDBA74 0%, #EA580C 62%, #7C2D12 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .4), 0 2px 0 #7C2D12, 0 0 0 2px #1C2433;
  color: #2A1005;
}
.sr-id { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.sr-name {
  font-size: var(--t-1);
  font-weight: 900;
  letter-spacing: -.02em;
  line-height: 1.2;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.sr-sub {
  font-size: 10px;
  font-weight: 800;
  line-height: 1.3;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.sr-sub b { color: var(--honey-ink); font-weight: 900; }

/* the rule restated where it matters: inside the channel that can win it */
.sr-notice {
  flex: none;
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  padding: 8px 10px;
  border-radius: 13px;
  background: linear-gradient(180deg, rgba(252, 211, 77, .14) 0%, rgba(245, 158, 11, .07) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 -2px 3px rgba(0, 0, 0, .3),
    inset 0 0 0 1px rgba(245, 158, 11, .34);
  color: #FDE68A;
  font-size: 10px;
  font-weight: 900;
  line-height: 1.3;
  text-shadow: 0 1px 0 #05070C;
}
.sr-notice-star { flex: none; width: 16px; height: 16px; }

.sr-list { flex: 1 1 auto; min-height: 0; list-style: none; margin: 0; padding: 0 2px 0 0; gap: 5px; }
.sr-skel { display: flex; flex-direction: column; gap: 5px; }
/* A roster with nobody on it yet — one quiet row, matching the board's own empty state. */
.sr-empty {
  min-height: 44px;
  display: grid;
  place-items: center;
  padding: 12px;
  border-radius: 14px;
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair);
  text-align: center;
  font-size: 11px;
  font-weight: 700;
  color: var(--ink-soft);
}
.sr-row {
  flex: none;
  min-width: 0;
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 9px 5px 6px;
  border-radius: 14px;
  background: var(--clay-face);
  background-color: #1C2433;
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel);
}
/* the medal is a sphere again — inside a roster these are people, not channels */
.sr-medal {
  flex: none;
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: linear-gradient(180deg, #2A354C 0%, #161E2D 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .12), inset 0 0 0 1px rgba(255, 255, 255, .08), 0 2px 0 #080C14;
  color: var(--ink);
  font-size: 11.5px;
  font-weight: 900;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 1px 0 #05070C;
}
.sr-row[data-metal="gold"] .sr-medal {
  background: linear-gradient(180deg, #FDE68A 0%, #F59E0B 62%, #B45309 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .55), 0 2px 0 var(--gold-lip);
  color: #3B2405;
}
.sr-row[data-metal="silver"] .sr-medal {
  background: linear-gradient(180deg, #F1F5F9 0%, #94A3B8 62%, #475569 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .6), 0 2px 0 #334155;
  color: #16202E;
}
.sr-row[data-metal="bronze"] .sr-medal {
  background: linear-gradient(180deg, #FDBA74 0%, #EA580C 62%, #7C2D12 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .4), 0 2px 0 #7C2D12;
  color: #2A1005;
}
.sr-row .stars-av { width: 30px; height: 30px; font-size: 11px; }
.sr-row .stars-av-flag { inset-inline-end: -3px; inset-block-end: -3px; }
.sr-row .stars-av-flag .fp { --fp-d: 15px; }
.sr-row .stars-av-flag .fp-chip { border-radius: 50%; font-size: 7px; letter-spacing: 0; }
.sr-row .stars-av-flag .fp-img { border-radius: 50%; box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .35), 0 0 0 2px #1C2433; }
.sr-id-col { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.sr-nm {
  min-width: 0;
  font-size: var(--t-3);
  font-weight: 800;
  letter-spacing: -.01em;
  line-height: 1.2;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 1px 0 #05070C;
}
.sr-tiq {
  min-width: 0;
  font-size: 9px;
  font-weight: 700;
  line-height: 1.2;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.sr-tiq b { color: var(--honey-ink); font-weight: 900; }
.sr-pay {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  min-width: 52px;
  justify-content: center;
  padding: 4px 8px 5px;
  border-radius: var(--radius-pill);
  background: linear-gradient(180deg, rgba(252, 211, 77, .16) 0%, rgba(245, 158, 11, .1) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 0 0 1px rgba(245, 158, 11, .34),
    0 2px 0 #0B111C;
  color: #FDE68A;
  font-size: 10.5px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  text-shadow: 0 1px 0 #05070C;
}
.sr-pay-star { flex: none; width: 14px; height: 14px; }
/* a place the 200-Star pool does not reach pays nothing, and says so in slate */
.sr-row.is-outside .sr-pay {
  background: var(--field);
  box-shadow: inset 0 0 0 1px var(--hair-off), 0 2px 0 #0B111C;
  color: var(--ink-soft);
}
/* the local player's own row, marked the same way the squad row on the card is */
.sr-row.is-you {
  background:
    radial-gradient(120% 140% at 0% 0%, rgba(252, 211, 77, .16), rgba(252, 211, 77, 0) 62%),
    linear-gradient(180deg, #2A3651 0%, #1A2333 100%);
  box-shadow:
    var(--clay-drop), var(--clay-spec), var(--clay-bevel),
    inset 0 0 0 1.5px rgba(252, 211, 77, .5);
}
.sr-you-tag {
  flex: none;
  padding: 3px 6px 4px;
  border-radius: var(--radius-pill);
  background: linear-gradient(180deg, #FDE68A 0%, #F59E0B 62%, #B45309 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .55), 0 2px 0 var(--gold-lip);
  color: #3B2405;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .06em;
  line-height: 1;
}
.sr-fine { flex: none; margin: 0; text-align: left; font-size: 10px; line-height: 1.4; }


/* ==========================================================================
   GAME MODE SELECTOR — bottom sheet triggered by the lobby Change key.
   Three large rows (Quick match / Play with friends / Practice vs Bot), the
   room UI on its own sub-screen, one reward caption and one sticky Start.
   Canvas #10141D, surface Dark Clay #1C2433, 24px top corners, ink #F8FAFC.
   Motion stays on transform/opacity so every press runs at 60fps.
   ========================================================================== */

/* ---- surface: Dark Clay #1C2433, 24px top corners, 85dvh, safe-area aware ----
   The frosted layer is the scrim's (its 4px blur sits behind this panel), so the
   panel itself stays live-blur-free: one dark fill + a white/10 rim + a cyan kiss. */
#sheet-game-modes,
.gm-sheet {
  border-radius: 24px 24px 0 0;
  /* the drawer never grows past 85dvh; .sheet's padding already carries the
     safe-area insets, so the content sits above the home indicator */
  max-height: 85vh;
  max-height: 85dvh;
  /* one spacing unit for the whole drawer (the 12px "gap-3" step) */
  --gm-gap: 12px;
  /* no grip handle up here: the header can sit closer to the top edge */
  padding-top: var(--s4);
  background: #1C2433;
  background-color: #1C2433;
  box-shadow:
    inset 0 1px 0 var(--hair-lit),
    inset 0 0 0 1px rgba(255, 255, 255, .10),
    0 -20px 44px -20px var(--shadow),
    0 0 24px -8px rgba(56, 189, 248, .12);
}
/* entry transition lives on .sheet (transform var(--motion-med)); this keeps it explicit */
#sheet-game-modes { transition: transform var(--motion-med); }

/* ---- header: title, one back key for the sub-screen, one close key ---- */
.gm-head {
  flex: none;
  display: flex;
  align-items: center;
  gap: var(--gm-gap);
}
.gm-head-txt { flex: 1 1 auto; min-width: 0; }
/* two reading levels: a hard title, a soft one-line instruction under it */
.gm-title.sheet-t {
  margin: 0;
  text-align: left;
  font-size: var(--t-1);
  font-weight: 800;
  letter-spacing: -.01em;
  line-height: 1.2;
  color: var(--ink);
}
.gm-sub {
  margin: 3px 0 0;
  font-size: var(--t-micro);
  font-weight: 700;
  letter-spacing: .01em;
  line-height: 1.3;
  color: var(--ink-soft);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* 44px clay keys: the back arrow only exists on the friends sub-screen */
.gm-key {
  --d: 3px;
  appearance: none;
  border: 0;
  flex: none;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  padding: 0;
  border-radius: 50%;
  background: linear-gradient(180deg, #2E3A55 0%, #232E44 100%);
  color: var(--ink);
  font-size: 20px;
  font-weight: 800;
  line-height: 1;
  cursor: pointer;
  box-shadow:
    0 var(--d) 0 #080C14,
    inset 0 1px 0 rgba(255, 255, 255, .14),
    var(--clay-ring);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast), color var(--motion-fast);
}
.gm-key .ico { width: 20px; height: 20px; }
.gm-key:hover:not(:active) { transform: translateY(-1px); }
.gm-key:active { transform: translateY(2px); --d: 0px; }
.gm-key:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
/* the dismiss key reads as a lit ring on hover, then sinks into the clay on press */
.gm-key.gm-x { font-size: 26px; font-weight: 600; }
.gm-key.gm-x:hover:not(:active) {
  color: var(--brand-ink);
  box-shadow:
    0 var(--d) 0 #080C14,
    inset 0 1px 0 rgba(255, 255, 255, .16),
    inset 0 0 0 1px rgba(56, 189, 248, .45),
    0 0 16px -6px rgba(56, 189, 248, .9);
}

/* ---- body: the one region that may scroll, chrome-free and header-free ---- */
.gm-body {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: var(--gm-gap);
  overflow-y: auto;
  overscroll-behavior: contain;
  touch-action: pan-y;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 2px 2px 4px;
  margin: 0 -2px;
}
.gm-body::-webkit-scrollbar { display: none; width: 0; height: 0; }
.gm-view { flex: none; display: flex; flex-direction: column; gap: var(--gm-gap); }
/* an author `display: flex` outranks the UA `[hidden]` rule, so every pane has to say it itself */
.gm-view[hidden] { display: none; }
.gm-list { display: flex; flex-direction: column; gap: var(--gm-gap); }

/* ---- mode rows: one glass card, a 76px pick, and the option strip inside ---- */
.gm-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--gm-gap);
  padding: 6px;
  border: 2px solid transparent;
  border-radius: var(--radius-md);
  background-color: #1C2433;
  background-image:
    linear-gradient(180deg, #202A3E 0%, #1C2433 100%) padding-box,
    linear-gradient(180deg, rgba(255, 255, 255, .10), rgba(255, 255, 255, .04)) border-box;
  box-shadow: var(--glass-border-top), var(--glass-border), var(--clay);
  transition: box-shadow var(--motion-fast), background-image var(--motion-fast), border-color var(--motion-fast);
}
/* selected: gradient border + the check badge inside the same row.
   The halo is electric cyan on purpose — it is the only glowing card in here. */
.gm-card.is-active {
  border-color: transparent;
  background-image:
    linear-gradient(180deg, #232E46 0%, #1C2433 100%) padding-box,
    linear-gradient(135deg, #22d3ee, #0ea5e9 55%, #0284c7) border-box;
  box-shadow:
    var(--clay),
    0 0 0 1px rgba(56, 189, 248, .5),
    0 0 26px -6px rgba(34, 211, 238, .55),
    inset 0 1px 0 rgba(255, 255, 255, .1),
    inset 0 0 24px -14px rgba(56, 189, 248, .95);
}
/* the pick is the whole row: icon, title, one line, check badge */
.gm-pick {
  appearance: none;
  border: 0;
  margin: 0;
  font: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: var(--s3);
  width: 100%;
  min-height: 60px;
  padding: 4px 6px;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--ink);
  text-align: left;
  transition: transform var(--motion-fast), opacity var(--motion-fast), background-color var(--motion-fast);
}
.gm-pick:hover:not(:active) { opacity: .92; }
/* the tap lands as a soft well inside the card, not as a page-wide ripple */
.gm-pick:active { transform: scale(.98); background-color: rgba(255, 255, 255, .05); }
.gm-pick:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.gm-pick[disabled] { opacity: .55; cursor: default; }
.gm-pick[disabled]:active { transform: none; }
/* gradient icon badge: dark glass well with the mode's own tinted halo */
.gm-ico {
  flex: none;
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border-radius: 16px;
  background: linear-gradient(180deg, #0A0F1C 0%, var(--field) 100%);
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, .55),
    inset 0 -1px 0 rgba(255, 255, 255, .08),
    inset 0 0 0 1px rgba(255, 255, 255, .06);
}
.gm-ico .ico { width: 26px; height: 26px; }
/* one well, three tints: amber swords, coral friends, emerald bot — each with its own glow */
.gm-ico.duel {
  color: #FDE68A;
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, .55),
    inset 0 0 0 1px rgba(252, 211, 77, .34),
    0 0 16px -4px rgba(245, 158, 11, .55);
}
.gm-ico.room {
  color: #FFC7B2;
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, .55),
    inset 0 0 0 1px rgba(255, 82, 43, .36),
    0 0 16px -4px rgba(255, 82, 43, .5);
}
.gm-ico.bot {
  color: var(--mint-ink);
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, .55),
    inset 0 0 0 1px rgba(110, 231, 183, .32),
    0 0 16px -4px rgba(16, 185, 129, .5);
}
/* the selected mode's icon burns a touch brighter than the row it sits in */
.gm-card.is-active .gm-ico.duel {
  color: #FEF3C7;
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, .55),
    inset 0 0 0 1px rgba(252, 211, 77, .55),
    0 0 18px -3px rgba(245, 158, 11, .8);
}
.gm-txt { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.gm-name {
  font-size: var(--t-2);
  font-weight: 800;
  letter-spacing: -.01em;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.gm-card.is-active .gm-name { color: var(--brand-ink); }
/* one short line by default; the friends blurb may break to a second line at
   360px rather than ellipsize — the 52px icon still owns the row's height */
.gm-desc {
  display: block;
  font-size: var(--t-micro);
  font-weight: 600;
  line-height: 1.35;
  color: var(--ink-soft);
  overflow-wrap: break-word;
}
/* check badge: lives in the row, so the title can never sit under it */
.gm-check {
  flex: none;
  display: none;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--brand-fill);
  color: var(--on-brand);
  box-shadow:
    0 2px 0 var(--brand-lip),
    0 6px 12px -6px var(--brand-glow),
    0 0 14px -4px rgba(56, 189, 248, .9),
    inset 0 1px 0 rgba(255, 255, 255, .45);
}
.gm-check .ico { width: 15px; height: 15px; }
.gm-card.is-active .gm-check { display: grid; }

/* ---- option strip inside the selected row: segmented control ---- */
.gm-seg {
  display: flex;
  align-items: center;
  gap: var(--s2);
  padding: 0 6px 6px;
}
.gm-seg .seg { flex: 1 1 auto; min-width: 0; }
.gm-seg .seg-b { min-height: 44px; }
/* The practice card carries two option rows — bot level and seat count — so its strip stacks
   rather than sitting side by side: three buttons across half a 360px card is not a tap target.
   Both rows keep the same 44px keys, so the card just gets taller. */
.gm-card[data-row="bot"] .gm-seg {
  flex-direction: column;
  align-items: stretch;
  gap: 6px;
}
/* ---- QUICK MATCH: collapsed obsidian coming-soon row ----
   One compact row, no sub-drawer and no padlock. A smoked-glass slab holds a muted
   titanium sword tile, two lines of copy and a single burnished champagne chip. */
.gm-card[data-row="online"] {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 0;
  min-height: 76px;
  padding: 14px 16px;
  border: 1px solid rgba(255, 255, 255, .08);
  border-radius: 18px;
  background: linear-gradient(135deg, rgba(22, 24, 33, .8), rgba(12, 14, 20, .9));
  background-color: transparent;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .06),
    0 16px 30px -24px rgba(0, 0, 0, .9);
}
/* the row is tappable only to explain itself: the cursor is a door, not a lock */
.gm-card[data-row="online"] .gm-pick {
  min-height: 0;
  padding: 0;
  gap: 14px;
  cursor: pointer;
}
/* no dim, lift or well: the obsidian face holds perfectly still under the finger */
.gm-card[data-row="online"] .gm-pick:hover:not(:active),
.gm-card[data-row="online"] .gm-pick:active {
  opacity: 1;
  transform: none;
  background-color: transparent;
}
.gm-card[data-row="online"] .gm-pick:focus-visible {
  outline: 2px solid rgba(212, 175, 55, .5);
  outline-offset: 4px;
}
/* deep dark glass well; the blades are steel, never gold */
.gm-card[data-row="online"] .gm-ico.duel {
  width: 44px;
  height: 44px;
  border-radius: 13px;
  color: #cbd5e1;
  background: linear-gradient(160deg, rgba(30, 34, 45, .94), rgba(8, 10, 15, .98));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .08),
    inset 0 0 0 1px rgba(255, 255, 255, .06);
}
.gm-card[data-row="online"] .gm-ico.duel .ico {
  width: 22px;
  height: 22px;
  filter: grayscale(1) brightness(.9);
  opacity: .75;
}
.gm-card[data-row="online"] .gm-txt { gap: 0; }
.gm-card[data-row="online"] .gm-name {
  margin-bottom: 2px;
  color: #f1f5f9;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0;
  line-height: 1.2;
}
.gm-card[data-row="online"] .gm-desc {
  color: #94a3b8;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* the inline-end chip: smoked obsidian glass, a hairline champagne rim, no glow loop */
.gm-badge-soon {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 4px 10px;
  border: 1px solid rgba(212, 175, 55, .35);
  border-radius: 999px;
  background: rgba(26, 22, 14, .7);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .1),
    0 0 10px rgba(212, 175, 55, .15);
  color: #f3d483;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.5px;
  line-height: 1.2;
  text-transform: uppercase;
  white-space: nowrap;
}

/* ---- FRIENDS: the entry pane ----
   Two actions and nothing else: a gold clay commitment, a hairline, a recessed well. The
   old pane stacked a code block, a coral invite slab and a second form on top of the
   create key, which is what made it read as three competing screens. */
.fr {
  display: flex;
  flex-direction: column;
  gap: var(--s3);
  padding: var(--s3);
  border-radius: var(--radius-md);
  background-color: #1C2433;
  background-image:
    linear-gradient(180deg, #202A3E 0%, #1C2433 100%);
  box-shadow: var(--glass-border-top), var(--glass-border), var(--clay);
}

/* the one gold slab on the screen: the only action that creates something */
.fr-create {
  --d: 5px;
  display: flex;
  align-items: center;
  gap: var(--s3);
  width: 100%;
  min-height: 68px;
  padding: 12px var(--s3);
  appearance: none;
  border: 0;
  border-radius: var(--radius-md);
  background: linear-gradient(180deg, #FFC53D 0%, #F0A81A 58%, #D98E0B 100%);
  color: #2B1B02;
  text-align: left;
  cursor: pointer;
  box-shadow:
    0 var(--d) 0 #8A5604,
    0 calc(var(--d) + 10px) 22px -10px rgba(245, 158, 11, .5),
    inset 0 2px 2px rgba(255, 255, 255, .55),
    inset 0 -3px 5px rgba(0, 0, 0, .16);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast);
}
.fr-create:hover:not(:active) { transform: translateY(-1px); }
.fr-create:active { transform: translateY(var(--press-y-lg)); --d: 1px; }
.fr-create:focus-visible { outline: 3px solid var(--honey-ink); outline-offset: 3px; }
.fr-create-ic {
  flex: none;
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: rgba(43, 27, 2, .14);
  box-shadow: inset 0 0 0 1px rgba(43, 27, 2, .18);
}
.fr-create-ic .ico { width: 20px; height: 20px; }
.fr-create-txt { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.fr-create-t { font-size: var(--t-2); font-weight: 900; letter-spacing: -.01em; line-height: 1.15; }
.fr-create-s { font-size: 10px; font-weight: 800; letter-spacing: .02em; color: #3A2604; }

/* the divider is a hairline with a word in it, never a second card */
.fr-or {
  display: flex;
  align-items: center;
  gap: var(--s2);
  margin: 0;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.fr-or::before,
.fr-or::after {
  content: '';
  flex: 1 1 auto;
  height: 1px;
  background: rgba(255, 255, 255, .09);
}

.fr-join { display: flex; align-items: center; gap: var(--s2); }
/* a carved well: the code is typed into the slab, not onto a floating field */
.fr-well {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 52px;
  padding: 0 14px;
  border-radius: var(--radius-sm);
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px rgba(255, 255, 255, .05);
  transition: box-shadow var(--motion-fast);
}
.fr-well:focus-within {
  box-shadow: var(--inset), inset 0 0 0 1px rgba(252, 211, 77, .45);
}
.fr-hash { flex: none; font-size: var(--t-micro); font-weight: 900; color: var(--ink-soft); }
.fr-input {
  flex: 1 1 auto;
  min-width: 0;
  width: 100%;
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: var(--t-1);
  font-weight: 800;
  letter-spacing: .2em;
  font-variant-numeric: tabular-nums;
  outline: none;
}
.fr-input::placeholder { letter-spacing: .02em; font-size: var(--t-micro); font-weight: 700; color: var(--ink-soft); }
.fr-join-btn {
  --d: 4px;
  flex: none;
  min-width: 84px;
  min-height: 52px;
  padding: 0 16px;
  appearance: none;
  border: 0;
  border-radius: var(--radius-sm);
  background: linear-gradient(180deg, #2E3A55 0%, #232E44 100%);
  color: var(--ink-soft);
  font-size: var(--t-2);
  font-weight: 900;
  cursor: default;
  box-shadow: 0 var(--d) 0 #0B111C, inset 0 1px 0 rgba(255, 255, 255, .12), var(--clay-ring);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast), color var(--motion-fast);
}
/* lit only once the well holds a full code — a Join that cannot work never looks pressable */
.fr-join-btn:not(:disabled) {
  background: linear-gradient(180deg, #FFC53D 0%, #D98E0B 100%);
  color: #2B1B02;
  cursor: pointer;
  box-shadow:
    0 var(--d) 0 #8A5604,
    inset 0 1px 0 rgba(255, 255, 255, .5);
}
.fr-join-btn:not(:disabled):active { transform: translateY(var(--press-y)); --d: 1px; }
.fr-join-btn:focus-visible { outline: 3px solid var(--honey-ink); outline-offset: 2px; }
.gm-err { margin: 0; font-size: var(--t-micro); font-weight: 700; }
.gm-err:not([hidden]) { color: var(--danger); }

/* ---- FRIENDS: the live lobby ----
   Bar (code · copy link · invite · count) → format switch → four seats → one action row. Every
   surface is clay: raised for something held, carved for something waiting to be filled. */
.lb { display: flex; flex-direction: column; gap: var(--s3); }

.lb-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 5px; min-width: 0; }
/* the code is the room's key: one tap copies the bare number, and the pill answers the press */
.lb-code {
  position: relative;
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 44px;
  padding: 0 11px;
  appearance: none;
  border: 0;
  border-radius: var(--radius-sm);
  background: linear-gradient(180deg, #2C3A57 0%, #222C41 100%);
  color: var(--honey-ink);
  font: inherit;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 0 0 1px rgba(252, 211, 77, .22);
  transition:
    transform var(--motion-fast),
    background-color var(--motion-fast),
    box-shadow var(--motion-fast);
}
.lb-code:hover { transform: scale(1.02); }
.lb-code:active { transform: scale(.96); }
.lb-code:focus-visible { outline: 3px solid var(--honey-ink); outline-offset: 2px; }
.lb-hash { font-size: var(--t-micro); font-weight: 900; color: var(--honey-ink); }
.lb-code b { font-size: var(--t-2); font-weight: 900; letter-spacing: .1em; line-height: 1; }

/* the reward: a gold ring runs off the pill while a check takes the hash's place */
.lb-code-check { display: none; width: 14px; height: 14px; flex: none; color: #6EE7B7; }
.lb-code.is-copied {
  animation: lb-code-pop 1.5s cubic-bezier(.2, .7, .2, 1);
  background: linear-gradient(180deg, #354964 0%, #222C41 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .2),
    inset 0 0 0 1.5px rgba(252, 211, 77, .9),
    0 0 0 3px rgba(252, 211, 77, .14),
    0 0 20px rgba(252, 211, 77, .32);
}
.lb-code.is-copied .lb-code-check { display: block; }
.lb-code.is-copied .lb-hash { display: none; }
.lb-code.is-copied::after {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: calc(var(--radius-sm) + 3px);
  border: 1px solid rgba(252, 211, 77, .7);
  pointer-events: none;
  animation: lb-code-ring .9s ease-out 1;
}
@keyframes lb-code-pop {
  0% { transform: scale(.94); }
  45% { transform: scale(1.05); }
  100% { transform: scale(1); }
}
@keyframes lb-code-ring {
  0% { opacity: .95; transform: scale(.96); }
  100% { opacity: 0; transform: scale(1.14); }
}

.lb-copy-link {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 44px;
  padding: 0 10px;
  appearance: none;
  border: 0;
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, .06);
  color: var(--ink-soft);
  font-size: var(--t-micro);
  font-weight: 800;
  cursor: pointer;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .13);
  transition: transform var(--motion-fast), background-color var(--motion-fast), color var(--motion-fast);
}
.lb-copy-link .ico { width: 14px; height: 14px; color: var(--honey-ink); }
.lb-copy-link:hover { background: rgba(255, 255, 255, .1); color: var(--ink); }
.lb-copy-link:active { transform: scale(.97); }
.lb-copy-link:focus-visible { outline: 3px solid var(--honey-ink); outline-offset: 2px; }

.lb-invite {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  padding: 0 10px;
  appearance: none;
  border: 0;
  border-radius: var(--radius-pill);
  background: rgba(252, 211, 77, .12);
  color: var(--honey-ink);
  font-size: var(--t-micro);
  font-weight: 800;
  cursor: pointer;
  box-shadow: inset 0 0 0 1px rgba(252, 211, 77, .26);
  transition: transform var(--motion-fast), background-color var(--motion-fast);
}
.lb-invite .ico { width: 15px; height: 15px; }
.lb-invite:active { transform: scale(.97); }
.lb-invite:focus-visible { outline: 3px solid var(--honey-ink); outline-offset: 2px; }

.lb-count {
  margin-left: auto;
  flex: none;
  font-size: var(--t-micro);
  font-weight: 800;
  letter-spacing: .02em;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* format: one carved track with four direct picks — 1v1 · 3P · 4P · 2v2 — and the single line
   that explains the choice. The host owns it; a guest's copy is read-only. */
.lb-mode { display: flex; flex-direction: column; gap: 6px; }
.lb-formats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 4px;
  padding: 4px;
  border-radius: var(--radius-pill);
  background: var(--field);
  box-shadow: var(--inset);
}
.lb-fmt {
  min-height: 38px;
  padding: 0 4px;
  appearance: none;
  border: 0;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--ink-soft);
  font: inherit;
  font-size: var(--t-micro);
  font-weight: 900;
  letter-spacing: .02em;
  cursor: pointer;
  transition: background var(--motion-fast), color var(--motion-fast), box-shadow var(--motion-fast);
}
.lb-fmt[aria-pressed="true"] {
  background: linear-gradient(180deg, #FFC53D 0%, #E09A0E 100%);
  color: #2B1B02;
  box-shadow: 0 2px 0 #8A5604, inset 0 1px 0 rgba(255, 255, 255, .5);
}
.lb-fmt.is-locked { cursor: default; }
.lb-fmt.is-locked[aria-pressed="false"] { opacity: .55; }
.lb-fmt:focus-visible { outline: 3px solid var(--honey-ink); outline-offset: 2px; }
.lb-mode-sub {
  margin: 0;
  min-height: 14px;
  text-align: center;
  font-size: 11px;
  font-weight: 700;
  line-height: 1.35;
  color: var(--ink-soft);
}

/* the start line: what stands between this roster and "Start Match", said plainly */
.lb-hint {
  margin: 0;
  min-height: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  text-align: center;
  font-size: var(--t-micro);
  font-weight: 700;
  line-height: 1.25;
  color: var(--ink-soft);
}
.lb-hint.is-ready { color: var(--honey-ink); }

/* the roster. The format owns the shape: a 1v1 duel is two large cards around the crest, 3P is a
   single row of three, 4P a two-by-two, and the 2v2 is Blue's column against Orange's.
   Raised for a person, carved and dashed for a well still open. */
.lb-slots { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.lb-slot {
  position: relative;
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 56px;
  padding: 8px 10px;
  appearance: none;
  border: 0;
  border-radius: var(--radius-sm);
  text-align: start;
  cursor: default;
  background: linear-gradient(180deg, #242F45 0%, #1D2636 100%);
  box-shadow:
    0 3px 0 #0C121C,
    inset 0 1px 0 rgba(255, 255, 255, .1),
    inset 0 0 0 1px rgba(255, 255, 255, .05);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast);
}
.lb-slot.is-host {
  background: linear-gradient(180deg, #2E3C5A 0%, #232E45 100%);
  box-shadow:
    0 3px 0 #0C121C,
    inset 0 1px 0 rgba(255, 255, 255, .16),
    inset 0 0 0 1px rgba(252, 211, 77, .24);
}
.lb-slot.is-you::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: inset 0 0 0 1px rgba(125, 211, 252, .28);
  pointer-events: none;
}
.lb-slot.is-away { opacity: .6; }
/* a seat the host (or its player) can flip is a control: give the tap a target it can feel */
.lb-slot[title]:active { transform: translateY(1px); }
.lb-slot:focus-visible { outline: 3px solid var(--honey-ink); outline-offset: 2px; }

.lb-av {
  flex: none;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: linear-gradient(180deg, #3B4A6B 0%, #28334B 100%);
  color: var(--ink);
  font-size: 14px;
  font-weight: 900;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .18), inset 0 0 0 1px rgba(255, 255, 255, .08);
}
/* individual: every seat wears its own colour — badge and avatar share it */
.lb-slot[data-color="0"] { box-shadow: 0 3px 0 #0C121C, inset 0 1px 0 rgba(255, 255, 255, .1), inset 0 0 0 1px rgba(59, 130, 246, .38); }
.lb-slot[data-color="0"] .lb-av { background: linear-gradient(180deg, #3B82F6 0%, #1D4ED8 100%); color: #EFF6FF; }
.lb-slot[data-color="1"] { box-shadow: 0 3px 0 #0C121C, inset 0 1px 0 rgba(255, 255, 255, .1), inset 0 0 0 1px rgba(239, 68, 68, .38); }
.lb-slot[data-color="1"] .lb-av { background: linear-gradient(180deg, #EF4444 0%, #B91C1C 100%); color: #FEF2F2; }
.lb-slot[data-color="2"] { box-shadow: 0 3px 0 #0C121C, inset 0 1px 0 rgba(255, 255, 255, .1), inset 0 0 0 1px rgba(34, 197, 94, .38); }
.lb-slot[data-color="2"] .lb-av { background: linear-gradient(180deg, #22C55E 0%, #15803D 100%); color: #F0FDF4; }
.lb-slot[data-color="3"] { box-shadow: 0 3px 0 #0C121C, inset 0 1px 0 rgba(255, 255, 255, .1), inset 0 0 0 1px rgba(234, 179, 8, .38); }
.lb-slot[data-color="3"] .lb-av { background: linear-gradient(180deg, #EAB308 0%, #A16207 100%); color: #FEFCE8; }
/* the host keeps the gold avatar — the crown reads on every seat colour */
.lb-slot.is-host .lb-av {
  background: linear-gradient(180deg, #FFD468 0%, #D98E0B 100%);
  color: #2B1B02;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .55), inset 0 0 0 1px rgba(43, 27, 2, .2);
}
.lb-slot-txt { display: flex; flex-direction: column; gap: 1px; min-width: 0; flex: 1 1 auto; }
.lb-name {
  font-size: var(--t-micro);
  font-weight: 800;
  color: var(--ink);
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.lb-role {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--ink-soft);
  line-height: 1.2;
}
.lb-slot.is-host .lb-role { color: var(--honey-ink); }
.lb-tags { display: flex; flex-direction: column; align-items: flex-end; gap: 3px; flex: none; }
.lb-crown { font-size: 13px; line-height: 1; filter: drop-shadow(0 1px 2px rgba(0, 0, 0, .5)); }
.lb-color {
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .07em;
  text-transform: uppercase;
  line-height: 1;
  padding: 3px 6px;
  border-radius: var(--radius-pill);
}
.lb-color[data-color="0"] { color: var(--blue-ink); background: rgba(59, 130, 246, .18); box-shadow: inset 0 0 0 1px rgba(59, 130, 246, .42); }
.lb-color[data-color="1"] { color: #FCA5A5; background: rgba(239, 68, 68, .16); box-shadow: inset 0 0 0 1px rgba(239, 68, 68, .42); }
.lb-color[data-color="2"] { color: #86EFAC; background: rgba(34, 197, 94, .16); box-shadow: inset 0 0 0 1px rgba(34, 197, 94, .42); }
.lb-color[data-color="3"] { color: #FDE68A; background: rgba(234, 179, 8, .16); box-shadow: inset 0 0 0 1px rgba(234, 179, 8, .42); }

/* the 1v1 duel — the room's default, so this is the layout most lobbies ever see. The plates and
   the crest are dressed further down, after the open-well rules they have to outrank. */
.lb-slots.is-duel {
  grid-template-columns: minmax(0, 1fr) 56px minmax(0, 1fr);
  gap: 0;
  align-items: stretch;
}

/* 3P — three compact cards on one row, so the roster never shows a well the format does not need */
.lb-slots.is-3p { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; }
.lb-slots.is-3p .lb-slot {
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  min-height: 90px;
  padding: 12px 6px 10px;
  text-align: center;
}
.lb-slots.is-3p .lb-av { width: 32px; height: 32px; font-size: 13px; }
.lb-slots.is-3p .lb-slot-txt { flex: 0 0 auto; align-items: center; gap: 1px; width: 100%; }
.lb-slots.is-3p .lb-name { max-width: 100%; font-size: 11px; }
.lb-slots.is-3p .lb-role { font-size: 8px; }
.lb-slots.is-3p .lb-tags { position: absolute; top: 6px; right: 6px; flex-direction: row; gap: 2px; }
.lb-slots.is-3p .lb-color { display: none; }
.lb-slots.is-3p .lb-plus { width: 28px; height: 28px; font-size: 18px; }

/* 2v2: Blue's column against Orange's, the crest between them; the column rim carries the colour */
.lb-slots.is-2v2 {
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  gap: 6px;
  align-items: stretch;
}
.lb-team {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  padding: 6px;
  border-radius: var(--radius-sm);
  background: rgba(0, 0, 0, .14);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .04);
}
.lb-team.is-blue { box-shadow: inset 0 0 0 1px rgba(59, 130, 246, .24), 0 0 16px -10px rgba(59, 130, 246, .6); }
.lb-team.is-orange { box-shadow: inset 0 0 0 1px rgba(249, 115, 22, .26), 0 0 16px -10px rgba(249, 115, 22, .6); }
.lb-team-h {
  margin: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
  line-height: 1.2;
  color: var(--ink-soft);
}
.lb-team.is-blue .lb-team-h { color: var(--blue-ink); }
.lb-team.is-orange .lb-team-h { color: #FDBA74; }
.lb-team-dot {
  width: 7px;
  height: 7px;
  flex: none;
  border-radius: 50%;
  background: #3B82F6;
  box-shadow: 0 0 8px rgba(59, 130, 246, .8);
}
.lb-team.is-orange .lb-team-dot { background: #F97316; box-shadow: 0 0 8px rgba(249, 115, 22, .8); }
/* inside a column the crest already owns the height: slots sit shorter and tighter */
.lb-team .lb-slot { min-height: 50px; padding: 7px 8px; gap: 7px; }
.lb-team .lb-av { width: 30px; height: 30px; font-size: 13px; }
.lb-team.is-blue .lb-slot .lb-av { background: linear-gradient(180deg, #3B82F6 0%, #1D4ED8 100%); color: #EFF6FF; }
.lb-team.is-orange .lb-slot .lb-av { background: linear-gradient(180deg, #FB923C 0%, #C2410C 100%); color: #FFF7ED; }
/* the host keeps the gold avatar in either column — the crown reads on every seat colour */
.lb-team .lb-slot.is-host .lb-av {
  background: linear-gradient(180deg, #FFD468 0%, #D98E0B 100%);
  color: #2B1B02;
}
/* the crest: a chiselled gold core riding a vertical laser thread that fades into the plates.
   Board furniture, never a control — nothing in it is focusable, so it can never take a tap. */
.lb-vs {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;
  width: 56px;
  min-width: 56px;
  padding: 2px 0;
}
/* the two laser threads: a hairline that is brightest at the crest and gone by the plate edge */
.lb-vs-thread {
  flex: 1 1 auto;
  width: 1px;
  min-height: 10px;
  border-radius: 1px;
  background: linear-gradient(180deg,
    rgba(252, 211, 77, 0) 0%,
    rgba(252, 211, 77, .45) 42%,
    rgba(255, 240, 180, 1) 100%);
  box-shadow: 0 0 8px rgba(252, 211, 77, .75);
}
.lb-vs-thread:last-child {
  background: linear-gradient(0deg,
    rgba(252, 211, 77, 0) 0%,
    rgba(252, 211, 77, .45) 42%,
    rgba(255, 240, 180, 1) 100%);
}
/* the core: the exact crest the brief specifies — chrome gold over obsidian, 48px */
.lb-vs-core {
  position: relative;
  flex: none;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 35% 35%, #ffe066 0%, #d4af37 40%, #704214 100%);
  box-shadow:
    0 0 20px rgba(255, 215, 0, .45),
    inset 0 2px 3px rgba(255, 255, 255, .7);
  isolation: isolate;
}
/* the outer energy rift: an ambient gold aura that breathes, and a hairline arc orbiting it.
   The mask keeps the aura outside the crest itself, so the disc stays a clean struck gold. */
.lb-vs-aura {
  position: absolute;
  inset: -9px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 215, 0, .34) 0%, rgba(255, 215, 0, .12) 46%, transparent 70%);
  -webkit-mask: radial-gradient(circle, transparent 0 23px, #000 24px);
  mask: radial-gradient(circle, transparent 0 23px, #000 24px);
  animation: lb-vs-breathe 2.8s ease-in-out infinite;
  pointer-events: none;
  z-index: -1;
}
.lb-vs-core::after {
  content: '';
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  background: conic-gradient(from 0deg,
    transparent 0deg,
    rgba(255, 244, 196, .95) 22deg,
    transparent 54deg,
    transparent 186deg,
    rgba(255, 244, 196, .55) 208deg,
    transparent 240deg);
  -webkit-mask: radial-gradient(circle, transparent 0 24px, #000 25px 26px, transparent 27px);
  mask: radial-gradient(circle, transparent 0 24px, #000 25px 26px, transparent 27px);
  animation: lb-vs-rift 6s linear infinite;
  pointer-events: none;
}
/* the crossed-swords micro-sigil: an embossed shadow behind the lettering, not a second icon */
.lb-vs-swords {
  position: absolute;
  width: 36px;
  height: 36px;
  color: rgba(43, 27, 2, .34);
  filter: drop-shadow(0 1px 0 rgba(255, 248, 214, .55));
  pointer-events: none;
}
/* chiselled gold lettering: a bronze cut, a specular top edge and a shadow under it */
.lb-vs-t {
  position: relative;
  z-index: 1;
  font-size: 15px;
  font-weight: 900;
  letter-spacing: .01em;
  line-height: 1;
  color: #4A2E05;
  text-shadow:
    0 1px 0 rgba(255, 246, 214, .95),
    0 -1px 1px rgba(52, 30, 2, .55),
    0 0 8px rgba(255, 240, 180, .35);
}
@keyframes lb-vs-breathe {
  0%, 100% { opacity: .55; transform: scale(.94); }
  50% { opacity: 1; transform: scale(1.06); }
}
@keyframes lb-vs-rift { to { transform: rotate(360deg); } }

/* short phones (360x640): the arena compresses on the 8px grid before the sheet ever scrolls */
@media (max-height: 660px) {
  .lb-mode { gap: 4px; }
  .lb-slots.is-duel .lb-plate { min-height: 112px; padding: 13px 8px 11px; gap: 6px; }
  .lb-slots.is-duel .lb-av { width: 44px; height: 44px; font-size: 17px; }
  .lb-slots.is-3p .lb-slot { min-height: 80px; }
  .lb-team .lb-slot { min-height: 46px; }
  .lb-team .lb-av { width: 28px; height: 28px; font-size: 12px; }
}

/* an open well: dashed, carved, and the one thing on the grid that invites a tap */
.lb-slot.is-open {
  justify-content: center;
  gap: 7px;
  border: 2px dashed rgba(255, 255, 255, .13);
  background: rgba(0, 0, 0, .16);
  box-shadow: var(--inset);
  cursor: pointer;
}
.lb-slot.is-open:hover { border-color: rgba(252, 211, 77, .4); }
.lb-slot.is-open:active { transform: scale(.985); }
.lb-plus {
  width: 26px;
  height: 26px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(252, 211, 77, .12);
  color: var(--honey-ink);
  font-size: 17px;
  font-weight: 700;
  line-height: 1;
  box-shadow: inset 0 0 0 1px rgba(252, 211, 77, .26);
}
.lb-open-t {
  font-size: var(--t-micro);
  font-weight: 800;
  color: var(--ink-soft);
  letter-spacing: .01em;
}

/* ---- the duel plates: holographic obsidian, a cyan laser rim, one crest between them ----
   Written after the generic slot and the open well, so a plate wins every tie it meets: a plate
   *is* a `.lb-slot`, and the duel is the one format that gets the full face-off treatment. */
.lb-slot.lb-plate {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 128px;
  padding: 18px 10px 14px;
  border: 0;
  border-radius: 16px;
  text-align: center;
  overflow: hidden;
  cursor: default;
  isolation: isolate;
  /* an opaque slab: the frosted read comes from the texture layers, never from a live blur */
  background:
    radial-gradient(120% 92% at 50% -10%, rgba(56, 189, 248, .15) 0%, rgba(56, 189, 248, 0) 58%),
    linear-gradient(180deg, #1B2436 0%, #0E1522 100%);
  box-shadow:
    0 0 0 1px rgba(56, 189, 248, .34),
    0 0 22px -8px rgba(56, 189, 248, .7),
    inset 0 1px 0 rgba(255, 255, 255, .12),
    inset 0 -16px 26px -20px rgba(0, 0, 0, .95);
}
/* the frosted grain: one sheen at the top, one hairline scanline pair over the whole plate */
.lb-slot.lb-plate::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .075) 0%, rgba(255, 255, 255, 0) 40%),
    repeating-linear-gradient(0deg, rgba(255, 255, 255, .022) 0 1px, transparent 1px 3px);
}
.lb-plate-halo {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: radial-gradient(76% 58% at 50% 108%, rgba(56, 189, 248, .2) 0%, transparent 72%);
}
/* the host's plate: the same slab, lit from above with gold and rimmed a stop brighter in cyan */
.lb-slot.lb-plate.is-host {
  background:
    radial-gradient(120% 92% at 50% -10%, rgba(252, 211, 77, .16) 0%, rgba(252, 211, 77, 0) 56%),
    linear-gradient(180deg, #212C40 0%, #101724 100%);
  box-shadow:
    0 0 0 1px rgba(125, 211, 252, .62),
    0 0 28px -8px rgba(56, 189, 248, .95),
    inset 0 0 0 1px rgba(125, 211, 252, .18),
    inset 0 1px 0 rgba(255, 255, 255, .16),
    inset 0 -16px 26px -20px rgba(0, 0, 0, .95);
}
/* a rival who is actually sitting: the plate slams in, then holds a mint rim */
.lb-slot.lb-plate.is-rival.is-ready {
  animation: lb-plate-slam 440ms cubic-bezier(.2, .9, .25, 1) both;
  box-shadow:
    0 0 0 1px rgba(125, 211, 252, .48),
    0 0 26px -9px rgba(56, 189, 248, .85),
    inset 0 0 0 1px rgba(94, 242, 176, .16),
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 -16px 26px -20px rgba(0, 0, 0, .95);
}
.lb-slot.lb-plate.is-rival.is-ready::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  box-shadow: inset 0 0 0 1px rgba(94, 242, 176, .22);
}
@keyframes lb-plate-slam {
  0% { opacity: 0; transform: translateY(-12px) scale(.9); filter: blur(3px); }
  58% { opacity: 1; transform: translateY(0) scale(1.045); filter: blur(0); }
  100% { opacity: 1; transform: scale(1); filter: blur(0); }
}

/* the plate's own type: one name at reading size, one role under it in tracked caps */
.lb-slots.is-duel .lb-slot-txt {
  flex: 0 0 auto;
  align-items: center;
  gap: 3px;
  width: 100%;
}
.lb-slots.is-duel .lb-name { max-width: 100%; font-size: var(--t-1); font-weight: 800; }
.lb-slots.is-duel .lb-role { font-size: 9px; letter-spacing: .12em; }
.lb-slots.is-duel .lb-tags { position: absolute; top: 8px; right: 8px; flex-direction: row; }
.lb-slots.is-duel .lb-color { display: none; }
.lb-slots.is-duel .lb-plus { width: 38px; height: 38px; font-size: 22px; }

/* the plate's portrait: a 54px disc, with Telegram's photo sitting over the monogram */
.lb-slots.is-duel .lb-av {
  position: relative;
  width: 54px;
  height: 54px;
  font-size: 21px;
  overflow: hidden;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .2),
    0 0 0 1px rgba(255, 255, 255, .1),
    0 10px 20px -12px rgba(0, 0, 0, .95);
}
/* a photo avatar is a mask: the image fills the disc, and the monogram waits underneath it.
   `position: relative` is what keeps the fill inside the disc rather than over the whole slot. */
.lb-av-photo { position: relative; overflow: hidden; }
.lb-av-fb { font-size: inherit; font-weight: 900; line-height: 1; }
.lb-av-photo img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* the two shoulder badges: a struck gold crown for the host, a mint neon READY for the rival */
.lb-badge {
  position: absolute;
  top: 8px;
  right: 8px;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .12em;
  line-height: 1;
  text-transform: uppercase;
}
.lb-badge-host {
  width: 22px;
  height: 22px;
  padding: 0;
  color: #3A2404;
  background: radial-gradient(circle at 34% 28%, #FFF3C4 0%, #FFD54A 38%, #C08A12 74%, #6B4405 100%);
  box-shadow:
    0 1px 0 #5A3A04,
    inset 0 1px 1px rgba(255, 255, 255, .78),
    0 0 12px -2px rgba(255, 213, 74, .85);
}
.lb-badge-host .ico { width: 13px; height: 13px; }
.lb-badge-ready {
  height: 20px;
  padding: 0 7px;
  color: #5EF2B0;
  background: linear-gradient(180deg, rgba(94, 242, 176, .22) 0%, rgba(16, 185, 129, .16) 100%);
  box-shadow:
    inset 0 0 0 1px rgba(94, 242, 176, .48),
    0 0 14px -4px rgba(94, 242, 176, .85);
  text-shadow: 0 0 8px rgba(94, 242, 176, .7);
  animation: lb-ready-pulse 2.6s ease-in-out infinite;
}
@keyframes lb-ready-pulse {
  0%, 100% { box-shadow: inset 0 0 0 1px rgba(94, 242, 176, .48), 0 0 14px -4px rgba(94, 242, 176, .85); }
  50% { box-shadow: inset 0 0 0 1px rgba(94, 242, 176, .8), 0 0 20px -2px rgba(94, 242, 176, 1); }
}

/* ---- the reserved host: the crown's chair held for a socket that stepped away ----
   The plate stays — avatar, name, crown and all — and an amber status rides at its head. It is a
   state, not an error: the room is alive, it is simply waiting for one person to come back. */
.lb-badge-away {
  gap: 4px;
  height: 20px;
  max-width: calc(100% - 12px);
  padding: 0 8px;
  color: #FDE68A;
  background: linear-gradient(180deg, rgba(251, 191, 36, .26) 0%, rgba(180, 83, 9, .22) 100%);
  box-shadow:
    inset 0 0 0 1px rgba(251, 191, 36, .55),
    0 0 16px -5px rgba(251, 191, 36, .95);
  text-transform: none;
  letter-spacing: .02em;
  white-space: nowrap;
  text-shadow: 0 0 8px rgba(251, 191, 36, .55);
  animation: lb-away-pulse 1.8s ease-in-out infinite;
}
.lb-away-dot {
  width: 5px;
  height: 5px;
  flex: none;
  border-radius: 50%;
  background: #FBBF24;
  box-shadow: 0 0 7px #FBBF24;
  animation: lb-away-blink 1.2s ease-in-out infinite;
}
@keyframes lb-away-pulse {
  0%, 100% { box-shadow: inset 0 0 0 1px rgba(251, 191, 36, .55), 0 0 16px -5px rgba(251, 191, 36, .95); }
  50% { box-shadow: inset 0 0 0 1px rgba(251, 191, 36, .9), 0 0 22px -2px rgba(251, 191, 36, 1); }
}
@keyframes lb-away-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: .28; }
}
/* On a duel plate the status is furniture in the column, not a corner stamp: it owns a line of its
   own above the portrait, so a long Persian phrase can never sit on the face. */
.lb-slot.lb-plate .lb-badge-away {
  position: relative;
  top: auto;
  right: auto;
  margin-bottom: -2px;
}
.lb-slot.lb-plate.is-host.is-away {
  opacity: 1;
  background:
    radial-gradient(120% 92% at 50% -10%, rgba(251, 191, 36, .15) 0%, rgba(251, 191, 36, 0) 56%),
    linear-gradient(180deg, #212C40 0%, #101724 100%);
  box-shadow:
    0 0 0 1px rgba(251, 191, 36, .38),
    0 0 24px -10px rgba(251, 191, 36, .8),
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 -16px 26px -20px rgba(0, 0, 0, .95);
}
.lb-slot.lb-plate.is-host.is-away .lb-plate-halo {
  background: radial-gradient(76% 58% at 50% 108%, rgba(251, 191, 36, .18) 0%, transparent 72%);
}
/* the crown moves to the other shoulder while the status is up: both marks read at a glance */
.lb-slot.lb-plate.is-waiting-host .lb-badge-host { right: auto; left: 8px; }
.lb-slot.lb-plate.is-reserved { cursor: default; }
.lb-av-reserved {
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 34% 28%, #FFF3C4 0%, #FFD54A 38%, #C08A12 74%, #6B4405 100%);
  color: #3A2404;
}
.lb-av-reserved .ico { width: 24px; height: 24px; }


/* an open rival plate: translucent glass, a dashed ring that marches, and the invite prompt */
.lb-slot.lb-plate.is-open {
  border: 0;
  gap: 6px;
  background:
    radial-gradient(88% 76% at 50% 50%, rgba(56, 189, 248, .1) 0%, rgba(56, 189, 248, 0) 72%),
    rgba(255, 255, 255, .028);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .06);
  animation: lb-well-breathe 3.4s ease-in-out infinite;
  cursor: pointer;
}
.lb-slot.lb-plate.is-open::before {
  background: radial-gradient(70% 60% at 50% 50%, rgba(56, 189, 248, .1) 0%, transparent 74%);
}
.lb-well-ring {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
.lb-well-ring rect {
  fill: none;
  stroke: rgba(125, 211, 252, .52);
  stroke-width: 1.4;
  stroke-dasharray: 4 4;
  vector-effect: non-scaling-stroke;
  filter: drop-shadow(0 0 3px rgba(56, 189, 248, .55));
  animation: lb-well-dash 1.6s linear infinite;
}
.lb-open-s {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .02em;
  color: var(--ink-soft);
  opacity: .72;
}
@keyframes lb-well-breathe {
  0%, 100% { box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .06), 0 0 0 rgba(56, 189, 248, 0); }
  50% { box-shadow: inset 0 0 0 1px rgba(125, 211, 252, .3), 0 0 24px -10px rgba(56, 189, 248, .8); }
}
@keyframes lb-well-dash { to { stroke-dashoffset: -16; } }

/* ---- the in-match arrival banner: a friend landed while this player is on a board ----
   A frosted obsidian pill over the top of the stage, cyan rim and gold lip, mint-to-amber energy
   kept to the action only. It never blocks the board: two compact keys and a name. */
.lb-hud {
  position: fixed;
  top: max(10px, env(safe-area-inset-top));
  left: 0;
  right: 0;
  z-index: 120;
  display: flex;
  justify-content: center;
  padding: 0 12px;
  pointer-events: none;
}
.lb-hud[hidden] { display: none; }
.lb-hud-card {
  pointer-events: auto;
  width: min(100%, 440px);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border-radius: 18px;
  background:
    radial-gradient(120% 140% at 8% 0%, rgba(56, 189, 248, .14) 0%, rgba(56, 189, 248, 0) 58%),
    linear-gradient(180deg, rgba(23, 31, 47, .95) 0%, rgba(9, 13, 21, .97) 100%);
  box-shadow:
    0 0 0 1px rgba(56, 189, 248, .44),
    0 0 0 2px rgba(252, 211, 77, .12),
    0 18px 34px -18px rgba(0, 0, 0, .95),
    inset 0 1px 0 rgba(255, 255, 255, .15),
    inset 0 0 24px rgba(56, 189, 248, .08);
  -webkit-backdrop-filter: blur(16px) saturate(1.15);
  backdrop-filter: blur(16px) saturate(1.15);
}
.lb-hud.is-in .lb-hud-card { animation: lb-hud-in 320ms cubic-bezier(.2, .9, .25, 1) both; }
.lb-hud .lb-av {
  width: 38px;
  height: 38px;
  flex: none;
  font-size: 15px;
  border-radius: 12px;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .18),
    0 0 0 1px rgba(125, 211, 252, .3),
    0 0 18px -8px rgba(56, 189, 248, .9);
}
.lb-hud-txt { display: flex; flex-direction: column; gap: 2px; min-width: 0; flex: 1 1 auto; }
.lb-hud-t {
  font-size: 12px;
  font-weight: 900;
  line-height: 1.25;
  color: var(--ink);
  text-shadow: 0 0 14px rgba(56, 189, 248, .28);
}
.lb-hud-s {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .04em;
  color: var(--ink-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.lb-hud-actions { display: flex; align-items: center; gap: 5px; flex: none; }
.lb-hud-b {
  appearance: none;
  border: 0;
  font: inherit;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .03em;
  line-height: 1;
  min-height: 32px;
  padding: 0 10px;
  border-radius: 10px;
  cursor: pointer;
  white-space: nowrap;
  transition: transform var(--motion-fast), box-shadow var(--motion-fast), background-color var(--motion-fast);
}
.lb-hud-b:active { transform: translateY(1px) scale(.98); }
.lb-hud-b:focus-visible { outline: 3px solid var(--honey-ink); outline-offset: 2px; }
.lb-hud-b.is-join {
  color: #2B1B02;
  background: linear-gradient(180deg, #FFD75E 0%, #F0A70C 100%);
  box-shadow:
    0 2px 0 #8A5604,
    inset 0 1px 0 rgba(255, 255, 255, .62),
    0 0 18px -6px rgba(252, 211, 77, .95);
}
.lb-hud-b.is-wait {
  color: var(--ink-soft);
  background: rgba(255, 255, 255, .07);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .14);
}
@keyframes lb-hud-in {
  from { opacity: 0; transform: translateY(-14px) scale(.96); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

/* a full duel: the crest burns hotter and its threads run brighter — the room is a face-off now */
#gm-view-lobby[data-state="ready"] .lb-vs-core {
  box-shadow:
    0 0 30px rgba(255, 215, 0, .7),
    inset 0 2px 3px rgba(255, 255, 255, .8);
}
#gm-view-lobby[data-state="ready"] .lb-vs-aura { animation-duration: 1.5s; }
#gm-view-lobby[data-state="ready"] .lb-vs-thread { box-shadow: 0 0 9px rgba(252, 211, 77, .85); }

/* ---- the duel countdown: 3 … 2 … 1 … FIGHT, over the lobby, above every sheet but the toast ---- */
.duel-count {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: grid;
  place-items: center;
  padding: 24px;
  animation: dc-veil-in 180ms ease-out both;
}
.duel-count[hidden] { display: none; }
.dc-veil {
  position: absolute;
  inset: 0;
  background: radial-gradient(120% 90% at 50% 46%, rgba(8, 12, 20, .82) 0%, rgba(4, 6, 11, .94) 100%);
}
.dc-card {
  position: relative;
  width: min(100%, 286px);
  padding: 20px 18px 16px;
  border-radius: 22px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  text-align: center;
  background: linear-gradient(180deg, #1D2739 0%, #101725 100%);
  box-shadow:
    0 0 0 1px rgba(125, 211, 252, .34),
    0 24px 48px -22px rgba(0, 0, 0, .95),
    inset 0 1px 0 rgba(255, 255, 255, .12);
  animation: dc-card-in 260ms cubic-bezier(.2, .9, .25, 1) both;
}
.dc-card.is-beat { animation: dc-beat 350ms cubic-bezier(.2, .9, .25, 1) both; }
.dc-kicker {
  margin: 0;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--honey-ink);
}
.dc-ring {
  position: relative;
  width: 96px;
  height: 96px;
  display: grid;
  place-items: center;
}
.dc-ring svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
  overflow: visible;
}
.dc-track { fill: none; stroke: rgba(255, 255, 255, .08); stroke-width: 4; }
.dc-arc {
  fill: none;
  stroke: #FFD54A;
  stroke-width: 4;
  stroke-linecap: round;
  stroke-dasharray: 339.29;
  stroke-dashoffset: 0;
  filter: drop-shadow(0 0 5px rgba(255, 213, 74, .85));
}
.dc-ring.is-tick .dc-arc { animation: dc-drain 350ms linear forwards; }
.dc-n {
  font-size: 42px;
  font-weight: 900;
  line-height: 1;
  color: #FFE9A8;
  text-shadow: 0 0 18px rgba(255, 213, 74, .55), 0 2px 0 rgba(0, 0, 0, .5);
  font-variant-numeric: tabular-nums;
}
.is-fight .dc-n {
  font-size: 27px;
  letter-spacing: .06em;
  color: #FFF6D2;
  text-shadow: 0 0 26px rgba(255, 213, 74, .9), 0 2px 0 rgba(0, 0, 0, .5);
}
.is-fight .dc-ring svg { opacity: 0; }
.is-fight .dc-card { box-shadow: 0 0 0 1px rgba(255, 213, 74, .6), 0 0 48px -14px rgba(255, 213, 74, .8), inset 0 1px 0 rgba(255, 255, 255, .16); }
.dc-line {
  margin: 0;
  font-size: var(--t-micro);
  font-weight: 700;
  color: var(--ink-soft);
}
.dc-cancel {
  appearance: none;
  border: 0;
  min-height: 40px;
  width: 100%;
  margin-top: 2px;
  border-radius: var(--radius-sm);
  background: rgba(255, 255, 255, .05);
  color: var(--ink-soft);
  font: inherit;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .1em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .1);
  transition: color var(--motion-fast), background-color var(--motion-fast);
}
.dc-cancel:hover { color: var(--ink); background: rgba(255, 255, 255, .08); }
.dc-cancel:active { transform: scale(.99); }
.dc-cancel:focus-visible { outline: 3px solid var(--honey-ink); outline-offset: 2px; }
@keyframes dc-veil-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes dc-card-in {
  from { opacity: 0; transform: translateY(10px) scale(.96); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes dc-beat {
  0% { transform: scale(1.06); }
  100% { transform: scale(1); }
}
@keyframes dc-drain { from { stroke-dashoffset: 0; } to { stroke-dashoffset: 339.29; } }

/* the invite picker lives in the flow only while a well is open */
.lb-pick { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.lb-pick[hidden] { display: none; }
.lb-pick-b {
  min-height: 44px;
  appearance: none;
  border: 0;
  border-radius: var(--radius-sm);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: rgba(252, 211, 77, .1);
  color: var(--honey-ink);
  font: inherit;
  font-size: var(--t-micro);
  font-weight: 800;
  cursor: pointer;
  box-shadow: inset 0 0 0 1px rgba(252, 211, 77, .24);
  transition: transform var(--motion-fast), background-color var(--motion-fast);
}
.lb-pick-b .ico { width: 15px; height: 15px; }
.lb-pick-b:active { transform: scale(.98); }
.lb-pick-b:focus-visible { outline: 3px solid var(--honey-ink); outline-offset: 2px; }

/* the foot row: one compact Leave key beside the one loud Start — no second full-width slab */
.gm-foot-row { display: flex; align-items: stretch; gap: 8px; }
.gm-foot-row .gm-start { flex: 1 1 0; width: auto; min-width: 0; }
.lb-leave {
  flex: none;
  width: 62px;
  min-height: 52px;
  appearance: none;
  border: 0;
  border-radius: var(--radius-sm);
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  background: rgba(255, 255, 255, .04);
  color: var(--ink-soft);
  font: inherit;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .06em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .1);
  transition: color var(--motion-fast), background-color var(--motion-fast);
}
.lb-leave .ico { width: 15px; height: 15px; }
.lb-leave[hidden] { display: none; }
.lb-leave:hover { color: var(--ink); background: rgba(255, 255, 255, .07); }
.lb-leave:active { transform: scale(.99); }
.lb-leave:focus-visible { outline: 3px solid var(--honey-ink); outline-offset: 2px; }

/* the Start key's three states: gold (host, ready), carved (host, short a player), waiting (guest).
   The lobby's Start is the screen's one warm slab — the blue CTA belongs to the mode list. */
.gm-start.is-lobby {
  background: linear-gradient(180deg, #FFC53D 0%, #F0A81A 58%, #D98E0B 100%);
  color: #2B1B02;
  box-shadow:
    0 var(--d) 0 #8A5604,
    0 calc(var(--d) + 10px) 20px -10px rgba(245, 158, 11, .5),
    inset 0 2px 3px rgba(255, 255, 255, .5),
    inset 0 -3px 6px rgba(0, 0, 0, .18);
}
/* the room is ready: the one warm slab earns a live gold ring — the only glow on the screen */
.gm-start.is-lobby.is-ready {
  box-shadow:
    0 var(--d) 0 #8A5604,
    0 0 0 1px rgba(255, 226, 130, .45),
    0 0 22px -2px rgba(245, 158, 11, .6),
    0 0 46px -8px rgba(255, 197, 61, .45),
    inset 0 2px 3px rgba(255, 255, 255, .55),
    inset 0 -3px 6px rgba(0, 0, 0, .18);
}
.gm-start[aria-disabled="true"] {
  background: linear-gradient(180deg, #2A3550 0%, #1F2839 100%);
  color: var(--ink-soft);
  box-shadow:
    0 var(--d) 0 #0B111C,
    inset 0 1px 0 rgba(255, 255, 255, .08),
    inset 0 0 0 1px rgba(255, 255, 255, .05);
}
.gm-start.is-idle:active { transform: none; --d: 5px; }
.gm-start.is-waiting {
  color: var(--honey-ink);
  animation: lb-breathe 2.4s ease-in-out infinite;
}
@keyframes lb-breathe {
  0%, 100% { box-shadow: 0 var(--d) 0 #0B111C, inset 0 1px 0 rgba(255, 255, 255, .08), inset 0 0 0 1px rgba(252, 211, 77, .18); }
  50% { box-shadow: 0 var(--d) 0 #0B111C, inset 0 1px 0 rgba(255, 255, 255, .12), inset 0 0 0 1px rgba(252, 211, 77, .5); }
}
html.reduced-motion .gm-start.is-waiting { animation: none; }

/* ---- sticky footer: one reward caption for the selected mode, one Start ---- */
.gm-foot {
  flex: none;
  display: flex;
  flex-direction: column;
  gap: var(--s2);
}
/* the entry pane owns its own actions, and the lobby hides the reward caption: both must actually
   leave the flow, which an author `display: flex` would otherwise veto */
.gm-foot[hidden],
.gm-rewards[hidden] { display: none; }
/* one centered capsule: WIN +30 (trophy) +65 (coin), never a row of loose numbers */
.gm-rewards {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: var(--s2);
  margin: 0;
  min-height: 26px;
  padding: 4px var(--s3);
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, .05);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .07);
  font-size: var(--t-micro);
  font-weight: 800;
  color: var(--ink-soft);
}
.gm-lead { text-transform: uppercase; letter-spacing: .08em; }
.gm-rw {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.gm-rw b { font-size: var(--t-micro); font-weight: 900; color: var(--ink); }
.gm-rw .ico { width: 14px; height: 14px; color: var(--honey-ink); }
.gm-rw .coin { width: 14px; height: 14px; }
/* the one loud key: a 3D clay slab that sinks into its lip on press */
.gm-start {
  --d: 5px;
  width: 100%;
  min-height: 52px;
  padding-top: 14px;
  padding-bottom: 14px;
  font-size: var(--t-1);
  font-weight: 900;
  letter-spacing: -.01em;
  box-shadow:
    0 var(--d) 0 var(--brand-lip),
    0 calc(var(--d) + 8px) 18px -8px var(--brand-glow),
    inset 0 2px 3px rgba(255, 255, 255, .34),
    inset 0 -3px 6px rgba(0, 0, 0, .28),
    inset 0 0 0 1px rgba(255, 255, 255, .14);
}
.gm-start:hover:not(:active) { transform: translateY(-1px); }
.gm-start:active { transform: translateY(var(--press-y)); --d: 1px; }

/* short columns: the drawer already caps at 85dvh, so only the badge shrinks */
@media (max-height: 700px) {
  .gm-ico { width: 46px; height: 46px; border-radius: 15px; }
  .gm-ico .ico { width: 23px; height: 23px; }
}
/* Short columns give up drawer chrome before a control shrinks. The cap has to be
   addressed by ID — the base rule is `#sheet-game-modes, .gm-sheet`, so a bare
   `.gm-sheet` override loses on specificity. */
@media (max-height: 660px) {
  #sheet-game-modes {
    --gm-gap: 10px;
    /* one more band of scrim is cheaper than a scroll inside the drawer */
    max-height: 90vh;
    max-height: 90dvh;
  }
  .gm-card { padding: 5px; }
}
@media (max-height: 600px) {
  #sheet-game-modes {
    --gm-gap: 9px;
    max-height: 92vh;
    max-height: 92dvh;
  }
  .gm-rewards { min-height: 24px; padding: 2px var(--s3); }
}
html.reduced-motion .gm-pick, html.reduced-motion .gm-key, html.reduced-motion .gm-card,
html.reduced-motion .fr-create, html.reduced-motion .fr-join-btn,
html.reduced-motion .lb-code, html.reduced-motion .lb-copy-link, html.reduced-motion .lb-invite, html.reduced-motion .lb-slot,
html.reduced-motion .lb-fmt, html.reduced-motion .lb-pick-b, html.reduced-motion .lb-leave { transition: none; }
html.reduced-motion .lb-badge-away, html.reduced-motion .lb-away-dot, html.reduced-motion .lb-hud.is-in .lb-hud-card { animation: none; }
html.reduced-motion .lb-code.is-copied { animation: none; }
html.reduced-motion .lb-code.is-copied::after { display: none; }
html.reduced-motion .lb-hud-b { transition: none; }


/* ==========================================================================
   PROFILE AESTHETIC — Telegram Gaming Mini-App energy.
   Rich gradients, ambient glows and vibrant accents layered over the Dark
   Clay base. Everything is transform/opacity + box-shadow only; presses
   never scale. The hero card's own rules live in the PROFILE V2 block above.
   ========================================================================== */

/* ---- quest / CTA card: dynamic pattern + glowing duel + claymorphic Play ---- */
.pf-quest {
  position: relative;
  overflow: hidden;
  border-radius: 22px;
  padding: 18px;
  border-top: 1px solid rgba(255, 255, 255, .16);
  background:
    radial-gradient(120% 95% at 88% 0%, rgba(34, 211, 238, .24), rgba(34, 211, 238, 0) 55%),
    radial-gradient(100% 85% at 4% 108%, rgba(168, 85, 247, .2), rgba(168, 85, 247, 0) 60%),
    linear-gradient(180deg, #26314B 0%, #1B2333 100%);
  background-color: #1C2433;
  box-shadow:
    var(--clay),
    var(--clay-ring),
    0 0 32px -12px rgba(34, 211, 238, .45);
}
.pf-quest-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .5;
  background-image:
    repeating-linear-gradient(135deg, rgba(255, 255, 255, .05) 0 1px, transparent 1px 16px),
    repeating-linear-gradient(45deg, rgba(34, 211, 238, .06) 0 1px, transparent 1px 16px);
  mask-image: radial-gradient(120% 100% at 50% 0%, #000 30%, transparent 100%);
  -webkit-mask-image: radial-gradient(120% 100% at 50% 0%, #000 30%, transparent 100%);
}
.pf-quest-empty,
.pf-quest-stats { position: relative; }
.pf-quest-empty { display: flex; flex-direction: column; align-items: center; gap: var(--s2); text-align: center; }
.pf-quest-ico {
  display: grid;
  place-items: center;
  width: 60px;
  height: 60px;
  border-radius: 20px;
  color: #FCD34D;
  background: linear-gradient(180deg, rgba(245, 158, 11, .3) 0%, rgba(245, 158, 11, .08) 100%);
  box-shadow:
    inset 0 0 0 1px rgba(252, 211, 77, .42),
    inset 0 2px 3px rgba(255, 255, 255, .2),
    0 0 26px -4px rgba(245, 158, 11, .8);
  animation: pf-duel-pulse 2.4s ease-in-out infinite;
}
.pf-quest-ico .ico { width: 30px; height: 30px; filter: drop-shadow(0 0 8px rgba(245, 158, 11, .8)); }
@keyframes pf-duel-pulse {
  0%, 100% { box-shadow: inset 0 0 0 1px rgba(252,211,77,.42), inset 0 2px 3px rgba(255,255,255,.2), 0 0 20px -6px rgba(245,158,11,.65); }
  50%      { box-shadow: inset 0 0 0 1px rgba(252,211,77,.6), inset 0 2px 3px rgba(255,255,255,.25), 0 0 34px -2px rgba(245,158,11,.95); }
}
.pf-quest-kicker {
  margin: 0;
  font-size: var(--t-micro);
  font-weight: 900;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: #67E8F9;
  text-shadow: 0 0 10px rgba(34, 211, 238, .5);
}
.pf-quest-title { margin: 2px 0 0; font-size: var(--t-1); font-weight: 900; letter-spacing: -.01em; color: var(--ink); text-wrap: balance; }
.pf-quest-sub { margin: 4px 0 0; font-size: var(--t-micro); font-weight: 600; line-height: 1.4; color: var(--ink-soft); max-width: 34ch; text-wrap: pretty; }
.pf-quest-copy { display: flex; flex-direction: column; align-items: center; }

/* the empty record's quiet status badge: one smoked pill, a honey hairline, no glow */
.pf-quest-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  max-width: 100%;
  margin-top: 2px;
  padding: 5px 12px;
  border-radius: 999px;
  border: 1px solid rgba(252, 211, 77, .2);
  background: linear-gradient(180deg, rgba(28, 38, 56, .72) 0%, rgba(10, 15, 25, .86) 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .05);
  color: var(--ink-soft);
  font-size: var(--t-micro);
  font-weight: 800;
  line-height: 1.35;
  letter-spacing: .02em;
  text-align: center;
}
.pf-quest-pill .ico {
  flex: none;
  width: 12px;
  height: 12px;
  color: #FCD34D;
  opacity: .82;
}

/* ---- badges: hexagonal medal slots, lit when unlocked, holographic when locked ---- */
.badge-rack {
  padding: 12px 12px;
  gap: var(--s1);
  border-top: 1px solid rgba(255, 255, 255, .07);
  box-shadow:
    inset 0 2px 5px rgba(0, 0, 0, .5),
    inset 0 -1px 0 rgba(255, 255, 255, .06),
    inset 0 0 0 1px rgba(255, 255, 255, .06),
    0 0 24px -14px rgba(34, 211, 238, .5);
}
.badge-chip {
  position: relative;
  width: 42px;
  height: 46px;
  border-radius: 0;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  background: linear-gradient(180deg, #3A4666 0%, #121A29 100%);
  box-shadow: none;
  display: grid;
  place-items: center;
  transition: transform var(--motion-fast), filter var(--motion-fast);
}
.badge-chip::before {
  content: "";
  position: absolute;
  inset: 2.5px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  background: linear-gradient(180deg, #1B2436 0%, #0B101B 100%);
}
.badge-chip > * { position: relative; z-index: 1; }
.badge-chip .ico { width: 19px; height: 19px; }
.badge-chip[data-state="unlocked"][data-accent="gold"] {
  background: linear-gradient(180deg, #fcd34d 0%, #b45309 100%);
  filter: drop-shadow(0 0 10px rgba(245, 158, 11, .7));
}
.badge-chip[data-state="unlocked"][data-accent="gold"] .ico { color: #FCD34D; filter: drop-shadow(0 0 5px rgba(245,158,11,.8)); }
.badge-chip[data-state="unlocked"][data-accent="sky"] {
  background: linear-gradient(180deg, #7dd3fc 0%, #0369a1 100%);
  filter: drop-shadow(0 0 10px rgba(56, 189, 248, .7));
}
.badge-chip[data-state="unlocked"][data-accent="sky"] .ico { color: #7DD3FC; filter: drop-shadow(0 0 5px rgba(56,189,248,.8)); }
.badge-chip[data-state="unlocked"][data-accent="mint"] {
  background: linear-gradient(180deg, #6ee7b7 0%, #047857 100%);
  filter: drop-shadow(0 0 10px rgba(16, 185, 129, .7));
}
.badge-chip[data-state="unlocked"][data-accent="mint"] .ico { color: #6EE7B7; filter: drop-shadow(0 0 5px rgba(16,185,129,.8)); }
.badge-chip[data-state="unlocked"][data-accent="coral"] {
  background: linear-gradient(180deg, #ffb59d 0%, #b83010 100%);
  filter: drop-shadow(0 0 10px rgba(255, 82, 43, .7));
}
.badge-chip[data-state="unlocked"][data-accent="coral"] .ico { color: #FFB59D; filter: drop-shadow(0 0 5px rgba(255,82,43,.8)); }
/* locked: a dark holographic hex with a slow iridescent sheen */
.badge-chip[data-state="locked"] {
  background: linear-gradient(180deg, rgba(139, 92, 246, .5) 0%, rgba(34, 211, 238, .35) 50%, rgba(236, 72, 153, .42) 100%);
  filter: drop-shadow(0 0 8px rgba(139, 92, 246, .35));
}
.badge-chip[data-state="locked"]::before {
  background: linear-gradient(160deg, #1a2036 0%, #0b101b 60%, #151b30 100%);
}
.badge-chip[data-state="locked"]::after {
  content: "";
  position: absolute;
  inset: 2.5px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  background: linear-gradient(120deg, transparent 30%, rgba(199, 210, 254, .22) 50%, transparent 70%);
  background-size: 260% 100%;
  animation: pf-holo 3.4s linear infinite;
  z-index: 0;
}
@keyframes pf-holo { from { background-position: 260% 0; } to { background-position: -120% 0; } }
.badge-chip[data-state="locked"] .ico { color: #64748B; opacity: .55; }
.badge-slot.is-equipped .badge-chip {
  background: linear-gradient(180deg, #fde68a 0%, #b45309 100%);
  filter: drop-shadow(0 0 12px rgba(251, 191, 36, .85));
}
.badge-slot.is-equipped .badge-chip .ico { color: #FCD34D; }
.badge-lock { position: relative; display: grid; place-items: center; }
.badge-lock .ico-main { width: 16px; height: 16px; opacity: .5; }
.badge-lock .ico-lock {
  position: absolute;
  right: -6px;
  bottom: -6px;
  width: 16px;
  height: 16px;
  padding: 2.5px;
  border-radius: 50%;
  background: #1C2433;
  box-shadow: inset 0 0 0 1px rgba(148, 163, 184, .35);
  color: #94A3B8;
}
.badge-slot:hover:not(:active) .badge-chip { transform: translateY(-2px); }
.badge-slot:active .badge-chip { transform: translateY(var(--press-y)); }

/* ---- identity rows: leading neon icon chip ---- */
.pf-tile-ico {
  flex: none;
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: linear-gradient(180deg, #0A0F1C 0%, #172235 100%);
  color: #67E8F9;
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, .55),
    inset 0 0 0 1px rgba(34, 211, 238, .22),
    0 0 12px -4px rgba(34, 211, 238, .5);
}
.pf-tile-ico .ico { width: 19px; height: 19px; }
.pf-rows .pf-tile.row { gap: var(--s2); }
.pf-tile.row .pf-chip-reward { flex: none; }
.pf-tile.row .chev { flex: none; width: 16px; height: 16px; }
.pf-tile.row.claimed { box-shadow: var(--clay), var(--clay-ring), inset 0 0 0 1px rgba(110, 231, 183, .2); }

/* ---- bottom dock: sharper active tab, indicator light + micro-animation ---- */
.dock-nav {
  border-top: 1px solid rgba(255, 255, 255, .1);
  background:
    radial-gradient(120% 160% at 50% 0%, rgba(34, 211, 238, .12), rgba(34, 211, 238, 0) 60%),
    var(--clay-face);
  background-color: #1C2433;
  box-shadow:
    0 var(--d) 0 #080C14,
    var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring),
    0 0 28px -16px rgba(34, 211, 238, .5);
}
.dock-nav .tab { position: relative; overflow: visible; }
.dock-nav .tab .ico { transition: transform var(--motion-fast), filter var(--motion-fast), color var(--motion-fast); }
.dock-nav .tab:hover:not([aria-current="page"]) .ico { filter: drop-shadow(0 0 6px rgba(125, 211, 252, .6)); color: var(--brand-ink); transform: translateY(-2px); }
.dock-nav .tab:active .ico { transform: translateY(2px) scale(.92); }
/* indicator light under the active tab + a lit top hairline */
.dock-nav .tab[aria-current="page"] {
  background: linear-gradient(180deg, #0ea5e9 0%, #0284c7 55%, #0369a1 100%);
  color: #fff;
  border-top: 1px solid rgba(255, 255, 255, .4);
  box-shadow:
    0 var(--d) 0 var(--brand-lip),
    0 calc(var(--d) + 8px) 18px -8px rgba(34, 211, 238, .85),
    inset 0 2px 4px rgba(255, 255, 255, .5),
    inset 0 -3px 5px rgba(3, 105, 161, .5),
    0 0 22px -4px rgba(34, 211, 238, .7);
}
.dock-nav .tab[aria-current="page"] .ico {
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, .35));
}
.dock-nav .tab[aria-current="page"]::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 4px;
  width: 5px;
  height: 5px;
  margin-left: -2.5px;
  border-radius: 50%;
  background: #E0F2FE;
  box-shadow: 0 0 8px 1px rgba(224, 242, 254, .95), 0 0 14px 3px rgba(34, 211, 238, .8);
}

/* ---- reduced motion: kill every new animation ---- */
html.reduced-motion .pf-avatar-glow,
html.reduced-motion .pf-quest-ico,
html.reduced-motion .badge-chip[data-state="locked"]::after { animation: none; }

/* the twin tiles stay 50/50 down to the 360px floor; below it a long nation name
   borrows the whole row rather than ellipsising mid-word */
@media (max-width: 359px) {
  .pf-hero-chip-row { grid-template-columns: minmax(0, 1fr); }
}

/* ==========================================================================
   THE MIND LADDER — Part 4: the mind sheet, its micro-interactions, the gate.
   One clay bottom sheet behind every ladder name. Depth is extrusion and inner
   shadow only: no backdrop-filter anywhere in this block, so the panel stays
   opaque slate over the scrim rather than turning to glass.
   ========================================================================== */

/* ---- surface + header ---- */
.mind-sheet {
  border-radius: 24px 24px 0 0;
  /* the brief's own ceiling, and the same 85dvh the mode sheet already proves at 360x640 */
  max-height: 85vh;
  max-height: 85dvh;
  gap: var(--s2);
  background: linear-gradient(180deg, #232E44 0%, #1C2433 46%);
  background-color: #1C2433;
  box-shadow:
    inset 0 1px 0 var(--hair-lit),
    inset 0 0 0 1px rgba(255, 255, 255, .06),
    0 -20px 44px -20px var(--shadow);
}
/* One aura for every mind: the ring reads --ml-aura's own sky fallback, never a league colour. */

.ms-head {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: var(--s2);
  min-width: 0;
}
/* The flag rides the corner of the avatar, so the identity column keeps its width at 320. */
.ms-marks { position: relative; flex: none; width: 54px; height: 54px; }
.ms-av {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  border-radius: 16px;
  background: linear-gradient(180deg, #2A354C 0%, #141B2A 100%);
  box-shadow:
    inset 0 0 0 2px var(--ml-aura, var(--brand-2)),
    inset 0 1px 0 rgba(255, 255, 255, .14),
    0 0 18px -6px var(--ml-aura, var(--brand-glow)),
    0 3px 0 #0A0F1A;
  color: var(--ink);
  font-size: 22px;
  font-weight: 900;
  line-height: 1;
}
.ms-av[data-len="2"] { font-size: 16px; }
.ms-av[data-len="3"] { font-size: 12px; letter-spacing: -.01em; }
/* the nation badge sits above the portrait (z 1) and the guild rank (z 2), never under them */
.ms-flag {
  position: absolute;
  right: -4px;
  bottom: -4px;
  z-index: 3;
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  border: 2px solid #0b0f19;
  background: #0b0f19;
  box-shadow: 0 5px 10px -3px rgba(0, 0, 0, .8);
  pointer-events: none;
}
.ms-flag:empty { display: none; }
.ms-flag .fp-ms { --fp-d: 22px; }
.ms-flag .fp-ms .fp-chip { border-radius: 50%; box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .4); }
.ms-flag .fp-ms .fp-img { box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .35); }
.fp-ms { --fp-d: 24px; }
.fp-ms .fp-chip { border-radius: 9px; font-size: 8px; box-shadow: inset 0 0 0 1px #0A0F1A, 0 0 0 2px #1C2433; }
.fp-ms .fp-img { border-radius: 50%; box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .35), 0 0 0 2px #1C2433; }

/* the identity column hugs its copy instead of stretching, so RTL text can never
   drift across the header into the close key */
.ms-id {
  flex: 0 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  text-align: start;
}
.ms-name {
  max-width: 100%;
  font-size: var(--t-1);
  font-weight: 900;
  letter-spacing: -.01em;
  line-height: 1.2;
  color: var(--ink);
  unicode-bidi: isolate;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ms-sub {
  max-width: 100%;
  font-size: 9.5px;
  font-weight: 900;
  letter-spacing: .06em;
  text-transform: uppercase;
  line-height: 1.3;
  color: var(--ml-aura, var(--brand-ink));
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* a mind carries no rank tier: hide the subtitle slot entirely when it is empty */
.ms-sub:empty { display: none; }
/* 48px circular clay key: the house extrusion, sunk by the same travel as .gm-key */
.ms-x {
  --d: 3px;
  position: relative;
  flex: none;
  margin-left: auto;
  appearance: none;
  border: 0;
  font: inherit;
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  padding: 0;
  border-radius: 50%;
  background: linear-gradient(180deg, #2E3A55 0%, #232E44 100%);
  color: var(--ink);
  cursor: pointer;
  box-shadow:
    0 var(--d) 0 #080C14,
    inset 0 1px 0 rgba(255, 255, 255, .14),
    var(--clay-ring);
  transition: transform var(--motion-fast), color var(--motion-fast), box-shadow var(--motion-fast);
}
.ms-x-g { font-size: 26px; font-weight: 600; line-height: .8; }
.ms-x:hover:not(:active) { color: var(--brand-ink); }
.ms-x:active { transform: translateY(var(--press-y)); --d: 0px; }
.ms-x:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }

/* ---- body ---- */
.ms-body { gap: var(--s3); padding-right: 2px; }

/* ---- the TIQ plaque: two balanced columns over one obsidian pane ----
   Start side carries the reading (label · digits · wins/rank pill), the end side
   the percentile gauge, split by one lit hairline. Radial gold and cyan bloom
   under the glass; the rim stays a single quiet line. */
.ms-hero {
  position: relative;
  flex: none;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 1px auto;
  align-items: center;
  gap: 12px;
  min-width: 0;
  padding: 12px 14px;
  border-radius: 18px;
  overflow: hidden;
  background:
    radial-gradient(120% 170% at 0% 0%, rgba(245, 158, 11, .16) 0%, rgba(245, 158, 11, 0) 54%),
    radial-gradient(95% 150% at 100% 100%, rgba(56, 189, 248, .14) 0%, rgba(56, 189, 248, 0) 60%),
    linear-gradient(180deg, rgba(255, 255, 255, .055) 0%, rgba(255, 255, 255, 0) 48%),
    linear-gradient(180deg, #182134 0%, #0D1422 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 0 0 1px rgba(245, 158, 11, .18),
    inset 0 -1px 0 rgba(0, 0, 0, .5),
    0 1px 0 #080D16,
    0 16px 30px -26px #000;
}
.ms-hero::after {
  content: '';
  position: absolute;
  inset: 0 16% auto;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(251, 191, 36, .6) 32%, rgba(56, 189, 248, .42) 70%, transparent);
  pointer-events: none;
}
.ms-hero-id { min-width: 0; display: flex; flex-direction: column; align-items: flex-start; gap: 4px; }
.ms-hero-k {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .16em;
  text-transform: uppercase;
  line-height: 1.2;
  color: #93A4BA;
}
.ms-hero-k::before {
  content: '';
  flex: none;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #FBBF24;
  box-shadow: 0 0 6px rgba(251, 191, 36, .85);
}
.ms-iq {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  color: var(--tiq);
  font-size: clamp(1.6rem, 1.35rem + 2.4vw, 2.1rem);
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  letter-spacing: -.02em;
  line-height: 1.05;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .55);
}
.ms-iq .tiq {
  flex: none;
  width: 20px;
  height: 20px;
  color: var(--honey);
  filter: drop-shadow(0 0 7px rgba(245, 158, 11, .55));
}
.ms-iq b { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
/* wins · rank ride one quiet pill under the score */
.ms-hero-sub {
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  padding: 3px 8px;
  border-radius: 7px;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
  line-height: 1.3;
  color: #B8C6D8;
  background: rgba(148, 163, 184, .08);
  box-shadow: inset 0 0 0 1px rgba(148, 163, 184, .16);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ms-hero-split {
  align-self: stretch;
  width: 1px;
  min-height: 52px;
  background: linear-gradient(180deg, transparent, rgba(255, 255, 255, .16) 22%, rgba(255, 255, 255, .16) 78%, transparent);
}
/* the shared ring, one size up so the percentile is the first thing you read */
.ms-ring-col { flex: none; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 5px; min-width: 72px; }
.ms-ring-c {
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .1em;
  text-transform: uppercase;
  line-height: 1.1;
  color: var(--ink-soft);
  text-align: center;
}
.ms-ring { width: 60px; height: 60px; }
.ms-ring b {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  font-size: 14px;
  letter-spacing: -.02em;
  font-variant-numeric: tabular-nums;
}

.ms-block { flex: none; display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.ms-h {
  margin: 0;
  font-size: 9.5px;
  font-weight: 900;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--ink-soft);
  text-shadow: 0 1px 0 rgba(0, 0, 0, .7);
}

/* three recessed obsidian micro-cards: a hairline rim, a lit top edge and one
   gold tick over each figure — no capsule, no RPG bars */
.ms-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
  min-width: 0;
}
.ms-stat {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  min-width: 0;
  padding: 12px 6px 11px;
  border-radius: 13px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .045) 0%, rgba(255, 255, 255, .008) 58%),
    #0C1321;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .06),
    inset 0 -1px 0 rgba(0, 0, 0, .55),
    inset 0 0 0 1px rgba(255, 255, 255, .055),
    0 2px 0 #080D16;
}
.ms-stat::before {
  content: '';
  position: absolute;
  inset: 0 22% auto;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(251, 191, 36, .38), transparent);
  pointer-events: none;
}
.ms-stat-v {
  font-size: clamp(1.05rem, .95rem + .9vw, 1.35rem);
  font-weight: 900;
  line-height: 1.1;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
  letter-spacing: .01em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ms-stat-l {
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
  line-height: 1.2;
  color: #8697AD;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Form + chips share one baseline row; the caption can never drift to the far edge */
.ms-block.is-inline {
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  min-width: 0;
}
.ms-block.is-inline .ms-h { flex: none; }
.ms-form { display: flex; align-items: center; gap: var(--s2); min-width: 0; }
.ms-dots { flex: none; display: flex; gap: 5px; }
.ms-dot {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  font-size: 11px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
/* emerald won with a bevel and a neon kiss; a lost race keeps the muted slate face */
.ms-dot.w {
  background: linear-gradient(180deg, #43E0AC 0%, #10A97A 52%, #077452 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .4),
    inset 0 -2px 2px rgba(0, 0, 0, .3),
    0 2px 0 #043D2C,
    0 0 10px -2px rgba(52, 211, 153, .7);
  color: #E9FFF7;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .3);
}
.ms-dot.l {
  background: linear-gradient(180deg, #334155 0%, #1E293B 58%, #131C2B 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .13),
    inset 0 -2px 2px rgba(0, 0, 0, .36),
    0 2px 0 #080D16;
  color: #C3CEDD;
}
.ms-dot.u { background: var(--field); box-shadow: var(--inset); color: var(--ink-soft); }
/* ---- the relic vault: three pedestals between the TIQ plaque and the scorecard ----
   One frosted obsidian shelf plate carries the row; a minted honor stands on a lit
   pedestal wearing its own accent's aura, and an unfilled socket stays recessed,
   dashed and silent. The shelf never grows past three columns, so a 320px phone
   reads the same row as a desktop. */
.relic-showcase-row {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
  min-width: 0;
  padding: 9px 8px 8px;
  border-radius: 15px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .04) 0%, rgba(255, 255, 255, .006) 58%),
    rgba(16, 22, 36, .6);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .08),
    inset 0 0 0 1px rgba(148, 163, 184, .09),
    inset 0 -1px 0 rgba(0, 0, 0, .5),
    0 2px 0 #080D16;
}
.relic-showcase-row::after {
  content: '';
  position: absolute;
  inset: 0 20% auto;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(251, 191, 36, .34) 34%, rgba(56, 189, 248, .26) 68%, transparent);
  pointer-events: none;
}

.relic-socket {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 0;
  /* a shelf of bare sockets keeps the same height as a shelf of minted ones */
  min-height: 75px;
  padding: 10px 4px 8px;
  border: 0;
  border-radius: 12px;
  font: inherit;
  appearance: none;
  -webkit-tap-highlight-color: transparent;
  --relic-aura: rgba(148, 163, 184, .4);
  --relic-rim: rgba(148, 163, 184, .3);
  --relic-ink: #CBD5E1;
}
/* cyan = Churchill titanium · amber = Einstein gold · emerald = Heisenberg chrome */
.relic-socket[data-accent="titanium"] { --relic-aura: rgba(34, 211, 238, .6); --relic-rim: rgba(34, 211, 238, .46); --relic-ink: #A5F3FC; }
.relic-socket[data-accent="quantum"]  { --relic-aura: rgba(245, 158, 11, .68); --relic-rim: rgba(245, 158, 11, .52); --relic-ink: #FDE047; }
.relic-socket[data-accent="frost"]    { --relic-aura: rgba(52, 211, 153, .6); --relic-rim: rgba(52, 211, 153, .48); --relic-ink: #6EE7B7; }

.relic-socket.is-owned {
  cursor: pointer;
  background:
    radial-gradient(80% 62% at 50% 0%, rgba(255, 255, 255, .06) 0%, rgba(255, 255, 255, 0) 70%),
    linear-gradient(180deg, #131B2C 0%, #0A101C 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .1),
    inset 0 0 0 1px var(--relic-rim),
    0 6px 14px -8px #000;
  transition: transform .13s ease, box-shadow .2s ease;
}
.relic-socket.is-owned:hover:not(:active) { transform: translateY(-1px); }
.relic-socket.is-owned:active { transform: scale(.95); transition-duration: .04s; }
.relic-socket.is-owned:focus-visible { outline: 2px solid var(--brand-2); outline-offset: 2px; }

/* the ambient bloom behind a minted coin — opacity only, so it can never push the row wider */
.relic-halo {
  position: absolute;
  inset: 4px 16% 24px;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 44%, var(--relic-aura) 0%, rgba(0, 0, 0, 0) 70%);
  filter: blur(4px);
  opacity: .5;
  animation: ms-relic-breathe 5.2s ease-in-out infinite;
  pointer-events: none;
}
@keyframes ms-relic-breathe {
  0%, 100% { opacity: .34; }
  50% { opacity: .62; }
}

.relic-frame {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: clamp(38px, 11vw, 46px);
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 22%, rgba(255, 255, 255, .14) 0%, rgba(255, 255, 255, .02) 46%, rgba(0, 0, 0, .35) 100%);
  box-shadow:
    0 2px 6px rgba(0, 0, 0, .72),
    0 10px 18px -12px #000,
    0 0 0 1px var(--relic-rim),
    0 0 14px -4px var(--relic-aura),
    inset 0 1px 0 rgba(255, 255, 255, .16);
}
.relic-frame .relic-coin {
  display: block;
  width: 82%;
  height: 82%;
  border-radius: 50%;
  filter: saturate(1.06) contrast(1.05) drop-shadow(0 1px 2px rgba(0, 0, 0, .7));
}

/* the engraved micro plaque: Latin digits, isolated from the sheet's own run direction */
.relic-tag {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  max-width: 100%;
  height: 13px;
  padding: 0 5px;
  border-radius: 4px;
  font-family: var(--ml-mono, ui-monospace, Menlo, Consolas, monospace);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: .04em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--relic-ink);
  background: linear-gradient(180deg, #0B111C 0%, #060A11 100%);
  box-shadow:
    inset 0 1px 2px rgba(0, 0, 0, .95),
    inset 0 0 0 1px rgba(255, 255, 255, .07),
    0 0 0 1px var(--relic-rim);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  unicode-bidi: isolate;
}

.relic-socket.is-empty {
  background: linear-gradient(180deg, rgba(6, 10, 17, .9) 0%, rgba(9, 14, 24, .72) 100%);
  box-shadow:
    inset 0 2px 5px rgba(0, 0, 0, .75),
    inset 0 0 0 1px rgba(255, 255, 255, .035);
}
.relic-ghost {
  width: clamp(30px, 9vw, 36px);
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  border: 1px dashed rgba(148, 163, 184, .35);
  background: radial-gradient(circle at 50% 35%, rgba(255, 255, 255, .03) 0%, rgba(255, 255, 255, 0) 70%);
  opacity: .35;
}
@media (prefers-reduced-motion: reduce) {
  .relic-halo { animation: none; opacity: .5; }
  .relic-socket.is-owned { transition: none; }
}

/* ---- foot keys: one locked obsidian plate, one luminous squad door ---- */
.ms-acts { flex: none; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--s2); margin-top: var(--s2); }
.ms-challenge,
.ms-guild {
  --d: 4px;
  position: relative;
  appearance: none;
  border: 0;
  font: inherit;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-width: 0;
  height: 48px;
  padding: 0 8px;
  border-radius: var(--radius-pill);
  font-size: var(--t-micro);
  font-weight: 900;
  letter-spacing: .01em;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  transition: transform var(--motion-fast), box-shadow var(--motion-fast), color var(--motion-fast);
}
.ms-challenge .ico,
.ms-guild .ico { flex: none; width: 15px; height: 15px; }
.ms-challenge span,
.ms-guild span { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
/* the locked key: a frozen frosted-obsidian plate — no fill, no lift, no press */
.ms-challenge {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .07) 0%, rgba(255, 255, 255, .015) 100%),
    #151D2C;
  color: #93A4BA;
  text-shadow: none;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, .09),
    inset 0 1px 0 rgba(255, 255, 255, .08),
    inset 0 -2px 3px rgba(0, 0, 0, .34),
    0 var(--d) 0 #090E17;
}
.ms-challenge:disabled,
.ms-challenge[aria-disabled="true"] {
  opacity: .55;
  cursor: not-allowed;
  pointer-events: none;
  color: #8C9BB0;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .05) 0%, rgba(255, 255, 255, .01) 100%),
    #131A28;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, .07),
    inset 0 1px 0 rgba(255, 255, 255, .06),
    inset 0 -2px 3px rgba(0, 0, 0, .3),
    0 4px 0 #090E17;
  transform: none;
}
.ms-ico-lock { display: none; }
.ms-challenge:disabled .ms-ico-key { display: none; }
.ms-challenge:disabled .ms-ico-lock { display: block; color: #A9B7C9; }
/* the hero squad door: obsidian depth with a gold-cyan aura and a lit rim */
.ms-guild {
  background:
    radial-gradient(120% 170% at 12% 0%, rgba(251, 191, 36, .26) 0%, rgba(251, 191, 36, 0) 52%),
    radial-gradient(120% 170% at 88% 100%, rgba(56, 189, 248, .3) 0%, rgba(56, 189, 248, 0) 58%),
    linear-gradient(180deg, rgba(255, 255, 255, .16) 0%, rgba(255, 255, 255, .02) 46%),
    linear-gradient(180deg, #22314C 0%, #121A2B 100%);
  color: #F1F8FF;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .5);
  box-shadow:
    inset 0 0 0 1px rgba(251, 191, 36, .38),
    inset 0 1px 0 rgba(255, 255, 255, .24),
    inset 0 -2px 3px rgba(0, 0, 0, .34),
    0 var(--d) 0 #070C15,
    0 calc(var(--d) + 10px) 22px -10px rgba(56, 189, 248, .55);
}
.ms-guild .ico { color: #FCD34D; filter: drop-shadow(0 0 4px rgba(251, 191, 36, .55)); }
/* no squad to open: the hero door rests as a muted obsidian plate, never a live key */
.ms-guild:disabled,
.ms-guild[aria-disabled="true"] {
  opacity: .55;
  cursor: not-allowed;
  color: #93A4BA;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .06) 0%, rgba(255, 255, 255, .012) 100%),
    #151D2C;
  text-shadow: none;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, .08),
    inset 0 1px 0 rgba(255, 255, 255, .07),
    inset 0 -2px 3px rgba(0, 0, 0, .32),
    0 4px 0 #090E17;
  transform: none;
}
.ms-guild:disabled .ico,
.ms-guild[aria-disabled="true"] .ico { color: #8C9BB0; filter: none; }
.ms-challenge:not(:disabled):active,
.ms-guild:not(:disabled):active { transform: translateY(var(--press-y)); --d: 1px; }
.ms-challenge:not(:disabled):focus-visible,
.ms-guild:not(:disabled):focus-visible { outline: 3px solid var(--brand-2); outline-offset: 3px; }

/* ==========================================================================
   THE SEIZE RELIC KEY AND THE CONFRONTATION CARD — when the mind under
   inspection stands on a serial that is not under its shield, the parked
   challenge plate wakes as a combat key. Same 48px geometry, same foot slot:
   the sheet never shifts when the offer appears. The card it opens keeps the
   certificate's centered obsidian head and puts one medallion on the table.
   ========================================================================== */

.ms-challenge.is-seize {
  background:
    radial-gradient(120% 170% at 10% 0%, rgba(224, 38, 79, .44) 0%, rgba(224, 38, 79, 0) 55%),
    radial-gradient(120% 170% at 90% 100%, rgba(251, 191, 36, .3) 0%, rgba(251, 191, 36, 0) 58%),
    linear-gradient(180deg, rgba(255, 255, 255, .15) 0%, rgba(255, 255, 255, .02) 46%),
    linear-gradient(180deg, #3B1B28 0%, #1A1020 52%, #121A2B 100%);
  color: #FFEDD5;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .58);
  box-shadow:
    inset 0 0 0 1px rgba(251, 191, 36, .44),
    inset 0 1px 0 rgba(255, 255, 255, .2),
    inset 0 -2px 3px rgba(0, 0, 0, .4),
    0 var(--d) 0 #0A0710;
}
/* the breath rides an overlay's opacity, not the shadow stack: animating box-shadow
   repaints the whole plate every frame, and a key this large is on screen while reading */
.ms-challenge.is-seize::after {
  content: '';
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  pointer-events: none;
  box-shadow: 0 10px 26px -8px rgba(224, 38, 79, .8), 0 0 0 1px rgba(251, 191, 36, .3);
  animation: ms-seize-breathe 2.6s ease-in-out infinite;
}
@keyframes ms-seize-breathe {
  0%, 100% { opacity: .3; }
  50% { opacity: 1; }
}
.ms-challenge.is-seize .ico { color: #FCA5A5; filter: drop-shadow(0 0 5px rgba(224, 38, 79, .75)); }
.ms-challenge.is-seize:hover:not(:active) { transform: translateY(-1px); }
.ms-challenge.is-seize:active { transform: translateY(var(--press-y)); }

/* ---- the shelf's own verdict: one line, never a second panel ---- */
.ms-shelter {
  margin: 0;
  align-self: flex-start;
  max-width: 100%;
  padding: 4px 9px;
  border-radius: var(--radius-pill);
  font-size: 10px;
  font-weight: 800;
  line-height: 1.4;
  color: #8394AC;
  background: rgba(148, 163, 184, .07);
  box-shadow: inset 0 0 0 1px rgba(148, 163, 184, .14);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ms-shelter[data-state="open"] {
  color: #FECACA;
  background: linear-gradient(180deg, rgba(224, 38, 79, .2), rgba(224, 38, 79, .08));
  box-shadow: inset 0 0 0 1px rgba(224, 38, 79, .46);
}
/* an exposed pedestal takes the rim the shield no longer carries; a guarded one steps back */
.relic-socket[data-shelter="open"] { box-shadow: inset 0 0 0 1px rgba(224, 38, 79, .5), 0 4px 14px -6px rgba(224, 38, 79, .55); }
.relic-socket[data-shelter="guarded"] { opacity: .78; }

/* ---- the confrontation card ---- */
.sheet.seize-sheet {
  gap: 10px;
  background:
    radial-gradient(120% 90% at 50% 0%, rgba(224, 38, 79, .16) 0%, rgba(224, 38, 79, 0) 58%),
    linear-gradient(180deg, var(--solid-a) 0%, var(--solid-b) 100%);
}
.sz-head { position: relative; flex: none; }
.sz-title {
  margin: 0;
  padding-inline: 42px;
  text-align: center;
  font-size: 14px;
  line-height: 1.3;
  font-weight: 900;
  color: #FFE4E6;
}
.sz-sub {
  margin: 3px 0 0;
  padding-inline: 42px;
  text-align: center;
  font-size: 8.5px;
  line-height: 1.4;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: #9B7A86;
}
.sz-x {
  position: absolute;
  top: -2px;
  right: 0;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 50%;
  cursor: pointer;
  font-size: 20px;
  line-height: 1;
  color: #C6B3B8;
  background: rgba(255, 255, 255, .05);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .08);
}
.sz-x:active { transform: scale(.92); }
.sz-x:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }

.sz-body { gap: 10px; padding-bottom: 2px; }

/* the medallion on the table: crest left, its name and serial beside it */
.sz-relic {
  flex: none;
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr);
  align-items: center;
  gap: 11px;
  padding: 10px;
  border-radius: 14px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .05), rgba(255, 255, 255, 0) 60%),
    var(--field);
  box-shadow: inset 0 0 0 1px rgba(251, 191, 36, .22), inset 0 1px 0 rgba(255, 255, 255, .06);
}
.sz-crest { display: grid; place-items: center; width: 58px; height: 58px; }
.sz-crest .sz-crest-ico { width: 58px; height: 58px; display: block; filter: drop-shadow(0 3px 8px rgba(0, 0, 0, .6)); }
.sz-relic-id { min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.sz-honor {
  font-size: 13px;
  font-weight: 900;
  line-height: 1.3;
  color: #F1F8FF;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sz-serial {
  align-self: flex-start;
  max-width: 100%;
  font-family: var(--font-stat);
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: .03em;
  line-height: 1.3;
  color: var(--gold-ink);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sz-holder {
  flex: none;
  margin: 0;
  display: flex;
  align-items: baseline;
  gap: 6px;
  font-size: 11px;
  line-height: 1.5;
}
.sz-holder-lbl { color: #7D8DA5; }
.sz-holder-name {
  min-width: 0;
  font-weight: 900;
  color: #E7EDF7;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sz-shelter {
  flex: none;
  margin: 0;
  text-align: center;
  font-size: 11px;
  font-weight: 800;
  line-height: 1.5;
  color: #8FA0B8;
}
.sz-shelter[data-state="open"] { color: #FCA5A5; }
.sz-shelter[data-state="guarded"] { color: #93A4BA; }

/* the two figures the seat costs: one slab each, equal, never a running total */
.sz-stakes {
  flex: none;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}
.sz-stake {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 9px 10px;
  border-radius: 12px;
  background: linear-gradient(180deg, rgba(255, 255, 255, .04), rgba(255, 255, 255, 0) 62%), var(--field);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .07);
}
.sz-stake.is-entry { box-shadow: inset 0 0 0 1px rgba(224, 38, 79, .3); }
.sz-stake-l {
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .1em;
  text-transform: uppercase;
  line-height: 1.3;
  color: #72829A;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sz-stake-v { display: flex; align-items: baseline; gap: 4px; min-width: 0; }
.sz-stake-v b {
  font-family: var(--font-stat);
  font-size: 17px;
  font-weight: 900;
  line-height: 1.15;
  font-variant-numeric: tabular-nums;
  color: #F1F8FF;
}
.sz-stake.is-entry .sz-stake-v b { color: #FECACA; }
.sz-unit { font-style: normal; font-size: 9px; font-weight: 700; color: #7D8DA5; }

.sz-bounty {
  flex: none;
  margin: 0;
  padding: 8px 10px;
  border-radius: 10px;
  text-align: center;
  font-size: 11px;
  font-weight: 900;
  line-height: 1.4;
  color: var(--gold-ink);
  background: linear-gradient(180deg, rgba(251, 191, 36, .12), rgba(251, 191, 36, .04));
  box-shadow: inset 0 0 0 1px rgba(251, 191, 36, .26);
}

.sz-note {
  flex: none;
  margin: 0;
  font-size: 9.5px;
  line-height: 1.6;
  text-align: center;
  color: #6E7E96;
}

.sz-foot { flex: none; padding-top: 2px; }
.sz-cta {
  --d: 4px;
  position: relative;
  appearance: none;
  border: 0;
  font: inherit;
  width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 0;
  height: 50px;
  padding: 0 12px;
  border-radius: var(--radius-pill);
  font-size: var(--t-micro);
  font-weight: 900;
  letter-spacing: .01em;
  line-height: 1.1;
  cursor: pointer;
  color: #FFEDD5;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .58);
  background:
    radial-gradient(120% 170% at 12% 0%, rgba(224, 38, 79, .46) 0%, rgba(224, 38, 79, 0) 54%),
    radial-gradient(120% 170% at 88% 100%, rgba(251, 191, 36, .32) 0%, rgba(251, 191, 36, 0) 58%),
    linear-gradient(180deg, rgba(255, 255, 255, .15) 0%, rgba(255, 255, 255, .02) 46%),
    linear-gradient(180deg, #3B1B28 0%, #1A1020 52%, #121A2B 100%);
  box-shadow:
    inset 0 0 0 1px rgba(251, 191, 36, .44),
    inset 0 1px 0 rgba(255, 255, 255, .2),
    inset 0 -2px 3px rgba(0, 0, 0, .4),
    0 var(--d) 0 #0A0710,
    0 calc(var(--d) + 10px) 24px -10px rgba(224, 38, 79, .6);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast);
}
.sz-cta .ico { flex: none; width: 15px; height: 15px; color: #FCA5A5; filter: drop-shadow(0 0 5px rgba(224, 38, 79, .75)); }
.sz-cta span { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.sz-cta:active { transform: translateY(var(--press-y)); --d: 1px; }
.sz-cta:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 3px; }
.sz-cta:disabled {
  opacity: .5;
  cursor: not-allowed;
  pointer-events: none;
  color: #93A4BA;
  text-shadow: none;
  background: linear-gradient(180deg, rgba(255, 255, 255, .05), rgba(255, 255, 255, .01)), #151D2C;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .08), 0 4px 0 #090E17;
  transform: none;
}
/* the parked challenge key keeps its lock, not the combat red: no glow survives the standby */
.sz-cta:disabled .ico { color: #8C9BB0; filter: none; }

/* ---- Persian: the card reads right-to-left, the numbers stay upright ---- */
.seize-sheet:lang(fa) :is(.sz-title, .sz-sub, .sz-honor, .sz-holder, .sz-shelter, .sz-bounty, .sz-note, .sz-stake-l, .sz-unit, .sz-cta) {
  font-family: 'Vazirmatn', system-ui, -apple-system, sans-serif;
  letter-spacing: 0;
  text-transform: none;
}
.seize-sheet:lang(fa) :is(.sz-head, .sz-body, .sz-relic-id, .sz-holder, .sz-stakes, .sz-foot) { direction: rtl; }
.seize-sheet:lang(fa) .sz-x { right: auto; left: 0; }

/* 320px: the crest gives first, then the stakes go stacked rather than squeezed */
@media (max-width: 360px) {
  .sz-relic { grid-template-columns: 50px minmax(0, 1fr); gap: 9px; padding: 9px; }
  .sz-crest, .sz-crest .sz-crest-ico { width: 50px; height: 50px; }
  .sz-honor { font-size: 12.5px; }
  .sz-stake-v b { font-size: 15.5px; }
  .sz-stake { padding: 8px 9px; }
}
@media (max-height: 640px) {
  .sz-note { display: none; }
  .sz-body { gap: 8px; }
}
@media (prefers-reduced-motion: reduce) {
  .ms-challenge.is-seize::after { animation: none; opacity: .55; }
  .ms-challenge.is-seize, .sz-cta, .bo-duel { transition: none; }
}

/* ==========================================================================
   THE SQUAD FACE OF THE MIND SHEET — real community photo, one rank badge,
   a frosted TIQ plate and a three-zone read. The header keeps the same 54px
   clay key; only the guild wears a photo, a metallic corner and a type tag.
   ========================================================================== */

/* the community photo sits inside the rim, so the cyan edge stays a true border */
.ms-av-img {
  position: absolute;
  inset: 3px;
  z-index: 1;
  width: calc(100% - 6px);
  height: calc(100% - 6px);
  border-radius: 13px;
  object-fit: cover;
  background: #0B1220;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, .38);
}
.ms-marks.is-guild .ms-av {
  border-radius: 17px;
  background: linear-gradient(180deg, #233049 0%, #0E1626 100%);
  box-shadow:
    inset 0 0 0 2px rgba(56, 189, 248, .85),
    inset 0 0 14px rgba(14, 165, 233, .3),
    0 0 20px -2px rgba(14, 165, 233, .55),
    0 3px 0 #0A0F1A;
}

/* one metallic rank, layered on the avatar corner where the flag sits for a mind */
.ms-rank {
  position: absolute;
  right: -6px;
  bottom: -6px;
  z-index: 2;
  display: grid;
  place-items: center;
  min-width: 27px;
  height: 19px;
  padding: 0 5px;
  border-radius: 7px;
  font-size: 9.5px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  letter-spacing: -.01em;
  line-height: 1;
  color: #1B1303;
  background: linear-gradient(180deg, #FFE9A8 0%, #E9B94C 52%, #B77A12 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .65),
    inset 0 -1px 0 rgba(0, 0, 0, .25),
    0 0 0 2px #1C2433,
    0 3px 7px -2px rgba(0, 0, 0, .8);
}
.ms-rank[hidden] { display: none; }
.ms-rank[data-rank="silver"] {
  color: #121A24;
  background: linear-gradient(180deg, #F4F8FC 0%, #C7D3E0 50%, #8B9AAC 100%);
}
.ms-rank[data-rank="bronze"] {
  color: #211005;
  background: linear-gradient(180deg, #F3C9A0 0%, #C98550 50%, #8D5424 100%);
}
.ms-rank[data-rank="num"] {
  color: #DBF2FE;
  background: linear-gradient(180deg, #3A4A67 0%, #26334B 52%, #172032 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .22),
    inset 0 -1px 0 rgba(0, 0, 0, .35),
    0 0 0 2px #1C2433,
    0 3px 7px -2px rgba(0, 0, 0, .8);
}

/* the subtitle carries the community kind and its handle, never the rank again */
#sheet-mind.is-guild .ms-sub {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
}
#sheet-mind.is-guild .ms-name { letter-spacing: -.015em; }
.ms-kind { flex: none; color: var(--brand-ink); }
.ms-sub-dot {
  flex: none;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: currentColor;
  opacity: .45;
}
.ms-handle {
  min-width: 0;
  direction: ltr;
  unicode-bidi: isolate;
  font-family: var(--font-numeric);
  font-weight: 800;
  letter-spacing: 0;
  text-transform: none;
  color: var(--ink-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* frosted plate: a cyan hairline over a deep-navy pane, with a soft corner bloom */
.ms-hero.is-squad {
  position: relative;
  overflow: hidden;
  padding: 12px 14px;
  border-radius: 18px;
  background:
    radial-gradient(120% 150% at 0% 0%, rgba(0, 210, 255, .16) 0%, rgba(0, 210, 255, 0) 56%),
    radial-gradient(100% 150% at 100% 100%, rgba(251, 191, 36, .12) 0%, rgba(251, 191, 36, 0) 58%),
    linear-gradient(180deg, rgba(255, 255, 255, .05) 0%, rgba(255, 255, 255, 0) 48%),
    linear-gradient(180deg, rgba(14, 24, 42, .75) 0%, rgba(9, 16, 30, .86) 100%);
  background-color: rgba(14, 24, 42, .75);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .12),
    inset 0 0 0 1px rgba(0, 210, 255, .2),
    0 14px 30px -22px #000;
}
.ms-hero.is-squad .ms-hero-k { color: #8FB4CC; }
.ms-hero.is-squad .ms-hero-k::before { background: #67E8F9; box-shadow: 0 0 6px rgba(103, 232, 249, .8); }
.ms-hero.is-squad .ms-iq {
  gap: 7px;
  color: #FBBF24;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .55);
}
.ms-hero.is-squad .ms-iq .tiq {
  width: 22px;
  height: 22px;
  color: #FBBF24;
  filter: drop-shadow(0 0 8px rgba(251, 191, 36, .7));
}
.ms-hero.is-squad .ms-hero-sub { color: #9FC3D8; }
.ms-hero.is-squad .ms-ring { width: 60px; height: 60px; }
.ms-hero.is-squad .ms-ring .mh-arc circle { stroke-width: 3.4; }
.ms-hero.is-squad .ms-ring .mh-arc-track { stroke: rgba(56, 189, 248, .15); }
.ms-hero.is-squad .ms-ring .mh-arc-fill { filter: drop-shadow(0 0 4px rgba(56, 189, 248, .8)); }
.ms-hero.is-squad .ms-ring b {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: radial-gradient(circle at 32% 26%, #22314C 0%, #0B1322 74%);
  color: #E0F7FF;
  font-size: 14px;
}
.ms-hero.is-squad .ms-ring-c { color: #7DD3FC; }

/* three focused cards: headcount · per-mind average · your slice of the pot */
.ms-squad-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  min-width: 0;
}
.ms-squad-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  padding: 9px 9px 10px;
  border-radius: 14px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .055) 0%, rgba(255, 255, 255, .012) 54%),
    var(--field);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .07),
    inset 0 -1px 0 rgba(0, 0, 0, .4),
    0 2px 0 #0A0F1A;
}
.ms-squad-top { display: flex; align-items: center; gap: 4px; min-width: 0; }
.ms-squad-ic {
  flex: none;
  width: 12px;
  height: 12px;
  color: var(--brand-3);
  filter: drop-shadow(0 0 4px rgba(56, 189, 248, .4));
}
.ms-squad-lbl {
  min-width: 0;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .07em;
  text-transform: uppercase;
  line-height: 1.2;
  color: var(--ink-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ms-squad-v {
  font-size: var(--t-1);
  font-weight: 900;
  line-height: 1.15;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ms-squad-card.is-share .ms-squad-v { color: #FCD34D; }
/* not a member yet: a quiet slate tag, never a bare dash */
.ms-squad-card.is-empty .ms-squad-v {
  align-self: flex-start;
  max-width: 100%;
  padding: 2px 6px;
  border-radius: 6px;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: uppercase;
  color: #8CA0B8;
  background: rgba(148, 163, 184, .1);
  box-shadow: inset 0 0 0 1px rgba(148, 163, 184, .16);
}

/* the guild door trades coral for a claymorphic emerald-cyan, matching the arena */
.ms-challenge.is-squad {
  background: linear-gradient(180deg, #5EEAD4 0%, #2DD4BF 46%, #0E92A8 100%);
  color: #032027;
  box-shadow:
    0 4px 0 #075E6B,
    0 12px 22px -10px rgba(45, 212, 191, .55),
    inset 0 2px 3px rgba(255, 255, 255, .45),
    inset 0 -2px 3px rgba(0, 0, 0, .2);
}
.ms-challenge.is-squad .ico { color: #053B47; }

/* ---- the tight phone: the keys lose their artwork before they lose a label ---- */
@media (max-width: 340px) {
  .ms-challenge .ico,
  .ms-guild .ico { display: none; }
  /* the lock is the whole message on a locked key, so it survives the tight phone */
  .ms-challenge:disabled .ms-ico-lock { display: block; }
  /* the squad sheet keeps its sword / channel glyph: both labels still fit beside them */
  #sheet-mind.is-guild .ms-challenge .ico,
  #sheet-mind.is-guild .ms-guild .ico { display: block; }
  .ms-dot { width: 25px; height: 25px; font-size: 10px; }
}

/* ---- the 320 floor: the type tag wraps before the handle is cut, and the
        third card's quiet tag keeps its words instead of ellipsising them ---- */
@media (max-width: 359px) {
  .ms-hero { gap: 9px; padding: 11px 12px; }
  .ms-hero-k { letter-spacing: .1em; }
  .ms-hero-sub { font-size: 8px; padding: 3px 6px; }
  .ms-ring-col { min-width: 62px; }
  .ms-ring { width: 54px; height: 54px; }
  .ms-ring b { width: 42px; height: 42px; font-size: 12.5px; }
  .ms-hero.is-squad .ms-ring { width: 56px; height: 56px; }
  .ms-hero.is-squad .ms-ring b { width: 44px; height: 44px; font-size: 13px; }
  #sheet-mind.is-guild .ms-sub {
    flex-direction: column;
    align-items: flex-start;
    gap: 0;
    white-space: normal;
  }
  #sheet-mind.is-guild .ms-sub-dot { display: none; }
  .ms-squad-lbl { font-size: 7.5px; letter-spacing: .04em; }
  .ms-squad-card.is-empty .ms-squad-v {
    font-size: 7.5px;
    letter-spacing: .02em;
    padding: 2px 4px;
    white-space: normal;
    overflow-wrap: anywhere;
    line-height: 1.3;
  }
}

/* ---- reduced motion: the throne still glows, it just stops moving ---- */
html.reduced-motion .ms-hero,
html.reduced-motion .ms-challenge,
html.reduced-motion .ms-guild,
html.reduced-motion .ms-x,
html.reduced-motion .lb-row { transition: none; }


/* ==========================================================================
   MATCHMAKING — the 1v1 Versus Arena stage (Quick match → Start 1v1 match).
   One full-viewport clay slab: a telemetry rail across the top, two extruded
   contender pods (you on a team-blue sphere, the rival still a scanner) either
   side of a tactical radar core with the VS medallion in it, then the search
   console, the stakes the race actually pays and a mind tip. Depth is the
   shared clay recipe — deep inner shadow, extruded lip, metallic top hairline —
   and nothing here carries a backdrop-filter. Every animation is
   transform/opacity only, so html.reduced-motion stills the whole stage.
   ========================================================================== */

.mm {
  position: absolute;
  inset: 0;
  z-index: 24;                          /* over the dock, the scrim and every sheet */
  display: flex;
  flex-direction: column;
  gap: var(--s3);
  /* the Telegram viewport is the phone's: the stage honours both safe areas */
  padding:
    max(var(--s3), env(safe-area-inset-top))
    max(var(--pad-app-x), env(safe-area-inset-right))
    max(var(--s3), env(safe-area-inset-bottom))
    max(var(--pad-app-x), env(safe-area-inset-left));
  background:
    radial-gradient(120% 72% at 50% 4%, rgba(56, 189, 248, .16), rgba(56, 189, 248, 0) 62%),
    radial-gradient(110% 60% at 50% 104%, rgba(255, 82, 43, .1), rgba(255, 82, 43, 0) 62%),
    linear-gradient(180deg, var(--bg-m) 0%, var(--bg) 56%, var(--bg-b) 100%);
  opacity: 0;
  transform: translate3d(0, 3%, 0);
  transition: opacity var(--motion-med), transform .3s var(--bounce);
  pointer-events: none;                 /* a fading stage never eats a tap */
  overflow: hidden;
}
.mm.open { opacity: 1; transform: none; pointer-events: auto; }
/* the match lands: one gold bloom across the stage, over in 300ms */
.mm::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(90% 62% at 50% 42%, rgba(252, 211, 77, .34), rgba(252, 211, 77, 0) 70%);
}
.mm.is-found::after { animation: mm-bloom .3s ease both; }
@keyframes mm-bloom {
  0%   { opacity: 0; }
  32%  { opacity: 1; }
  100% { opacity: 0; }
}
/* no motion: the bloom stops travelling and simply holds while the rival locks in */
html.reduced-motion .mm.is-found::after { animation: none; opacity: .34; }

/* ---- header: muted gold caps over the promise ---- */
.mm-head {
  flex: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--s1);
  text-align: center;
}
.mm-kicker {
  margin: 0;
  font-size: var(--t-micro);
  font-weight: 800;
  letter-spacing: .24em;
  text-indent: .24em;
  text-transform: uppercase;
  color: var(--tiq);
  opacity: .78;
}
.mm-title { margin: 0; font-size: var(--t-hd); font-weight: var(--w-2); color: var(--ink); }

/* ---- the arena card: a lit slab with the two sides' ambience pooled at the edges
       and a 2.5% engineering grid over the clay so the surface reads as an instrument ---- */
.mm-stage {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  max-height: 600px;
  margin: auto 0;                         /* a tall phone gets atmosphere, not a taller slab */
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;         /* the bands hold the card's top and bottom edges */
  gap: var(--s2);
  padding: var(--s3) var(--s2);
  border-radius: var(--r-panel);
  background:
    radial-gradient(56% 42% at 4% 38%, rgba(56, 189, 248, .15), rgba(56, 189, 248, 0) 68%),
    radial-gradient(56% 42% at 96% 38%, rgba(255, 82, 43, .14), rgba(255, 82, 43, 0) 68%),
    var(--clay-face);
  box-shadow: var(--clay), var(--clay-ring);
  overflow: hidden;
}
.mm-stage::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: .025;
  background-image:
    repeating-linear-gradient(0deg, #fff 0 1px, rgba(255, 255, 255, 0) 1px 9px),
    repeating-linear-gradient(90deg, #fff 0 1px, rgba(255, 255, 255, 0) 1px 9px);
}
/* the grid is a surface treatment, never a layer over the readout */
.mm-stage > * { position: relative; z-index: 1 }

/* ---- telemetry rail: what this seat, this radius and this board are running ---- */
.mm-tele {
  align-self: stretch;
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 4px 5px;
  border-radius: var(--radius-sm);
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair);
}
.mm-tele-c {
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 7px;
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, .045);
  box-shadow: inset 0 0 0 1px var(--hair), inset 0 1px 0 rgba(255, 255, 255, .1);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .05em;
  text-transform: uppercase;
  line-height: 1.25;
  color: var(--chip-ink);
  white-space: nowrap;
}
.mm-tele-c .ico { width: 11px; height: 11px; color: var(--brand-3); }
.mm-tele-c b { color: var(--ink); font-variant-numeric: tabular-nums; }
.mm-tele-c:first-child { color: var(--brand-ink); }
.mm-tele-c:first-child .ico { color: var(--brand-ink); }
.mm-tele-c:last-child .ico { color: var(--honey-ink); }
/* widened: the radius chip turns gold, because it is the one number that moved */
.mm-tele-c.is-wide {
  color: var(--tiq);
  background: rgba(252, 211, 77, .1);
  box-shadow: inset 0 0 0 1px rgba(252, 211, 77, .4), inset 0 1px 0 rgba(255, 255, 255, .1);
}
.mm-tele-c.is-wide .ico,
.mm-tele-c.is-wide b { color: var(--tiq); }

/* ---- the arena: two contender pods either side of the tactical core ---- */
.mm-arena {
  --orb: 84px;
  position: relative;
  align-self: stretch;
  flex: 1 1 auto;
  min-height: 0;
  max-height: 300px;
  display: grid;
  grid-template-columns: 1fr auto 1fr;   /* the pods stay partners, never a list */
  align-items: stretch;
  justify-items: center;
  gap: var(--s2);
}

.mm-pod {
  --aura: #38BDF8;
  --aura-glow: rgba(56, 189, 248, .42);
  --pod-shine: rgba(125, 211, 252, .5);
  position: relative;
  min-width: 0;
  min-height: 156px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-evenly;
  gap: 4px;
  padding: 8px 6px 9px;
  border-radius: var(--radius-md);
  background: linear-gradient(180deg, #26324B 0%, #1B2334 100%);
  box-shadow:
    var(--clay-drop),
    var(--clay-spec),
    var(--clay-bevel),
    inset 0 0 0 1px rgba(255, 255, 255, .06),
    inset 0 0 26px rgba(0, 0, 0, .4);
}
/* the metallic hairline along the top edge: the pod is lit from above */
.mm-pod::before {
  content: '';
  position: absolute;
  left: 12px;
  right: 12px;
  top: 0;
  height: 1px;
  border-radius: 1px;
  background: linear-gradient(90deg, rgba(255, 255, 255, 0), var(--pod-shine), rgba(255, 255, 255, 0));
}
.mm-pod.is-rival { --pod-shine: rgba(252, 211, 77, .46); --aura: #FCD34D; --aura-glow: rgba(252, 211, 77, .5); }

.mm-pod-role {
  flex: none;
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.mm-pod.is-you .mm-pod-role { color: var(--brand-ink); }
.mm-pod.is-rival .mm-pod-role { color: var(--honey-ink); }

/* ---- the sphere: a lit clay ball with the tier aura as its rim, not a flat disc ---- */
.mm-orb { position: relative; flex: none; width: var(--orb); height: var(--orb); }
.mm-aura {
  position: absolute;
  inset: -30%;
  border-radius: 50%;
  pointer-events: none;
  background: radial-gradient(closest-side, var(--aura-glow), rgba(0, 0, 0, 0) 72%);
}
.mm-face {
  position: relative;
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  overflow: hidden;
  background:
    radial-gradient(circle at 32% 24%, rgba(255, 255, 255, .6), rgba(255, 255, 255, 0) 42%),
    radial-gradient(circle at 66% 84%, rgba(0, 0, 0, .5), rgba(0, 0, 0, 0) 58%),
    radial-gradient(circle at 50% 36%, #7DD3FC 0%, #0EA5E9 44%, #0B3A5E 100%);
  box-shadow:
    inset 0 0 0 2px var(--aura),
    inset 0 5px 9px rgba(255, 255, 255, .16),
    inset 0 -7px 13px rgba(0, 0, 0, .45),
    0 10px 20px -10px rgba(0, 0, 0, .9),
    0 0 20px -4px var(--aura-glow);
}
.mm-img { position: relative; width: 100%; height: 100%; object-fit: cover; }
.mm-initial {
  position: relative;
  font-size: calc(var(--orb) * .38);
  font-weight: 900;
  line-height: 1;
  color: #fff;
  text-shadow: 0 2px 4px rgba(0, 0, 0, .55);
}
/* the rival is the other side of the arena: warm where you are cold */
.mm-pod.is-rival .mm-face {
  background:
    radial-gradient(circle at 32% 24%, rgba(255, 255, 255, .55), rgba(255, 255, 255, 0) 42%),
    radial-gradient(circle at 66% 84%, rgba(0, 0, 0, .55), rgba(0, 0, 0, 0) 58%),
    radial-gradient(circle at 50% 36%, #FFC49A 0%, #FF522B 44%, #5B1A0C 100%);
}
/* until the match lands there is no one in this sphere: a breathing slate ghost */
.mm-pod.is-rival:not(.is-locked) .mm-face {
  background:
    radial-gradient(circle at 32% 24%, rgba(255, 255, 255, .3), rgba(255, 255, 255, 0) 44%),
    radial-gradient(circle at 66% 84%, rgba(0, 0, 0, .55), rgba(0, 0, 0, 0) 58%),
    radial-gradient(circle at 50% 36%, #3B4A68 0%, #26314B 48%, #131A29 100%);
  box-shadow:
    inset 0 0 0 2px rgba(148, 163, 184, .42),
    inset 0 5px 9px rgba(255, 255, 255, .1),
    inset 0 -7px 13px rgba(0, 0, 0, .45),
    0 10px 20px -10px rgba(0, 0, 0, .9);
}
.mm-scan {
  position: relative;
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  color: #B6C2D6;
  animation: mm-breathe 1.7s ease-in-out infinite;
}
.mm-scan .ico { width: calc(var(--orb) * .46); height: calc(var(--orb) * .46); }
@keyframes mm-breathe {
  0%, 100% { opacity: .42; transform: scale(.94); }
  50%      { opacity: .92; transform: scale(1); }
}
/* the corner flag: the ladder's own photo cascade, in the pod's size */
.mm-flag { position: absolute; right: -3px; bottom: -3px; z-index: 2; --fp-d: 24px; }
.mm-flag .fp-chip { border-radius: 9px; font-size: 8px; box-shadow: inset 0 0 0 1px #0A0F1A, 0 0 0 2px #1C2433; }
.mm-flag .fp-img { box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .35), 0 0 0 2px #1C2433; }

/* locked in: the gold shockwave, then the pod settles with its new rival */
.mm-shock {
  position: absolute;
  inset: -5px;
  border-radius: 50%;
  box-shadow: inset 0 0 0 2px rgba(252, 211, 77, .95), 0 0 18px rgba(252, 211, 77, .55);
  opacity: 0;
  pointer-events: none;
}
.mm-pod.is-locked .mm-shock { animation: mm-shock .62s ease-out both; }
@keyframes mm-shock {
  0%   { opacity: 0; transform: scale(.74); }
  20%  { opacity: 1; }
  100% { opacity: 0; transform: scale(1.5); }
}
.mm-pod.is-locked { animation: mm-impact .3s var(--bounce) both; }
@keyframes mm-impact {
  0%   { transform: scale(.86); }
  55%  { transform: scale(1.07); }
  100% { transform: scale(1); }
}

.mm-pod-name {
  flex: none;
  max-width: 100%;
  overflow: hidden;
  font-size: var(--t-micro);
  font-weight: 900;
  letter-spacing: .02em;
  text-transform: uppercase;
  color: var(--ink);
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* TIQ is gold + the brain glyph, on a plaque that is extruded like every key */
.mm-plaque {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 100%;
  padding: 3px 9px;
  border-radius: 10px;
  background: var(--gold-face);
  box-shadow:
    0 3px 0 var(--gold-lip),
    inset 0 1px 0 rgba(255, 255, 255, .6),
    inset 0 -2px 3px rgba(0, 0, 0, .22),
    0 6px 14px -8px rgba(245, 158, 11, .85);
  font-size: var(--t-micro);
  font-weight: 900;
  line-height: 1.35;
  color: #2A1B04;
  font-variant-numeric: tabular-nums;
}
.mm-plaque .ico { width: 12px; height: 12px; color: #7A4A05; }
/* an unread rival sits in a groove; the lock is what pays out the gold */
.mm-pod.is-rival:not(.is-locked) .mm-plaque {
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px rgba(252, 211, 77, .26);
  color: var(--tiq);
}
.mm-pod.is-rival:not(.is-locked) .mm-plaque .ico { color: var(--honey-ink); }
.mm-pod.is-rival:not(.is-locked) .mm-pod-name { color: var(--ink-soft); }

/* ---- the tactical core: compass ring, sweep, synapse pulses, VS medallion ---- */
.mm-core {
  --core: 96px;
  position: relative;
  z-index: 1;
  flex: none;
  align-self: center;
  display: grid;
  place-items: center;
  width: var(--core);
  height: var(--core);
}
.mm-radar { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.mm-dial {
  fill: rgba(14, 21, 38, .62);
  stroke: rgba(56, 189, 248, .2);
  stroke-width: 1.5;
}
.mm-compass {
  fill: none;
  stroke: rgba(125, 211, 252, .46);
  stroke-width: 1.4;
  stroke-linecap: round;
  stroke-dasharray: 2 7;
  transform-box: view-box;
  transform-origin: 50px 50px;
  animation: mm-spin 15s linear infinite;
}
.mm-sweep {
  transform-box: view-box;
  transform-origin: 50px 50px;
  animation: mm-spin 3.4s linear infinite;
}
@keyframes mm-spin { to { transform: rotate(360deg); } }
.mm-axis { stroke: rgba(252, 211, 77, .34); stroke-width: 1.6; stroke-linecap: round; }
.mm-node { fill: var(--brand-3); animation: mm-flow 1.5s ease-in-out infinite; }
.mm-node.n-l2 { animation-delay: .18s; }
.mm-node.n-r { fill: var(--tiq); animation-delay: .5s; }
.mm-node.n-r2 { fill: var(--tiq); animation-delay: .68s; }
/* the nodes ride the axis toward their own pod: the bridge is live at both ends */
@keyframes mm-flow {
  0%, 100% { opacity: .28; transform: translateX(0); }
  50%      { opacity: 1; transform: translateX(-3px); }
}
.mm-node.n-r, .mm-node.n-r2 { animation-name: mm-flow-r; }
@keyframes mm-flow-r {
  0%, 100% { opacity: .28; transform: translateX(0); }
  50%      { opacity: 1; transform: translateX(3px); }
}
.mm-blip { fill: rgba(125, 211, 252, .8); animation: mm-blip 3.4s ease-in-out infinite; }
.mm-blip.b2 { animation-delay: 1.7s; }
@keyframes mm-blip {
  0%, 62%, 100% { opacity: 0; }
  68%           { opacity: .95; }
  88%           { opacity: .12; }
}
/* synapse pulses: they radiate from the core and stop at the pods' inner edge */
.mm-pulse {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 84px;
  height: 84px;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1.5px rgba(56, 189, 248, .46);
  opacity: 0;
  transform: translate(-50%, -50%) scale(.42);
  animation: mm-ping 2.6s cubic-bezier(.3, .6, .4, 1) infinite;
}
.mm-pulse.gold { box-shadow: inset 0 0 0 1.5px rgba(252, 211, 77, .42); animation-delay: .87s; }
.mm-pulse.p3 { animation-delay: 1.73s; }
@keyframes mm-ping {
  0%   { opacity: 0;  transform: translate(-50%, -50%) scale(.42); }
  18%  { opacity: .7; }
  100% { opacity: 0;  transform: translate(-50%, -50%) scale(1.22); }
}
/* the medallion: clay-and-gold, extruded, lit from above */
.mm-vs {
  position: relative;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background:
    radial-gradient(circle at 34% 24%, rgba(255, 255, 255, .62), rgba(255, 255, 255, 0) 46%),
    linear-gradient(180deg, #FDE68A 0%, #F59E0B 58%, #B45309 100%);
  box-shadow:
    0 4px 0 #7C3A06,
    0 0 0 2px rgba(252, 211, 77, .5),
    0 0 22px rgba(252, 211, 77, .4),
    inset 0 -5px 9px rgba(0, 0, 0, .3);
  animation: mm-throb 2.2s ease-in-out infinite;
}
.mm-vs-t {
  font-size: 17px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: .01em;
  color: #2A1B04;
  text-shadow: 0 1px 0 rgba(255, 255, 255, .45);
}
@keyframes mm-throb {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.055); }
}

/* ---- search console: the cycling line, the segmented sweep, the elapsed clock ---- */
.mm-console {
  align-self: stretch;
  flex: none;
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 7px 9px 8px;
  border-radius: var(--radius-sm);
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair);
}
.mm-status {
  margin: 0;
  min-height: 17px;
  font-size: var(--t-3);
  font-weight: 800;
  letter-spacing: .01em;
  color: var(--chip-ink);
  text-align: center;
}
.mm-status.swap { animation: mm-swap .46s ease both; }
@keyframes mm-swap {
  0%   { opacity: 0; transform: translateY(4px); }
  100% { opacity: 1; transform: none; }
}
.mm-console-row { display: flex; align-items: center; gap: var(--s2); }
.mm-seg { flex: 1 1 auto; min-width: 0; display: flex; gap: 3px; }
.mm-seg i {
  flex: 1 1 0;
  height: 7px;
  border-radius: 2px;
  background: linear-gradient(180deg, #38BDF8, #0284C7);
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .4);
  opacity: .16;
  transform: scaleY(.66);
  animation: mm-seg 1.2s linear infinite;
  animation-delay: calc(var(--i, 0) * .085s);
}
@keyframes mm-seg {
  0%, 74%, 100% { opacity: .16; transform: scaleY(.66); }
  16%, 44%      { opacity: 1;   transform: scaleY(1); }
}
.mm-timer {
  flex: none;
  margin: 0;
  font-size: var(--t-micro);
  font-weight: 900;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.mm-timer b { color: var(--tiq); font-variant-numeric: tabular-nums; letter-spacing: .02em; }

/* ---- stakes: the same numbers the settlement pays, on a raised clay key ---- */
.mm-stakes {
  align-self: stretch;
  flex: none;
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 5px 7px;
  border-radius: var(--radius-sm);
  background: linear-gradient(180deg, #26324B 0%, #1B2334 100%);
  box-shadow:
    var(--clay-spec),
    var(--clay-bevel),
    inset 0 0 0 1px rgba(255, 255, 255, .06),
    0 8px 16px -12px rgba(0, 0, 0, .9);
}
.mm-stakes-t {
  flex: none;
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .12em;
  text-transform: uppercase;
  line-height: 1.2;
  color: var(--ink-soft);
}
.mm-stakes-c {
  min-width: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 3px 6px;
  border-radius: 9px;
  background: rgba(255, 255, 255, .05);
  box-shadow: inset 0 0 0 1px var(--hair), inset 0 1px 0 rgba(255, 255, 255, .1);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .03em;
  text-transform: uppercase;
  line-height: 1.3;
  color: var(--chip-ink);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.mm-stakes-c .ico { width: 11px; height: 11px; }
.mm-stakes-c b { color: var(--ink); }
.mm-stakes-c.is-tiq, .mm-stakes-c.is-tiq .ico { color: var(--tiq); }
.mm-stakes-c.is-gold .ico { color: var(--honey-ink); }
.mm-stakes-c.is-cup .ico { color: var(--brand-ink); }

/* ---- mind tip: one inset footer card that keeps trading lines ---- */
.mm-tip {
  align-self: stretch;
  flex: none;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 8px;
  border-radius: var(--radius-sm);
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px rgba(125, 211, 252, .14);
}
.mm-tip > .ico { flex: none; width: 15px; height: 15px; color: var(--violet); }
.mm-tip-t {
  margin: 0;
  min-height: 25px;
  font-size: var(--t-micro);
  font-weight: 700;
  line-height: 1.3;
  color: var(--chip-ink);
}
.mm-tip-t.swap { animation: mm-swap .46s ease both; }

/* ---- a quiet queue: two clay keys appear under the stage, Cancel still below ----
   The same ghost key every other secondary action uses, only narrowed so the pair
   fits the stage's width. */
.mm-fallback {
  align-self: stretch;
  flex: none;
  display: flex;
  gap: var(--s2);
  width: 100%;
}
.mm-fallback.on { animation: mm-swap .46s ease both; }
.mm-fallback .btn {
  flex: 1 1 0;
  min-width: 0;
  padding: 0 var(--s3);
  font-size: var(--t-3);
}

/* ---- the one key on the stage: coral rim, real lip, sink on press ---- */
.mm-cancel {
  --d: 5px;
  flex: none;
  width: 100%;
  min-height: 52px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--s2);
  appearance: none;
  border: 0;
  font: inherit;
  font-size: var(--t-1);
  font-weight: 900;
  cursor: pointer;
  color: var(--ink);
  border-radius: var(--radius-md);
  background: linear-gradient(180deg, #2A3550 0%, #202A3E 100%);
  box-shadow:
    0 var(--d) 0 #0B0E14,
    inset 0 0 0 1.5px rgba(255, 82, 43, .48),
    inset 0 2px 3px rgba(255, 255, 255, .14),
    inset 0 -3px 6px rgba(0, 0, 0, .32);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast);
}
.mm-cancel .mm-x { font-size: 1.15em; line-height: 1; color: var(--cta-hi); }
.mm-cancel:hover:not(:active) { transform: translateY(-1px); }
.mm-cancel:active { transform: translateY(var(--press-y)); --d: 1px; }
.mm-cancel:focus-visible { outline: 3px solid var(--cta); outline-offset: 3px; }

/* ---- short and narrow phones: the arena gives before a control does ---- */
@media (max-height: 700px) {
  .mm-stage { gap: var(--s2); padding: var(--s2) var(--s2); }
  .mm-arena { --orb: 74px; max-height: 226px; }
  .mm-core { --core: 88px; }
  .mm-pulse { width: 78px; height: 78px; }
  .mm-vs { width: 42px; height: 42px; }
  .mm-vs-t { font-size: 16px; }
  .mm-cancel { min-height: 48px; }
}
@media (max-height: 620px) {
  .mm-arena { --orb: 66px; max-height: 196px; }
  .mm-pod { min-height: 150px; gap: 3px; padding: 6px 5px 7px; }
  .mm-core { --core: 80px; }
  .mm-pulse { width: 70px; height: 70px; }
}
@media (max-width: 340px) {
  .mm-tele { gap: 3px; padding: 4px 3px; }
  .mm-tele-c { padding: 3px 5px; font-size: 8px; letter-spacing: .03em; }
  .mm-stakes { gap: 3px; padding: 5px 5px; }
  .mm-stakes-c { padding: 3px 5px; font-size: 8px; }
  .mm-pod-name { max-width: 9ch; }
}
/* a tall phone: the arena takes the extra height before anything else does */
@media (min-height: 860px) {
  .mm-arena { --orb: 96px; }
  .mm-core { --core: 108px; }
  .mm-pulse { width: 94px; height: 94px; }
  .mm-vs { width: 52px; height: 52px; }
  .mm-vs-t { font-size: 19px; }
}

/* ---- reduced motion: the stage still reads, it just stops sweeping ---- */
html.reduced-motion .mm { transition: none; }
html.reduced-motion .mm-cancel { transition: none; }
html.reduced-motion .mm-compass,
html.reduced-motion .mm-sweep,
html.reduced-motion .mm-pulse,
html.reduced-motion .mm-node,
html.reduced-motion .mm-blip,
html.reduced-motion .mm-vs,
html.reduced-motion .mm-seg i,
html.reduced-motion .mm-scan,
html.reduced-motion .mm-shock,
html.reduced-motion .mm-status.swap,
html.reduced-motion .mm-tip-t.swap,
html.reduced-motion .mm-pod.is-locked { animation: none; }
/* the sweep is the only thing that would otherwise freeze mid-dial */
html.reduced-motion .mm-sweep { opacity: .5; }
html.reduced-motion .mm-seg i { opacity: .55; transform: none; }
html.reduced-motion .mm-blip { opacity: .5; }

/* ==========================================================================
   ADMIN COMMAND CENTER — the Home FAB and the
   full-viewport Dark Clay stage (src/admin.ts).
   Same one palette: opaque slabs, a real 0-blur extrusion under every key, a
   metallic top hairline, translateY press-sink. No backdrop-filter anywhere,
   and every interactive target is at least 48px.
   ========================================================================== */

/* ---- the Home key: a sculpted clay squircle, anchored above the launcher ---- */
.admin-fab {
  --d: 4px;
  position: absolute;
  right: 4px;                          /* the badge rides 3px past this edge: clip room */
  bottom: 168px;                       /* refined in JS: clears the PLAY dock */
  z-index: 6;
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  appearance: none;
  cursor: pointer;
  border-radius: 17px;
  background:
    radial-gradient(120% 100% at 50% -32%, rgba(255, 255, 255, .1), transparent 62%),
    var(--clay-face);
  box-shadow:
    0 var(--d) 0 #0A0E15,
    var(--clay-drop), var(--clay-spec), var(--clay-bevel),
    inset 0 0 0 1px rgba(56, 189, 248, .34),
    0 0 18px -6px rgba(56, 189, 248, .45);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast);
}
.admin-fab:active { transform: translateY(var(--press-y)); --d: 1px; }
.admin-fab:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 3px; }
.admin-fab-ico { width: 26px; height: 26px; color: var(--tiq); }
/* ---- the Home key's live-unread counter: a luxury obsidian micro-badge ----
   src/admin.ts owns `data-count`, `data-state`, `is-in` / `is-out` and `hidden`.
   One compact tabular pill perched on the key's top-end corner: a deep crimson
   gradient for ordinary unread, royal amber over obsidian ink when the set holds
   a VIP purchase. The 1.5px slate hairline is what separates it from the shield's
   rim; zero is an EXIT, not a blink — JS keeps the pill in the layout for one
   220ms scale-out, then takes it out for real. */
.admin-fab-badge {
  position: absolute;
  top: -3px;
  inset-inline-end: -3px;              /* logical: the top-end corner in every language */
  z-index: 2;
  display: grid;
  place-items: center;
  box-sizing: border-box;
  min-width: 18px;
  max-width: 40px;
  height: 18px;
  padding: 0 5px;
  border: 1.5px solid #0f172a;
  border-radius: 9999px;
  background: linear-gradient(135deg, #ef4444, #b91c1c);
  color: #ffffff;
  font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  text-align: center;
  letter-spacing: 0;
  white-space: nowrap;
  overflow: hidden;
  pointer-events: none;
  opacity: 1;
  transform: scale(1);
  box-shadow:
    0 0 10px rgba(239, 68, 68, .45),
    inset 0 1px 0 rgba(255, 255, 255, .22);
  transition:
    opacity .2s cubic-bezier(.16, 1, .3, 1),
    transform .2s cubic-bezier(.16, 1, .3, 1);
}
/* the amber variant: a VIP purchase in the unread set, gold over obsidian ink */
.admin-fab-badge[data-state="vip"] {
  background: linear-gradient(135deg, #fbbf24, #b45309);
  color: #1c1206;
  box-shadow:
    0 0 10px rgba(251, 191, 36, .45),
    inset 0 1px 0 rgba(255, 255, 255, .38);
}
/* the arrival: one crisp pop, never a bounce that outlives the count */
@keyframes badge-pop {
  from { opacity: 0; transform: scale(.55); }
  to   { opacity: 1; transform: scale(1); }
}
.admin-fab-badge.is-in { animation: badge-pop .24s cubic-bezier(.16, 1, .3, 1) both; }
/* the clear: scale down and fade; `hidden` follows once the exit has played */
.admin-fab-badge.is-out {
  opacity: 0;
  transform: scale(.4);
}
html.reduced-motion .admin-fab-badge,
html.reduced-motion .admin-fab-badge.is-in {
  animation: none !important;
  transition: none !important;
}
/* an author `display` beats the UA [hidden] rule — the rest state must really vanish */
.admin-fab-badge[hidden] { display: none !important; }
/* still used by the Server tab's live lamp (`.adm-server[data-state="live"] .adm-srv-lamp`) */
@keyframes adm-dot { 0%, 100% { opacity: 1 } 50% { opacity: .4 } }

/* ---- the stage: one full-viewport clay slab ---- */
.admin {
  position: absolute;
  inset: 0;
  z-index: 1002;                       /* over the dock, the sheets and matchmaking */
  display: flex;
  flex-direction: column;
  gap: var(--s3);
  /* the Telegram viewport is the phone's: the stage honours both safe areas */
  padding:
    max(var(--s3), env(safe-area-inset-top))
    max(var(--pad-app-x), env(safe-area-inset-right))
    max(var(--s3), env(safe-area-inset-bottom))
    max(var(--pad-app-x), env(safe-area-inset-left));
  background:
    radial-gradient(120% 70% at 50% 0%, rgba(252, 211, 77, .1), rgba(252, 211, 77, 0) 60%),
    radial-gradient(110% 60% at 50% 104%, rgba(56, 189, 248, .1), rgba(56, 189, 248, 0) 62%),
    linear-gradient(180deg, var(--bg-m) 0%, var(--bg) 56%, var(--bg-b) 100%);
  opacity: 0;
  transform: translate3d(0, 3%, 0);
  transition: opacity var(--motion-med), transform .3s var(--bounce);
  pointer-events: none;                /* a fading stage never eats a tap */
  overflow: hidden;
}
.admin.open { opacity: 1; transform: none; pointer-events: auto; }
html.reduced-motion .admin { transition: none; }

.admin-head { flex: none; display: flex; align-items: center; gap: var(--s2); }
.admin-head-txt { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
/* engraved amber kicker: wide warm tracking over a dark under-shadow is the whole illusion */
.admin-kicker {
  margin: 0;
  font-size: var(--t-micro);
  font-weight: 800;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--honey-ink);
  text-shadow: 0 1px 0 rgba(0, 0, 0, .6), 0 0 12px rgba(245, 158, 11, .28);
}
/* embossed: the title sits pressed into the slab, one dark chisel under one soft crown */
.admin-title {
  margin: 0;
  font-size: var(--t-hd);
  font-weight: var(--w-2);
  color: var(--ink);
  text-shadow: 0 1px 0 rgba(0, 0, 0, .45), 0 -1px 0 rgba(255, 255, 255, .12);
}
.admin-close {
  --d: 3px;
  flex: none;
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  appearance: none;
  cursor: pointer;
  border-radius: 12px;
  /* a recessed charcoal pellet: a deep floor, a rim-lit top edge, a sculpted bevel */
  background:
    radial-gradient(130% 110% at 50% -26%, rgba(255, 255, 255, .1), transparent 58%),
    linear-gradient(180deg, #1B2333 0%, #10151F 100%);
  color: var(--ink-soft);
  box-shadow:
    0 var(--d) 0 #0A0E15,
    0 10px 20px -6px rgba(0, 0, 0, .55),
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 -2px 5px rgba(0, 0, 0, .5),
    inset 0 0 0 1px rgba(255, 255, 255, .05);
  transition: transform .18s var(--bounce), box-shadow var(--motion-fast), color var(--motion-fast);
}
.admin-close-x { width: 15px; height: 15px; }
.admin-close:hover { color: var(--ink); }
.admin-close:active {
  transform: translateY(2px) scale(.96);
  --d: 1px;
  box-shadow:
    0 1px 0 #0A0E15,
    0 4px 10px -4px rgba(0, 0, 0, .5),
    inset 0 2px 6px rgba(0, 0, 0, .55),
    inset 0 1px 0 rgba(255, 255, 255, .06),
    inset 0 0 0 1px rgba(255, 255, 255, .04);
}
.admin-close:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
html.reduced-motion .admin-close { transition: none; }

/* ---- the tactile bottom dock: a recessed clay well with a springy gold pill ----
   Pinned under the scrolling body, above the safe area. Seven equal keys, one
   absolute gold pill that slides on the bounce curve, and a raised clay cap on
   the active tab. Every key stays a 48px+ target down to 360px. */
.admin-nav {
  flex: none;
  position: relative;
  display: flex;
  gap: 2px;
  min-height: 64px;
  padding: 5px;
  border-radius: var(--radius-lg);
  background:
    radial-gradient(120% 150% at 50% 0%, rgba(56, 189, 248, .08), rgba(56, 189, 248, 0) 58%),
    var(--field);
  box-shadow:
    var(--inset),
    inset 0 0 0 1px var(--hair-off),
    inset 0 -1px 0 rgba(255, 255, 255, .05),
    0 14px 28px -22px rgba(0, 0, 0, .9);
}
.admin-nav-pill {
  position: absolute;
  top: 5px;
  bottom: 5px;
  left: 5px;
  width: calc((100% - 22px) / 7);
  border-radius: var(--radius-md);
  background: linear-gradient(180deg, rgba(252, 211, 77, .2) 0%, rgba(245, 158, 11, .06) 100%);
  box-shadow:
    inset 0 0 0 1px rgba(252, 211, 77, .26),
    0 0 20px -6px rgba(245, 158, 11, .65);
  pointer-events: none;
  transition: transform .34s var(--bounce);
}
html.reduced-motion .admin-nav-pill { transition: none; }
.admin-tab {
  flex: 1 1 0;
  min-width: 0;
  min-height: 52px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  padding: 0;
  appearance: none;
  border: 0;
  font: inherit;
  cursor: pointer;
  position: relative;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--ink-soft);
  font-size: var(--t-micro);
  font-weight: 800;
  letter-spacing: .01em;
  transition: transform var(--motion-fast), box-shadow var(--motion-fast),
              background var(--motion-fast), color var(--motion-fast);
}
.admin-tab-ico {
  width: 20px;
  height: 20px;
  flex: none;
  transition: transform var(--motion-fast), filter var(--motion-fast), color var(--motion-fast);
}
.admin-tab-l {
  display: block;
  max-width: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.admin-tab:hover:not([aria-selected="true"]) .admin-tab-ico {
  color: var(--brand-ink);
  transform: translateY(-2px);
  filter: drop-shadow(0 0 6px rgba(125, 211, 252, .55));
}
.admin-tab:active { transform: translateY(var(--press-y)); }
.admin-tab:active .admin-tab-ico { transform: translateY(2px) scale(.92); }
.admin-tab:focus-visible { outline: 3px solid var(--brand-2); outline-offset: -3px; }
/* the live tab is a raised clay cap inside the well, lit by gold ambient glow */
.admin-tab[aria-selected="true"] {
  background: var(--clay-face);
  color: var(--ink);
  box-shadow:
    0 3px 0 #0A0E15,
    var(--clay-spec), var(--clay-bevel),
    inset 0 0 0 1px rgba(252, 211, 77, .34),
    0 0 22px -8px rgba(245, 158, 11, .8);
}
.admin-tab[aria-selected="true"] .admin-tab-ico {
  color: var(--honey-ink);
  animation: adm-ico-pop .42s var(--bounce) both;
}
@keyframes adm-ico-pop {
  0%   { transform: translateY(1px) scale(.8); }
  55%  { transform: translateY(-3px) scale(1.14); }
  100% { transform: translateY(0) scale(1); }
}
html.reduced-motion .admin-tab[aria-selected="true"] .admin-tab-ico { animation: none; }
/* the unread pill: amber clay sitting on the Inbox key's shoulder */
.admin-nav-badge {
  position: absolute;
  top: 4px;
  left: calc(50% + 7px);
  min-width: 18px;
  height: 18px;
  display: grid;
  place-items: center;
  padding: 0 5px;
  border-radius: var(--radius-pill);
  background: var(--gold-face);
  color: #10141D;
  font-size: 10px;
  font-weight: 900;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  box-shadow:
    0 2px 0 var(--gold-lip),
    0 0 12px -2px rgba(245, 158, 11, .85),
    inset 0 1px 0 rgba(255, 255, 255, .55);
}
.admin-nav-badge[hidden] { display: none; }
@media (max-height: 660px) {
  .admin-nav { min-height: 60px; padding: 4px; }
  .admin-nav-pill { top: 4px; bottom: 4px; left: 4px; width: calc((100% - 20px) / 7); }
  .admin-tab { min-height: 48px; }
}
@media (max-height: 600px) {
  .admin-tab { min-height: 44px; }
}
/* Seven keys get tight on a 320px phone: drop the printed labels, keep every
   accessible name via aria-label, and let the icons centre in the well. */
@media (max-width: 359px) {
  .admin-tab-l { display: none; }
  .admin-tab-ico { width: 22px; height: 22px; }
}

.admin-body {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  display: flex;
  flex-direction: column;
  gap: var(--s2);
  /* the dashboard is long now: the tail clears the pinned dock on every phone */
  padding-bottom: 80px;
}
.admin-panel { display: flex; flex-direction: column; gap: var(--s2); }

/* ---- Controls sub-navigation: three obsidian keys over the long control stack ----
   The wrapper is the sticky element and owns the stage-colored backdrop; the track
   itself stays the specified translucent glass. Every key is equal-width, so the
   bar fits a 320px phone without truncation or a horizontal scroll. */
.adm-ctrl-tabs-wrap {
  position: sticky;
  top: 0;
  z-index: 8;
  padding: 2px 0 7px;
  background: linear-gradient(180deg, var(--bg) 0%, var(--bg) 84%, rgba(16, 20, 29, 0) 100%);
}
.adm-ctrl-tabs {
  display: flex;
  gap: 4px;
  padding: 4px;
  border: 1px solid rgba(255, 255, 255, .08);
  border-radius: 9999px;
  background: rgba(255, 255, 255, .04);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .06),
    0 12px 26px -22px rgba(0, 0, 0, .95);
}
.adm-ctrl-tab {
  flex: 1 1 0;
  min-width: 0;
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 8px;
  appearance: none;
  border: 1px solid transparent;
  border-radius: 9999px;
  background: transparent;
  color: var(--ink-soft);
  font: inherit;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .01em;
  white-space: nowrap;
  cursor: pointer;
  transition:
    color var(--motion-fast),
    background var(--motion-fast),
    border-color var(--motion-fast),
    box-shadow var(--motion-fast);
}
.adm-ctrl-tab .ico { width: 14px; height: 14px; flex: none; color: currentColor; }
.adm-ctrl-tab:hover { color: var(--ink); background: rgba(255, 255, 255, .035); }
.adm-ctrl-tab[aria-selected="true"] {
  color: #FEF08A;
  font-weight: 700;
  background: linear-gradient(135deg, rgba(234, 179, 8, .2), rgba(234, 179, 8, .08));
  border-color: rgba(234, 179, 8, .4);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .14),
    0 0 18px -6px rgba(234, 179, 8, .55);
}
.adm-ctrl-tab:focus-visible { outline: 2px solid var(--honey-ink); outline-offset: 2px; }

/* one view at a time: hidden removes it from layout, the fade makes the swap feel intentional */
.adm-ctrl-view {
  display: flex;
  flex-direction: column;
  gap: var(--s2);
  opacity: 0;
  transition: opacity .15s ease-out;
}
.adm-ctrl-view[hidden] { display: none; }
.adm-ctrl-view.is-visible { opacity: 1; }
html.reduced-motion .adm-ctrl-view { transition: none; }
@media (max-width: 350px) {
  .adm-ctrl-tab { min-height: 40px; gap: 4px; padding: 0 4px; font-size: 10.5px; }
  .adm-ctrl-tab .ico { width: 13px; height: 13px; }
}

.adm-sec-h {
  display: flex;
  align-items: baseline;
  gap: var(--s2);
  margin: 0;
  font-size: var(--t-micro);
  font-weight: 800;
  letter-spacing: var(--ls-3);
  text-transform: uppercase;
  color: var(--ink-soft);
}
.adm-note { margin: var(--s2) 0 0; font-size: var(--t-micro); line-height: 1.45; color: var(--ink-soft); }

/* ==========================================================================
   STATS — the executive telemetry dashboard: a state rail, three sections
   (live engagement pulse, new-player inflow, retention & loyalty), each with
   its own accent and clay slab, over one quiet latency badge. Every number is
   the Worker's measured registry reading; the body scrolls, so it reads
   top-down in three seconds.
   ========================================================================== */
.admin-panel[data-apanel="stats"] { flex: 1 1 auto; min-height: 0; }

/* ---- the telemetry bar: a recessed rail with the state lamp, the exact capture time and the
        refresh key. Syncing / live / stale / locked / offline all read from `data-state`. ---- */
.adm-live {
  flex: none;
  display: flex;
  align-items: center;
  gap: var(--s2);
  min-height: 48px;
  padding: 4px 4px 4px 12px;
  border-radius: var(--radius-md);
  background: var(--field);
  box-shadow:
    var(--inset),
    inset 0 0 0 1px var(--hair-off),
    inset 0 -1px 0 rgba(255, 255, 255, .04);
}
.adm-live-state {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.adm-live-state::before {
  content: '';
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ink-soft);
  box-shadow: 0 0 0 3px rgba(148, 163, 184, .14);
}
.adm-live-state[data-state="live"] { color: var(--mint-ink); }
.adm-live-state[data-state="live"]::before {
  background: var(--mint);
  box-shadow: 0 0 0 3px rgba(16, 185, 129, .18), 0 0 10px 1px rgba(16, 185, 129, .75);
}
.adm-live-state[data-state="loading"],
.adm-live-state[data-state="stale"],
.adm-live-state[data-state="slow"] { color: var(--honey-ink); }
.adm-live-state[data-state="loading"]::before,
.adm-live-state[data-state="stale"]::before,
.adm-live-state[data-state="slow"]::before {
  background: var(--honey);
  box-shadow: 0 0 0 3px rgba(245, 158, 11, .18);
}
/* `error` is a Worker that answered and was wrong; only `offline` is one that never answered. */
.adm-live-state[data-state="locked"],
.adm-live-state[data-state="offline"],
.adm-live-state[data-state="error"] { color: var(--red-ink); }
.adm-live-state[data-state="locked"]::before,
.adm-live-state[data-state="offline"]::before,
.adm-live-state[data-state="error"]::before {
  background: var(--bad-1);
  box-shadow: 0 0 0 3px rgba(224, 38, 79, .18);
}
@media (prefers-reduced-motion: no-preference) {
  .adm-live-state[data-state="loading"]::before { animation: adm-pulse 1.4s ease-in-out infinite; }
}
html.reduced-motion .adm-live-state::before { animation: none; }
.adm-live-stamp {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: right;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--brand-ink);
  font-variant-numeric: tabular-nums;
}
.adm-live-refresh {
  flex: none;
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  padding: 0;
  appearance: none;
  border: 0;
  cursor: pointer;
  border-radius: calc(var(--radius-md) - 6px);
  background: var(--clay-face);
  color: var(--honey-ink);
  box-shadow: 0 var(--lip) 0 #0A0E15, var(--clay-drop), var(--clay-spec), var(--clay-bevel);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast), color var(--motion-fast);
}
.adm-live-refresh .ico { width: 16px; height: 16px; }
.adm-live-refresh:active { transform: translateY(var(--press-y)); --lip: 1px; }
.adm-live-refresh:focus-visible { outline: 3px solid var(--brand-2); outline-offset: -3px; }
.adm-live-refresh[data-busy="true"] { cursor: progress; color: var(--mint-ink); }
.adm-live-refresh[data-busy="true"] .ico { animation: adm-live-spin .75s linear infinite; }
@keyframes adm-live-spin { to { transform: rotate(360deg); } }
html.reduced-motion .adm-live-refresh[data-busy="true"] .ico { animation-duration: 1.8s; }

/* ---- the refusal / outage card: the panel says what happened, never what it wishes ---- */
.adm-alert {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 11px 12px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(224, 38, 79, .42);
  background: linear-gradient(180deg, rgba(74, 16, 34, .94) 0%, rgba(40, 12, 22, .96) 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .06), 0 12px 22px -18px rgba(0, 0, 0, .9);
}
.adm-alert[hidden] { display: none; }
.adm-alert[data-kind="offline"] {
  border-color: rgba(245, 158, 11, .42);
  background: linear-gradient(180deg, rgba(66, 45, 11, .94) 0%, rgba(34, 24, 10, .96) 100%);
}
.adm-alert-i {
  flex: none;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 10px;
  background: rgba(224, 38, 79, .18);
  color: var(--red-ink);
}
.adm-alert[data-kind="offline"] .adm-alert-i {
  background: rgba(245, 158, 11, .16);
  color: var(--honey-ink);
}
.adm-alert-i .ico { width: 16px; height: 16px; }
.adm-alert-txt { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.adm-alert-txt b {
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--red-ink);
}
.adm-alert[data-kind="offline"] .adm-alert-txt b { color: var(--honey-ink); }
.adm-alert-txt span { font-size: var(--t-micro); line-height: 1.45; color: var(--ink-soft); }

/* ---- the executive sections: accent tick, high-contrast title, quiet meta ---- */
.adm-block {
  --adm-accent: var(--brand-ink);
  --adm-accent-soft: rgba(125, 211, 252, .2);
  flex: none;
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.adm-block[data-accent="sky"] {
  --adm-accent: #38bdf8;
  --adm-accent-soft: rgba(56, 189, 248, .22);
}
.adm-block[data-accent="mint"] {
  --adm-accent: var(--mint-ink);
  --adm-accent-soft: rgba(16, 185, 129, .24);
}
.adm-block[data-accent="violet"] {
  --adm-accent: var(--violet);
  --adm-accent-soft: rgba(167, 139, 250, .24);
}
.adm-block[data-accent="gold"] {
  --adm-accent: var(--gold-ink);
  --adm-accent-soft: rgba(245, 158, 11, .26);
}
.adm-block-h { display: flex; align-items: baseline; gap: var(--s2); padding: 0 2px; }
.adm-block-t {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  margin: 0;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .12em;
  line-height: 1.2;
  text-transform: uppercase;
  color: var(--ink);
}
.adm-block-t::before {
  content: '';
  flex: none;
  width: 3px;
  height: 11px;
  border-radius: 2px;
  background: var(--adm-accent);
  box-shadow: 0 0 8px var(--adm-accent-soft), 0 0 0 1px rgba(0, 0, 0, .25);
}
.adm-block-s {
  margin-left: auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}

/* ---- the pulse grid: three compact clay tiles across the phone column ---- */
.adm-grid {
  flex: none;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}
.adm-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 3px;
  min-width: 0;
  min-height: 142px;
  padding: 10px 9px 11px;
  border-radius: var(--radius-md);
  background: var(--clay-face);
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring);
}
/* the icon chip rides the top row, next to the live dot when the card carries one */
.adm-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s2);
  min-height: 32px;
}
.adm-card-i,
.adm-tool-i {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 11px;
  background: var(--field);
  color: var(--brand-ink);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-card-i .ico,
.adm-tool-i .ico { width: 17px; height: 17px; }
.adm-card-i .coin,
.adm-tool-i .coin { width: 17px; height: 17px; }
/* the pulsing live mark: a mint ember against the slab */
.adm-live-dot {
  flex: none;
  width: 8px;
  height: 8px;
  margin-right: 3px;
  border-radius: 50%;
  background: var(--mint);
  box-shadow: 0 0 0 3px rgba(16, 185, 129, .18), 0 0 10px 1px rgba(16, 185, 129, .75);
}
.adm-live-dot[data-live="false"] { background: var(--ink-soft); box-shadow: 0 0 0 3px rgba(148, 163, 184, .14); }
@keyframes adm-pulse {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(.72); opacity: .55; }
}
@media (prefers-reduced-motion: no-preference) {
  .adm-live-dot[data-live="true"] { animation: adm-pulse 1.8s ease-in-out infinite; }
}
html.reduced-motion .adm-live-dot { animation: none; }
/* the figure is the whole point: bold gold, tabular, engraved into the slab */
.adm-card-v {
  font-size: clamp(1.3rem, 1rem + 1.6vw, 1.7rem);
  font-weight: 900;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--honey-ink);
  text-shadow: 0 1px 0 rgba(0, 0, 0, .55);
}
.adm-card-l {
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .06em;
  line-height: 1.3;
  text-transform: uppercase;
  color: var(--ink-soft);
}
/* the tactical sub-line under the label: the news that earns the card its slot */
.adm-card-s {
  display: block;
  min-width: 0;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .03em;
  line-height: 1.3;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--brand-ink);
  font-variant-numeric: tabular-nums;
}
.adm-card-s b { color: var(--mint-ink); }

/* ---- one clay slab under each executive section: title row, content beneath ---- */
.adm-slab {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px;
  border-radius: var(--radius-md);
  background: var(--clay-face);
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring);
}

/* ---- acquisition: three tone-coded inflow pills under one card title ---- */
.adm-inflow-h {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--s2);
  min-width: 0;
}
.adm-inflow-t {
  min-width: 0;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .04em;
  text-transform: uppercase;
  color: var(--ink);
}
.adm-inflow-s {
  flex: none;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.adm-inflow {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}
.adm-inflow-pill {
  --tone: var(--mint-ink);
  --tone-soft: rgba(16, 185, 129, .18);
  position: relative;
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  overflow: hidden;
  padding: 10px 8px 10px 11px;
  border-radius: 13px;
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-inflow-pill::before {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 3px;
  background: var(--tone);
  opacity: .9;
}
.adm-inflow-pill[data-window="today"] {
  --tone: #34d399;
  --tone-soft: rgba(52, 211, 153, .18);
}
.adm-inflow-pill[data-window="week"] {
  --tone: #fbbf24;
  --tone-soft: rgba(251, 191, 36, .18);
}
.adm-inflow-pill[data-window="month"] {
  --tone: var(--violet);
  --tone-soft: var(--violet-soft);
}
.adm-inflow-dot {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--tone);
  box-shadow: 0 0 0 3px var(--tone-soft), 0 0 8px var(--tone);
}
.adm-inflow-txt {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}
/* The label wraps instead of ellipsising. On a 320px phone three columns cannot hold
   "This Month · 30D" on one line, and clipping it to "This Month (…" hides which window the
   pill measures. Two short lines fit inside the height the big count already sets, so the row
   stays a row, the type stays readable and nothing is ever cut off. */
.adm-inflow-l {
  min-width: 0;
  font-size: 8px;
  font-weight: 900;
  line-height: 1.25;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--ink-soft);
  overflow-wrap: break-word;
}
.adm-inflow-v {
  font-size: clamp(1.15rem, 1rem + 1.1vw, 1.45rem);
  font-weight: 900;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--tone);
  text-shadow: 0 1px 0 rgba(0, 0, 0, .5);
}

/* ---- trends: one bounded window of the Worker's growth rings, drawn as inline SVG ---- */
/* The three series, in hues that stay separable on obsidian: sky, mint and amber. Every surface
   that has to agree with the plot — line, marker, pod dot, inspector token — reads these two
   variables through --tone / --tone-soft, so a series can only disagree with itself once. */
.adm-trend {
  --s-active: #22d3ee;
  --s-active-soft: rgba(34, 211, 238, .18);
  --s-signups: #10b981;
  --s-signups-soft: rgba(16, 185, 129, .18);
  --s-matches: #f59e0b;
  --s-matches-soft: rgba(245, 158, 11, .20);
  gap: 9px;
}
/* The plot has exactly one curve, and `data-metric` is the only thing that decides its hue: the
   line, its area gradient, its halo and its nodes all resolve to the pod that is pressed, so a
   single-series chart can never be drawn in the previous metric's colour. */
.adm-trend[data-metric="active"] { --plot-tone: var(--s-active); }
.adm-trend[data-metric="signups"] { --plot-tone: var(--s-signups); }
.adm-trend[data-metric="matches"] { --plot-tone: var(--s-matches); }
.adm-trend-h {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}
.adm-trend-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.adm-trend-t {
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .04em;
  line-height: 1.2;
  text-transform: uppercase;
  color: var(--ink);
}
.adm-trend-s {
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

/* the timeframe switch: three quiet segments, the selected one carrying the block's sky accent */
.adm-trend-keys {
  flex: none;
  display: flex;
  gap: 3px;
  padding: 3px;
  border-radius: var(--radius-pill);
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-trend-key {
  appearance: none;
  border: 0;
  font: inherit;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  min-height: 30px;
  padding: 4px 8px;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--ink-soft);
  transition: background var(--motion-fast), color var(--motion-fast);
}
.adm-trend-key b {
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .06em;
  line-height: 1.1;
}
.adm-trend-key span {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .04em;
  line-height: 1.1;
  text-transform: uppercase;
  opacity: .78;
}
.adm-trend-key:active { transform: translateY(1px); }
.adm-trend-key:focus-visible { outline: 3px solid var(--brand-2); outline-offset: -3px; }
.adm-trend-key[aria-pressed="true"] {
  background: rgba(56, 189, 248, .16);
  color: var(--brand-ink);
  box-shadow: inset 0 0 0 1px rgba(125, 211, 252, .34);
}
.adm-trend-key[aria-pressed="true"] span { opacity: 1; }

/* the match-type slice: three equal obsidian segments — one lane each, so ALL, PVP and VS BOT
   land on the same width and the same 36px touch target whatever the label's letter count */
.adm-trend-modes {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 4px;
  min-width: 0;
  padding: 4px;
  border-radius: 12px;
  background: #070b12;
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-trend-mode {
  appearance: none;
  border: 0;
  font: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 36px;
  padding: 0 6px;
  border-radius: 9px;
  background: transparent;
  color: var(--ink-soft);
  transition: background var(--motion-fast), color var(--motion-fast), box-shadow var(--motion-fast);
}
.adm-trend-mode b {
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .08em;
  line-height: 1;
  white-space: nowrap;
}
.adm-trend-mode:active { transform: translateY(1px); }
.adm-trend-mode:focus-visible { outline: 3px solid var(--brand-2); outline-offset: -3px; }
/* the one selected segment: a gold rim and a restrained halo, never a floodlight */
.adm-trend-mode[aria-pressed="true"] {
  background:
    linear-gradient(180deg, rgba(251, 191, 36, .14) 0%, rgba(251, 191, 36, .05) 100%);
  color: #fde68a;
  box-shadow:
    inset 0 0 0 1px rgba(251, 191, 36, .42),
    inset 0 1px 0 rgba(255, 255, 255, .10),
    0 0 12px rgba(251, 191, 36, .12);
}

/* the plot: a recessed obsidian band the SVG fills edge to edge, scaling its own viewBox
   uniformly. The wash at the top is a 6% sky bloom — enough to seat the grid, not a spotlight. */
.adm-trend-plot {
  position: relative;
  min-height: 96px;
  padding: 4px 2px 2px;
  border-radius: 13px;
  background:
    radial-gradient(124% 92% at 50% -12%, rgba(56, 189, 248, .07) 0%, rgba(56, 189, 248, 0) 62%),
    var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-trend-svg {
  display: block;
  width: 100%;
  height: auto;
  /* horizontal drags inspect the chart; the vertical swipe still scrolls the panel */
  touch-action: pan-y;
  cursor: crosshair;
}
.adm-trend-svg.is-blank { visibility: hidden; }
.adm-trend-empty {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0;
  padding: 12px 16px;
  font-size: 9px;
  font-weight: 700;
  line-height: 1.45;
  text-align: center;
  color: var(--ink-soft);
}
.adm-trend-empty[hidden] { display: none; }

/* the drawing itself: hairline grid, one gradient-filled series, one dotted series */
.adm-trend-grid line {
  stroke: rgba(148, 163, 184, .18);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}
.adm-trend-axis text {
  font-size: 10px;
  font-weight: 800;
  fill: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}
/* the gutter labels sit in a fixed slice of the viewBox, so they run a touch smaller */
.adm-trend-y { font-size: 9.5px; letter-spacing: .01em; }
.adm-trend-x { letter-spacing: .02em; }
.adm-trend-line {
  fill: none;
  stroke: var(--plot-tone);
  stroke-width: 2.25;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
  transition: stroke var(--motion-fast);
}
/* the area under the single curve: the gradient's own stops take --plot-tone, so the fill and the
   line above it are the same hue by construction rather than by two places agreeing */
.adm-trend-stop { stop-color: var(--plot-tone); }
.adm-trend-fill { transition: opacity var(--motion-fast); }
/* the ambient glow is the same curve laid down as one wide, faint stroke rather than an SVG
   blur: a filter would be re-rasterised on every pointer move over the plot, a stroke is not. */
.adm-trend-halo {
  fill: none;
  stroke: var(--plot-tone);
  stroke-width: 5.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: .16;
  vector-effect: non-scaling-stroke;
  transition: stroke var(--motion-fast);
  pointer-events: none;
}
/* the nodes make a flat zero stretch read as measured rather than as a missing series */
.adm-trend-dots circle {
  fill: var(--plot-tone);
  stroke: var(--field);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}
.adm-trend-guide {
  stroke: rgba(226, 232, 240, .34);
  stroke-width: 1;
  stroke-dasharray: 3 3;
  vector-effect: non-scaling-stroke;
}
.adm-trend-mark {
  fill: var(--plot-tone);
  stroke: var(--field);
  stroke-width: 1.6;
  vector-effect: non-scaling-stroke;
}
.adm-trend-hit { fill: transparent; }

/* the legend: three obsidian pods, each carrying its own sum across the window on screen.
   Frosted glass here is a 6% white face over the recess, a 1px hairline rim and a single
   specular line at the top edge — no live `backdrop-filter`, which would blur the chart behind
   it on every scroll frame of a phone. */
/* the pods' own header: what the figures under them are summed over. It takes the place of the
   footer row that used to print those same three sums a second time. */
.adm-trend-metric-h {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
  padding: 0 2px;
}
.adm-trend-metric-k {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.adm-trend-metric-r {
  flex: none;
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .08em;
  direction: ltr;
  unicode-bidi: isolate;
  color: var(--ink);
}
.adm-trend-legend {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}
/* the two tagged slices have no signup series to offer, so their row is two equal pods rather than
   three lanes with a hole where the hidden one used to be */
.adm-trend[data-mode="pvp"] .adm-trend-legend,
.adm-trend[data-mode="bot"] .adm-trend-legend {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.adm-trend-chip {
  appearance: none;
  border: 0;
  font: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  min-height: 38px;
  padding: 7px 9px;
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .055) 0%, rgba(255, 255, 255, .014) 46%, rgba(255, 255, 255, 0) 100%),
    var(--field);
  box-shadow:
    inset 0 0 0 1px var(--hair-off),
    inset 0 1px 0 rgba(255, 255, 255, .07),
    0 1px 2px rgba(0, 0, 0, .45);
  transition: opacity var(--motion-fast), box-shadow var(--motion-fast),
    background var(--motion-fast), transform var(--motion-fast);
}
.adm-trend-chip:focus-visible { outline: 3px solid var(--brand-2); outline-offset: -3px; }
/* a pod this slice cannot answer with is taken away, not greyed out */
.adm-trend-chip[hidden] { display: none; }
/* the status dot: a 7px core inside a 3px tinted ring, so the three hues read at arm's length.
   Only the pod holding the curve keeps its halo — the others still say which hue is theirs. */
.adm-trend-dot {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--tone, var(--ink-soft));
  box-shadow:
    0 0 0 3px color-mix(in srgb, var(--tone, var(--ink-soft)) 15%, transparent),
    0 0 8px color-mix(in srgb, var(--tone, var(--ink-soft)) 45%, transparent);
  transition: opacity var(--motion-fast), box-shadow var(--motion-fast);
}
.adm-trend-chip[aria-pressed="false"] .adm-trend-dot { opacity: .5; box-shadow: none; }
.adm-trend-chip[data-gseries="active"] { --tone: var(--s-active); --tone-soft: var(--s-active-soft); }
.adm-trend-chip[data-gseries="signups"] { --tone: var(--s-signups); --tone-soft: var(--s-signups-soft); }
.adm-trend-chip[data-gseries="matches"] { --tone: var(--s-matches); --tone-soft: var(--s-matches-soft); }
.adm-trend-chip-t {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--ink-soft);
  transition: color var(--motion-fast);
}
/* the figure: pure LTR digits inside whatever direction the panel is laid out in, so a Persian
   UI can mirror the pod without ever reordering `11` into `1 1` */
.adm-trend-chip-v {
  flex: none;
  font-size: 13px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -.01em;
  font-variant-numeric: tabular-nums;
  direction: ltr;
  unicode-bidi: isolate;
  color: var(--tone, var(--ink));
  text-shadow: 0 0 12px var(--tone-soft, transparent);
}

/* the pod holding the one curve on screen: a rim in its own hue and a tinted glass face. Its
   figure keeps the hue either way, because that is what ties the number to the series. */
.adm-trend-chip[aria-pressed="true"] {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .09) 0%, rgba(255, 255, 255, 0) 55%),
    color-mix(in srgb, var(--tone) 19%, var(--field));
  box-shadow:
    inset 0 0 0 1.5px color-mix(in srgb, var(--tone) 84%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, .10),
    0 0 16px color-mix(in srgb, var(--tone) 26%, transparent);
}
.adm-trend-chip[aria-pressed="true"] .adm-trend-chip-t { color: var(--ink); }
.adm-trend-chip:active { transform: translateY(1px); }

/* the inspector: the bucket's own hour, then the plotted series' count inside it */
.adm-trend-read {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
  margin: 0;
  padding-top: 8px;
  border-top: 1px solid var(--hair-off);
  font-variant-numeric: tabular-nums;
}
/* at rest there is nothing here that the pods do not already say, so the row goes away */
.adm-trend-read[hidden] { display: none; }
.adm-trend-ts {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 4px 9px;
  border-radius: var(--radius-pill);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .05) 0%, rgba(255, 255, 255, 0) 100%),
    var(--field);
  box-shadow:
    inset 0 0 0 1px rgba(125, 211, 252, .34),
    inset 0 1px 0 rgba(255, 255, 255, .08),
    0 0 10px rgba(56, 189, 248, .12);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .06em;
  line-height: 1.3;
  text-transform: uppercase;
  /* `TUE 19:30 TEHRAN` is one LTR run: equal-width digits, and no bidi reordering inside it */
  font-variant-numeric: tabular-nums;
  direction: ltr;
  unicode-bidi: isolate;
  color: var(--ink);
}
/* the one reading, in the plotted series' own hue: the bucket's count, not the window's sum */
.adm-trend-tok {
  display: flex;
  align-items: center;
  gap: 3px;
  flex: 0 1 auto;
  min-width: 0;
  margin-inline-start: auto;
  padding: 3px 6px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--tone) 16%, var(--field));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tone) 52%, transparent);
  transition: background var(--motion-fast), box-shadow var(--motion-fast);
}
.adm-trend-tok[data-gtok="active"] { --tone: var(--s-active); }
.adm-trend-tok[data-gtok="signups"] { --tone: var(--s-signups); }
.adm-trend-tok[data-gtok="matches"] { --tone: var(--s-matches); }
.adm-trend-tok-dot {
  flex: none;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--tone);
}
.adm-trend-tok-l {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 7.5px;
  font-weight: 900;
  letter-spacing: .05em;
  line-height: 1.2;
  text-transform: uppercase;
  color: var(--ink);
}
.adm-trend-tok-v {
  flex: none;
  /* logical, not physical: in an RTL panel the figure still lands on the trailing edge */
  margin-inline-start: auto;
  font-size: 10px;
  font-weight: 900;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
  direction: ltr;
  unicode-bidi: isolate;
  color: var(--tone);
}

/* the copy column takes the whole row when the switch cannot sit beside it, rather than
   squeezing the title into a two-word column */
@media (max-width: 380px) {
  .adm-trend-h { flex-wrap: wrap; }
  .adm-trend-copy { flex: 1 1 100%; }
  .adm-trend-keys { margin-left: auto; }
  .adm-trend-key { padding: 4px 7px; }
  /* three lanes still hold a full 36px target at 320px; only the type steps down */
  .adm-trend-mode { min-height: 36px; padding: 0 4px; }
  .adm-trend-mode b { font-size: 8.5px; letter-spacing: .05em; }
  /* three pods in 264px: the pod stops breathing before its label has to truncate */
  .adm-trend-chip { gap: 5px; padding: 6px 6px; min-height: 36px; }
  .adm-trend-chip-t { font-size: 8px; letter-spacing: .02em; }
  .adm-trend-chip-v { font-size: 12px; }
  .adm-trend-dot {
    width: 6px;
    height: 6px;
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--tone, var(--ink-soft)) 16%, transparent);
  }
}

/* the narrowest phones: the label gives up a half-pixel of tracking, never a letter */
@media (max-width: 340px) {
  .adm-trend-chip { gap: 4px; padding: 6px 5px; }
  .adm-trend-chip-t { font-size: 7.5px; letter-spacing: .01em; }
  .adm-trend-chip-v { font-size: 11.5px; }
}

/* ---- engagement: three at-a-glance tiles, a returning count and two measured shares ---- */
.adm-ret-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 7px;
  min-width: 0;
}
.adm-ret-tile {
  --tone: var(--violet);
  --tone-soft: rgba(167, 139, 250, .16);
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  padding: 11px 12px 12px;
  border-radius: 12px;
  background:
    radial-gradient(120% 140% at 0% 0%, var(--tone-soft), transparent 58%),
    var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-ret-tile[data-tone="mint"] {
  --tone: #34d399;
  --tone-soft: rgba(16, 185, 129, .14);
}
.adm-ret-tile[data-tone="honey"] {
  --tone: #fbbf24;
  --tone-soft: rgba(245, 158, 11, .13);
}
.adm-ret-label {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .01em;
  line-height: 1.3;
  color: var(--ink);
}
.adm-ret-label::before {
  content: '';
  flex: none;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--tone);
  box-shadow: 0 0 6px var(--tone-soft);
}
.adm-ret-sub {
  min-width: 0;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: .01em;
  line-height: 1.35;
  color: var(--ink-soft);
}
.adm-ret-fig {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 8px;
  min-width: 0;
  margin-top: 7px;
}
/* the figure is the whole story: chrome-white falling into the tile's own tone */
.adm-ret-fig b {
  font-size: clamp(1.85rem, 1.5rem + 1.6vw, 2.4rem);
  font-weight: 900;
  line-height: 1;
  letter-spacing: -.015em;
  font-variant-numeric: tabular-nums;
  color: var(--tone);
  text-shadow: 0 1px 0 rgba(0, 0, 0, .55);
}
@supports ((-webkit-background-clip: text) or (background-clip: text)) {
  .adm-ret-fig b {
    background: linear-gradient(178deg, #ffffff 4%, #cbd5e1 44%, var(--tone) 100%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    text-shadow: none;
    filter: drop-shadow(0 1px 0 rgba(0, 0, 0, .5));
  }
}
.adm-ret-pill {
  display: inline-block;
  max-width: 100%;
  overflow: hidden;
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .03em;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
  color: var(--violet);
  background: var(--violet-soft);
  box-shadow: inset 0 0 0 1px rgba(167, 139, 250, .34);
}
.adm-ret-bar {
  height: 4px;
  margin-top: 9px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(7, 11, 18, .55);
  box-shadow: inset 0 0 0 1px var(--hair-off);
}
.adm-ret-bar i {
  display: block;
  width: 0;
  height: 100%;
  border-radius: inherit;
  transition: width .34s var(--bounce);
}
.adm-ret-bar[data-tone="mint"] i {
  background: linear-gradient(90deg, #10b981, #34d399);
  box-shadow: 0 0 8px rgba(16, 185, 129, .5);
}
.adm-ret-bar[data-tone="honey"] i {
  background: linear-gradient(90deg, #f59e0b, #fbbf24);
  box-shadow: 0 0 8px rgba(245, 158, 11, .45);
}
.adm-ret-bar[data-empty="true"] i { visibility: hidden; }
html.reduced-motion .adm-ret-bar i { transition: none; }

/* wide screens read the three tiles across; phones keep the calm stack */
@media (min-width: 560px) {
  .adm-ret-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 8px;
  }
}

/* ---- system footer: one quiet latency badge under the dashboard ---- */
.adm-sysfoot {
  flex: none;
  display: flex;
  justify-content: center;
  padding: 2px 0 0;
}
.adm-sysfoot-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .08em;
  line-height: 1;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  color: var(--ink-soft);
  background: rgba(255, 255, 255, .02);
  box-shadow: inset 0 0 0 1px var(--hair-off);
}
.adm-sysfoot-badge b { font-weight: 900; color: var(--brand-ink); }
.adm-sysfoot-sep { opacity: .5; }

/* the narrowest phones: keep all three time windows on one row, each label free to wrap */
@media (max-width: 400px) {
  .adm-card { padding: 9px 7px 10px; }
  .adm-card-l { font-size: 8px; letter-spacing: .04em; }
  .adm-inflow { gap: 4px; }
  .adm-inflow-pill { gap: 5px; padding: 9px 6px 9px 9px; }
  .adm-inflow-l { letter-spacing: .02em; }
  .adm-inflow-dot {
    width: 6px;
    height: 6px;
    box-shadow: 0 0 0 2px var(--tone-soft), 0 0 6px var(--tone);
  }
}

/* ---- bento metric tiles: shared by the player card's mini readouts ---- */
.adm-cells {
  display: grid;
  gap: 6px;
}
.adm-cells .adm-stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  padding: 9px 10px 8px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, .07);
  background: rgba(255, 255, 255, .03);
}
.adm-stat-v {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  overflow: hidden;
  font-family: var(--font-numeric), monospace;
  font-size: 1.05rem;
  font-weight: 800;
  line-height: 1.15;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.adm-stat-vt {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.adm-stat-v .coin { width: 15px; height: 15px; }
.adm-stat-i { flex: none; width: 15px; height: 15px; color: var(--tiq); }
.adm-stat-l {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: .68rem;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: .04em;
  text-transform: uppercase;
  color: var(--text-dim);
}

/* the nations strip: one clay slab, four mini meters — flag, filled track, exact share */
.adm-nations {
  display: flex;
  flex-direction: column;
  gap: var(--s2);
  padding: 11px 12px 12px;
  border-radius: var(--radius-md);
  background: var(--clay-face);
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring);
}
.adm-nations-h { display: flex; align-items: baseline; gap: var(--s2); }
.adm-nations-t {
  font-size: var(--t-micro);
  font-weight: 800;
  letter-spacing: var(--ls-3);
  text-transform: uppercase;
  color: var(--ink-soft);
}
.adm-nations-s {
  flex: 1 1 auto;
  min-width: 0;
  text-align: right;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--brand-ink);
}
.adm-nations-s[data-live="true"] { color: var(--mint-ink); }
.adm-nations-list.is-meters {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.adm-nat {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 24px;
  min-width: 0;
}
.adm-nat .fp { --fp-d: 20px; }
.adm-nat .fp-chip { border-radius: 7px; font-size: 8px; }
/* the recessed track, one gold run of clay along it, the share poured in */
.adm-nat-track {
  flex: 1 1 auto;
  min-width: 0;
  height: 8px;
  border-radius: 4px;
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
  overflow: hidden;
}
.adm-nat-fill {
  display: block;
  height: 100%;
  border-radius: 4px;
  background: linear-gradient(90deg, #f59e0b 0%, #fbbf24 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .35), 0 0 8px rgba(245, 158, 11, .35);
}
.adm-nat:last-child .adm-nat-fill { background: linear-gradient(90deg, #64748B 0%, #94A3B8 100%); box-shadow: none; }
.adm-nat-p {
  flex: none;
  min-width: 34px;
  text-align: right;
  font-size: var(--t-3);
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
}
/* the flag we could not name is the globe, and it wears the same 20px well as the rest */
.adm-nat-globe { font-size: 13px; line-height: 1; }
.adm-nat-empty { color: var(--ink-soft); font-size: var(--t-3); font-weight: 800; }

/* ==========================================================================
   CONTROLS — a 48px row per switch, the tuning grid.
   ========================================================================== */
.adm-sw {
  display: flex;
  align-items: center;
  gap: var(--s2);
  width: 100%;
  min-height: 48px;
  padding: 0 10px;
  appearance: none;
  border: 0;
  font: inherit;
  text-align: left;
  cursor: pointer;
  border-radius: var(--radius-md);
  background: var(--clay-face);
  color: var(--ink);
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast);
}
.adm-sw:active { transform: translateY(var(--press-y)); }
.adm-sw:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.adm-sw-i {
  flex: none;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 10px;
  background: var(--field);
  color: var(--brand-ink);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-sw-i .ico { width: 15px; height: 15px; }
.adm-sw-t { flex: 1 1 auto; min-width: 0; font-size: var(--t-2); font-weight: 800; color: var(--ink); }
.adm-knob {
  flex: none;
  width: 50px;
  height: 30px;
  display: flex;
  align-items: center;
  padding: 3px;
  border-radius: var(--radius-pill);
  background: var(--field);
  box-shadow: var(--inset);
  transition: background var(--motion-fast), box-shadow var(--motion-fast);
}
.adm-knob i {
  display: block;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: linear-gradient(180deg, #64748B 0%, #475569 100%);
  box-shadow: 0 2px 0 rgba(0, 0, 0, .45), inset 0 1px 0 rgba(255, 255, 255, .25);
  transition: transform var(--motion-fast), background var(--motion-fast);
}
.adm-sw[aria-checked="true"] .adm-knob {
  background: var(--mint-soft);
  box-shadow: var(--inset), inset 0 0 0 1px rgba(16, 185, 129, .4);
}
.adm-sw[aria-checked="true"] .adm-knob i {
  transform: translateX(20px);
  background: var(--gold-face);
  box-shadow: 0 2px 0 var(--gold-lip), inset 0 1px 0 rgba(255, 255, 255, .5);
}
@media (prefers-reduced-motion: reduce) { .adm-knob i { transition: none; } }

/* ---- the mandatory channel gate card: obsidian, one switch, one channel, one save key ---- */
.fjadm-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  border-radius: 16px;
  background:
    radial-gradient(120% 90% at 50% -20%, rgba(212, 175, 55, .08) 0%, rgba(212, 175, 55, 0) 62%),
    linear-gradient(180deg, #15120C 0%, #0C0B09 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 236, 179, .12),
    inset 0 0 0 1px rgba(212, 175, 55, .16),
    0 14px 30px -22px #000;
}
.fjadm-head { display: flex; align-items: center; gap: 9px; min-width: 0; }
.fjadm-crest {
  flex: none;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  color: #F6D87A;
  background: radial-gradient(circle at 32% 28%, #2A2314 0%, #14100A 68%);
  box-shadow: inset 0 0 0 1px rgba(212, 175, 55, .34), 0 6px 16px -8px rgba(212, 175, 55, .55);
}
.fjadm-crest .ico { width: 15px; height: 15px; }
.fjadm-copy { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.fjadm-t { font-size: 11px; font-weight: 900; color: var(--ink); }
.fjadm-s { font-size: 9px; font-weight: 600; line-height: 1.4; color: var(--ink-soft); overflow-wrap: anywhere; }
.fjadm-pill {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 8px;
  border-radius: 999px;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .1em;
  color: #8A8478;
  background: rgba(255, 255, 255, .04);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .08);
}
.fjadm-pill i { width: 5px; height: 5px; border-radius: 50%; background: currentColor; }
.fjadm-pill[data-on="true"] {
  color: #F6D87A;
  background: rgba(212, 175, 55, .13);
  box-shadow: inset 0 0 0 1px rgba(212, 175, 55, .38), 0 0 18px -8px rgba(246, 216, 122, .8);
}
.fjadm-card .adm-sw {
  background: rgba(255, 255, 255, .035);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .06);
}
.fjadm-fld {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-height: 48px;
  padding: 6px 10px;
  border-radius: 12px;
  background: rgba(0, 0, 0, .28);
  box-shadow: inset 0 0 0 1px rgba(212, 175, 55, .14);
}
.fjadm-k { font-size: 8px; font-weight: 900; letter-spacing: .1em; text-transform: uppercase; color: #9A8A62; }
.fjadm-fld .adm-input { min-height: 24px; font-size: 12px; color: #F4EFE6; }
.fjadm-fld .adm-input::placeholder { color: #6F685C; opacity: 1; }
.fjadm-foot { display: flex; align-items: center; gap: 8px; min-width: 0; }
.fjadm-note {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 9px;
  font-weight: 600;
  line-height: 1.45;
  color: var(--ink-soft);
  overflow-wrap: anywhere;
}
.fjadm-save { flex: none; min-height: 38px; padding: 0 15px; font-size: 10px; border-radius: 12px; }
.adm-btn.fjadm-save {
  background: linear-gradient(180deg, #F7DC86 0%, #E7BE55 45%, #C99A32 100%);
  color: #1B1405;
  box-shadow:
    inset 0 1px 0 rgba(255, 252, 230, .8),
    0 2px 0 #7E5F14,
    0 8px 18px -12px rgba(212, 175, 55, .9);
}
.fjadm-save:disabled { opacity: .6; cursor: default; }
.fjadm .adm-block-s { color: #C8A552; }
.fjadm .adm-block-s[data-tone="warn"] { color: #FCD34D; }
.fjadm .adm-block-s[data-tone="off"] { color: var(--ink-soft); }

/* ---- the section-header chip: ellipsised, right-aligned, one line ---- */
.adm-sec-chip {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: right;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: none;
  color: var(--ink-soft);
}
.adm-sec-chip[data-on="true"] { color: var(--honey-ink); }
.adm-field {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--s2);
  min-height: 48px;
  padding: 0 11px;
  border-radius: var(--radius-sm);
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-field .ico { flex: none; width: 15px; height: 15px; color: var(--honey); }
.adm-input {
  flex: 1 1 auto;
  align-self: stretch;                 /* the field itself is the 48px target, not just the glyph run */
  min-width: 0;
  appearance: none;
  border: 0;
  background: none;
  outline: none;
  font: inherit;
  font-size: var(--t-2);
  color: var(--ink);
  -webkit-user-select: text;
  user-select: text;
}
.adm-input::placeholder { color: var(--ink-soft); opacity: .65; }

/* ---- the shared clay key ---- */
.adm-btn {
  appearance: none;
  border: 0;
  font: inherit;
  cursor: pointer;
  min-height: 48px;
  padding: 0 16px;
  border-radius: var(--radius-md);
  background: var(--clay-face);
  color: var(--ink);
  font-size: var(--t-2);
  font-weight: 800;
  box-shadow: 0 var(--lip) 0 #0A0E15, var(--clay-drop), var(--clay-spec), var(--clay-bevel);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast), filter var(--motion-fast);
}
.adm-btn:active { transform: translateY(var(--press-y)); --lip: 1px; }
.adm-btn:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.adm-btn-wide { width: 100%; margin-top: var(--s3); }
.adm-btn-primary {
  background: var(--brand-fill);
  color: var(--on-brand);
  box-shadow: 0 var(--lip) 0 var(--brand-lip), var(--brand-shadow);
}
.adm-btn-danger {
  background: linear-gradient(180deg, var(--bad-1) 0%, var(--bad-2) 100%);
  color: #fff;
  box-shadow: 0 var(--lip) 0 #7F0B2A, var(--bad-shadow);
}
.adm-btn-danger.armed { filter: saturate(1.2) brightness(1.12); }

/* ---- the tuning grid: two 62px cells a row, each a caption over a stepper ---- */
.adm-tunes {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}
.adm-tune {
  display: flex;
  flex-direction: column;
  min-width: 0;
  border-radius: var(--radius-md);
  background: var(--clay-face);
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring);
}
.adm-tune-n {
  padding: 4px 8px 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 9px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.adm-tune .adm-steps-c {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
  padding: 1px 2px 0;
}
/* the sixth cell is a key, not a stepper: the same slab, pressed as one control */
.adm-tune-key {
  appearance: none;
  border: 0;
  font: inherit;
  text-align: left;
  cursor: pointer;
  padding: 0;
  transition: transform var(--motion-fast), box-shadow var(--motion-fast);
}
.adm-tune-key:active { transform: translateY(var(--press-y)); }
.adm-tune-key:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.adm-tune-b {
  flex: 1 1 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 1px 2px 2px;
  border-radius: var(--radius-sm);
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
  color: var(--brand-ink);
  font-size: var(--t-2);
  font-weight: 800;
}
.adm-step {
  width: 48px;
  height: 48px;
  flex: none;
  display: grid;
  place-items: center;
  padding: 0;
  appearance: none;
  border: 0;
  cursor: pointer;
  border-radius: var(--radius-sm);
  background: var(--field);
  color: var(--brand-ink);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast);
}
.adm-step .ico { width: 18px; height: 18px; }
.adm-step:active { transform: translateY(var(--press-y)); }
.adm-step:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.adm-val {
  min-width: 40px;
  flex: 1 1 auto;
  text-align: center;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: var(--t-2);
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
}

/* ==========================================================================
   ARENA & TOURNAMENT — the season machine inside Controls.
   Frosted slate cards (a translucent #0D131F face with a 1px razor edge, no
   backdrop-filter), tactile state keys with an emerald / crimson / amber glow,
   a monospaced instrument clock, and the player's own Mind Ladder capsule
   rendered with the real .ml-season classes so the preview cannot drift.
   ========================================================================== */
.adm-arena { display: flex; flex-direction: column; gap: 6px; }
.adm-arena-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
  padding: 12px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(148, 163, 184, .18);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .035) 0%, rgba(255, 255, 255, 0) 42%),
    rgba(13, 19, 31, .85);
  box-shadow:
    0 16px 32px -26px rgba(0, 0, 0, .95),
    inset 0 1px 0 rgba(255, 255, 255, .06);
}
.adm-arena-card.is-danger {
  border-color: rgba(224, 38, 79, .32);
  background:
    linear-gradient(180deg, rgba(224, 38, 79, .09) 0%, rgba(224, 38, 79, 0) 46%),
    rgba(13, 19, 31, .85);
}
.adm-arena-head { display: flex; align-items: center; gap: 9px; min-width: 0; }
.adm-arena-ico {
  flex: none;
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 10px;
  background: var(--field);
  color: var(--brand-ink);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-arena-ico .ico { width: 16px; height: 16px; }
.adm-arena-card.is-danger .adm-arena-ico { color: var(--red-ink); }
.adm-arena-copy { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.adm-arena-copy b { font-size: var(--t-2); font-weight: 800; color: var(--ink); }
.adm-arena-copy small {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.adm-arena-beacon {
  flex: none;
  width: 9px;
  height: 9px;
  margin-right: 3px;
  border-radius: 50%;
  background: #64748B;
  box-shadow: 0 0 0 3px rgba(100, 116, 139, .16);
  transition: background var(--motion-fast), box-shadow var(--motion-fast);
}
#adm-arena[data-state="active"] .adm-arena-beacon {
  background: var(--mint);
  box-shadow: 0 0 0 3px rgba(16, 185, 129, .18), 0 0 12px 1px rgba(16, 185, 129, .8);
}
#adm-arena[data-state="maintenance"] .adm-arena-beacon {
  background: var(--red);
  box-shadow: 0 0 0 3px rgba(224, 38, 79, .18), 0 0 12px 1px rgba(224, 38, 79, .8);
}
#adm-arena[data-state="finale"] .adm-arena-beacon {
  background: var(--honey);
  box-shadow: 0 0 0 3px rgba(245, 158, 11, .18), 0 0 12px 1px rgba(245, 158, 11, .8);
}
#adm-arena[data-lock="true"] .adm-arena-beacon {
  background: var(--red);
  box-shadow: 0 0 0 3px rgba(224, 38, 79, .2), 0 0 12px 1px rgba(224, 38, 79, .85);
}
@media (prefers-reduced-motion: no-preference) {
  #adm-arena[data-state="active"][data-lock="false"] .adm-arena-beacon { animation: adm-pulse 2.2s ease-in-out infinite; }
}
html.reduced-motion .adm-arena-beacon { animation: none; }

/* ---- the three state keys: one recessed track, the live one lit ---- */
.adm-arena-seg {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 4px;
  padding: 4px;
  border-radius: 12px;
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-state-key {
  position: relative;
  min-width: 0;
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 4px;
  appearance: none;
  border: 0;
  font: inherit;
  font-size: var(--t-micro);
  font-weight: 800;
  letter-spacing: .01em;
  cursor: pointer;
  border-radius: 9px;
  background: transparent;
  color: var(--ink-soft);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast),
              background var(--motion-fast), color var(--motion-fast);
}
.adm-state-key i {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #64748B;
  box-shadow: 0 0 0 2px rgba(100, 116, 139, .16);
  transition: background var(--motion-fast), box-shadow var(--motion-fast);
}
.adm-state-key:active { transform: translateY(var(--press-y)); }
.adm-state-key:focus-visible { outline: 3px solid var(--brand-2); outline-offset: -3px; }
.adm-state-key[aria-checked="true"] { color: var(--ink); }
.adm-state-key[data-tone="emerald"][aria-checked="true"] {
  background: linear-gradient(180deg, rgba(16, 185, 129, .3) 0%, rgba(5, 150, 105, .12) 100%);
  color: var(--mint-ink);
  box-shadow:
    inset 0 0 0 1px rgba(52, 211, 153, .5),
    0 2px 0 #064E3B,
    0 0 20px -7px rgba(16, 185, 129, .85);
}
.adm-state-key[data-tone="emerald"][aria-checked="true"] i {
  background: #34D399;
  box-shadow: 0 0 9px 1px rgba(52, 211, 153, .9);
}
.adm-state-key[data-tone="crimson"][aria-checked="true"] {
  background: linear-gradient(180deg, rgba(224, 38, 79, .32) 0%, rgba(179, 18, 60, .12) 100%);
  color: var(--red-ink);
  box-shadow:
    inset 0 0 0 1px rgba(251, 113, 133, .48),
    0 2px 0 #7F0B2A,
    0 0 20px -7px rgba(224, 38, 79, .9);
}
.adm-state-key[data-tone="crimson"][aria-checked="true"] i {
  background: #FB7185;
  box-shadow: 0 0 9px 1px rgba(251, 113, 133, .9);
}
.adm-state-key[data-tone="amber"][aria-checked="true"] {
  background: linear-gradient(180deg, rgba(245, 158, 11, .32) 0%, rgba(180, 83, 9, .12) 100%);
  color: var(--honey-ink);
  box-shadow:
    inset 0 0 0 1px rgba(252, 211, 77, .48),
    0 2px 0 #78350F,
    0 0 20px -7px rgba(245, 158, 11, .9);
}
.adm-state-key[data-tone="amber"][aria-checked="true"] i {
  background: #FCD34D;
  box-shadow: 0 0 9px 1px rgba(252, 211, 77, .9);
}

/* the queue lock reads crimson the moment it is armed */
.adm-arena-lock[aria-checked="true"] {
  box-shadow:
    var(--clay-drop), var(--clay-spec), var(--clay-bevel),
    inset 0 0 0 1px rgba(224, 38, 79, .42),
    0 0 22px -8px rgba(224, 38, 79, .8);
}
.adm-arena-lock[aria-checked="true"] .adm-knob {
  background: rgba(224, 38, 79, .2);
  box-shadow: var(--inset), inset 0 0 0 1px rgba(224, 38, 79, .45);
}
.adm-arena-lock[aria-checked="true"] .adm-knob i {
  background: linear-gradient(180deg, #FB7185 0%, #E0264F 100%);
  box-shadow: 0 2px 0 #7F0B2A, 0 0 14px rgba(224, 38, 79, .8), inset 0 1px 0 rgba(255, 255, 255, .35);
}
.adm-arena-fine {
  margin: 0;
  font-size: 9.5px;
  line-height: 1.5;
  color: var(--ink-soft);
}

/* ---- season title + the division ladder ---- */
.adm-arena-fld { display: flex; flex-direction: column; gap: 5px; min-width: 0; }
.adm-arena-k {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin: 0;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .09em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.adm-arena-k span { color: #64748B; letter-spacing: .04em; }
.adm-arena-fld .adm-input {
  min-height: 48px;
  padding: 0 11px;
  border-radius: 9px;
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
  color: var(--ink);
}
.adm-arena-fld .adm-input:focus-visible {
  outline: 3px solid var(--brand-2);
  outline-offset: -1px;
}
.adm-divs { display: flex; flex-direction: column; gap: 4px; }
.adm-divs-h { margin-bottom: 1px; }
.adm-div {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 48px;
  padding: 0 10px;
  border-radius: 9px;
  border: 1px solid rgba(148, 163, 184, .1);
  background: rgba(255, 255, 255, .025);
  cursor: text;
}
.adm-div > span {
  flex: 1 1 auto;
  min-width: 0;
  font-size: var(--t-3);
  font-weight: 800;
  color: var(--ink);
}
.adm-div-dot {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #94A3B8;
  box-shadow: 0 0 0 2px rgba(148, 163, 184, .14);
}
.adm-div-dot[data-div="bronze"] { background: #C98A5B; box-shadow: 0 0 0 2px rgba(201, 138, 91, .18); }
.adm-div-dot[data-div="silver"] { background: #CBD5E1; box-shadow: 0 0 0 2px rgba(203, 213, 225, .18); }
.adm-div-dot[data-div="gold"] { background: #FCD34D; box-shadow: 0 0 0 2px rgba(252, 211, 77, .18); }
.adm-div-dot[data-div="platinum"] { background: #67E8F9; box-shadow: 0 0 0 2px rgba(103, 232, 249, .18); }
.adm-div-dot[data-div="diamond"] { background: #93C5FD; box-shadow: 0 0 0 2px rgba(147, 197, 253, .18); }
.adm-div-dot[data-div="challenger"] { background: #F0ABFC; box-shadow: 0 0 0 2px rgba(240, 171, 252, .2); }
.adm-div-i {
  flex: none;
  width: 86px;
  height: 48px;
  appearance: textfield;
  -moz-appearance: textfield;
  border: 0;
  background: transparent;
  outline: none;
  text-align: right;
  font: inherit;
  font-size: var(--t-2);
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--honey-ink);
  -webkit-user-select: text;
  user-select: text;
}
.adm-div-i::-webkit-outer-spin-button,
.adm-div-i::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
.adm-div-i[readonly] { color: var(--ink-soft); }
.adm-div-i:focus-visible {
  border-radius: 6px;
  outline: 2px solid var(--brand-2);
  outline-offset: 2px;
}

/* ---- the clock: one monospaced instrument ---- */
.adm-count {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 58px;
  padding: 6px 10px;
  border-radius: 12px;
  border: 1px solid rgba(245, 158, 11, .22);
  background: linear-gradient(180deg, #0A111E 0%, #0E1526 100%);
  box-shadow:
    var(--inset),
    inset 0 0 0 1px rgba(255, 255, 255, .03),
    0 0 26px -16px rgba(245, 158, 11, .8);
  font-family: ui-monospace, "SFMono-Regular", "Cascadia Mono", Consolas, monospace;
  font-size: clamp(1rem, .84rem + 1.4vw, 1.28rem);
  font-weight: 800;
  letter-spacing: .035em;
  font-variant-numeric: tabular-nums;
  color: var(--honey-ink);
  text-align: center;
  text-shadow: 0 0 14px rgba(245, 158, 11, .32);
  white-space: nowrap;
  overflow: hidden;
}
#adm-arena[data-state="maintenance"] .adm-count,
#adm-season[data-state="maintenance"] .adm-count {
  border-color: rgba(224, 38, 79, .28);
  color: var(--red-ink);
  text-shadow: 0 0 14px rgba(224, 38, 79, .3);
}
.adm-presets { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 4px; }
.adm-preset {
  min-width: 0;
  min-height: 48px;
  padding: 0 2px;
  appearance: none;
  border: 1px solid rgba(148, 163, 184, .14);
  cursor: pointer;
  border-radius: 9px;
  background: var(--field);
  color: var(--brand-ink);
  font: inherit;
  font-size: var(--t-micro);
  font-weight: 800;
  letter-spacing: .01em;
  white-space: nowrap;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .04);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast), color var(--motion-fast);
}
.adm-preset:hover { color: var(--ink); }
.adm-preset:active { transform: translateY(var(--press-y)); }
.adm-preset:focus-visible { outline: 3px solid var(--brand-2); outline-offset: -3px; }
.adm-expiry { display: flex; align-items: flex-end; gap: 6px; }
.adm-expiry-fld { flex: 1 1 auto; }
.adm-expiry .adm-input { color: var(--ink); color-scheme: dark; }
.adm-expiry-set { flex: none; min-height: 48px; padding: 0 16px; }

/* ---- the Mind Ladder preview: the real capsule, in player colours ---- */
.adm-pv {
  padding: 10px;
  border-radius: 12px;
  border: 1px solid rgba(245, 158, 11, .16);
  background:
    radial-gradient(120% 130% at 0% 0%, rgba(245, 158, 11, .07) 0%, transparent 58%),
    rgba(9, 14, 23, .72);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .05);
}
.adm-pv-top { display: flex; align-items: center; gap: 8px; min-width: 0; }
.adm-pv-crest {
  flex: none;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 10px;
  border: 1px solid rgba(252, 211, 77, .28);
  background: rgba(245, 158, 11, .1);
  color: var(--tiq);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .08);
}
.adm-pv-crest .ico { width: 16px; height: 16px; }
.adm-pv-title { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.adm-pv-title b {
  font-size: var(--t-3);
  font-weight: 800;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.adm-pv-title small {
  min-width: 0;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .04em;
  color: var(--ink-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.adm-pv .ml-season { flex: none; }
.adm-pv-note { margin: 8px 0 0; font-size: 9px; line-height: 1.45; color: var(--ink-soft); }

/* the capsule's live states, shared with the real ladder header */
.ml-season[data-tone="ending"] {
  border-color: rgba(252, 211, 77, .55);
  background:
    radial-gradient(130% 180% at 0% 0%, rgba(251, 191, 36, .28) 0%, transparent 58%),
    rgba(245, 158, 11, .14);
  color: #FDE68A;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .1),
    inset 0 0 0 1px rgba(255, 255, 255, .04),
    0 1px 0 rgba(0, 0, 0, .4),
    0 0 20px -10px rgba(245, 158, 11, .95);
}
.ml-season[data-tone="ending"] .ml-season-k { color: rgba(253, 230, 138, .75); }
.ml-season[data-tone="locked"] {
  border-color: rgba(251, 113, 133, .42);
  background:
    radial-gradient(130% 180% at 0% 0%, rgba(251, 113, 133, .2) 0%, transparent 58%),
    rgba(224, 38, 79, .12);
  color: var(--red-ink);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .08),
    inset 0 0 0 1px rgba(255, 255, 255, .03),
    0 1px 0 rgba(0, 0, 0, .4),
    0 0 20px -12px rgba(224, 38, 79, .9);
}
.ml-season[data-tone="locked"] .ml-season-k { color: rgba(253, 164, 175, .72); }
.ml-season[data-tone="locked"] .ml-pulse {
  background: #FB7185;
  box-shadow: 0 0 0 3px rgba(251, 113, 133, .14), 0 0 8px rgba(224, 38, 79, .9), inset 0 0 1px #FFE4E6;
}
.ml-season[data-tone="closed"] {
  border-color: rgba(148, 163, 184, .28);
  background: rgba(148, 163, 184, .09);
  color: #CBD5E1;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .06), 0 1px 0 rgba(0, 0, 0, .4);
}
.ml-season[data-tone="closed"] .ml-season-k { color: rgba(203, 213, 225, .62); }
.ml-season[data-tone="closed"] .ml-pulse {
  background: #94A3B8;
  box-shadow: 0 0 0 3px rgba(148, 163, 184, .14), 0 0 6px rgba(148, 163, 184, .55);
}
.ml-season[data-tone="closed"] .ml-pulse::after { display: none; }

/* ---- the final snapshot ---- */
.adm-arena-snap { display: flex; flex-direction: column; gap: 0; margin: 0; padding: 0; list-style: none; }
.adm-snap-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  border-top: 1px solid rgba(148, 163, 184, .09);
  font-size: var(--t-3);
}
.adm-snap-row:first-child { border-top: 0; }
.adm-snap-rank {
  flex: none;
  width: 24px;
  font-size: 10px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  color: var(--ink-soft);
}
.adm-snap-row:nth-child(1) .adm-snap-rank { color: var(--honey-ink); }
.adm-snap-row:nth-child(2) .adm-snap-rank { color: #CBD5E1; }
.adm-snap-row:nth-child(3) .adm-snap-rank { color: #C98A5B; }
.adm-snap-name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 800;
  color: var(--ink);
}
.adm-snap-tiq {
  flex: none;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--honey-ink);
}
.adm-reset, .adm-stop { width: 100%; margin: 0; }
.adm-stop { display: flex; align-items: center; justify-content: center; gap: 8px; }
.adm-stop .ico { width: 16px; height: 16px; }

@media (max-width: 380px) {
  .adm-arena-card { padding: 10px; gap: 8px; }
  .adm-preset { font-size: 9px; }
  .adm-count { font-size: 1rem; letter-spacing: 0; }
  .adm-div-i { width: 72px; }
  .adm-pv .ml-season { padding: 4px 8px; }
}

/* ==========================================================================
   TOOLS — the grants, the ladder preview and the two resets.
   ========================================================================== */
.adm-tools { display: flex; gap: var(--s2); }
.adm-tool {
  flex: 1 1 0;
  min-width: 0;
  min-height: 118px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 2px;
  padding: 12px 12px 13px;
  appearance: none;
  border: 0;
  font: inherit;
  text-align: left;
  cursor: pointer;
  border-radius: var(--radius-md);
  background: var(--clay-face);
  color: var(--ink);
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast);
}
.adm-tool:active { transform: translateY(var(--press-y)); }
.adm-tool:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.adm-tool-v {
  font-size: clamp(1.25rem, 1rem + 1.6vw, 1.7rem);
  font-weight: 900;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--honey-ink);
  text-shadow: 0 1px 0 rgba(0, 0, 0, .55);
}
.adm-tool-t {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

/* ---- live server: one readable stack — status, counters, controls, inspector ----
   Four clay groups on the stage instead of one crowded slab: a status card that
   says what the backend is doing, four tactile counters, an operation card and
   the inspector well. The stage body is the only scroll area. */
.adm-server {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

/* the section masthead: the name and the raw connection state */
.adm-server-head { display: flex; align-items: center; gap: var(--s2); padding: 0 2px; }
.adm-server-t {
  flex: 1 1 auto;
  min-width: 0;
  font-size: var(--t-1);
  font-weight: 800;
  letter-spacing: -.01em;
  color: var(--ink);
}
.adm-server-chip {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 26px;
  padding: 0 10px;
  border-radius: var(--radius-pill);
  font-size: 9.5px;
  font-weight: 900;
  letter-spacing: .09em;
  text-transform: uppercase;
  color: var(--ink-soft);
  background: var(--field);
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, .45), inset 0 0 0 1px var(--hair-off);
  transition: color var(--motion-fast), background var(--motion-fast), box-shadow var(--motion-fast);
}
.adm-server-chip::before {
  content: '';
  flex: none;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 8px 1px currentColor;
}
.adm-server[data-state="live"] .adm-server-chip {
  color: var(--mint-ink);
  background: rgba(16, 185, 129, .12);
  box-shadow: inset 0 0 0 1px rgba(16, 185, 129, .38), inset 0 2px 4px rgba(0, 0, 0, .35);
}
.adm-server[data-state="connecting"] .adm-server-chip,
.adm-server[data-state="denied"] .adm-server-chip {
  color: var(--honey-ink);
  background: var(--honey-soft);
  box-shadow: inset 0 0 0 1px rgba(245, 158, 11, .34), inset 0 2px 4px rgba(0, 0, 0, .35);
}
.adm-server[data-state="offline"] .adm-server-chip {
  color: var(--red-ink);
  background: rgba(224, 38, 79, .12);
  box-shadow: inset 0 0 0 1px rgba(224, 38, 79, .34), inset 0 2px 4px rgba(0, 0, 0, .35);
}

/* ---- the status card: a soft clay slab tinted by the room's own state ---- */
.adm-srv-hero {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 14px 14px 14px 16px;
  border-radius: 22px;
  background:
    radial-gradient(120% 160% at 0% 0%, rgba(16, 185, 129, .17), rgba(16, 185, 129, 0) 56%),
    var(--clay-face);
  box-shadow:
    0 18px 30px -24px rgba(0, 0, 0, .95),
    inset 0 2px 2px rgba(255, 255, 255, .1),
    inset 0 -4px 7px rgba(0, 0, 0, .28),
    inset 0 0 0 1px rgba(255, 255, 255, .055);
}
.adm-server[data-state="connecting"] .adm-srv-hero,
.adm-server[data-state="denied"] .adm-srv-hero {
  background:
    radial-gradient(120% 160% at 0% 0%, rgba(245, 158, 11, .15), rgba(245, 158, 11, 0) 56%),
    var(--clay-face);
}
.adm-server[data-state="offline"] .adm-srv-hero {
  background:
    radial-gradient(120% 160% at 0% 0%, rgba(224, 38, 79, .16), rgba(224, 38, 79, 0) 56%),
    var(--clay-face);
}
.adm-srv-lamp {
  flex: none;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: var(--ink-soft);
  box-shadow:
    0 0 0 4px rgba(148, 163, 184, .12),
    0 0 0 8px rgba(148, 163, 184, .05);
  transition: background var(--motion-fast), box-shadow var(--motion-fast);
}
.adm-server[data-state="live"] .adm-srv-lamp {
  background: var(--mint);
  box-shadow:
    0 0 0 4px rgba(16, 185, 129, .16),
    0 0 0 8px rgba(16, 185, 129, .06),
    0 0 16px 3px rgba(16, 185, 129, .6);
}
.adm-server[data-state="connecting"] .adm-srv-lamp,
.adm-server[data-state="denied"] .adm-srv-lamp {
  background: var(--honey);
  box-shadow: 0 0 0 4px rgba(245, 158, 11, .16), 0 0 12px 2px rgba(245, 158, 11, .35);
}
.adm-server[data-state="offline"] .adm-srv-lamp {
  background: var(--bad-1);
  box-shadow: 0 0 0 4px rgba(224, 38, 79, .14), 0 0 12px 2px rgba(224, 38, 79, .3);
}
@media (prefers-reduced-motion: no-preference) {
  .adm-server[data-state="live"] .adm-srv-lamp { animation: adm-dot 2.4s ease-in-out infinite; }
}
html.reduced-motion .adm-srv-lamp { animation: none; }
.adm-srv-state-txt { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.adm-srv-state-txt b {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 17px;
  font-weight: 900;
  letter-spacing: -.01em;
  color: var(--ink);
}
.adm-server[data-state="live"] .adm-srv-state-txt b { color: var(--mint-ink); }
.adm-server[data-state="live"][data-maint="true"] .adm-srv-state-txt b { color: var(--honey-ink); }
.adm-server[data-state="live"][data-maint="true"] .adm-srv-hero {
  background:
    radial-gradient(120% 160% at 0% 0%, rgba(245, 158, 11, .15), rgba(245, 158, 11, 0) 56%),
    var(--clay-face);
}
.adm-server[data-state="offline"] .adm-srv-state-txt b { color: var(--red-ink); }
.adm-server[data-state="denied"] .adm-srv-state-txt b { color: var(--honey-ink); }
.adm-srv-state-txt span {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.35;
  color: var(--ink-soft);
}
.adm-srv-ping {
  min-width: 68px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0;
  padding: 8px 10px;
  border-radius: 16px;
  background: rgba(8, 13, 24, .55);
  box-shadow: inset 0 2px 6px rgba(0, 0, 0, .5), inset 0 0 0 1px rgba(255, 255, 255, .055);
}
.adm-srv-ping b {
  font-size: 21px;
  font-weight: 900;
  line-height: 1.05;
  font-variant-numeric: tabular-nums;
  color: var(--mint-ink);
}
.adm-srv-ping[data-tone="warm"] b { color: var(--honey-ink); }
.adm-srv-ping[data-tone="bad"] b { color: var(--red-ink); }
.adm-srv-ping[data-tone="off"] b { color: var(--ink-soft); }
.adm-srv-ping span {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

/* ---- the counters: two-up clay tiles, one icon and one plain-language label ---- */
.adm-srv-stats { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.adm-srv-stat {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  padding: 11px 12px;
  border-radius: 18px;
  background: var(--clay-face);
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring);
}
.adm-srv-stat-i {
  flex: none;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 13px;
  background: var(--field);
  color: var(--brand-ink);
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, .48), inset 0 0 0 1px var(--hair-off);
}
.adm-srv-stat-i .ico { width: 17px; height: 17px; }
.adm-srv-stat[data-tone="mint"] .adm-srv-stat-i { color: var(--mint-ink); }
.adm-srv-stat[data-tone="brand"] .adm-srv-stat-i { color: var(--chip-ink); }
.adm-srv-stat[data-tone="honey"] .adm-srv-stat-i { color: var(--honey-ink); }
.adm-srv-stat-txt { min-width: 0; display: flex; flex-direction: column; gap: 0; }
.adm-srv-stat-txt b {
  font-size: 23px;
  font-weight: 900;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
}
.adm-srv-stat-l {
  font-size: 10.5px;
  font-weight: 700;
  line-height: 1.25;
  color: var(--ink-soft);
}

/* ---- controls: two keys and the maintenance lock in one clay card ---- */
.adm-srv-controls {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  border-radius: 22px;
  background: var(--clay-face);
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring);
}
.adm-srv-buttons { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.adm-srv-buttons .adm-btn {
  min-height: 50px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 10px;
  font-size: var(--t-2);
}
.adm-srv-buttons .ico { flex: none; width: 16px; height: 16px; }
.adm-srv-refresh .ico { color: var(--honey-ink); }
.adm-srv-refresh[data-busy="true"] { cursor: progress; color: var(--mint-ink); }
.adm-srv-refresh[data-busy="true"] .ico { color: var(--mint-ink); animation: adm-live-spin .75s linear infinite; }
html.reduced-motion .adm-srv-refresh[data-busy="true"] .ico { animation-duration: 1.8s; }
/* destructive, but still a clay key: red ink and a red rim, never a neon block */
.adm-srv-flush {
  color: var(--red-ink);
  background: linear-gradient(180deg, rgba(224, 38, 79, .16) 0%, rgba(140, 20, 48, .14) 100%), var(--clay-face);
  box-shadow:
    0 var(--lip) 0 rgba(90, 8, 28, .6),
    var(--clay-spec), var(--clay-bevel),
    inset 0 0 0 1px rgba(224, 38, 79, .32);
}
.adm-srv-flush .ico { color: var(--red-ink); }
.adm-srv-hint { margin: 0; padding: 0 2px; font-size: 10.5px; line-height: 1.4; color: var(--ink-soft); }

/* the maintenance row: a recessed track with the lock, a plain-language caption and the knob */
.adm-srv-maint {
  appearance: none;
  border: 0;
  font: inherit;
  text-align: left;
  cursor: pointer;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 58px;
  padding: 10px 12px;
  border-radius: 16px;
  background: var(--field);
  color: var(--ink);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
  transition: box-shadow var(--motion-fast);
}
.adm-srv-maint:active { transform: translateY(1px); }
.adm-srv-maint:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.adm-srv-maint-i {
