}
.adm-srv-maint-i .ico { width: 16px; height: 16px; }
.adm-srv-maint-copy { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.adm-srv-maint-top { display: flex; align-items: center; gap: 8px; min-width: 0; }
.adm-srv-maint-top b { font-size: var(--t-2); font-weight: 800; color: var(--ink); }
.adm-srv-maint-state {
  flex: none;
