  box-shadow: 0 2px 0 var(--gold-lip), inset 0 1px 0 rgba(255, 255, 255, .5);
}
@media (prefers-reduced-motion: reduce) { .adm-srv-knob i { transition: none; } }

/* ---- the inspector: a heading with its reading, then a recessed well of clay rows ---- */
.adm-server-inspector { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.adm-server-inspector-head { display: flex; align-items: flex-start; flex-wrap: wrap; gap: 6px 10px; padding: 0 2px; }
.adm-server-inspector-copy { flex: 1 1 150px; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.adm-server-inspector-t {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--ink);
}
.adm-server-inspector-sub { font-size: 10.5px; font-weight: 600; color: var(--ink-soft); }
.adm-server-inspector-meta {
  flex: none;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 3px 9px;
  border-radius: var(--radius-pill);
  background: var(--field);
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, .4), inset 0 0 0 1px var(--hair-off);
  font-size: 10px;
  font-weight: 800;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}
.adm-server[data-state="live"] .adm-server-inspector-meta { color: var(--mint-ink); }
.adm-server-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 7px;
  list-style: none;
  border-radius: 20px;
  background: var(--field);
  box-shadow:
    inset 0 3px 8px rgba(0, 0, 0, .55),
    inset 0 -1px 0 rgba(255, 255, 255, .05),
    inset 0 0 0 1px var(--hair-off);
}
.adm-server-group {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 6px 2px;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .09em;
  text-transform: uppercase;
  color: var(--mint-ink);
}
.adm-server-group[data-tone="sky"] { color: var(--brand-ink); }
.adm-server-group[data-tone="honey"] { color: var(--honey-ink); }
.adm-server-group b {
  flex: none;
  min-width: 19px;
  padding: 1px 6px;
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, .08);
  color: var(--ink);
  font-size: 9.5px;
  text-align: center;
}
.adm-server-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 58px;
  padding: 8px 8px 8px 9px;
  border-radius: 16px;
  background: var(--clay-face);
  box-shadow:
    0 8px 16px -14px rgba(0, 0, 0, .9),
    inset 0 1px 1px rgba(255, 255, 255, .07),
    inset 0 -2px 3px rgba(0, 0, 0, .25),
    inset 0 0 0 1px rgba(255, 255, 255, .05);
}
.adm-server-i {
  flex: none;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 12px;
  background: var(--field);
  color: var(--brand-ink);
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, .5), inset 0 0 0 1px var(--hair-off);
}
.adm-server-i .ico { width: 17px; height: 17px; }
.adm-server-row.is-multi .adm-server-i { color: var(--mint-ink); }
.adm-server-row.is-lobby .adm-server-i { color: var(--honey-ink); }
.adm-server-txt { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.adm-server-n {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--t-2);
  font-weight: 800;
  color: var(--ink);
}
.adm-server-m {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  font-size: 10.5px;
  font-weight: 600;
  line-height: 1.35;
  font-variant-numeric: tabular-nums;
  color: var(--ink-soft);
}
.adm-server-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  min-height: 148px;
  padding: 22px 16px;
  text-align: center;
}
.adm-server-empty-i {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  margin-bottom: 5px;
  border-radius: 16px;
  background: var(--clay-face);
  color: var(--ink-soft);
  box-shadow: var(--clay-spec), var(--clay-bevel), var(--clay-ring), 0 10px 18px -16px rgba(0, 0, 0, .9);
}
.adm-server-empty-i .ico { width: 19px; height: 19px; }
.adm-server[data-state="connecting"] .adm-server-empty-i .ico { animation: adm-live-spin 1.6s linear infinite; }
html.reduced-motion .adm-server[data-state="connecting"] .adm-server-empty-i .ico { animation: none; }
.adm-server-empty b { font-size: var(--t-2); font-weight: 800; color: var(--ink); }
.adm-server-empty-b { max-width: 250px; font-size: 10.5px; line-height: 1.45; color: var(--ink-soft); }
/* the one action a roster row carries, still a full 48px key */
.adm-abort {
  flex: none;
  min-width: 66px;
  min-height: 48px;
  padding: 0 12px;
  border-radius: 14px;
  font-size: 11px;
  font-weight: 800;
  color: var(--red-ink);
  background: linear-gradient(180deg, rgba(224, 38, 79, .14) 0%, rgba(140, 20, 48, .12) 100%), var(--clay-face);
  box-shadow:
    0 var(--lip) 0 rgba(90, 8, 28, .55),
    var(--clay-spec), var(--clay-bevel),
    inset 0 0 0 1px rgba(224, 38, 79, .3);
}
.adm-code {
  padding: 1px 4px;
  border-radius: 4px;
  background: rgba(0, 0, 0, .28);
  box-shadow: inset 0 0 0 1px var(--hair-off);
  color: var(--honey-ink);
  font-size: .95em;
  white-space: nowrap;
}

/* ==========================================================================
   ADMIN LIVE ACTIVITY — the dual-tier incoming event feed at the head of the
   Inbox. Two materials, one geometry: an opaque obsidian card, a 42px
   medallion and a minmax(0, 1fr) text column that can never widen a 320px
   admin column. Tier A is cyan/mint; Tier B is Imperial Gold with a bevel,
   a linear highlight, a corner jewel and a diagonal sheen. Every handle,
   amount and timestamp carries dir="ltr" + unicode-bidi: isolate.
   ========================================================================== */
.admin-activity {
  display: flex;
  flex-direction: column;
  gap: 9px;
  min-width: 0;
  max-width: 100%;
}
.admin-events-head {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  max-width: 100%;
}
.admin-events-h { flex: 0 1 auto; min-width: 0; margin: 0; }
.admin-events-live {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px;
  border-radius: var(--radius-pill);
  background: rgba(0, 210, 255, .09);
  box-shadow: inset 0 0 0 1px rgba(0, 210, 255, .32);
  color: #7FE7FF;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .12em;
  line-height: 1;
}
.admin-events-live-dot {
  width: 5px;
  height: 5px;
  flex: none;
  border-radius: 50%;
  background: #39E6B4;
  box-shadow: 0 0 7px 1px rgba(16, 185, 129, .9);
}
@keyframes event-live-breathe { 0%, 100% { opacity: 1 } 50% { opacity: .42 } }
@media (prefers-reduced-motion: no-preference) {
  .admin-events-live-dot { animation: event-live-breathe 2.4s ease-in-out infinite; }
}
html.reduced-motion .admin-events-live-dot { animation: none !important; }
.admin-events-unread {
  flex: none;
  margin-inline-start: auto;          /* logical: the far edge in RTL too */
  padding: 3px 8px;
  border-radius: var(--radius-pill);
  background: var(--gold-face);
  color: #10141D;
  font-size: 9.5px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  box-shadow:
    0 2px 0 var(--gold-lip),
    inset 0 1px 0 rgba(255, 255, 255, .5),
    0 0 12px -3px rgba(245, 158, 11, .8);
}
.admin-events-unread[hidden] { display: none !important; }
.admin-activity-rule {
  flex: none;
  height: 1px;
  margin: 2px 0 4px;
  background: linear-gradient(90deg, transparent, rgba(148, 163, 184, .28) 18%,
    rgba(148, 163, 184, .28) 82%, transparent);
}
.admin-events {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
  min-width: 0;
  max-width: 100%;
}
.admin-events-empty {
  margin: 0;
  padding: 14px 12px;
  border-radius: var(--radius-md);
  background: var(--clay-face);
  box-shadow: var(--clay-drop), var(--clay-bevel), inset 0 0 0 1px var(--hair-off);
  color: var(--ink-soft);
  font-size: var(--t-micro);
  line-height: 1.5;
  text-align: center;
}
.admin-events-empty[hidden] { display: none !important; }

/* ---- shared chassis: the medallion never grows, the text column always shrinks ---- */
.event-card {
  position: relative;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  align-items: start;
  gap: 10px;
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  padding: 11px 11px 12px;
  border-radius: var(--radius-md);
  isolation: isolate;
  overflow: hidden;
}
.event-medallion,
.event-body { position: relative; z-index: 1; }
.event-medallion {
  width: 42px;
  height: 42px;
  flex: none;
  display: grid;
  place-items: center;
  border-radius: 13px;
  font-size: 21px;
  line-height: 1;
}
.event-medallion .ico { display: block; width: 22px; height: 22px; }
.event-body {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  max-width: 100%;
}
.event-top { display: flex; align-items: center; gap: 6px; min-width: 0; max-width: 100%; }
.event-title {
  margin: 0;
  min-width: 0;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .1em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.event-tier {
  flex: none;
  padding: 2px 6px;
  border-radius: var(--radius-pill);
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .08em;
  line-height: 1.2;
}
.event-card.is-unread .event-top::before {
  content: '';
  flex: none;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #39E6B4;
  box-shadow: 0 0 7px 1px rgba(16, 185, 129, .8);
}
.event-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 8px;
  min-width: 0;
  max-width: 100%;
  font-size: 10px;
  line-height: 1.35;
  color: var(--ink-soft);
}
.event-meta > * { min-width: 0; max-width: 100%; }
/* a label and its value stay welded together when the meta row wraps on a 320px phone */
.event-pair {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  max-width: 100%;
}
.event-pair > * { min-width: 0; }
.event-k { opacity: .72; font-weight: 700; letter-spacing: .04em; }
.event-handle {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--ink);
  font-weight: 800;
}
.event-time { color: var(--ink-soft); }
/* handles, currency and timestamps keep their own LTR run inside an RTL sentence */
.event-ltr {
  direction: ltr;
  unicode-bidi: isolate;
  font-variant-numeric: tabular-nums;
  font-feature-settings: 'tnum' 1;
}
/* Persian/Arabic are joined scripts: tracking would tear the words apart */
html[data-lang="fa"] :is(.event-body, .admin-events-head, .admin-events-empty),
html[data-lang="ar"] :is(.event-body, .admin-events-head, .admin-events-empty) { direction: rtl; }
html[data-lang="fa"] :is(.event-title, .event-tier, .event-k, .admin-events-live),
html[data-lang="ar"] :is(.event-title, .event-tier, .event-k, .admin-events-live) { letter-spacing: 0; }

/* ---- Tier 1: New Member — cyan / mint, cyan hairline, quiet node medallion ---- */
.event-card-join {
  background: linear-gradient(135deg, rgba(0, 210, 255, .15) 0%,
    rgba(12, 21, 31, .94) 62%, rgba(12, 21, 31, .96) 100%);
  box-shadow:
    var(--clay-drop),
    inset 0 0 0 1px rgba(0, 210, 255, .38),
    inset 0 1px 0 rgba(255, 255, 255, .07),
    0 0 18px -10px rgba(0, 210, 255, .8);
}
.event-card-join .event-medallion {
  color: #8DEBFF;
  background: linear-gradient(160deg, rgba(0, 210, 255, .22), rgba(6, 16, 24, .9));
  box-shadow:
    inset 0 0 0 1px rgba(0, 210, 255, .5),
    inset 0 1px 0 rgba(255, 255, 255, .16),
    0 0 14px -6px rgba(0, 210, 255, .85);
}
.event-card-join .event-title { color: #9DEFFF; }
.event-card-join .event-tier {
  color: #06232B;
  background: linear-gradient(180deg, #7CF0D0, #22BFA8);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .5);
}
.event-card-join .event-handle { color: #A7F3E4; }

/* ---- Tier 2: VIP Purchase — Imperial Gold obsidian, beveled, lit ---- */
.event-card-vip {
  background: linear-gradient(135deg, rgba(255, 184, 0, .12) 0%,
    rgba(18, 24, 38, .9) 58%, rgba(11, 15, 24, .96) 100%);
  border: 1px solid rgba(255, 215, 0, .4);
  box-shadow:
    var(--clay-drop),
    inset 0 1px 0 rgba(255, 233, 168, .22),
    inset 0 -1px 0 rgba(92, 56, 8, .6),
    0 0 22px -10px rgba(255, 184, 0, .8);
}
/* the linear highlight bar across the crown of the card */
.event-card-vip::before {
  content: '';
  position: absolute;
  inset-block-start: 0;
  inset-inline: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, rgba(255, 215, 0, .18) 12%,
    rgba(255, 236, 160, .9) 42%, rgba(255, 215, 0, .28) 72%, transparent);
  pointer-events: none;
}
/* a diagonal sheen: translucent, untappable, and clipped by the card itself */
.event-card-vip::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(112deg, transparent 34%, rgba(255, 236, 170, .085) 49%,
    rgba(255, 255, 255, .045) 54%, transparent 68%);
  pointer-events: none;
}
.event-card-vip > .event-jewel {
  position: absolute;
  top: 9px;
  inset-inline-end: 9px;
  width: 8px;
  height: 8px;
  transform: rotate(45deg);
  border-radius: 2px;
  background: linear-gradient(135deg, #FFF8DC 0%, #FCD34D 45%, #A46A12 100%);
  box-shadow: 0 0 9px rgba(255, 184, 0, .85), inset 0 0 0 1px rgba(255, 255, 255, .5);
  pointer-events: none;
}
.event-card-vip .event-medallion {
  color: #FFE9AE;
  background: linear-gradient(160deg, #3A2A12 0%, #17120B 55%, #0C1019 100%);
  box-shadow:
    inset 0 0 0 1px rgba(255, 215, 0, .6),
    inset 0 1px 0 rgba(255, 246, 200, .3),
    inset 0 -2px 3px rgba(0, 0, 0, .6),
    0 3px 0 #0A0E15,
    0 0 16px -3px rgba(255, 184, 0, .7);
  filter: drop-shadow(0 0 7px rgba(255, 184, 0, .55));
  text-shadow: 0 0 12px rgba(255, 184, 0, .8);
}
.event-card-vip .event-title {
  color: #F6D97F;
  text-shadow: 0 0 10px rgba(255, 184, 0, .32);
}
@supports ((-webkit-background-clip: text) or (background-clip: text)) {
  .event-card-vip .event-title {
    background: linear-gradient(100deg, #FFF3C4 0%, #FFD75E 38%, #E8A72B 72%, #FFF0B8 100%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
    text-shadow: none;
  }
}
.event-card-vip .event-tier {
  color: #211603;
  background: linear-gradient(180deg, #FFE9A8, #E9A62C);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .65), 0 0 10px -3px rgba(255, 184, 0, .8);
}
.event-card-vip.is-unread .event-top::before {
  background: #FFB800;
  box-shadow: 0 0 8px 1px rgba(255, 184, 0, .9);
}
.event-card-vip .event-handle { color: #FFE9AE; }
.event-amount {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  max-width: 100%;
  padding: 3px 8px;
  border-radius: var(--radius-pill);
  background: linear-gradient(180deg, rgba(255, 184, 0, .16), rgba(255, 184, 0, .05));
  box-shadow: inset 0 0 0 1px rgba(255, 215, 0, .42);
  color: #FFE29A;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.event-amount b { font-size: 12px; }
.event-amount-u { font-size: 8.5px; letter-spacing: .06em; opacity: .82; }

/* ---- 320px–390px phones: everything still fits one column, no h-scroll ---- */
@media (max-width: 390px) {
  .admin-events-head { gap: 6px; }
  .admin-events-live, .admin-events-unread { padding: 3px 6px; font-size: 8.5px; }
  .event-card { grid-template-columns: 38px minmax(0, 1fr); gap: 8px; padding: 10px 9px 11px; }
  .event-medallion { width: 38px; height: 38px; border-radius: 11px; font-size: 19px; }
  .event-medallion .ico { width: 20px; height: 20px; }
  .event-title { font-size: 10.5px; letter-spacing: .06em; }
  .event-meta { gap: 3px 6px; font-size: 9.5px; }
  .event-amount b { font-size: 11px; }
}

/* ==========================================================================
   INBOX — the support desk: filter chips over ticket cards, one expanded
   card carrying the profile, a deeply recessed reply well and the two keys.
   ========================================================================== */
.adm-inbox-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
/* the type bar and the verification bar read as one control group, not two loose rows */
.adm-filter-stack {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}
.adm-chip {
  appearance: none;
  border: 0;
  font: inherit;
  cursor: pointer;
  height: 32px;
  min-height: 32px;
  padding: 0 12px;
  border-radius: var(--radius-pill);
  background: var(--field);
  color: var(--ink-soft);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .01em;
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast),
              background var(--motion-fast), color var(--motion-fast);
}
.adm-chip:active { transform: translateY(var(--press-y)); }
.adm-chip:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
/* active: an obsidian chip lit by amber, not a filled pill competing with the page's one action */
.adm-chip[aria-pressed="true"] {
  color: var(--honey-ink);
  background:
    linear-gradient(180deg, rgba(245, 158, 11, .2) 0%, rgba(245, 158, 11, .06) 100%),
    var(--field);
  box-shadow:
    inset 0 0 0 1px rgba(245, 158, 11, .44),
    inset 0 1px 0 rgba(255, 255, 255, .08),
    0 0 14px -6px rgba(245, 158, 11, .85);
}
/* the Obsidian VIP shortcut: gold ink over an obsidian face, lit but not filled until chosen */
.adm-chip-vip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--gold-ink);
  background: linear-gradient(180deg, rgba(38, 32, 22, .92) 0%, rgba(13, 16, 24, .94) 100%);
  box-shadow:
    var(--inset),
    inset 0 0 0 1px rgba(252, 211, 77, .34),
    0 0 16px -7px rgba(245, 158, 11, .8);
}
.adm-chip-vip > span[aria-hidden="true"] {
  font-size: 11px;
  line-height: 1;
  filter: drop-shadow(0 0 5px rgba(245, 158, 11, .55));
}
.adm-chip-vip[aria-pressed="true"] > span[aria-hidden="true"] { filter: none; }

.adm-inbox-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.adm-ticket {
  border-radius: var(--radius-md);
  background: var(--clay-face);
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring);
  transition: box-shadow var(--motion-fast);
}
.adm-ticket.is-open {
  box-shadow:
    var(--clay-drop), var(--clay-spec), var(--clay-bevel),
    inset 0 0 0 1px rgba(252, 211, 77, .28);
}
.adm-ticket-main {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
  min-height: 48px;
  padding: 10px 11px;
  appearance: none;
  border: 0;
  font: inherit;
  text-align: left;
  cursor: pointer;
  border-radius: var(--radius-md);
  background: none;
  color: var(--ink);
}
.adm-ticket-main:focus-visible { outline: 3px solid var(--brand-2); outline-offset: -3px; }
.adm-ticket-top {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}
.adm-ticket-cat {
  flex: none;
  padding: 3px 7px;
  border-radius: var(--radius-pill);
  background: var(--field);
  color: var(--brand-ink);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  box-shadow: inset 0 0 0 1px var(--hair-off);
}
.adm-ticket-cat[data-cat="bug"] { color: var(--red-ink); }
.adm-ticket-cat[data-cat="stars"] { color: var(--honey-ink); }
.adm-ticket-who {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--t-micro);
  font-weight: 800;
  color: var(--ink);
}
.adm-ticket-when {
  flex: none;
  font-size: 9px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--ink-soft);
}
.adm-ticket-status {
  flex: none;
  padding: 3px 7px;
  border-radius: var(--radius-pill);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
  background: var(--field);
  color: var(--ink-soft);
  box-shadow: inset 0 0 0 1px var(--hair-off);
}
.adm-ticket-status[data-status="new"] {
  background: var(--honey-soft);
  color: var(--honey-ink);
  box-shadow: inset 0 0 0 1px rgba(245, 158, 11, .4);
}
.adm-ticket-status[data-status="replied"] {
  background: var(--mint-soft);
  color: var(--mint-ink);
  box-shadow: inset 0 0 0 1px rgba(16, 185, 129, .4);
}
.adm-ticket-snip {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  font-size: var(--t-micro);
  line-height: 1.45;
  color: var(--ink-soft);
}
.adm-ticket-detail {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0 11px 11px;
  padding-top: 10px;
  border-top: 1px solid var(--hair);
}
.adm-ticket-profile {
  margin: 0;
  font-size: 10px;
  font-weight: 700;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}
.adm-ticket-full {
  margin: 0;
  font-size: var(--t-2);
  line-height: 1.5;
  color: var(--ink);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.adm-ticket-prev {
  margin: 0;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  background: var(--field);
  box-shadow: var(--inset);
  font-size: var(--t-micro);
  line-height: 1.45;
  color: var(--mint-ink);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
/* the reply well: deepest recess in the panel, with a faint woven texture */
.adm-reply-field {
  display: flex;
  min-height: 84px;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  background:
    repeating-linear-gradient(-45deg, rgba(255, 255, 255, .02) 0 6px, rgba(255, 255, 255, 0) 6px 12px),
    var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-reply {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 68px;
  resize: none;
  appearance: none;
  border: 0;
  background: none;
  outline: none;
  font: inherit;
  font-size: var(--t-2);
  line-height: 1.45;
  color: var(--ink);
  -webkit-user-select: text;
  user-select: text;
}
.adm-reply::placeholder { color: var(--ink-soft); opacity: .65; }
.adm-ticket-actions { display: flex; gap: var(--s2); }
.adm-send { flex: 1 1 auto; }
.adm-resolve { flex: none; }
.adm-resolve[aria-pressed="true"] {
  background: var(--mint-soft);
  color: var(--mint-ink);
  box-shadow:
    0 2px 0 var(--mint-lip),
    inset 0 0 0 1px rgba(16, 185, 129, .4);
}
.adm-btn-gold {
  background: var(--gold-face);
  color: #10141D;
  box-shadow:
    0 var(--lip) 0 var(--gold-lip),
    0 12px 24px -12px rgba(245, 158, 11, .6),
    inset 0 1px 0 rgba(255, 255, 255, .5);
}
.adm-inbox-empty {
  margin: 0;
  padding: 20px 6px;
  text-align: center;
  font-size: var(--t-micro);
  color: var(--ink-soft);
}
/* a short phone: the reply well keeps its depth, the roster did the shrinking already */
@media (max-height: 700px) {
  .adm-reply-field { min-height: 76px; }
  .adm-reply { min-height: 60px; }
}

/* ==========================================================================
   USERS — the player directory: a recessed search well, filter chips over
   directory cards, one expanded card carrying the telemetry grid, the ban
   key and the two coin grants.
   ========================================================================== */
.adm-search {
  display: flex;
  align-items: center;
  gap: var(--s2);
  min-height: 48px;
  padding: 0 11px;
  border-radius: var(--radius-sm);
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-search > .ico { flex: none; width: 15px; height: 15px; color: var(--honey); }
.adm-search-x {
  flex: none;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  appearance: none;
  border: 0;
  cursor: pointer;
  border-radius: var(--radius-pill);
  background: var(--clay-face);
  color: var(--ink-soft);
  box-shadow: 0 2px 0 #0A0E15, inset 0 1px 0 rgba(255, 255, 255, .06);
  transition: transform var(--motion-fast), color var(--motion-fast);
}
.adm-search-x .ico { width: 12px; height: 12px; }
.adm-search-x:active { transform: translateY(var(--press-y)); }
.adm-search-x:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.adm-search-x[hidden] { display: none; }

/* ---- the query toolbar: three recessed clay keys that open bespoke floating menus ----
   The menu is portalled to the Admin stage by admin.ts, so the scrolling body can never clip it.
   It is anchored under its trigger at z-index 100, flips above near the stage floor, and owns a
   260px scroll well of its own. */
.adm-adv {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}
/* a phone gets a calm 2x2 toolbar: four equal keys, no clipping and no horizontal scroll */
@media (max-width: 520px) {
  .adm-adv { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
.adm-fn {
  position: relative;
  min-width: 0;
  min-height: 52px;
  display: flex;
  border-radius: var(--radius-sm);
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
  transition: background var(--motion-fast), box-shadow var(--motion-fast);
}
.adm-fn:hover {
  box-shadow: var(--inset), inset 0 0 0 1px rgba(148, 163, 184, .22);
}
.adm-fn[data-on="true"] {
  background: linear-gradient(180deg, rgba(252, 211, 77, .09) 0%, rgba(252, 211, 77, .02) 100%), var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px rgba(252, 211, 77, .34);
}
.adm-fn[data-open="true"] {
  box-shadow:
    var(--inset),
    inset 0 0 0 1px rgba(252, 211, 77, .52),
    0 0 0 3px rgba(245, 158, 11, .10);
}
.adm-fn:focus-within { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.adm-fn-trigger {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 52px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 3px;
  padding: 6px 9px;
  appearance: none;
  border: 0;
  border-radius: inherit;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.adm-fn-trigger:focus { outline: none; }
.adm-fn-k {
  display: block;
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .12em;
  line-height: 1;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.adm-fn[data-on="true"] .adm-fn-k,
.adm-fn[data-open="true"] .adm-fn-k { color: var(--honey-ink); }
.adm-fn-face {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  height: 18px;
}
.adm-fn-flag { flex: none; display: grid; place-items: center; width: 15px; height: 15px; }
.adm-fn-flag .fp { --fp-d: 15px; }
.adm-fn-flag .fp-chip { border-radius: 50%; font-size: 6px; letter-spacing: 0; }
.adm-fn-globe { width: 14px; height: 14px; color: var(--honey); }
.adm-fn-v {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11.5px;
  font-weight: 800;
  line-height: 1;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.adm-fn-chev {
  flex: none;
  width: 10px;
  height: 10px;
  color: var(--ink-soft);
  transform: rotate(90deg);
  transition: transform var(--motion-fast), color var(--motion-fast);
}
.adm-fn[data-on="true"] .adm-fn-chev,
.adm-fn[data-open="true"] .adm-fn-chev { color: var(--honey-ink); }
.adm-fn[data-open="true"] .adm-fn-chev { transform: rotate(-90deg); }

/* the native plan selector, dressed as the same recessed clay key as its neighbours.
   The visible face is a mirror; the real <select> is an invisible full-pod hit target above it,
   so the 52px key opens the native list on any phone without a cramped 18px control. */
.adm-fn-plan {
  flex-direction: column;
  justify-content: center;
  gap: 3px;
  padding: 6px 9px;
}
.adm-fn-plan[data-on="true"] .adm-fn-k { color: var(--honey-ink); }
.adm-fn-plan-face { position: relative; display: flex; width: 100%; }
.adm-fn-select {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  appearance: none;
  border: 0;
  border-radius: inherit;
  background: transparent;
  opacity: 0;
  cursor: pointer;
}
.adm-fn-select:focus { outline: none; }
.adm-fn-select option { background: #0D131F; color: var(--ink); }
.adm-fn-plan .adm-fn-chev {
  position: absolute;
  right: 0;
  top: 50%;
  margin-top: -5px;
  pointer-events: none;
}
.adm-fn-plan[data-on="true"] .adm-fn-chev { color: var(--honey-ink); }

/* ---- the floating menu: deep frosted slate, one razor rim, one soft ambient shadow ---- */
.custom-select-menu {
  position: absolute;
  z-index: 100;
  max-height: 260px;
  padding: 6px;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(13, 19, 31, 0.94);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.65);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  scrollbar-width: thin;
  scrollbar-color: rgba(148, 163, 184, .34) transparent;
  opacity: 0;
  transform: translateY(-4px) scale(.985);
  transform-origin: top center;
  transition: opacity .15s ease, transform .18s cubic-bezier(.22, .61, .36, 1);
}
.custom-select-menu[hidden] { display: none; }
.custom-select-menu[data-flip="true"] {
  transform: translateY(4px) scale(.985);
  transform-origin: bottom center;
}
.custom-select-menu.is-open { opacity: 1; transform: none; }
.custom-select-menu::-webkit-scrollbar { width: 6px; }
.custom-select-menu::-webkit-scrollbar-track { background: transparent; }
.custom-select-menu::-webkit-scrollbar-thumb {
  border: 1px solid transparent;
  border-radius: 99px;
  background: rgba(148, 163, 184, .34);
  background-clip: padding-box;
}
.custom-select-menu::-webkit-scrollbar-thumb:hover {
  border: 1px solid transparent;
  background: rgba(252, 211, 77, .5);
  background-clip: padding-box;
}

/* one option per row: a quiet slate voice that wakes to white under the finger */
.custom-select-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  min-height: 38px;
  padding: 10px 14px;
  appearance: none;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #94A3B8;
  font: inherit;
  font-size: 13px;
  font-weight: 500;
  line-height: 1.2;
  text-align: left;
  cursor: pointer;
  transition: background var(--motion-fast), color var(--motion-fast);
}
.custom-select-item::before {
  content: '';
  position: absolute;
  left: 0;
  top: 9px;
  bottom: 9px;
  width: 2px;
  border-radius: 0 2px 2px 0;
  background: var(--honey);
  opacity: 0;
  transition: opacity var(--motion-fast);
}
.custom-select-item:hover,
.custom-select-item:focus {
  background: rgba(255, 255, 255, 0.05);
  color: #F8FAFC;
  outline: none;
}
.custom-select-item:hover::before,
.custom-select-item:focus::before { opacity: .8; }
.custom-select-item[aria-selected="true"] {
  color: #F8FAFC;
  background: linear-gradient(90deg, rgba(245, 158, 11, .10), rgba(245, 158, 11, .035));
}
.custom-select-item[aria-selected="true"]::before {
  opacity: 1;
  box-shadow: 0 0 8px rgba(245, 158, 11, .7);
}
.custom-select-ico {
  flex: none;
  width: 16px;
  height: 16px;
  color: var(--honey-ink);
}
.custom-select-flag {
  flex: none;
  display: grid;
  place-items: center;
  width: 18px;
  height: 18px;
}
.custom-select-flag .fp { --fp-d: 18px; }
.custom-select-flag .fp-chip { border-radius: 50%; font-size: 7px; letter-spacing: 0; }
.custom-select-flag .fp-img {
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, .16),
    inset 0 0 0 1px rgba(0, 0, 0, .35);
}
.custom-select-code {
  flex: none;
  min-width: 22px;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .06em;
  color: var(--honey-ink);
  font-variant-numeric: tabular-nums;
}
.custom-select-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.custom-select-chip {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 50px;
  height: 24px;
  padding: 0 7px;
  border-radius: 7px;
  background: rgba(148, 163, 184, .12);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .07);
  color: #CBD5E1;
  font-size: 10.5px;
  font-weight: 900;
  letter-spacing: .02em;
  font-variant-numeric: tabular-nums;
  transition: background var(--motion-fast), color var(--motion-fast), box-shadow var(--motion-fast);
}
.custom-select-item:hover .custom-select-chip,
.custom-select-item:focus .custom-select-chip {
  background: rgba(148, 163, 184, .18);
  color: #F8FAFC;
}
.custom-select-item[aria-selected="true"] .custom-select-chip {
  background: rgba(245, 158, 11, .12);
  box-shadow: inset 0 0 0 1px rgba(245, 158, 11, .28);
  color: var(--honey-ink);
}
.custom-select-check {
  flex: none;
  display: grid;
  place-items: center;
  width: 16px;
  height: 16px;
  color: var(--honey-ink);
  opacity: 0;
  transform: scale(.55);
  filter: drop-shadow(0 0 6px rgba(245, 158, 11, .7));
  transition: opacity var(--motion-fast), transform .18s var(--bounce);
}
.custom-select-check .ico { width: 14px; height: 14px; }
.custom-select-item[aria-selected="true"] .custom-select-check {
  opacity: 1;
  transform: none;
}

.adm-users-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s2);
  margin: 0;
  font-size: var(--t-micro);
  font-weight: 800;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}
.adm-users-src {
  padding: 3px 8px;
  border-radius: var(--radius-pill);
  background: var(--field);
  color: var(--honey-ink);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .08em;
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-users-src[data-live="true"] { color: var(--mint-ink); }
.adm-users-meta-r {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
/* the directory's refresh key: a small clay cap beside the registry chip, spinning while it reads */
.adm-users-refresh {
  flex: none;
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  padding: 0;
  appearance: none;
  border: 0;
  cursor: pointer;
  border-radius: 9px;
  background: var(--clay-face);
  color: var(--honey-ink);
  box-shadow: 0 var(--lip) 0 #0A0E15, var(--clay-drop), var(--clay-spec), var(--clay-bevel);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast), color var(--motion-fast);
}
.adm-users-refresh .ico { width: 14px; height: 14px; }
.adm-users-refresh:active { transform: translateY(var(--press-y)); --lip: 1px; }
.adm-users-refresh:focus-visible { outline: 3px solid var(--brand-2); outline-offset: -3px; }
.adm-users-refresh[data-busy="true"] { cursor: progress; color: var(--mint-ink); }
.adm-users-refresh[data-busy="true"] .ico { animation: adm-live-spin .75s linear infinite; }
html.reduced-motion .adm-users-refresh[data-busy="true"] .ico { animation-duration: 1.8s; }

.adm-users-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}
/* zero results still read like a console state, not a dead end: a key returns every filter home */
.adm-users-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 22px 14px 18px;
  border-radius: var(--radius-md);
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
  text-align: center;
}
.adm-users-empty[hidden] { display: none; }
.adm-users-empty-i {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 14px;
  background: var(--clay-face);
  color: var(--honey-ink);
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring);
}
.adm-users-empty-i .ico { width: 20px; height: 20px; }
.adm-users-empty-t {
  margin: 0;
  font-size: var(--t-2);
  font-weight: 800;
  color: var(--ink);
}
.adm-users-empty-s {
  margin: 0;
  max-width: 280px;
  font-size: var(--t-micro);
  line-height: 1.45;
  color: var(--ink-soft);
}
.adm-users-reset { margin-top: 4px; }
.adm-user {
  border-radius: var(--radius-md);
  background: var(--clay-face);
