  background: var(--honey);
  box-shadow: 0 0 6px rgba(245, 158, 11, .72);
}
.adm-user-side {
  flex: none;
  display: flex;
  align-items: center;
  gap: 6px;
}
.adm-user-st {
  flex: none;
  padding: 3px 7px;
  border-radius: var(--radius-pill);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
  background: var(--field);
  color: var(--ink-soft);
  box-shadow: inset 0 0 0 1px var(--hair-off);
}
.adm-user-st[data-st="live"] {
  background: var(--mint-soft);
  color: var(--mint-ink);
  box-shadow: inset 0 0 0 1px rgba(16, 185, 129, .4);
}
.adm-user-st[data-st="ban"] {
  background: linear-gradient(180deg, var(--bad-1) 0%, var(--bad-2) 100%);
  color: #fff;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .18);
}
.adm-user-st[data-st="mute"] {
  background: var(--honey-soft);
  color: var(--honey-ink);
  box-shadow: inset 0 0 0 1px rgba(245, 158, 11, .4);
}
.adm-user-go {
  width: 14px;
  height: 14px;
  flex: none;
  color: var(--ink-soft);
  transition: transform var(--motion-fast);
}
