.adm-user-detail {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0 11px 11px;
  padding-top: 10px;
  border-top: 1px solid var(--hair);
}
.adm-user-id {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
  margin: 0;
  font-variant-numeric: tabular-nums;
}
.adm-user-id-group {
  display: inline-flex;
  align-items: center;
  gap: 2px;
}
.adm-user-id-chip {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  min-width: 0;
  padding: 3px 7px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, .06);
  background: rgba(255, 255, 255, .03);
}
.adm-user-id-k {
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .06em;
