}
.adm-user-id-v {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 10px;
  font-weight: 800;
  color: var(--chip-ink);
}
.adm-user-id-dot {
  padding: 0 2px;
  font-size: 10px;
  font-weight: 900;
  color: var(--text-dim);
}
.adm-user-cells {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}
.adm-user-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
