}
.adm-user-actions .adm-ugrant {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-height: 42px;
  padding: 0 12px;
  appearance: none;
  border: 1px solid rgba(255, 255, 255, .09);
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, .04);
  color: var(--ink);
  font: inherit;
  font-size: var(--t-micro);
  font-weight: 800;
  font-variant-numeric: tabular-nums;
