}
.adm-ugrant .coin { width: 14px; height: 14px; flex: none; }
@media (max-width: 359px) {
  .adm-user-cells { grid-template-columns: minmax(0, 1fr); }
}

/* ==========================================================================
   SQUADS & CHANNEL WAR — the registry audit. Four compact pulse tiles over a
   real-time filter bar, then one card per registered channel or group with its
   ownership badge, war contribution and the three tactical keys.
   ========================================================================== */
.adm-grid-squads { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.adm-grid-squads .adm-card { min-height: 116px; }
.adm-grid-squads .adm-card-l { font-size: 9.5px; letter-spacing: .045em; }
.adm-grid-squads .adm-card-s { font-size: 9.5px; }
.adm-squads-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.adm-squad {
  display: flex;
  flex-direction: column;
  gap: 9px;
  min-width: 0;
  padding: 11px 11px 14px;
  border-radius: var(--radius-md);
  background: var(--clay-face);
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring);
}
.adm-squad[data-banned="true"] {
  box-shadow:
    var(--clay-drop), var(--clay-spec), var(--clay-bevel),
    inset 0 0 0 1px rgba(244, 63, 94, .34);
}
.adm-squad-head {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  min-width: 0;
}
.adm-squad-ico {
  position: relative;
  overflow: hidden;
  flex: none;
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
  font-size: 14px;
  line-height: 1;
}
.adm-squad-mark {
  font-size: 14px;
  font-weight: 850;
  letter-spacing: .02em;
  color: var(--ink, currentColor);
}
.adm-squad-av {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.adm-squad-av[hidden] { display: none; }
.adm-squad-txt {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
/* two clean lines: a mixed fa/en title keeps each script whole instead of being cut mid-word */
.adm-squad-name {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  white-space: normal;
  overflow-wrap: anywhere;
  unicode-bidi: isolate;
  font-size: var(--t-2);
  font-weight: 800;
  line-height: 1.25;
  color: var(--ink);
}
.adm-squad-sub {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 6px;
  min-width: 0;
}
/* the handle is never ellipsised: it wraps, so @Computer_Science100 stays complete */
.adm-squad-handle {
  min-width: 0;
  max-width: 100%;
  font-size: 10px;
  font-weight: 700;
  line-height: 1.35;
  color: var(--brand-ink);
  font-variant-numeric: tabular-nums;
  unicode-bidi: isolate;
  overflow-wrap: anywhere;
  word-break: break-word;
