.adm-squad-kind {
  flex: none;
  padding: 1px 6px;
  border-radius: var(--radius-pill);
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .05em;
  text-transform: uppercase;
  line-height: 1.5;
  color: var(--ink-soft);
  background: var(--field);
  box-shadow: inset 0 0 0 1px var(--hair-off);
}
.adm-squad-kind[data-kind="channel"] {
