.adm-squad-badges {
  flex: none;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
}
.adm-squad-st {
  padding: 3px 8px;
  border-radius: var(--radius-pill);
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: .045em;
  text-transform: uppercase;
  white-space: nowrap;
  background: var(--field);
  color: var(--ink-soft);
  box-shadow: inset 0 0 0 1px var(--hair-off);
}
.adm-squad-st[data-status="verified"] {
  background: var(--mint-soft);
  color: var(--mint-ink);
  box-shadow: inset 0 0 0 1px rgba(16, 185, 129, .4);
}
.adm-squad-st[data-status="pending"] {
  background: var(--honey-soft);
  color: var(--honey-ink);
  box-shadow: inset 0 0 0 1px rgba(245, 158, 11, .4);
}
.adm-squad-st[data-status="revoked"] {
  background: linear-gradient(180deg, var(--bad-1) 0%, var(--bad-2) 100%);
