.adm-squad-purged {
  padding: 2px 7px;
  border-radius: var(--radius-pill);
  font-size: 9.5px;
  font-weight: 900;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--bad-ink, #fecdd3);
  box-shadow: inset 0 0 0 1px rgba(244, 63, 94, .45);
}
/* the enlisted facts, as micro-tags: owner, chat id (copyable), registration stamp */
.adm-squad-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  min-width: 0;
}
.adm-squad-tag {
  display: inline-flex;
