  width: 11px;
  height: 11px;
  opacity: .8;
}
.adm-squad-tag b { color: var(--ink-soft); font-weight: 800; }
.adm-squad-owner-h {
  color: var(--brand-ink);
  direction: ltr;
  unicode-bidi: isolate;
}
.adm-squad-id {
  appearance: none;
  font: inherit;
  font-family: var(--font-numeric);
