  cursor: pointer;
  transition: color var(--motion-fast), border-color var(--motion-fast), box-shadow var(--motion-fast);
}
.adm-squad-id span { min-width: 0; overflow-wrap: anywhere; }
.adm-squad-id-ico { color: var(--honey-ink); opacity: .8; }
.adm-squad-id:hover:not(:disabled) {
  color: var(--honey-ink);
  border-color: rgba(245, 158, 11, .44);
  box-shadow: 0 0 14px -8px rgba(245, 158, 11, .9);
