.adm-squad-tag-date span { white-space: nowrap; }
.adm-squad-cells {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}
.adm-squad-cell {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  padding: 7px 9px;
  border-radius: 10px;
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-squad-cell b {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--t-2);
  font-weight: 800;
  color: var(--honey-ink);
  font-variant-numeric: tabular-nums;
}
.adm-squad-cell span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
/* two equal keys on top, the war verdict across the full width: nothing can be clipped */
.adm-squad-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
  min-width: 0;
}
.adm-squad-actions .adm-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  width: 100%;
  min-width: 0;
  min-height: 44px;
  padding: 6px 8px;
  font-size: var(--t-micro);
  line-height: 1.25;
  text-align: center;
  white-space: normal;
  overflow-wrap: anywhere;
  text-decoration: none;
}
.adm-squad-actions .adm-squad-act-ico { flex: none; width: 13px; height: 13px; }
.adm-squad-actions .adm-squad-open.is-full,
.adm-squad-actions .adm-squad-restore { grid-column: 1 / -1; }
/* the purge is a quiet crimson key: it never competes with Verify as a second loud action */
.adm-squad-actions .adm-squad-purge {
  grid-column: 1 / -1;
  color: #FECDD3;
  background: var(--clay-face);
  box-shadow:
    0 var(--lip) 0 #0A0E15,
    var(--clay-drop), var(--clay-spec), var(--clay-bevel),
    inset 0 0 0 1px rgba(244, 63, 94, .38);
}
.adm-squad-actions .adm-btn[disabled] { opacity: .45; cursor: not-allowed; }
@media (max-width: 359px) {
  .adm-squad-cells { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 344px) {
  .adm-squad { padding: 10px 10px 14px; }
  .adm-squad-actions .adm-btn { font-size: 9px; padding: 6px 6px; }
  .adm-squad-st { font-size: 8.5px; padding: 2px 6px; }
}

/* ==========================================================================
   STARS VAULT & PAYOUTS — the invite programme's manual settlement queue.
   The Squads row card is the template: clay slab, recessed cells, one gold key
   for the action that records a payment. A waiting request wears honey, a paid
   one mint, a rejected one crimson — the same three tones the registry uses.
   ========================================================================== */
.adm-grid-vault { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.adm-grid-vault .adm-card { min-height: 116px; }
.adm-grid-vault .adm-card-l { font-size: 9.5px; letter-spacing: .045em; }
.adm-grid-vault .adm-card-s {
  font-size: 9.5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.adm-vault-list, .adm-vault-flags {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}
.adm-vault-list:empty, .adm-vault-flags:empty { display: none; }
.adm-vault-req, .adm-vault-flag {
  display: flex;
  flex-direction: column;
  gap: 9px;
  min-width: 0;
  padding: 11px 11px 12px;
  border-radius: var(--radius-md);
  background: var(--clay-face);
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring);
}
.adm-vault-req[data-status="waiting"] {
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), inset 0 0 0 1px rgba(252, 211, 77, .28);
}
.adm-vault-req[data-status="rejected"], .adm-vault-flag {
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), inset 0 0 0 1px rgba(244, 63, 94, .34);
}
.adm-vault-h { display: flex; align-items: center; gap: 8px; min-width: 0; }
.adm-vault-who { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.adm-vault-name {
  font-size: var(--t-2);
  font-weight: 800;
  color: var(--ink);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.adm-vault-id {
  font-size: 9.5px;
  font-weight: 700;
  color: var(--text-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.adm-vault-st {
  flex: none;
  padding: 3px 8px;
  border-radius: var(--radius-pill);
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: .045em;
  text-transform: uppercase;
  white-space: nowrap;
  background: var(--field);
  color: var(--ink-soft);
  box-shadow: inset 0 0 0 1px var(--hair-off);
}
.adm-vault-st[data-status="waiting"] {
  background: var(--honey-soft);
  color: var(--honey-ink);
  box-shadow: inset 0 0 0 1px rgba(245, 158, 11, .4);
}
.adm-vault-st[data-status="paid"] {
  background: var(--mint-soft);
  color: var(--mint-ink);
  box-shadow: inset 0 0 0 1px rgba(16, 185, 129, .4);
}
.adm-vault-st[data-status="rejected"], .adm-vault-st[data-status="revoked"] {
  background: linear-gradient(180deg, var(--bad-1) 0%, var(--bad-2) 100%);
  color: #fff;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .18);
}
.adm-vault-cells { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; }
.adm-vault-cell {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  padding: 7px 9px;
  border-radius: 10px;
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-vault-cell b {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--t-2);
  font-weight: 800;
  color: var(--honey-ink);
  font-variant-numeric: tabular-nums;
}
.adm-vault-cell span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.adm-vault-actions { display: flex; flex-wrap: wrap; gap: 6px; }
.adm-vault-actions .adm-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 1 1 auto;
  min-height: 48px;
  padding: 0 12px;
  font-size: var(--t-micro);
}
.adm-vault-actions .adm-btn[disabled] { opacity: .45; cursor: not-allowed; }
.adm-vault-review { gap: 8px; padding: 11px 10px 9px; }
@media (max-width: 359px) {
  .adm-vault-cells { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* ==========================================================================
   ACCESS CONTROL — the role registry and the drawer that rides over the stage
   with a confirm dialog above it.
   Same one palette: opaque clay slabs, no backdrop-filter, 44px+ targets.
   ========================================================================== */
.adm-acl-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

/* ---- one admin: avatar initial, name + tg id, a role chip, the revoke key ---- */
.adm-admin {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 56px;
  padding: 8px 10px;
  border-radius: var(--radius-md);
  background: var(--clay-face);
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring);
}
.adm-admin-av {
  flex: none;
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: linear-gradient(180deg, #26314A 0%, #1B2333 100%);
  color: var(--ink);
  font-size: var(--t-2);
  font-weight: 900;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .14), inset 0 -2px 4px rgba(0, 0, 0, .38), var(--clay-ring);
}
.adm-admin.is-root .adm-admin-av {
  background: var(--gold-face);
  color: #10141D;
  box-shadow: 0 2px 0 var(--gold-lip), inset 0 1px 0 rgba(255, 255, 255, .5);
}
.adm-admin-txt {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.adm-admin-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--t-2);
  font-weight: 800;
  color: var(--ink);
}
.adm-admin-sub {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 10px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--ink-soft);
}
.adm-admin-role {
  flex: none;
  padding: 3px 8px;
  border-radius: var(--radius-pill);
  background: var(--field);
  color: var(--brand-ink);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
  box-shadow: inset 0 0 0 1px var(--hair-off);
}
.adm-admin-role[data-role="superadmin"] {
  background: var(--honey-soft);
  color: var(--honey-ink);
  box-shadow: inset 0 0 0 1px rgba(245, 158, 11, .4);
}
.adm-admin-role[data-role="root"] {
  background: var(--gold-face);
  color: #10141D;
  box-shadow: 0 2px 0 var(--gold-lip), inset 0 1px 0 rgba(255, 255, 255, .5);
}
.adm-admin-x {
  flex: none;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  padding: 0;
  appearance: none;
  border: 0;
  cursor: pointer;
  border-radius: var(--radius-sm);
  background: var(--field);
  color: var(--red-ink);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
  transition: transform var(--motion-fast), filter var(--motion-fast);
}
.adm-admin-x .ico { width: 16px; height: 16px; }
.adm-admin-x:active { transform: translateY(var(--press-y)); }
.adm-admin-x:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.adm-admin-x[disabled] { opacity: .35; cursor: default; filter: saturate(.4); }
.adm-admin-x[disabled]:active { transform: none; }

/* ---- the shared segmented key row: recessed track, raised gold key ---- */
.adm-seg {
  display: flex;
  gap: 4px;
  padding: 4px;
  border-radius: var(--radius-md);
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-seg-b {
  flex: 1 1 0;
  min-width: 0;
  min-height: 44px;
  padding: 0 6px;
  appearance: none;
  border: 0;
  font: inherit;
  cursor: pointer;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-soft);
  font-size: var(--t-micro);
  font-weight: 800;
  letter-spacing: .01em;
  transition: transform var(--motion-fast), box-shadow var(--motion-fast),
              background var(--motion-fast), color var(--motion-fast);
}
.adm-seg-b:active { transform: translateY(var(--press-y)); }
.adm-seg-b:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.adm-seg-b[aria-pressed="true"] {
  background: var(--clay-face);
  color: var(--ink);
  box-shadow:
    0 2px 0 #0A0E15,
    var(--clay-spec), var(--clay-bevel),
    inset 0 0 0 1px rgba(252, 211, 77, .34);
}

/* ---- the drawers: one full-stage slab that springs in over the body ---- */
.adm-drawer {
  position: absolute;
  inset: 0;
  z-index: 3;
  display: flex;
  flex-direction: column;
  gap: var(--s2);
  padding:
    max(var(--s3), env(safe-area-inset-top))
    max(var(--pad-app-x), env(safe-area-inset-right))
    max(var(--s3), env(safe-area-inset-bottom))
    max(var(--pad-app-x), env(safe-area-inset-left));
  background:
    radial-gradient(120% 70% at 50% 0%, rgba(252, 211, 77, .1), rgba(252, 211, 77, 0) 60%),
    linear-gradient(180deg, var(--bg-m) 0%, var(--bg) 56%, var(--bg-b) 100%);
  opacity: 0;
  transform: translate3d(0, 4%, 0);
  transition: opacity var(--motion-med), transform .3s var(--bounce);
  pointer-events: none;
}
.adm-drawer[hidden] { display: none; }
.adm-drawer.open { opacity: 1; transform: none; pointer-events: auto; }
html.reduced-motion .adm-drawer { transition: none; }
.adm-drawer-head { flex: none; display: flex; align-items: center; gap: var(--s2); }
.adm-drawer-t {
  flex: 1 1 auto;
  margin: 0;
  font-size: var(--t-hd);
  font-weight: var(--w-2);
  color: var(--ink);
  text-shadow: 0 1px 0 rgba(0, 0, 0, .45), 0 -1px 0 rgba(255, 255, 255, .12);
}
.adm-drawer-x {
  --d: 3px;
  flex: none;
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  padding: 0;
  appearance: none;
  border: 0;
  cursor: pointer;
  border-radius: 12px;
  background:
    radial-gradient(130% 110% at 50% -26%, rgba(255, 255, 255, .1), transparent 58%),
    linear-gradient(180deg, #1B2333 0%, #10151F 100%);
  color: var(--ink-soft);
  box-shadow:
    0 var(--d) 0 #0A0E15,
    0 10px 20px -6px rgba(0, 0, 0, .55),
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 -2px 5px rgba(0, 0, 0, .5),
    inset 0 0 0 1px rgba(255, 255, 255, .05);
}
.adm-drawer-x .ico { width: 15px; height: 15px; }
.adm-drawer-x:active { transform: translateY(var(--press-y)); --d: 1px; }
.adm-drawer-x:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.adm-drawer-body {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  display: flex;
  flex-direction: column;
  gap: var(--s3);
  padding-bottom: 72px;
}
.adm-drawer-foot { flex: none; display: flex; gap: var(--s2); }
.adm-drawer-foot .adm-btn { flex: 1 1 0; }

/* ---- the stacked field: label over a recessed well, and the hint under it ---- */
.adm-fld { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.adm-fld-row { display: flex; gap: var(--s2); }
.adm-fld-row .adm-fld { flex: 1 1 0; }
.adm-fld-l {
  margin: 0;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.adm-fld .adm-input {
  min-height: 48px;
  padding: 0 11px;
  border-radius: var(--radius-sm);
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.adm-fld .adm-input:focus-visible {
  outline: 2px solid var(--brand-2);
  outline-offset: 1px;
}
.adm-area {
  min-height: 108px;
  padding: 10px 11px;
  resize: vertical;
  line-height: 1.5;
}
.adm-hint { margin: 0; font-size: var(--t-micro); line-height: 1.4; color: var(--ink-soft); }
.adm-hint[data-state="ok"] { color: var(--mint-ink); }
.adm-hint[data-state="bad"] { color: var(--red-ink); }

/* ---- the confirm dialog: one question above the drawer that asked it ---- */
.adm-confirm {
  position: absolute;
  inset: 0;
  z-index: 4;
  display: grid;
  place-items: center;
  padding: 0 18px;
  background: rgba(6, 9, 14, .66);
  opacity: 0;
  transition: opacity var(--motion-fast);
  pointer-events: none;
}
.adm-confirm[hidden] { display: none; }
.adm-confirm.open { opacity: 1; pointer-events: auto; }
.adm-confirm-panel {
  width: min(100%, 340px);
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 16px;
  border-radius: var(--radius-lg);
  background: linear-gradient(180deg, var(--solid-a) 0%, var(--solid-b) 100%);
  box-shadow:
    0 18px 44px -18px rgba(0, 0, 0, .9),
    inset 0 1px 0 var(--hair-lit),
    inset 0 0 0 1px rgba(245, 158, 11, .35);
  transform: scale(.92) translateY(6px);
  transition: transform .24s var(--bounce);
}
.adm-confirm.open .adm-confirm-panel { transform: none; }
html.reduced-motion .adm-confirm, html.reduced-motion .adm-confirm-panel { transition: none; }
.adm-confirm-t { margin: 0; font-size: var(--t-1); font-weight: 900; color: var(--ink); }
.adm-confirm-b { margin: 0; font-size: var(--t-micro); line-height: 1.5; color: var(--ink-soft); overflow-wrap: anywhere; }
.adm-confirm-actions { display: flex; gap: var(--s2); margin-top: var(--s2); }
.adm-confirm-actions .adm-btn { flex: 1 1 0; }

/* a 340 phone: the two-up CTA fields fold, never clip */
@media (max-width: 359px) {
  .adm-fld-row { flex-direction: column; }
}

/* ==========================================================================
   VIP STOREFRONT & REVENUE — the admin plan sheet over the record's own ledger.
   Three revenue chips, three tier slabs with a whole-Stars price and an ON/OFF
   storefront key, then the newest receipts. Opaque clay, fixed table columns,
   every control >= 44px and nothing that can run past the phone column.
   ========================================================================== */
.vipadm { --adm-accent: var(--violet); --adm-accent-soft: rgba(167, 139, 250, .24); gap: 7px; }
.vipadm .adm-block-s[data-tone="ok"] { color: var(--mint-ink); }
.vipadm .adm-block-s[data-tone="bad"] { color: var(--red-ink); }
.vipadm-kpis .adm-card { min-height: 118px; }
.vipadm-kpis .adm-card-i { color: var(--honey-ink); }
.vipadm-kpis .adm-card-v {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.vipadm-plans { display: flex; flex-direction: column; gap: 7px; }
.vipadm-plan {
  display: flex;
  flex-direction: column;
  gap: 9px;
  min-width: 0;
  padding: 11px 12px 10px;
  border-radius: var(--radius-md);
  background: var(--clay-face);
  box-shadow: var(--clay-drop), var(--clay-spec), var(--clay-bevel), var(--clay-ring);
  transition: opacity var(--motion-fast);
}
.vipadm-plan[data-on="false"] { opacity: .78; }
.vipadm-plan-head { display: flex; align-items: center; gap: 9px; min-width: 0; }
.vipadm-plan-ico {
  flex: none;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 10px;
  background: var(--field);
  color: var(--honey-ink);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.vipadm-plan-ico .ico { width: 16px; height: 16px; }
.vipadm-plan-copy { display: flex; flex-direction: column; gap: 1px; flex: 1 1 auto; min-width: 0; }
.vipadm-plan-t {
  font-size: var(--t-2);
  font-weight: 900;
  line-height: 1.15;
  color: var(--ink);
}
.vipadm-plan-s {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

/* the storefront key: an explicit ON / OFF word beside the sliding knob */
.vipadm-toggle {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 48px;
  padding: 0 5px 0 9px;
  appearance: none;
  border: 0;
  font: inherit;
  cursor: pointer;
  border-radius: var(--radius-pill);
  background: var(--field);
  color: var(--ink-soft);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
  transition: color var(--motion-fast), box-shadow var(--motion-fast), transform var(--motion-fast);
}
.vipadm-toggle:active { transform: translateY(var(--press-y)); }
.vipadm-toggle:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.vipadm-toggle-l {
  width: 24px;
  text-align: center;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .06em;
}
.vipadm-toggle-knob {
  flex: none;
  display: flex;
  align-items: center;
  width: 42px;
  height: 26px;
  padding: 3px;
  border-radius: var(--radius-pill);
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
  transition: background var(--motion-fast), box-shadow var(--motion-fast);
}
.vipadm-toggle-knob i {
  display: block;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: linear-gradient(180deg, #64748B 0%, #475569 100%);
  box-shadow: 0 2px 0 rgba(0, 0, 0, .45), inset 0 1px 0 rgba(255, 255, 255, .25);
  transition: transform var(--motion-fast), background var(--motion-fast);
}
.vipadm-toggle[aria-checked="true"] { color: var(--mint-ink); }
.vipadm-toggle[aria-checked="true"] .vipadm-toggle-knob {
  background: var(--mint-soft);
  box-shadow: var(--inset), inset 0 0 0 1px rgba(16, 185, 129, .4);
}
.vipadm-toggle[aria-checked="true"] .vipadm-toggle-knob i {
  transform: translateX(16px);
  background: var(--gold-face);
  box-shadow: 0 2px 0 var(--gold-lip), inset 0 1px 0 rgba(255, 255, 255, .5);
}
@media (prefers-reduced-motion: reduce) { .vipadm-toggle-knob i { transition: none; } }

/* price + one save key: the input holds whole XTR, the key commits this tier */
.vipadm-plan-row { display: flex; align-items: flex-end; gap: 7px; min-width: 0; }
.vipadm-price { display: flex; flex-direction: column; gap: 4px; flex: 1 1 auto; min-width: 0; }
.vipadm-price-k {
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.vipadm-price-field {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  min-height: 48px;
  padding: 0 10px;
  border-radius: var(--radius-sm);
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
}
.vipadm-star { flex: none; width: 15px; height: 15px; }
.vipadm-price-i {
  flex: 1 1 auto;
  width: 100%;
  min-width: 0;
  appearance: none;
  border: 0;
  background: none;
  outline: none;
  font: inherit;
  font-size: var(--t-2);
  font-weight: 800;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
  -webkit-user-select: text;
  user-select: text;
}
.vipadm-price-i::-webkit-outer-spin-button,
.vipadm-price-i::-webkit-inner-spin-button { appearance: none; margin: 0; }
.vipadm-price-i { -moz-appearance: textfield; }
.vipadm-price-u {
  flex: none;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .06em;
  color: var(--honey-ink);
}
.vipadm-save { flex: none; min-height: 48px; padding: 0 14px; }
.vipadm-save.is-busy { cursor: progress; filter: saturate(.7) brightness(.9); }
.vipadm-plan-stat {
  margin: 0;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .03em;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}
.vipadm-plan-stat b { color: var(--honey-ink); }

/* the receipts audit: fixed columns and ellipsis, so a long Telegram name never widens it */
.vipadm-audit { gap: 8px; padding: 11px 10px 9px; }
.vipadm-audit-h { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; min-width: 0; }
.vipadm-audit-t {
  min-width: 0;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--ink);
}
.vipadm-audit-s {
  flex: none;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}
.vipadm-table { width: 100%; table-layout: fixed; border-collapse: collapse; }
.vipadm-table th {
  padding: 0 4px 6px;
  text-align: left;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.vipadm-table th:nth-child(1) { width: 32%; }
.vipadm-table th:nth-child(2) { width: 17%; }
.vipadm-table th:nth-child(3) { width: 14%; }
.vipadm-table th:nth-child(4) { width: 17%; }
.vipadm-table th:nth-child(5) { width: 20%; }
.vipadm-table td {
  padding: 7px 4px;
  border-top: 1px solid var(--hair-off);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 9.5px;
  font-weight: 700;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.vipadm-user { display: flex; align-items: center; gap: 6px; min-width: 0; }
.vipadm-mono {
  flex: none;
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair-off);
  font-size: 10px;
  font-weight: 900;
  color: var(--honey-ink);
}
.vipadm-user-t { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 800; }
.vipadm-num { text-align: right; color: var(--honey-ink); font-weight: 900; }
.vipadm-date { color: var(--ink-soft); }
.vipadm-status {
  display: inline-block;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 2px 6px;
  border-radius: var(--radius-pill);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.vipadm-status[data-state="on"] {
  color: var(--mint-ink);
  background: var(--mint-soft);
  box-shadow: inset 0 0 0 1px rgba(16, 185, 129, .32);
}
.vipadm-status[data-state="off"] {
  color: var(--ink-soft);
  background: var(--field);
  box-shadow: inset 0 0 0 1px var(--hair-off);
}
.vipadm-empty { margin: 4px 0 0; font-size: var(--t-micro); line-height: 1.4; color: var(--ink-soft); }
.vipadm-empty[hidden] { display: none; }

/* a 320 phone: tighter cells keep all five columns, date included, inside the slab */
@media (max-width: 359px) {
  .vipadm-plan { padding: 10px; }
  .vipadm-table th, .vipadm-table td { padding-left: 3px; padding-right: 3px; }
  .vipadm-table th:nth-child(1) { width: 30%; }
  .vipadm-table th:nth-child(2) { width: 16%; }
  .vipadm-table th:nth-child(3) { width: 13%; }
  .vipadm-table th:nth-child(4) { width: 18%; }
  .vipadm-table th:nth-child(5) { width: 23%; }
  .vipadm-status { padding: 2px 4px; font-size: 7px; }
}

/* ==========================================================================
   HOME CAROUSEL — the two authentic slides
   Nations Cup (slide 0) is a national-standings showcase; The Mind Ladder
   (slide 1) is the individual TIQ prestige card. Both are opaque Dark Clay
   tiles: extruded bevels, deep inner shadows, zero backdrop-filter and zero
   blur. Leaderboard rows run at 30px (Top 5) and every CTA is a 48px pill.
   ========================================================================== */

/* ---- pager dots: keep the 6px visual, widen the pointer target ----
   The row stays the 20px indicator strip; the ::after band gives each dot a
   48x28 hit area (the same trick .btn.sm uses). The band is anchored to the
   row top and reaches the card's bottom edge, so it fills the card's whole
   28px dot reserve without ever overlapping the CTA above it. */
.dot::after { content: ""; position: absolute; inset: 0 -10px -8px; }

/* ---- one 48px clay CTA pill per slide ---- */
.card-cta {
  --d: 3px;
  position: relative;
  flex: none;
  width: 100%;
  min-height: 48px;
  padding: 0 var(--s4);
  font-size: var(--t-2);
  letter-spacing: .01em;
  border-radius: var(--radius-pill);
  background: linear-gradient(180deg, #26314A 0%, #1B2333 100%);
  color: var(--ink);
  box-shadow:
    0 var(--d) 0 #080C14,
    0 calc(var(--d) + 6px) 14px -8px rgba(0, 0, 0, .5),
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 -2px 4px rgba(0, 0, 0, .38),
    var(--clay-ring);
}
.card-cta::after { content: ""; position: absolute; inset: -4px 0; }
.card-cta:hover:not(:active) { transform: translateY(-1px); }
.card-cta:active { transform: translateY(2px); --d: 1px; }
.card-cta:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.car-card .card-cta { width: 100%; }
/* the one CTA per leaderboard slide: the foot block owns the 8px air, so the
   button itself carries no extra margin */
.car-card .slide-cta { margin-top: 0; }

/* ---- the personal standing bar: one structured 3-zone esports HUD row ----
   Shared by both leaderboard slides (Nations Cup + The Mind Ladder) and rendered by
   home.ts into three fixed zones:

     · LEFT   — the compact glowing rank badge (global slide) or the flag plate plus
                the nation name (national slide);
     · CENTER — the translucent standing pill: the field the rank sits inside on the
                global slide ("of 1,204 minds"), the percentile share on the national one;
     · RIGHT  — the tabular score readout, ending in the same brain token the rows
                above wear, so the numbers stack into one column.

   It is a plain flow item inside `.slide-foot`: no absolute positioning, no negative
   margins, no fixed height. The only rule that keeps it off row #5 lives on the list
   above it (the rows share their band exactly — see the leaderboard block below). */
.hud-mine {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  box-sizing: border-box;
  min-width: 0;
  min-height: 32px;
  padding: 8px 12px;
  border-radius: 14px;
  background: linear-gradient(90deg, rgba(0, 210, 255, .14) 0%, rgba(14, 24, 42, .85) 50%, rgba(245, 158, 11, .14) 100%);
  border: 1px solid rgba(0, 210, 255, .3);
  box-shadow: 0 4px 14px rgba(0, 0, 0, .35);
  font-variant-numeric: tabular-nums;
}
/* LEFT zone: never shrinks below the badge, the label ellipsizes instead of pushing
   the pill or the score out of the bar */
.hm-l {
  display: flex;
  align-items: center;
  gap: 7px;
  flex: 0 1 auto;
  min-width: 0;
}
.hm-badge {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 26px;
  height: 22px;
  padding: 0 6px;
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(56, 189, 248, .62) 0%, rgba(14, 116, 233, .4) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .45),
    inset 0 0 0 1px rgba(125, 232, 255, .55),
    0 0 10px rgba(0, 210, 255, .38);
  color: #EAF6FF;
  font-size: 11.5px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -.02em;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 8px rgba(186, 240, 255, .6);
}
/* no standing yet: the badge keeps its footprint, the glow goes out */
.hm-badge.is-off {
  background: rgba(255, 255, 255, .05);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .12);
  color: rgba(233, 240, 252, .55);
  text-shadow: none;
}
/* the flag plate: the same 22px photo chip the rows use, one size down */
.hm-flag {
  flex: none;
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  overflow: hidden;
}
.hm-flag .fp { --fp-d: 22px; }
.hm-flag .fp-chip { border-radius: 50%; font-size: 7px; letter-spacing: 0; }
.hm-flag.is-off { background: rgba(255, 255, 255, .06); box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .12); }
.hm-name {
  min-width: 0;
  flex: 0 1 auto;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: #E8F1FF;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* CENTER zone: the standing tag — a quiet glass pill, never the loudest thing */
.hm-c {
  flex: none;
  display: flex;
  align-items: center;
  min-width: 0;
}
.hm-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, .07);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .14);
  color: #AFC0D8;
  font-size: 9px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: .1em;
  text-transform: uppercase;
  white-space: nowrap;
}
.hm-pill b {
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0;
  color: #F4F8FF;
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1, "lnum" 1;
}
.hm-pill.is-off b { display: none; }
/* RIGHT zone: the tabular score, hugging the right edge so it lands under the
   score column of rows #1–#5 */
.hm-r {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 3px;
  direction: ltr;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1, "lnum" 1;
}
.hm-v {
  font-size: 14px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -.01em;
  color: var(--honey-ink);
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1, "lnum" 1;
  text-shadow:
    0 1px 0 rgba(0, 0, 0, .5),
    0 0 10px rgba(252, 211, 77, .16);
}
.hm-u {
  font-size: 8.5px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: .1em;
  color: var(--violet);
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1, "lnum" 1;
  text-shadow: 0 0 8px rgba(167, 139, 250, .35);
}
/* each slide keeps its own accent on the unit: violet minds, cyan nations */
.nations-mine .hm-u { color: #22D3EE; text-shadow: 0 0 8px rgba(34, 211, 238, .45); }

/* the narrowest phone (320px): the bar gives back padding, the name keeps the slack */
@media (max-width: 344px) {
  .hud-mine { gap: 6px; padding: 7px 10px; }
  .hm-l { gap: 6px; }
  .hm-name { font-size: 11px; letter-spacing: .03em; }
  .hm-pill { padding: 2px 6px; font-size: 8.5px; gap: 3px; }
  .hm-pill b { font-size: 9.5px; }
  .hm-v { font-size: 13px; }
  /* "AVG TIQ" is four characters longer than the old "PTS": on the narrowest bar the
     unit gives back tracking and a half-pixel so the nation name keeps its slack. */
  .nations-mine .hm-u { font-size: 7.5px; letter-spacing: .04em; }
  .hm-badge { min-width: 24px; height: 20px; padding: 0 5px; font-size: 11px; }
  .hm-flag, .hm-flag .fp { --fp-d: 20px; width: 20px; height: 20px; }
  /* the trend delta is the one column a 320px row can live without: the nation name
     keeps its full width instead of collapsing to three letters. The four tracks here
     match the four children that remain — the compact-height grid only re-adds the
     trend track from 345px up, where `.tr` is still rendered. */
  .car-card.nations-cup .mini-rank.nations-rank > li:not(.is-error) { grid-template-columns: 19px 26px minmax(0, 1fr) 92px; }
  .car-card.nations-cup .mini-rank.nations-rank .tr { display: none; }
  .car-card.nations-cup .mini-rank.nations-rank .rk { width: 19px; height: 19px; font-size: 11px; }
  .car-card.nations-cup .mini-rank.nations-rank .fl { flex-basis: 26px; width: 26px; height: 26px; }
}

/* ---- The Mind Ladder: TIQ hero card ----
   Same frame as Nations Cup: the card hosts one inner column (`.slide-inner`)
   that owns the padding and splits the height between the podium band and the
   pinned foot. */
.car-card.mind-ladder {
  position: relative;
  isolation: isolate;
  justify-content: stretch;
  gap: 0;
  padding: 0 0 16px;
  overflow: hidden;
  border-radius: var(--r-panel);
  border-top: 1px solid rgba(255, 255, 255, .12);
  background:
    radial-gradient(120% 90% at 12% 0%, rgba(139, 92, 246, .18), rgba(139, 92, 246, 0) 55%),
    radial-gradient(110% 85% at 90% 0%, rgba(245, 158, 11, .12), rgba(245, 158, 11, 0) 60%),
    linear-gradient(180deg, #202A3E 0%, #1C2433 100%);
  box-shadow:
    0 8px 20px rgba(0, 0, 0, .18),
    inset 0 2px 2px rgba(255, 255, 255, .08),
    inset 0 -3px 3px rgba(0, 0, 0, .35),
    inset 0 0 0 1px rgba(255, 255, 255, .06);
}
.mind-head { display: flex; align-items: center; justify-content: space-between; gap: var(--s2); min-width: 0; min-height: 20px; }
.car-card.mind-ladder .car-kicker::before { content: none; display: none; }
.mind-kicker {
  color: #F3F7FF;
  gap: var(--s2);
  min-width: 0;
  font-size: 12.5px;
  font-weight: 900;
  letter-spacing: .15em;
  text-transform: uppercase;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .4);
}
.mind-ico {
  flex: none;
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  background: linear-gradient(180deg, #a78bfa 0%, #7c3aed 100%);
  color: #fff;
  box-shadow:
    0 2px 0 #4c1d95,
    inset 0 1px 0 rgba(255, 255, 255, .5),
    inset 0 -2px 3px rgba(0, 0, 0, .22);
}
.mind-ico .ico { width: 14px; height: 14px; }
/* the seasonal crest: an obsidian capsule with a gold hairline and a live pulse — the
   season the ladder is running, never a raw head-count pill */
.mind-top {
  position: relative;
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 9px 4px 7px;
  border-radius: var(--radius-pill);
  background: linear-gradient(180deg, rgba(255, 255, 255, .085) 0%, rgba(255, 255, 255, .028) 100%);
  border: 1px solid rgba(255, 215, 0, .22);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .13),
    0 2px 8px -4px rgba(0, 0, 0, .85);
  color: #F2D79A;
  font-size: 9.5px;
  font-weight: 900;
  letter-spacing: .15em;
  line-height: 1;
  text-transform: uppercase;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.mind-season { display: block; }
/* the live pulse: a 5px amber bead with a slow radar ping; it goes out when the
   Worker has not answered yet, so the crest never lies about being live */
.mind-pulse {
  position: relative;
  flex: none;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #FBBF24;
  box-shadow: 0 0 7px rgba(251, 191, 36, .85);
}
.mind-pulse::after {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  border: 1px solid rgba(251, 191, 36, .55);
  animation: mindPing 2.6s cubic-bezier(.2, .7, .3, 1) infinite;
}
@keyframes mindPing {
  0% { transform: scale(.55); opacity: .95; }
  70%, 100% { transform: scale(2); opacity: 0; }
}
.mind-top:not(.is-live) .mind-pulse { background: #64748B; box-shadow: none; }
.mind-top:not(.is-live) .mind-pulse::after { content: none; }
html.reduced-motion .mind-pulse::after { animation: none; opacity: .3; }
/* podium: five slabs that grow into the band — shield, ringed portrait + flag, handle, TIQ */
.mind-podium {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 7px;
  min-height: 0;
}
/* one row = one unified glass slab: [ minted shield ][ ringed portrait ][ handle ][ TIQ ].
   The trend is a bare tick on the handle, so the score column is the row's only right
   edge and the name owns every pixel the old capsule used to eat. */
.mind-row {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  flex: 1 1 auto;
  height: auto;
  min-height: 40px;
  max-height: 64px;
  padding: 4px 10px;
  border-radius: 12px;
  background: linear-gradient(180deg, rgba(255, 255, 255, .055) 0%, rgba(255, 255, 255, .022) 100%);
  border: 1px solid rgba(255, 255, 255, .07);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .07),
    0 1px 2px rgba(0, 0, 0, .28);
  overflow: hidden;
  box-sizing: border-box;
}
/* the podium's ambient wash sits INSIDE the slab (the row clips it) so #1 reads as lit
   from behind, not as a brighter border */
.mind-row::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  background: radial-gradient(120% 130% at 0% 50%, rgba(255, 196, 60, .16) 0%, rgba(255, 196, 60, 0) 62%);
  opacity: 0;
  pointer-events: none;
}
.mind-row[data-rank="1"]::before { opacity: 1; }
.mind-row[data-rank="2"]::before {
  opacity: 1;
  background: radial-gradient(120% 130% at 0% 50%, rgba(203, 213, 225, .13) 0%, rgba(203, 213, 225, 0) 62%);
}
.mind-row[data-rank="3"]::before {
  opacity: 1;
  background: radial-gradient(120% 130% at 0% 50%, rgba(251, 146, 60, .14) 0%, rgba(251, 146, 60, 0) 62%);
}
/* every direct child rides above that wash */
.mind-row > * { position: relative; z-index: 1; }
/* #1 wears the gold hairline and the ambient back-glow; #2 platinum, #3 bronze */
.mind-row[data-rank="1"] {
  border-color: rgba(255, 215, 0, .25);
  box-shadow:
    inset 0 1px 0 rgba(255, 236, 180, .14),
    0 0 18px -6px rgba(255, 200, 60, .45),
    0 2px 4px rgba(0, 0, 0, .3);
}
.mind-row[data-rank="2"] {
  border-color: rgba(203, 213, 225, .2);
  box-shadow:
    inset 0 1px 0 rgba(226, 232, 240, .12),
    0 0 14px -8px rgba(203, 213, 225, .3);
}
.mind-row[data-rank="3"] {
  border-color: rgba(251, 146, 60, .22);
  box-shadow:
    inset 0 1px 0 rgba(254, 215, 170, .12),
    0 0 14px -8px rgba(251, 146, 60, .32);
}
/* rank emblem: a minted shield — flat shoulders, a rounded point, a specular top edge */
.mind-rank {
  position: relative;
  flex: none;
  width: 27px;
  height: 28px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  border-radius: 8px 8px 13px 13px / 7px 7px 16px 16px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .16) 0%, rgba(255, 255, 255, 0) 46%),
    linear-gradient(180deg, #2C374D 0%, #1A2130 100%);
  color: #B6C3D8;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, .1),
    inset 0 1px 0 rgba(255, 255, 255, .16),
    0 2px 0 rgba(6, 9, 15, .6),
    0 3px 8px -3px rgba(0, 0, 0, .7);
  font-size: 12.5px;
  font-weight: 900;
  letter-spacing: -.02em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.mind-rank-n {
  display: block;
  line-height: 1;
  direction: ltr;
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1, "lnum" 1;
}
.mind-crown {
  display: block;
  width: 12px;
  height: 8px;
  color: #6B3D06;
  filter: drop-shadow(0 1px 0 rgba(255, 244, 210, .5));
}
.mind-rank.gold {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .62) 0%, rgba(255, 255, 255, 0) 44%),
    linear-gradient(180deg, #FFE9A3 0%, #F6C846 38%, #DA9C1A 74%, #B9760C 100%);
  color: #2A1B03;
  box-shadow:
    inset 0 0 0 1px rgba(255, 248, 214, .6),
    inset 0 -2px 3px rgba(120, 53, 15, .32),
    0 2px 0 #6B3D06,
    0 4px 12px -3px rgba(245, 196, 69, .5);
}
.mind-rank.silver {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .7) 0%, rgba(255, 255, 255, 0) 46%),
    linear-gradient(180deg, #F4F8FD 0%, #D3DCE8 40%, #A7B4C6 74%, #7E8DA2 100%);
  color: #1B2433;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, .62),
    inset 0 -2px 3px rgba(51, 65, 85, .3),
    0 2px 0 #3A4658,
    0 4px 12px -3px rgba(203, 213, 225, .38);
}
.mind-rank.bronze {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .58) 0%, rgba(255, 255, 255, 0) 46%),
    linear-gradient(180deg, #FFD9B0 0%, #E8A468 40%, #C4783C 76%, #96501F 100%);
  color: #2E1503;
  box-shadow:
    inset 0 0 0 1px rgba(255, 226, 196, .5),
    inset 0 -2px 3px rgba(124, 45, 18, .3),
    0 2px 0 #4A2410,
    0 4px 12px -3px rgba(224, 155, 98, .42);
}
/* the portrait: a real face inside a machined metal ring, per-medal on the podium */
.mind-av {
  position: relative;
  flex: none;
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #fff;
  background: conic-gradient(from 210deg,
    #8A97AD 0deg, #E7EEF9 58deg, #93A1B7 126deg,
    #6E7C93 196deg, #DCE6F4 268deg, #8A97AD 360deg);
  box-shadow:
    0 2px 6px rgba(0, 0, 0, .5),
    0 0 0 1px rgba(255, 255, 255, .06);
}
/* the clay disc inside the ring: the letter that holds the place while a photo loads */
.mind-av::before {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: 50%;
  background: radial-gradient(circle at 32% 26%, #2E3A54 0%, #141B2A 72%);
}
.mind-row[data-rank="1"] .mind-av {
  background: conic-gradient(from 210deg,
    #B8860B 0deg, #FFE9A3 56deg, #C9971C 124deg,
    #8A5E08 194deg, #FFDF8A 266deg, #B8860B 360deg);
  box-shadow:
    0 2px 7px rgba(0, 0, 0, .5),
    0 0 10px rgba(245, 196, 69, .4);
}
.mind-row[data-rank="2"] .mind-av {
  background: conic-gradient(from 210deg,
    #7E8DA2 0deg, #F8FBFF 56deg, #A7B4C6 124deg, #64748B 194deg, #E7EEF9 266deg, #7E8DA2 360deg);
  box-shadow:
    0 2px 7px rgba(0, 0, 0, .5),
    0 0 9px rgba(203, 213, 225, .28);
}
.mind-row[data-rank="3"] .mind-av {
  background: conic-gradient(from 210deg,
    #96501F 0deg, #FFD9B0 56deg, #C4783C 124deg, #7A3E15 194deg, #F0B57E 266deg, #96501F 360deg);
  box-shadow:
    0 2px 7px rgba(0, 0, 0, .5),
    0 0 9px rgba(224, 155, 98, .3);
}
.mind-ini { position: relative; z-index: 1; font-size: 12px; font-weight: 900; letter-spacing: .01em; }
/* the mind's own photo sits inside the sphere; the nation pin stays on top */
.mind-av-img {
  position: absolute;
  inset: 2px;
  z-index: 1;
  width: calc(100% - 4px);
  height: calc(100% - 4px);
  border-radius: 50%;
  object-fit: cover;
  background: #0B1220;
  opacity: 0;
  transition: opacity .18s ease;
}
.mind-av-img.is-loaded { opacity: 1; }
html.reduced-motion .mind-av-img { transition: none; }
.mind-av .mind-flag {
  position: absolute;
  inset-inline-end: 0;
  inset-block-end: 0;
  z-index: 2;
  --fp-d: 13px;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  overflow: hidden;
  box-shadow: 0 0 0 2px #1C2433;
}
/* the identity cell: handle + a bare delta tick. It is the only flexible column, so the
   handle ellipsizes instead of ever pushing the score out of the slab. */
.mind-id {
  display: flex;
  align-items: baseline;
  gap: 5px;
  flex: 1 1 auto;
  min-width: 0;
}
.mind-nm {
  min-width: 0;
  font-size: 13.5px;
  font-weight: 700;
  letter-spacing: .005em;
  color: #EAF1FC;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* the trend: no capsule, no reserved column — a 9px tick that only exists when the rank
   really moved, so a steady row carries nothing between the handle and the score */
.mind-delta {
  flex: none;
  font-size: 9px;
  font-weight: 900;
  font-style: normal;
  line-height: 1;
  letter-spacing: -.02em;
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1, "lnum" 1;
}
.mind-delta.up { color: var(--mint-ink); text-shadow: 0 0 6px rgba(110, 231, 183, .35); }
.mind-delta.down { color: #FDA4AF; text-shadow: 0 0 6px rgba(253, 164, 175, .3); }
/* score lockup: the rating, the explicit unit, then the signature gold brain token */
.mind-score {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 14.5px;
  font-weight: 900;
  letter-spacing: -.01em;
  color: #FFD86B;
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1, "lnum" 1;
  text-shadow:
    0 1px 0 rgba(0, 0, 0, .55),
    0 0 12px rgba(252, 211, 77, .3);
  white-space: nowrap;
}
.mind-tiq-k {
  flex: none;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .09em;
  line-height: 1;
  color: var(--violet);
  text-shadow: 0 0 8px rgba(167, 139, 250, .3);
}
/* the TIQ token: one gold brain, the same object in the rows and in your own strip */
.mind-brain {
  flex: none;
  width: 15px;
  height: 15px;
  display: grid;
  place-items: center;
  border-radius: 5px;
  color: #FFF3CF;
  background: linear-gradient(180deg, rgba(255, 214, 102, .34) 0%, rgba(180, 120, 10, .24) 100%);
  box-shadow:
    inset 0 0 0 1px rgba(255, 214, 102, .38),
    0 0 8px rgba(245, 180, 40, .3);
}
.mind-brain-ico { display: block; width: 10px; height: 10px; }
/* an unoccupied rank: a frosted, dashed slot with a lock — reserved, never broken */
.mind-row.is-empty {
  background: linear-gradient(180deg, rgba(255, 255, 255, .028) 0%, rgba(255, 255, 255, .012) 100%);
  border: 1px dashed rgba(255, 255, 255, .11);
  box-shadow: none;
}
/* a reserved seat is never lit from behind, even when it inherits a podium rank */
.mind-row.is-empty::before { opacity: 0; }
.mind-row.is-empty .mind-rank {
  color: rgba(169, 182, 204, .5);
  background: rgba(255, 255, 255, .03);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .06);
}
.mind-row.is-empty .mind-nm { color: rgba(196, 208, 226, .58); font-weight: 600; }
.mind-row.is-empty .mind-score { color: rgba(252, 211, 77, .34); text-shadow: none; }
.mind-row.is-empty .mind-tiq-k { color: rgba(196, 181, 253, .35); text-shadow: none; }
.mind-row.is-empty .mind-brain {
  color: rgba(255, 243, 207, .4);
  background: rgba(255, 255, 255, .04);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .07);
}
/* an empty seat wears no metal, even when it holds a podium rank on a cold server */
.mind-row.is-empty .mind-crown { display: none; }
.mind-row.is-empty .mind-av {
  background: rgba(255, 255, 255, .035);
  color: rgba(196, 208, 226, .5);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, .1),
    inset 0 -2px 4px rgba(0, 0, 0, .24);
}
.mind-row.is-empty .mind-av::before { content: none; }
.mind-av-ico { position: relative; z-index: 1; display: block; width: 12px; height: 12px; }
.mind-av .mind-flag-none {
  display: grid;
  place-items: center;
  background: linear-gradient(180deg, #39445C 0%, #232C3E 100%);
  color: #A9B6CC;
}
.mind-flag-ico { display: block; width: 9px; height: 9px; }
/* your own standing: the shared 3-zone HUD row, worn as a cyan neon-glass slab — the
   one bar on the card that is lit from inside instead of from above */
.mind-mine {
  position: relative;
  background:
    linear-gradient(90deg, rgba(34, 211, 238, .18) 0%, rgba(11, 20, 33, .94) 46%, rgba(34, 211, 238, .12) 100%);
  border: 1px solid rgba(34, 211, 238, .42);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .16),
    inset 0 0 0 1px rgba(34, 211, 238, .1),
    0 6px 18px -9px rgba(0, 200, 255, .55),
    0 3px 10px rgba(0, 0, 0, .4);
}
/* the sheen: a 1px light line across the top edge, never a wash over the type */
.mind-mine::before {
  content: "";
  position: absolute;
  inset: 0 12px auto;
  height: 1px;
  border-radius: 1px;
  background: linear-gradient(90deg,
    rgba(34, 211, 238, 0) 0%,
    rgba(186, 240, 255, .7) 22%,
    rgba(186, 240, 255, .28) 60%,
    rgba(34, 211, 238, 0) 100%);
  pointer-events: none;
}
.mind-mine .hm-name { letter-spacing: .1em; }
/* the standing pill: "of 1,204 minds" — the field the rank sits inside, never a percentile */
.mind-mine .hm-pill {
  background: rgba(34, 211, 238, .1);
  box-shadow: inset 0 0 0 1px rgba(34, 211, 238, .3);
  color: #9FE4F5;
  letter-spacing: .09em;
}
.mind-mine .hm-pill b {
  color: #EAFDFF;
  text-shadow: 0 0 8px rgba(34, 211, 238, .5);
}
.hm-pill-u {
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .08em;
  color: rgba(159, 228, 245, .7);
}
.mind-mine .hm-badge {
  background: linear-gradient(180deg, rgba(56, 189, 248, .7) 0%, rgba(14, 116, 233, .46) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .5),
    inset 0 0 0 1px rgba(125, 232, 255, .6),
    0 0 12px rgba(0, 210, 255, .45);
}

/* ============================================================================================
   LEADERBOARD SLIDES — Nations Cup + The Mind Ladder.

   Both cards are the same pinned box (the track's content box), so they run one shared
   column instead of two hand-tuned stacks:

     · `.slide-inner` owns the padding and splits the height three ways — the header on
       the top edge, the five standings rows across the upper-to-mid band, and the
       personal standing bar + the one CTA on the bottom edge;
     · the five rows SHARE the band exactly (`flex: 1 1 0`, `min-height: 0`): a row can
       never be taller than its share, so the band can never overflow its own box and
       the foot below it can never be covered. This is the whole overlap fix — the
       personal bar is a flow item, and the list above it is now incapable of spilling;
     · the personal bar is a structured 3-zone HUD row (`.hud-mine`) sitting directly
       under row #5 with a hairline rule above it, then the one CTA, then the dots.
   ============================================================================================ */

/* the card is a frame for that column: it keeps only the bottom reserve the pager
   dots live in (16px here + the column's 8px = 24px of air under the CTA) */
#home-carousel > .car-card.nations-cup,
#home-carousel > .car-card.mind-ladder {
  justify-content: stretch;
  gap: 0;
  padding: 0 0 16px;
}

/* the one inner column: padding owner + height split */
.car-card.nations-cup > .slide-inner,
.car-card.mind-ladder > .slide-inner {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 100%;
  box-sizing: border-box;
  padding: 12px 14px 8px;
  gap: 6px;
}

/* the standings band: five rows that share the space they are given — never more */
.mini-rank.nations-rank,
.mind-podium {
  flex: 1 1 auto;
  min-height: 0;
  justify-content: space-between;
}
.mini-rank.nations-rank { gap: 6px; }
.mind-podium { gap: 6px; }
/* one row = one equal slice of the band. `flex-basis: 0` + `min-height: 0` is what
   stops the 40px floor from overflowing the band and painting over the foot.
   The 13px right inset is the bar's 12px padding plus its 1px border, so the score
   column above and the score inside the standing bar end on the same pixel. */
.car-card.mind-ladder .mind-podium > .mind-row,
.car-card.nations-cup .mini-rank.nations-rank > li:not(.is-error) {
  flex: 1 1 0;
  min-height: 0;
  max-height: 64px;
  padding-right: 13px;
}

/* the foot: hairline rule → personal standing bar → the one CTA, in that order,
   pinned to the bottom edge of the column */
.car-card.nations-cup .slide-foot,
.car-card.mind-ladder .slide-foot {
  flex: none;
  margin-top: auto;
  margin-bottom: 0;
  padding-bottom: 8px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}
/* the divider between the ladder and the player's own standing: a zero-weight
   hairline that fades at both ends, so the footer reads as its own band */
.car-card.nations-cup .slide-foot::before,
.car-card.mind-ladder .slide-foot::before {
  content: "";
  display: block;
  flex: none;
  height: 1px;
  margin: 0 2px;
  border-radius: 1px;
  background: linear-gradient(90deg,
    rgba(255, 255, 255, 0) 0%,
    rgba(255, 255, 255, .13) 14%,
    rgba(255, 255, 255, .13) 86%,
    rgba(255, 255, 255, 0) 100%);
}

/* ---- the leaderboard command: one key, both slides ----
   Shared by The Mind Ladder and Nations Cup so the two leaderboard CTAs are the same
   object: a machined obsidian slab with a 1px specular line along its top edge, a violet
   hairline and a chevron chip that leans forward on hover. The press is a scale-down (not
   a translate), so the tap reads as a key being pushed into the card. The horizontal padding
   stays at 14px: the Persian label is the longest string this key carries on a 320px card. */
.car-card .slide-cta {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 48px;
  padding: 12px 14px;
  border-radius: 14px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .085) 0%, rgba(255, 255, 255, 0) 46%),
    linear-gradient(180deg, #232D42 0%, #141B28 100%);
  border: 1px solid rgba(196, 181, 253, .22);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .18),
    inset 0 -1px 0 rgba(0, 0, 0, .55),
    0 10px 22px -14px rgba(0, 0, 0, .95),
    0 0 0 1px rgba(8, 12, 20, .5);
  color: #E6DDFF;
  font-size: 12.5px;
  font-weight: 900;
  letter-spacing: .08em;
  line-height: 1.2;
  text-transform: uppercase;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .55);
  transition: transform .12s ease, border-color .16s ease, box-shadow .16s ease;
}
/* the specular sheen: a soft light cap, inset so it never paints past the edge */
.car-card .slide-cta::before {
  content: "";
  position: absolute;
  inset: 1px 1px auto;
  height: 44%;
  border-radius: 13px 13px 22px 22px;
  background: linear-gradient(180deg, rgba(255, 255, 255, .1) 0%, rgba(255, 255, 255, 0) 100%);
  pointer-events: none;
}
.slide-cta-t { position: relative; display: block; min-width: 0; white-space: nowrap; }
.slide-cta-go {
  position: relative;
  flex: none;
  width: 21px;
  height: 21px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(196, 181, 253, .14);
  box-shadow: inset 0 0 0 1px rgba(196, 181, 253, .3);
  color: #D9CDFF;
  transition: transform .16s ease, background .16s ease;
}
.slide-cta-ico { display: block; width: 11px; height: 11px; }
.car-card .slide-cta:hover:not(:active) .slide-cta-go {
  transform: translateX(2px);
  background: rgba(196, 181, 253, .24);
}
.car-card .slide-cta:active {
  transform: scale(.985);
  border-color: rgba(196, 181, 253, .42);
  box-shadow:
    inset 0 2px 7px rgba(0, 0, 0, .5),
    0 4px 10px -9px rgba(0, 0, 0, .9);
}
html.reduced-motion .car-card .slide-cta,
html.reduced-motion .slide-cta-go { transition: none; }

/* short columns: the chrome gives up first, the rows keep their share. Nothing here
   sets a row floor — a floor is exactly what used to push the list over the foot. */
@media (max-height: 700px) {
  .car-card.nations-cup > .slide-inner,
  .car-card.mind-ladder > .slide-inner { padding: 10px 14px 6px; gap: 5px; }
  .mini-rank.nations-rank,
  .mind-podium { gap: 5px; }
  .nations-head { row-gap: 0; }
  .nations-cup-subtitle { font-size: .68rem; }
  .car-card.nations-cup .slide-foot,
  .car-card.mind-ladder .slide-foot { gap: 7px; padding-bottom: 6px; }
}
/* compact rows: a 24–28px slice needs a 22px portrait, or the row clips its own face.
   The card is short here, so the list trades portrait size for five legible lines. */
@media (max-height: 680px) {
  .car-card.mind-ladder .mind-row { padding-top: 1px; padding-bottom: 1px; gap: 7px; }
  .car-card.mind-ladder .mind-av { width: 22px; height: 22px; }
  .car-card.mind-ladder .mind-ini { font-size: 10px; }
  .car-card.mind-ladder .mind-rank { width: 22px; height: 24px; font-size: 10.5px; border-radius: 7px 7px 11px 11px / 6px 6px 13px 13px; }
  .car-card.mind-ladder .mind-crown { width: 10px; height: 6px; }
  .car-card.mind-ladder .mind-nm { font-size: 12.5px; }
  .car-card.mind-ladder .mind-score { font-size: 13.5px; }
  .car-card.mind-ladder .mind-av .mind-flag { --fp-d: 11px; width: 11px; height: 11px; }
  .car-card.nations-cup .mini-rank.nations-rank > li.nations-row { padding-top: 1px; padding-bottom: 1px; }
  .car-card.nations-cup .mini-rank.nations-rank > li:not(.is-error) { column-gap: 6px; }
  .car-card.nations-cup .mini-rank.nations-rank .fl { flex-basis: 26px; width: 26px; height: 26px; }
  .car-card.nations-cup .mini-rank.nations-rank .rk { width: 19px; height: 19px; font-size: 11px; }
  .car-card.nations-cup .mini-rank.nations-rank .nm { font-size: 12.5px; }
  .car-card.nations-cup .mini-rank.nations-rank .score-val { font-size: 13.5px; }
  .car-card.nations-cup .mini-rank.nations-rank .score-brain-icon { width: 15px; height: 15px; }
}
/* the compact-height grid above keeps a trend column, but the ≤344px query hands that
   column's track to the score, because `.tr` is not rendered there at all — the score
   would then sit in a 24px track and paint backwards over the nation name. The five
   tracks therefore only apply where the trend column actually survives. */
@media (min-width: 345px) and (max-height: 680px) {
  .car-card.nations-cup .mini-rank.nations-rank > li:not(.is-error) {
    grid-template-columns: 19px 26px minmax(0, 1fr) 24px 90px;
  }
}
/* the floor: only a window this short cannot carry five full rows — the tail row
   steps aside rather than letting the list squeeze into a smear */
@media (max-height: 560px) {
  .mini-rank.nations-rank li.nations-row:nth-child(5),
  .mind-podium .mind-row:nth-child(5) { display: none; }
}
@media (max-height: 520px) {
  .mini-rank.nations-rank li.nations-row:nth-child(4),
  .mind-podium .mind-row:nth-child(4) { display: none; }
}
/* the narrowest phone: the standing bar drops the word "minds" (the number carries it)
   and the row gives back a pixel of gutter, so a real handle still survives before it
   ellipsizes. Nothing here removes a column the row needs to stay legible. */
@media (max-width: 360px) {
  .hm-pill-u { display: none; }
  /* The methodology note is the longest subtitle this header has carried; on the narrowest
     cards it gives back a fraction of a point so the whole sentence survives before ellipsis. */
  .nations-cup-subtitle { font-size: .64rem; letter-spacing: .02em; }
  .car-card.mind-ladder .mind-row { gap: 6px; padding-left: 8px; }
  /* the header keeps its whole title at 320px: the crest and the kicker both give back
     tracking instead of letting the wordmark clip */
  .car-card.mind-ladder .mind-kicker { font-size: 11.5px; letter-spacing: .1em; }
  .car-card.mind-ladder .mind-ico { width: 20px; height: 20px; }
  .car-card.mind-ladder .mind-ico .ico { width: 12px; height: 12px; }
  .car-card.mind-ladder .mind-top { padding: 4px 7px 4px 6px; letter-spacing: .1em; }
}
@media (max-width: 344px) {
  .car-card.mind-ladder .mind-tiq-k { display: none; }
  .car-card.mind-ladder .mind-score { font-size: 14px; }
}

/* ============================================================================================
   CHANNEL WAR — the winner-takes-all hero slide (carousel index 0).

   Same clay slab as its siblings, but this poster never stretches to fill the
   track: it hugs its own content (capped at 100cqh, centred), so no dead band can
   open under the admin strip. The 36px bottom reserve is the pager's lane — a
   20px dot row 8px off the card edge plus 8px of air above it.

   One composed poster, read top to bottom: a quiet header row, a centered reward
   stage (the authentic Telegram Stars PNG over the metallic jackpot), a compact
   gold-rimmed throne plaque, the solid-gold command and a slim glass enlistment
   strip. The stage can still give height back on short phones; on tall ones the
   poster simply ends under the admin strip, with the pager 8px below it.
   ============================================================================================ */
.car-card.carousel-slide-tournament {
  position: relative;
  isolation: isolate;
  justify-content: flex-start;
  gap: 8px;
  padding: 12px 14px 36px;
  overflow: hidden;
  border-radius: var(--r-panel);
  border-top: 1px solid rgba(255, 218, 133, .2);
  background:
    radial-gradient(95% 68% at 50% -8%, rgba(251, 191, 36, .13), rgba(251, 191, 36, 0) 58%),
    radial-gradient(150% 120% at 50% 118%, rgba(0, 0, 0, .62), rgba(0, 0, 0, 0) 62%),
    linear-gradient(180deg, #1B2334 0%, #131A28 52%, #0A0F18 100%);
  box-shadow:
    0 12px 26px rgba(0, 0, 0, .32),
    inset 0 1px 0 rgba(255, 239, 196, .09),
    inset 0 0 0 1px rgba(251, 191, 36, .12),
    inset 0 0 44px rgba(0, 0, 0, .35);
}
/* the atmosphere pass: diagonal specular streaks from the upper left edge and a
   deep obsidian vignette that lets the royal stage breathe at the center */
.car-card.carousel-slide-tournament::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background:
    linear-gradient(116deg, transparent 18%, rgba(255, 243, 198, .07) 27%, rgba(255, 243, 198, .015) 34%, transparent 43%),
    linear-gradient(116deg, transparent 52%, rgba(251, 191, 36, .055) 60%, transparent 69%),
    linear-gradient(296deg, transparent 12%, rgba(125, 211, 252, .028) 22%, transparent 32%),
    radial-gradient(125% 105% at 50% 42%, transparent 46%, rgba(2, 5, 10, .58) 100%);
}
/* the metallic hairline: gold at the lit corner, cooling to obsidian along the rim */
.car-card.carousel-slide-tournament::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  pointer-events: none;
  background: linear-gradient(142deg,
    rgba(255, 232, 166, .55) 0%,
    rgba(196, 129, 31, .24) 24%,
    rgba(13, 18, 28, 0) 48%,
    rgba(251, 191, 36, .18) 78%,
    rgba(255, 245, 205, .38) 100%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask-composite: exclude;
}
.car-card.carousel-slide-tournament > * { position: relative; z-index: 1; }

/* ---- header: the star pod and title on the left, the live clock on the right ---- */
.tour-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s2);
  min-width: 0;
  min-height: 20px;
}
.car-card.carousel-slide-tournament .car-kicker::before { content: none; display: none; }
.tour-kicker {
  color: #F8FAFC;
  gap: 8px;
  min-width: 0;
  font-size: 12.5px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
}
/* 22x22 recessed well: the star is lit, the pod is in shadow */
.tour-star-pod {
  flex: none;
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  border-radius: 7px;
  background: linear-gradient(180deg, #0C1322 0%, #141D30 100%);
  box-shadow:
    inset 0 1px 3px rgba(0, 0, 0, .55),
    inset 0 0 0 1px rgba(251, 191, 36, .18);
}
.tour-star-ico {
  display: block;
  width: 16px;
  height: 16px;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, .5));
}
.tour-title {
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ---- the reward stage: one centered lockup, lit from behind the Star. The soft
   radial is the stage floor, so the flexible height around the lockup reads as
   deliberate air rather than a dead band. ---- */
.tour-hero {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 0;
  text-align: center;
  background: radial-gradient(58% 54% at 50% 40%, rgba(251, 191, 36, .12), rgba(251, 191, 36, 0) 72%);
}
.tour-star-stage {
  position: relative;
  flex: none;
  width: 112px;
  height: 112px;
  display: grid;
  place-items: center;
  isolation: isolate;
}
/* the royal backlight: a warm gold core under the trophy, an engraved inner orbit,
   and a crest halo at the outer rim — all strictly behind the untouched Star */
.tour-star-stage::before {
  content: "";
  position: absolute;
  inset: -16px;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 50%, transparent 58.8%, rgba(255, 214, 120, .36) 59.4%, rgba(255, 214, 120, .36) 60.1%, transparent 60.8%),
    radial-gradient(circle at 50% 50%, transparent 46.6%, rgba(255, 191, 60, .16) 47.2%, transparent 48.1%),
    radial-gradient(closest-side, rgba(255, 200, 70, .34) 0%, rgba(255, 170, 40, .15) 44%, rgba(150, 82, 12, .06) 66%, rgba(251, 191, 36, 0) 78%);
  box-shadow:
    inset 0 0 0 1px rgba(255, 222, 145, .14),
    inset 0 0 28px rgba(251, 191, 36, .14);
  animation: tour-stage-breathe 4.6s ease-in-out infinite;
  pointer-events: none;
  z-index: 0;
}
/* the pedestal ring: a struck gold rim under the trophy, grounded by its own shadow */
.tour-star-stage::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -1px;
  width: 76%;
  height: 14px;
  transform: translateX(-50%);
  border-radius: 50%;
  background: radial-gradient(closest-side, rgba(255, 208, 92, .34) 0%, rgba(251, 191, 36, .12) 48%, rgba(251, 191, 36, 0) 76%);
  box-shadow: 0 1px 0 rgba(255, 240, 190, .22), 0 5px 12px rgba(0, 0, 0, .45);
  pointer-events: none;
  z-index: 0;
}
/* the authentic Star: the app's own Telegram Stars asset on a slow levitation loop */
.tour-star-img {
  position: relative;
  z-index: 1;
  display: block;
  width: 104px;
  height: 104px;
  object-fit: contain;
  /* the stage's gold dish is the depth: no filter on the moving image */
  animation: star-float 3.4s ease-in-out infinite;
}
@keyframes star-float {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-4px); }
}
@keyframes tour-stage-breathe {
  0%, 100% { opacity: .78; transform: scale(.985); }
  50% { opacity: 1; transform: scale(1.035); }
}

/* ---- the prize type: the jackpot and its rule, both centered under the Star ---- */
.tour-vault {
  flex: none;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
}
/* high-relief gold: a six-stop leaf gradient, a dark struck contour and one warm bloom */
.tour-vault-v {
  font-size: 44px;
  font-weight: 900;
  line-height: .96;
  letter-spacing: .055em;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  background: linear-gradient(180deg, #FFFDF3 0%, #FFF2BC 20%, #FFD666 38%, #FFB224 58%, #E8890C 76%, #A95305 91%, #7C3E02 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: #FCD34D;
  -webkit-text-fill-color: transparent;
  /* a crisp struck contour instead of three drop-shadow passes */
  -webkit-text-stroke: 1px rgba(124, 45, 18, .55);
}
/* a motivating hook: warm ivory under the jackpot, balanced over two lines when tight */
.tour-vault-sub {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 0;
  max-width: 100%;
  padding: 0 2px;
  font-size: 11.5px;
  font-weight: 700;
  line-height: 1.42;
  letter-spacing: .012em;
  color: #E8D9AE;
  text-shadow: 0 1px 2px rgba(0, 0, 0, .55);
  text-wrap: balance;
}
.tour-vault-sub > span { min-width: 0; overflow-wrap: break-word; }

/* ---- the throne: a compact obsidian plaque with a gold hairline. Two segments
   on one line — the crown and its dimmed kicker at the reading start, the
   reigning handle at the far end in bright gold. No blur, no halo loop. ---- */
.tour-hud {
  position: relative;
  flex: none;
  align-self: center;
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  max-width: 100%;
  min-width: 0;
  padding: 6px 12px;
  border: 1px solid rgba(245, 196, 81, 0.3);
  border-radius: 8px;
  background: rgba(20, 27, 45, 0.85);
  box-shadow: 0 2px 8px rgba(0, 0, 0, .28);
  overflow: hidden;
}
.tour-hud.is-unclaimed { border-color: rgba(245, 196, 81, .2); }
.tour-hud.is-reigning { border-color: rgba(245, 196, 81, .42); }
/* the leading segment: a quiet crown and the label it introduces */
.tour-leader-tag {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
}
.tour-leader-ico {
  flex: none;
  width: 12px;
  height: 12px;
  color: #F5C451;
  opacity: .78;
}
.tour-hud.is-reigning .tour-leader-ico { opacity: 1; }
.tour-leader-k {
  flex: none;
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: .14em;
  line-height: 1;
  color: rgba(203, 213, 225, .62);
  text-transform: uppercase;
  white-space: nowrap;
}
/* the separator belongs to the dare only: a reigning name needs no divider */
.tour-leader-sep {
  display: none;
  flex: none;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
  color: rgba(245, 196, 81, .45);
}
.tour-hud.is-unclaimed .tour-leader-sep { display: block; }
/* the handle is a label, never a headline: gold, LTR and clipped, never wrapped */
.tour-leader-h {
  flex: 0 1 auto;
  min-width: 0;
  font-size: 12.5px;
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: .01em;
  color: #FCD34D;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* the live deadline: a frosted dark-gold capsule with a live beacon */
.tour-clock {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 22px;
  padding: 0 9px;
  border-radius: var(--radius-pill);
  border: 1px solid rgba(251, 191, 36, .34);
  background:
    linear-gradient(180deg, rgba(76, 54, 14, .6) 0%, rgba(24, 22, 20, .55) 52%, rgba(10, 13, 20, .82) 100%);
  -webkit-backdrop-filter: blur(12px) saturate(1.1);
  backdrop-filter: blur(12px) saturate(1.1);
  font-family: ui-monospace, "SFMono-Regular", "Roboto Mono", Menlo, Consolas, monospace;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .02em;
  color: #FFDF8A;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
  box-shadow:
    inset 0 1px 0 rgba(255, 241, 192, .18),
    inset 0 -1px 0 rgba(0, 0, 0, .35),
    0 2px 8px rgba(0, 0, 0, .32);
}
.tour-clock b { color: #FFE9A3; font-weight: 800; }
/* the live beacon: an amber core with a crimson edge and a breathing ring */
.tour-clock-dot {
  flex: none;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #FFE9A3 0%, #FBBF24 38%, #F97316 68%, #DC2626 100%);
  animation: tour-beacon-pulse 2.2s ease-in-out infinite;
}
@keyframes tour-beacon-pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(251, 146, 60, .5), 0 0 6px rgba(251, 146, 60, .8); }
  50% { box-shadow: 0 0 0 3px rgba(251, 146, 60, 0), 0 0 10px rgba(220, 38, 38, .75); }
}
/* ---- the primary command: one solid metallic gold bar. No gloss overlay and no
   moving sheen — the finish is the metal itself, with a single crisp inner
   highlight and a deep-espresso ultra-bold label. The press is a 2% scale. ---- */
.tour-cta {
  position: relative;
  flex: none;
  width: 100%;
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 16px;
  border: 0;
  border-radius: 12px;
  background: linear-gradient(180deg, #FDE68A 0%, #F59E0B 55%, #D97706 100%);
  color: #1E1303;
  font: inherit;
  font-size: 14px;
  font-weight: 900;
  letter-spacing: .045em;
  line-height: 1;
  text-align: center;
  text-transform: uppercase;
  white-space: nowrap;
  cursor: pointer;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.6), 0 2px 8px rgba(0, 0, 0, 0.35);
  transition: transform var(--motion-fast), filter var(--motion-fast);
}
.tour-cta-ico {
  flex: none;
  width: 16px;
  height: 16px;
  color: #1E1303;
}
.tour-cta-t { position: relative; }
.tour-cta:hover { filter: brightness(1.04); }
.tour-cta:active { transform: scale(0.98); filter: none; }
.tour-cta:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }

/* ---- the secondary command: a slim inline glass strip. Dimmed silver copy, the
   Telegram paper-plane in bright cyan and a quiet forward chevron — visible, but
   never competing with the gold command above it. No live blur. ---- */
.tour-admin {
  position: relative;
  flex: none;
  width: 100%;
  height: 38px;
  min-height: 38px;
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  padding: 0 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.04);
  color: rgba(203, 213, 225, .78);
  font: inherit;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .06em;
  line-height: 1;
  text-transform: uppercase;
  white-space: nowrap;
  cursor: pointer;
  box-shadow: none;
  transition: transform var(--motion-fast), border-color var(--motion-fast),
              background var(--motion-fast), color var(--motion-fast);
  overflow: hidden;
}
/* the paper-plane reads as a bare glyph, not a socket */
.tour-admin-pod {
  flex: none;
  width: 16px;
  height: 16px;
  display: grid;
  place-items: center;
}
.tour-admin-ico {
  flex: none;
  width: 14px;
  height: 14px;
  color: #38BDF8;
}
.tour-admin-t {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-align: start;
  text-overflow: ellipsis;
}
.tour-admin-chev {
  flex: none;
  font-size: 15px;
  font-weight: 700;
  line-height: 1;
  color: rgba(203, 213, 225, .55);
  transition: transform var(--motion-fast), color var(--motion-fast);
}
.tour-admin:hover {
  border-color: rgba(245, 196, 81, .28);
  background: rgba(255, 255, 255, .06);
  color: #F1F5F9;
}
.tour-admin:hover .tour-admin-chev { transform: translateX(2px); color: #9BE7FF; }
.tour-admin:active { transform: translateY(1px); }
.tour-admin:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }

/* reduced motion: the beacon, crown and sheen hold still; the star rests in its bloom */
html.reduced-motion .tour-clock-dot,
html.reduced-motion .tour-star-stage::before { animation: none; }
html.reduced-motion .tour-cta,
html.reduced-motion .tour-admin,
html.reduced-motion .tour-admin-chev,
html.reduced-motion .tour-admin-pod { transition: none; }
html.reduced-motion .tour-star-img { animation: none; }
@media (prefers-reduced-motion: reduce) {
  .tour-star-img,
  .tour-star-stage::before,
  .tour-clock-dot { animation: none; }
}

/* The 320px floor: the star pod, CHANNEL WAR and the clock share the header row;
   the centered stage narrows, so the jackpot type and its rule line give first. */
@media (max-width: 350px) {
  .car-card.carousel-slide-tournament { padding-left: 10px; padding-right: 10px; gap: 8px; }
  .tour-kicker { gap: 5px; font-size: 12px; letter-spacing: .05em; }
  .tour-clock { height: 21px; padding: 0 6px; gap: 4px; font-size: 9px; }
  .tour-hero { gap: 4px; }
  .tour-vault-sub { font-size: 10px; }
  .tour-hud { gap: 6px; padding: 6px 10px; }
  .tour-leader-k { font-size: 8px; letter-spacing: .1em; }
  .tour-leader-h { font-size: 12px; }
  .tour-cta { gap: 6px; padding: 0 10px; font-size: 13.5px; letter-spacing: .045em; }
  .tour-cta-ico { width: 15px; height: 15px; }
  .tour-admin { gap: 7px; padding: 0 10px; font-size: 9.5px; letter-spacing: .04em; }
  .tour-admin-pod { width: 16px; height: 16px; }
  .tour-admin-chev { font-size: 14px; }
}

/* On shorter columns the floating admin shield rides higher into the card, so
   the glass key takes a matching extra slice of bottom air; the stage gives back
   the same pixels so nothing crowds. */
@media (max-height: 760px) {
  .tour-hero { gap: 4px; }
  .tour-star-stage { width: 68px; height: 68px; }
  .tour-star-stage::before { inset: -10px; }
  .tour-star-stage::after { height: 10px; }
  .tour-star-img { width: 60px; height: 60px; }
  .tour-vault-v { font-size: 32px; }
  .tour-vault-sub { font-size: 10.5px; }
}

/* The 640–680h phones: one notch tighter than the tall reference, so the stage
   and the card rhythm pay for the longer prize hook instead of the copy. */
@media (max-height: 680px) {
  .car-card.carousel-slide-tournament { gap: 8px; }
  .tour-star-stage { width: 58px; height: 58px; }
  .tour-star-stage::before { inset: -9px; }
  .tour-star-img { width: 52px; height: 52px; }
}

/* The short-phone floor (<640h, e.g. 320x568): the stage and the two action
   heights give a few pixels so the stacked lockup still lands whole. */
@media (max-height: 620px) {
  .car-card.carousel-slide-tournament { gap: 8px; }
  .tour-hero { gap: 3px; }
  .tour-star-stage { width: 56px; height: 56px; }
  .tour-star-stage::before { inset: -8px; }
  .tour-star-stage::after { height: 8px; }
  .tour-star-img { width: 50px; height: 50px; }
  .tour-vault { gap: 4px; }
  .tour-vault-v { font-size: 28px; }
  .tour-vault-sub { font-size: 10px; line-height: 1.35; }
  .tour-hud { padding-top: 4px; padding-bottom: 4px; }
  .tour-cta { min-height: 46px; }
}

/* The 600px floor: the track is at its shortest here, so the stage gives another
   slice and the deck closes its rhythm — every line still lands whole. */
@media (max-height: 600px) {
  .car-card.carousel-slide-tournament { gap: 5px; }
  .tour-hero { gap: 0; }
  .tour-star-stage { width: 38px; height: 38px; }
  .tour-star-stage::before { inset: -6px; }
  .tour-star-stage::after { height: 6px; }
  .tour-star-img { width: 34px; height: 34px; }
  .tour-vault { gap: 2px; }
  .tour-vault-v { font-size: 24px; }
  .tour-vault-sub { font-size: 9.5px; line-height: 1.32; }
  .tour-hud { padding-top: 3px; padding-bottom: 3px; }
  .tour-cta { min-height: 44px; }
  html[data-lang="fa"] .tour-vault-v { line-height: 1.35; }
}

/* ---- Persian: the Channel War slide. Vazirmatn wins on every Persian line, tracking
   collapses to zero so the script is never split, and the header/HUD mirror while the
   digits and the champion's handle stay LTR. ---- */
html[data-lang="fa"] .tour-head { direction: rtl; }
html[data-lang="fa"] :is(.tour-kicker, .tour-title) {
  letter-spacing: 0 !important;
  text-transform: none !important;
  line-height: 1.5;
}
html[data-lang="fa"] .tour-vault { max-width: 100%; }
html[data-lang="fa"] .tour-vault-v {
  direction: rtl;
  font-size: 32px;
  line-height: 1.35;
  letter-spacing: 0 !important;
  padding: 0 2px 3px;
  font-family: 'Vazirmatn', system-ui, -apple-system, sans-serif;
  font-variant-numeric: tabular-nums;
}
html[data-lang="fa"] .tour-vault-sub {
  direction: rtl;
  gap: 5px;
  font-size: 11px;
  line-height: 1.55;
  letter-spacing: 0;
}
html[dir="rtl"] .tour-hud { direction: rtl; }
html[data-lang="fa"] .tour-hud {
  direction: rtl;
  padding: 6px 12px;
}
html[data-lang="fa"] .tour-leader-k {
  letter-spacing: 0 !important;
  text-transform: none !important;
  line-height: 1.45;
}
html[data-lang="fa"] .tour-leader-sep { line-height: 1.4; }
/* a handle is never mirrored by the RTL base: '@name' must keep its leading @ */
html[data-lang="fa"] .tour-leader-h { direction: ltr; unicode-bidi: isolate; display: inline-block; }
/* the button itself mirrors, so the swords sit at the reading start and the
   exclamation lands after the last letter instead of before the first */
html[data-lang="fa"] .tour-cta {
  direction: rtl;
  letter-spacing: 0 !important;
  text-transform: none !important;
  font-size: 15px;
}
html[data-lang="fa"] .tour-cta-t { direction: rtl; unicode-bidi: isolate; line-height: 1.5; }
html[data-lang="fa"] .tour-admin {
  direction: rtl;
  letter-spacing: 0 !important;
  text-transform: none !important;
}
html[data-lang="fa"] .tour-admin-t {
  text-align: right;
  line-height: 1.5;
  letter-spacing: 0;
}
/* the growth key's chevron is the only glyph that mirrors: it already points forward */
html[data-lang="fa"] .tour-admin-chev { transform: scaleX(-1); }
html[data-lang="fa"] .tour-admin:hover .tour-admin-chev { transform: scaleX(-1) translateX(2px); }
html[data-lang="fa"] .tour-clock {
  direction: rtl;
  gap: 4px;
  padding: 0 7px;
  font-family: 'Vazirmatn', system-ui, -apple-system, sans-serif;
  font-size: 9px;
  letter-spacing: 0;
  font-variant-numeric: tabular-nums;
}
/* every number keeps its own isolate, so the bidi algorithm can never lift the hour
   off its unit and drop it at the far end of the phrase */
html[data-lang="fa"] .tour-clock bdi { direction: ltr; unicode-bidi: isolate; }
@media (max-height: 760px) {
  html[data-lang="fa"] .tour-vault-v { font-size: 28px; }
}
@media (max-height: 680px) {
  html[data-lang="fa"] .tour-hud { padding-top: 4px; padding-bottom: 4px; }
  html[data-lang="fa"] .tour-vault-v { font-size: 25px; line-height: 1.3; }
}
@media (max-height: 620px) {
  html[data-lang="fa"] .tour-vault-v { font-size: 24px; }
  html[data-lang="fa"] .tour-vault-sub { font-size: 10px; line-height: 1.45; }
}
@media (max-height: 600px) {
  html[data-lang="fa"] .tour-hud { padding-top: 3px; padding-bottom: 3px; }
  html[data-lang="fa"] .tour-vault-v { font-size: 22px; line-height: 1.3; }
  html[data-lang="fa"] .tour-vault-sub { font-size: 9.5px; line-height: 1.4; }
}

/* ============================================================================================
   RACE DOCK, SECOND PASS — one clean row: YOUR chip | the mine key | BOT chip.

   The chat key no longer floats in the dock (it lives in the top bar), so the dock is a single
   64px row: two equal chips around a fixed 64px mine key, all on the same 8px rhythm. The board
   slab already reaches 7px past the board's box, so a 5px margin is the 12px the slab asks for.
   Horizontal space is the scarce axis at 360px: the chips are `flex: 1 1 0`, the key is
   `flex: none`, and every text line ellipsizes rather than pushing a neighbour.

   The bottom safe area is already paid by the app shell (`--pad-b: max(--s3, env(...))`), which is
   what keeps this row off the home indicator; paying it again here would lift the dock twice.
   ============================================================================================ */
.chips {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 64px;
  margin-top: 5px;                    /* 5 + the slab's 7px overhang = 12px below the frame */
  padding-top: 0;
  row-gap: 0;
}
.chip {
  flex: 1 1 0;
  width: auto;
  min-width: 0;
  height: 64px;
  gap: 6px;
  padding: 0 8px;
  border-radius: 18px;
}
.chip-row { gap: 6px; }
/* the 40px team ball: the board's own token, doubling as the seat avatar */
.chip-ball { width: 40px; height: 40px; }
.chip .ball { inset: 2px; width: 36px; height: 36px; }
.chip .timer { width: 40px; height: 40px; }
.chip .timer-n { font-size: 14px; }
.chip-txt { gap: 5px; }
.who-line { gap: 5px; }
.chip .who {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: .01em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* a 64px row holds the name and the ammo pill; the XP tag stays in the DOM for the ladder but
   does not compete for the row's last pixels */
.chip .xp { display: none; }
.chip .walls {
  width: fit-content;
  max-width: 100%;
  height: 20px;
  padding: 0 8px;
  border-radius: 999px;
  gap: 5px;
  font-size: 12px;
  font-weight: 600;
}
.chip .walls .wall-w { display: none; }
.chip .walls .wall-glyph { width: 9px; height: 5px; }
/* the mine key: its own slot, never squeezed by a chip */
.mine-btn {
  flex: none;
  width: 64px;
  height: 64px;
  border-radius: 18px;
}

/* three and four seats keep the 2-up party grid; the mine key rides the dock's right column */
.chips[data-players="3"],
.chips[data-players="4"] {
  display: grid;
  grid-template-columns: 1fr 1fr;
  height: auto;
  padding-right: 72px;
}
.chips[data-players="3"] .mine-btn,
.chips[data-players="4"] .mine-btn {
  position: absolute;
  right: 0;
  top: 50%;
  margin-top: -32px;
  width: 64px;
  height: 64px;
}

/* ============================================================================================
   RACE DOCK, FOURTH PASS — the cockpit: one carved chat rail, two mirrored resource cards.

   The row is no longer "two cards and a stray key". A 38px console rail spans the dock and holds
   the quick-chat pill in a slot of its own, so the key never straddles the board's rim and never
   floats in dead space; the two cards below are the same object mirrored — a 40px avatar well, the
   seat's name and flag, then a two-cell tactical dock (walls | mines). The local seat's mine cell
   is the arm key; every rival's is a sealed fog cell (`.mine-fog`), which is what makes the pair
   read as one cockpit instead of a card and its leftover.

   The height budget at 360x640 is fixed arithmetic, not a guess: 2px of air + 38px rail + 4px gap
   + 80px card = 124px — exactly the band the dock already owned (36px margin + 88px), so the board
   loses nothing. Width: the dock is 328 at 360, so a card is 160 (8 + 40 + 6 + 98 + 8) and each
   tactical cell 47, which is an icon, a digit and room to breathe.
   ============================================================================================ */
.chips {
  position: relative;
  flex: none;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px 8px;                          /* rail -> cards, then card <-> card */
  height: auto;
  margin-top: 10px;                      /* clears the slab's own drop shadow, not just its box */
  padding: 0;
}

.chat-key {
  position: relative;
  z-index: 1;
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-width: 148px;
  height: 38px;                          /* 38x148: the target is never a thumb's guess */
  padding: 0 16px;
  border: 0;
  border-radius: 999px;
  background: var(--field);
  color: var(--ink-soft);
  font: inherit;
  cursor: pointer;
  box-shadow:
    inset 0 2px 5px rgba(0, 0, 0, .5),
    inset 0 -1px 0 rgba(255, 255, 255, .05),
    inset 0 0 0 1px var(--hair);
  transition: color var(--motion-fast), box-shadow var(--motion-fast), transform var(--motion-fast);
}
.chat-key .ico { width: 16px; height: 16px; flex: none; }
.chat-key:active {
  transform: translateY(1px);
  box-shadow:
    inset 0 3px 7px rgba(0, 0, 0, .6),
    inset 0 0 0 1px var(--hair);
}
.chat-key:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.chat-key[disabled] { opacity: .42; filter: saturate(.4); cursor: default; }
/* the rival said something: the slot warms until the sheet is opened, then goes quiet again */
.chat-ping {
  position: absolute;
  top: 6px;
  right: 11px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--honey);
  box-shadow: 0 0 8px -1px var(--honey);
  opacity: 0;
  transition: opacity .2s ease;
}
.chat-key.is-ping {
  color: var(--honey-ink);
  box-shadow:
    inset 0 2px 5px rgba(0, 0, 0, .5),
    inset 0 0 0 1px rgba(245, 158, 11, .42),
    inset 0 0 14px -6px rgba(245, 158, 11, .9);
}
.chat-key.is-ping .chat-ping { opacity: 1; animation: breathe 1.8s ease-in-out infinite; }

/* ---- the card: one slab, one team rim, two rows of reading ---- */
.chip {
  position: relative;
  min-width: 0;
  width: auto;
  height: 72px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 8px;
  border-radius: 20px;
  overflow: clip;
  background: linear-gradient(180deg,
    color-mix(in srgb, var(--tint) 7%, var(--solid-a)) 0%,
    color-mix(in srgb, var(--tint) 3%, var(--solid-b)) 100%);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--tint) 36%, transparent),
    inset 0 1px 0 var(--hair-lit),
    inset 0 -2px 3px rgba(0, 0, 0, .32),
    0 6px 14px -12px var(--shadow-soft);
  transition: transform .2s ease, filter .2s ease, background .2s ease, box-shadow .2s ease;
}
/* the seat that is waiting: matte clay, one step back — still legible, visibly idle */
.chip:not(.active) { filter: saturate(.82) brightness(.94); }
.chip::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow:
    inset 0 0 0 2px color-mix(in srgb, var(--tint) 62%, transparent),
    0 0 16px -2px var(--glow);
  opacity: 0;
  pointer-events: none;
  transition: opacity .24s ease;
}
/* the seat to move: lifted 2px, lit from its own colour, and its rim breathes */
.chip.active {
  filter: none;
  transform: translateY(-2px);
  background: linear-gradient(180deg,
    color-mix(in srgb, var(--tint) 13%, var(--solid-a)) 0%,
    color-mix(in srgb, var(--tint) 6%, var(--solid-b)) 100%);
  box-shadow:
    inset 0 0 0 1.5px color-mix(in srgb, var(--tint) 72%, transparent),
    inset 0 1px 0 var(--hair-lit),
    inset 0 -2px 3px rgba(0, 0, 0, .3),
    0 0 20px -6px var(--glow),
    0 8px 16px -10px var(--shadow-soft);
}
.chip.active::after { opacity: 1; animation: chip-rim 2.6s ease-in-out infinite; }
.chip.thinking::after { opacity: 1; animation: breathe 1.5s ease-in-out infinite; }
@keyframes chip-rim { 0%, 100% { opacity: .55; } 50% { opacity: 1; } }

/* ---- the avatar well: a recessed socket, the seat's own ball seated in it ---- */
.chip-ball {
  position: relative;
  flex: none;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--field);
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, .55),
    inset 0 0 0 1px var(--hair);
}
.chip .ball {
  position: absolute;
  inset: 2px;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: radial-gradient(circle at 32% 26%, #fff8 0%, var(--tint) 58%, #0004 100%);
  box-shadow: 0 1px 3px -1px var(--glow), inset 0 0 0 1px rgba(255, 255, 255, .18);
}
/* the monogram: engraved on the token, never competing with it */
.av-in {
  font-size: 13px;
  font-weight: 800;
  line-height: 1;
  letter-spacing: .02em;
  color: #fff;
  opacity: .82;
  text-shadow: 0 1px 2px rgba(0, 0, 0, .55);
}
/* the clock rides the avatar's own well now, so it is drawn in the seat's light ink rather than
   the app's cyan: a blue halo around a crimson token read as "selected", not as "time left" */
.chip .timer { inset: 0; width: 40px; height: 40px; }
.chip .timer-fill { stroke: var(--ink-t); }
.chip .timer-n {
  position: absolute;
  inset: auto -5px -5px auto;
  display: none;
  place-items: center;
  min-width: 17px;
  height: 16px;
  padding: 0 4px;
  border-radius: 999px;
  background: var(--tint);
  color: #fff;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
  text-shadow: none;
  box-shadow:
    0 0 0 2px var(--tint-glass),
    0 2px 5px -1px rgba(0, 0, 0, .6);
}
.chip.timing .timer-n { display: grid; }

/* ---- the text column: name + flag over the tactical dock ---- */
.chip-txt {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
}
.who-line { display: flex; align-items: center; gap: 4px; min-width: 0; }
.chip .who {
  flex: 0 1 auto;
  min-width: 0;
  color: var(--ink-t);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: .07em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.chip .flag-badge { flex: none; width: 15px; height: 15px; }
.chip .flag-badge .fp { --fp-d: 15px; }
.chip .flag-badge .fp-chip { font-size: 7px; }
.chip .xp { display: none; }             /* the ladder's number is not a HUD reading */

/* ---- the tactical dock: two cells, same order on every card ----
   Walls on the left in the seat's colour, mines on the right in the app's amber. The cells are
   recessed wells, so the pair reads as instrument readouts rather than two badges. */
.res {
  display: flex;
  align-items: stretch;
  gap: 4px;
  height: 24px;
  min-width: 0;
}
.res-cell {
  flex: 1 1 0;
  min-width: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  height: 24px;
  padding: 0 5px;
  border-radius: 8px;
  background: var(--field);
  color: var(--ink-t);
  font-size: 10.5px;
  font-weight: 800;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
  white-space: nowrap;
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, .55),
    inset 0 -1px 0 rgba(255, 255, 255, .05),
    inset 0 0 0 1px var(--hair);
}
.res-cell .ico { width: 13px; height: 13px; flex: none; }
.res-n { min-width: 1ch; text-align: center; }
button.res-cell {
  appearance: none;
  border: 0;
  font-family: inherit;
  cursor: pointer;
  transition: color var(--motion-fast), background var(--motion-fast),
              box-shadow var(--motion-fast), transform var(--motion-fast);
}
button.res-cell:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 1px; }

/* the wall cell: a crisp two-course wall in the seat's own colour.
   The `#walls-N` element carries `.walls` as well as `.res-cell`, and an older pass sized that
   class for a standalone pill — so the cell's own geometry is restated here, at the same
   specificity but later in the sheet, or the wall would sit 4px short of its mine twin. */
.chip .walls {
  flex: 1 1 0;
  width: auto;
  max-width: none;
  height: 24px;
  padding: 0 5px;
  gap: 3px;
  border-radius: 8px;
  font-size: 10.5px;
  font-weight: 800;
  display: inline-flex;
}
.chip .walls .wall-glyph {
  width: 13px;
  height: 13px;
  border-radius: 0;
  background: none;
  box-shadow: none;
  color: var(--tint);
  filter: drop-shadow(0 0 5px var(--glow));
}
.chip .walls.depleted { color: var(--ink-soft); opacity: .62; }
.chip .walls.depleted .wall-glyph { color: var(--ink-soft); filter: none; }
.chip .walls.pop { animation: step-pop .34s cubic-bezier(.2, 1.3, .5, 1); }
.chip .walls.dry-warn { animation: wall-warn .64s ease-out; }

/* the mine key: the local seat's own cell, golden and pressable */
.chip .res .mine-btn { color: var(--honey-ink); }
.chip .res .mine-btn .ico { filter: drop-shadow(0 0 5px rgba(245, 158, 11, .5)); }
.chip .res .mine-btn[aria-pressed="true"] {
  color: #fff3d6;
  background: linear-gradient(180deg, #4A3110 0%, #2A1B06 100%);
  box-shadow:
    inset 0 0 0 2px #fbbf24,
    inset 0 0 14px -2px rgba(245, 158, 11, .55),
    inset 0 1px 0 rgba(255, 255, 255, .16),
    inset 0 -3px 0 rgba(0, 0, 0, .5),
    0 0 16px -4px rgba(245, 158, 11, .75);
}
.chip .res .mine-btn[aria-pressed="true"] .ico { animation: breathe 1.6s ease-in-out infinite; }
.chip .res .mine-btn[disabled] { opacity: .42; cursor: default; filter: saturate(.5); }
.chip .res .mine-btn[disabled] .ico { animation: none; }
.chip .res .mine-btn:active { transform: translateY(1px); }

/* ---- fog of war: the rival's stash is sealed, never counted ----
   The same bomb, the same well, the same amber — only the badge differs: a sculpted clay jewel
   with a "?" struck into it instead of a number. Nothing in the DOM ever holds their count. */
.chip .mine-fog { color: var(--honey-ink); cursor: default; }
.chip .mine-fog .ico { filter: drop-shadow(0 0 5px rgba(245, 158, 11, .38)); }
.mine-fog .fog-n {
  display: grid;
  place-items: center;
  width: 15px;
  height: 15px;
  border-radius: 50%;
  font-size: 9.5px;
  font-weight: 900;
  line-height: 1;
  color: #fde68a;
  background: radial-gradient(circle at 34% 26%,
    rgba(252, 211, 77, .34) 0%, rgba(252, 211, 77, .10) 44%, rgba(0, 0, 0, .34) 100%);
  box-shadow:
    inset 0 0 0 1px rgba(252, 211, 77, .38),
    inset 0 1px 0 rgba(255, 255, 255, .16),
    inset 0 -2px 3px rgba(0, 0, 0, .45),
    0 1px 3px -1px rgba(0, 0, 0, .6);
  text-shadow: 0 1px 1px rgba(0, 0, 0, .6);
}
/* provably spent — every charge they buried has already gone off — the well goes cold */
.chip .mine-fog[data-fog="spent"] { opacity: .5; }
.mine-fog[data-fog="spent"] .fog-n {
  color: var(--ink-soft);
  background: rgba(255, 255, 255, .05);
  box-shadow: inset 0 0 0 1px var(--hair);
  text-shadow: none;
}

/* ---- three and four seats: the same cards, 2-up, one step compact ----
   The older reflow pass sized these cards for a 52px row with a floating mine key; every rule
   here carries a .chip step so it outranks that pass and the key comes back into the dock. */
.chips[data-players="3"],
.chips[data-players="4"] { padding-right: 0; gap: 4px 8px; }
.chips[data-players="3"] #chip-2 { grid-column: 1 / -1; }
.chips[data-players="3"] .chip,
.chips[data-players="4"] .chip { height: 54px; gap: 5px; padding: 0 7px; border-radius: 18px; }
.chips[data-players="3"] .chip .chip-ball,
.chips[data-players="4"] .chip .chip-ball { width: 32px; height: 32px; }
.chips[data-players="3"] .chip .ball,
.chips[data-players="4"] .chip .ball { inset: 2px; width: 28px; height: 28px; }
.chips[data-players="3"] .chip .timer,
.chips[data-players="4"] .chip .timer { inset: 0; width: 32px; height: 32px; }
.chips[data-players="3"] .chip .av-in,
.chips[data-players="4"] .chip .av-in { font-size: 11px; }
.chips[data-players="3"] .chip .chip-txt,
.chips[data-players="4"] .chip .chip-txt { gap: 3px; }
.chips[data-players="3"] .chip .who,
.chips[data-players="4"] .chip .who { font-size: 10.5px; }
.chips[data-players="3"] .chip .res,
.chips[data-players="4"] .chip .res { height: 20px; gap: 3px; }
.chips[data-players="3"] .chip .res-cell,
.chips[data-players="4"] .chip .res-cell { height: 20px; padding: 0 4px; border-radius: 7px; font-size: 9.5px; }
.chips[data-players="3"] .chip .res-cell .ico,
.chips[data-players="4"] .chip .res-cell .ico { width: 11px; height: 11px; }
/* the key is a cell of the dock in every layout: the old pass parked it in a column of its own */
.chips[data-players="3"] .chip .mine-btn,
.chips[data-players="4"] .chip .mine-btn { position: static; margin: 0; width: auto; height: 20px; }
.chips[data-players="3"] .chip .mine-fog .fog-n,
.chips[data-players="4"] .chip .mine-fog .fog-n { width: 13px; height: 13px; font-size: 8.5px; }

/* ---- 340: the card is 140 wide. The ornaments give way, never the name or the counts ---- */
@media (max-width: 340px) {
  .chip { gap: 5px; padding: 0 7px; }
  .chip-ball { width: 34px; height: 34px; }
  .chip .ball { inset: 2px; width: 30px; height: 30px; }
  .chip .timer { inset: 0; width: 34px; height: 34px; }
  .chat-key { min-width: 132px; padding: 0 12px; }
  .hud-rail::before,
  .hud-rail::after { width: calc(50% - 70px); }
}

/* reduced motion: the rim stops breathing, the slot still warms */
html.reduced-motion .chat-key,
html.reduced-motion .chip { transition: none; }
html.reduced-motion .chip.active::after,
html.reduced-motion .chat-key.is-ping .chat-ping { animation: none; }
@media (prefers-reduced-motion: reduce) {
  .chat-key, .chip { transition: none; }
  .chip.active::after, .chat-key.is-ping .chat-ping { animation: none; }
}

/* ============================================================================================
   RACE DOCK, FIFTH PASS — the ultra-slim cockpit: two 50px strips, one icon-only chat key.

   The rail is gone. The dock is one low row — strip | 38px chat key | strip — so the whole HUD
   band drops from ~124px to ~60px and the board keeps the difference. Each strip is the same
   object mirrored: a 34px avatar orb, the seat's name + flag over its wall-count pill, and a
   dedicated 40px tactical mine pod on the right end behind a 1px engraved groove. The local
   seat's pod is the arm key; every rival's is the same pod with a sealed "?" corner badge. The
   chat key carries no text at all — one crisp speech bubble in a 38x38 squircle.
   ============================================================================================ */
.chips {
  position: relative;
  flex: none;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  height: auto;
  margin-top: 10px;                      /* clears the slab's own drop shadow and bottom lip */
  padding: 0;
}
.chip {
  flex: 1 1 0;
  min-width: 0;
  height: 50px;
  gap: 4px;
  padding: 0 4px;
  border-radius: 14px;
}
.chip-txt { gap: 4px; }
.who-line { gap: 3px; }
.chip .who {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .08em;
}
.chip .flag-badge { width: 13px; height: 13px; }
.chip .flag-badge .fp { --fp-d: 13px; }

/* ---- the chat key: zero text, zero rail — a 38x38 tactile squircle in the gap ---- */
.chat-key {
  flex: none;
  align-self: center;
  width: 38px;
  min-width: 38px;
  height: 38px;
  padding: 0;
  gap: 0;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: linear-gradient(180deg, #2A3650 0%, #1B2333 100%);
  color: var(--ink-soft);
  box-shadow:
    inset 0 0 0 1px var(--hair),
    inset 0 1px 0 var(--hair-lit),
    inset 0 -2px 3px rgba(0, 0, 0, .4),
    0 4px 10px -6px var(--shadow-soft);
}
.chat-key .ico { width: 19px; height: 19px; flex: none; }
.chat-key .chat-ping { top: 3px; right: 3px; }
.chat-key:active {
  transform: translateY(1px);
  box-shadow:
    inset 0 0 0 1px var(--hair),
    inset 0 2px 4px rgba(0, 0, 0, .5),
    inset 0 -1px 0 rgba(255, 255, 255, .04);
}

/* ---- the avatar orb: a compact 34px socket with the turn ring around it ---- */
.chip-ball { width: 34px; height: 34px; }
.chip .ball { inset: 2px; width: 30px; height: 30px; }
.chip .timer { inset: 0; width: 34px; height: 34px; }
.chip .av-in { font-size: 12px; }
.chip .timer-n { font-size: 12px; }

/* ---- the wall-count pill: fit-content, directly under the name ---- */
.chip .res {
  display: flex;
  align-items: center;
  height: 18px;
  min-width: 0;
}
.chip .res .walls {
  flex: none;
  width: fit-content;
  max-width: 100%;
  height: 18px;
  padding: 0 7px 0 5px;
  gap: 4px;
  border-radius: 6px;
  font-size: 10.5px;
  font-weight: 800;
  display: inline-flex;
}
.chip .res .walls .wall-glyph { width: 12px; height: 12px; }

/* ---- the tactical mine pod: a dedicated 40px recessed clay key, walled off by a groove ----
   The pod is the strip's right end: the local seat's is the arm key (`#mine-btn`), every rival's
   is the sealed `.mine-fog` twin. A 1px engraved groove separates it from the readings; the count
   lives on a micro-badge anchored to its bottom-right corner — a crisp gold digit for YOU, a
   sculpted "?" for the rival until the public record proves the stash spent. */
.chip .mine-pod {
  position: relative;
  flex: none;
  align-self: center;
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  margin: 0 0 0 4px;
  padding: 0;
  border: 0;
  border-radius: 12px;
  background: linear-gradient(180deg, #222D43 0%, #161D2B 100%);
  color: var(--honey-ink);
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, .55),
    inset 0 -1px 0 rgba(255, 255, 255, .06),
    inset 0 0 0 1px color-mix(in srgb, var(--honey) 26%, transparent),
    0 3px 8px -5px var(--shadow-soft);
  transition: transform var(--motion-fast), box-shadow var(--motion-fast),
              background var(--motion-fast), opacity var(--motion-fast);
}
.chip span.mine-pod { cursor: default; }
.chip button.mine-pod { cursor: pointer; }
.chip .mine-pod::before {
  content: "";
  position: absolute;
  left: -3px;
  top: 7px;
  bottom: 7px;
  width: 1px;
