}
.chip button.mine-pod[aria-pressed="true"] .bomb-ico { animation: breathe 1.6s ease-in-out infinite; }
.chip button.mine-pod[disabled] { opacity: .42; cursor: default; filter: saturate(.5); }
.chip button.mine-pod[disabled] .bomb-ico { animation: none; }

/* the micro-badge on the pod's corner: both pods wear the same 15px jewel */
.chip .mine-pod .res-n {
