.chips[data-players="3"] .chip .ball,
.chips[data-players="4"] .chip .ball { inset: 2px; width: 30px; height: 30px; }
.chips[data-players="3"] .chip .timer,
.chips[data-players="4"] .chip .timer { inset: 0; width: 34px; height: 34px; }
