/* ---- the View All cards carry the archetype, the edition serial and its metal ---- */
.badge-card {
  --card-aura: 148, 163, 184;
  --card-ink: #CBD5E1;
}
.badge-card[data-accent="titanium"] { --card-aura: 6, 182, 212; --card-ink: #A5F3FC; }
.badge-card[data-accent="quantum"]  { --card-aura: 245, 158, 11; --card-ink: #FDE047; }
.badge-card[data-accent="frost"]    { --card-aura: 16, 185, 129; --card-ink: #6EE7B7; }
.badge-card-arch {
  display: block;
  font-size: 8.5px;
  line-height: 1.2;
  font-weight: 900;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #7DD3FC;
}
.badge-card[data-accent="titanium"] .badge-card-arch { color: #A5F3FC; }
.badge-card[data-accent="quantum"]  .badge-card-arch { color: #FDE047; }
.badge-card[data-accent="frost"]    .badge-card-arch { color: #6EE7B7; }
.badge-card-ser {
  display: inline-flex;
  align-self: flex-start;
  align-items: center;
  height: 16px;
  margin-top: 2px;
  padding: 0 6px;
  border-radius: 5px;
  overflow: hidden;
  white-space: nowrap;
  font-family: ui-monospace, "SFMono-Regular", Menlo, Consolas, "Liberation Mono", monospace;
  font-size: 9px;
  line-height: 1;
  font-weight: 700;
  letter-spacing: .1em;
  font-variant-numeric: tabular-nums;
  color: #A4B3C7;
  background: linear-gradient(180deg, #070C15 0%, #111927 100%);
  box-shadow:
    inset 0 1px 2px rgba(0, 0, 0, .85),
    inset 0 -1px 0 rgba(255, 255, 255, .05),
    inset 0 0 0 1px rgba(255, 255, 255, .055);
}
.badge-card-ser.is-serial {
  color: #DCE7F3;
  background: linear-gradient(180deg, #0B1420 0%, #172131 100%);
  box-shadow:
    inset 0 1px 2px rgba(0, 0, 0, .85),
    inset 0 -1px 0 rgba(255, 255, 255, .06),
    inset 0 0 0 1px rgba(var(--card-aura), .3);
}
.badge-card-ser.is-unlocked {
  color: var(--card-ink);
  background: linear-gradient(180deg, rgba(var(--card-aura), .18) 0%, rgba(7, 12, 21, .72) 100%);
  box-shadow:
    inset 0 1px 2px rgba(0, 0, 0, .72),
    inset 0 0 0 1px rgba(var(--card-aura), .42);
  text-shadow: 0 0 6px rgba(var(--card-aura), .4);
}
.badge-card-ser.is-editions {
  color: #C3D2E4;
  background: linear-gradient(180deg, #0A111B 0%, #121B28 100%);
  box-shadow:
    inset 0 1px 2px rgba(0, 0, 0, .8),
    inset 0 0 0 1px rgba(var(--card-aura), .18);
}
.badge-card.is-equipped .badge-card-ser {
  color: var(--card-ink);
  background: linear-gradient(180deg, rgba(var(--card-aura), .2) 0%, rgba(var(--card-aura), .06) 55%, rgba(7, 12, 21, .72) 100%);
  box-shadow:
    inset 0 1px 2px rgba(0, 0, 0, .72),
    inset 0 0 0 1px rgba(var(--card-aura), .5),
    0 0 8px -2px rgba(var(--card-aura), .45);
  text-shadow: 0 0 6px rgba(var(--card-aura), .5);
}
.badge-card-lore { font-style: normal; }

@media (max-width: 380px) {
  .badge-card-arch { font-size: 8px; letter-spacing: .08em; }
  .badge-card-ser { font-size: 8.5px; }
}

#sheet-squad {
  padding-top: 14px;
  padding-bottom: calc(10px + env(safe-area-inset-bottom));
  gap: var(--s2);
  border: 1px solid rgba(245, 208, 127, .12);
  border-bottom: 0;
  background:
    radial-gradient(120% 78% at 4% 0%, rgba(252, 211, 77, .085) 0%, rgba(252, 211, 77, 0) 60%),
    radial-gradient(90% 60% at 100% 0%, rgba(245, 158, 11, .055) 0%, rgba(245, 158, 11, 0) 64%),
    linear-gradient(180deg, rgba(21, 24, 32, .985) 0%, rgba(8, 11, 17, .998) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 240, 191, .13),
    0 -26px 60px -34px rgba(245, 158, 11, .32);
  -webkit-backdrop-filter: blur(18px) saturate(1.06);
  backdrop-filter: blur(18px) saturate(1.06);
}
#sheet-squad.is-hub {
  height: calc(86vh - env(safe-area-inset-top));
  height: calc(86dvh - env(safe-area-inset-top));
  max-height: calc(86vh - env(safe-area-inset-top));
  max-height: calc(86dvh - env(safe-area-inset-top));
}
.sq-top {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s2);
  min-height: 48px;
}
.sq-head {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.sq-title {
  margin: 0;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  text-align: left;
  font-size: 19px;
  font-weight: 900;
  line-height: 1.15;
  letter-spacing: -.015em;
  color: var(--ink);
}
.sq-sub {
  margin: 0;
  overflow: hidden;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.3;
  color: var(--text-dim);
  white-space: nowrap;
  text-overflow: ellipsis;
}
.sq-sub[hidden] { display: none; }
.sq-top-actions {
  flex: none;
  display: flex;
  align-items: center;
  gap: 6px;
}
/* The seam between the two squad views, shown only once a squad is bound. It stays
   a ghost key — hairline rim, no fill, no bloom — so it never competes with the
   close disc or the sheet's real primary action. */
.sq-explore {
  display: none;
  flex: none;
  align-items: center;
  gap: 5px;
  height: 30px;
  padding: 0 10px 0 8px;
  border: 0;
  border-radius: var(--radius-pill);
  background: rgba(252, 211, 77, .055);
  box-shadow:
    inset 0 1px 0 rgba(255, 246, 210, .08),
    inset 0 0 0 1px rgba(252, 211, 77, .26);
  color: var(--gold-ink);
  font-family: inherit;
  font-size: 9.5px;
  font-weight: 900;
  letter-spacing: .05em;
  text-transform: uppercase;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background var(--motion-fast),
    box-shadow var(--motion-fast),
    color var(--motion-fast),
    transform var(--motion-fast);
}
.sq-explore.is-on { display: inline-flex; }
.sq-explore .ico { flex: none; width: 12px; height: 12px; }
.sq-explore:hover {
  background: rgba(252, 211, 77, .11);
  box-shadow:
    inset 0 1px 0 rgba(255, 246, 210, .12),
    inset 0 0 0 1px rgba(252, 211, 77, .42);
  color: #FEF3C7;
}
.sq-explore:active { transform: translateY(1px); }
.sq-explore:focus-visible { outline: 3px solid var(--brand-2); outline-offset: 2px; }
.sq-x { flex: none; }
.sq-search-view { flex: 1 1 auto; min-height: 0; }
.sq-hub {
  flex: 1 1 auto;
  min-height: 0;
  gap: var(--s2);
}

.sq-banner {
  position: relative;
  flex: none;
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr);
  grid-template-areas:
    "av id"
    "stats stats";
  align-items: center;
  column-gap: 10px;
  row-gap: 10px;
  min-width: 0;
  padding: 12px;
  border: 1px solid rgba(252, 211, 77, .16);
  border-top-color: rgba(255, 240, 191, .25);
  border-radius: 18px;
  background:
    radial-gradient(130% 200% at 0% 0%, rgba(252, 211, 77, .11) 0%, rgba(252, 211, 77, 0) 58%),
    radial-gradient(90% 130% at 100% 100%, rgba(245, 158, 11, .05) 0%, rgba(245, 158, 11, 0) 60%),
    linear-gradient(165deg, rgba(31, 33, 40, .92) 0%, rgba(11, 15, 22, .95) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 244, 205, .11),
    inset 0 -1px 0 rgba(0, 0, 0, .55),
    0 18px 38px -30px rgba(0, 0, 0, .98),
    0 0 28px -20px rgba(252, 211, 77, .42);
  -webkit-backdrop-filter: blur(18px) saturate(1.08);
  backdrop-filter: blur(18px) saturate(1.08);
}
.sq-crest {
  --sqc-hi: #E0F2FE;
  --sqc-mid: #38BDF8;
  --sqc-lo: #0369A1;
  --sqc-deep: #082F49;
  --sqc-aura: rgba(56, 189, 248, .46);
  position: relative;
  flex: none;
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  isolation: isolate;
}
.sq-crest-aura {
  position: absolute;
  inset: -13px;
  z-index: -1;
  border-radius: 50%;
  background: radial-gradient(closest-side, var(--sqc-aura) 0%, rgba(0, 0, 0, 0) 76%);
  filter: blur(8px);
  pointer-events: none;
  animation: sq-crest-breathe 5.2s ease-in-out infinite;
}
.sq-crest-coin {
  position: relative;
  width: 100%;
  height: 100%;
  padding: 5px;
  border-radius: 50%;
  background:
    radial-gradient(58% 56% at 32% 22%, rgba(255, 255, 255, .58) 0%, rgba(255, 255, 255, 0) 56%),
    conic-gradient(from 205deg,
      var(--sqc-deep) 0deg,
      var(--sqc-lo) 26deg,
      var(--sqc-mid) 74deg,
      var(--sqc-hi) 112deg,
      var(--sqc-mid) 150deg,
      var(--sqc-lo) 196deg,
      var(--sqc-deep) 232deg,
      var(--sqc-lo) 274deg,
      var(--sqc-hi) 314deg,
      var(--sqc-mid) 344deg,
      var(--sqc-deep) 360deg);
  box-shadow:
    0 4px 0 var(--sqc-deep),
    0 10px 18px -10px rgba(0, 0, 0, .9),
    0 0 22px -6px var(--sqc-aura),
    inset 0 1px 1px rgba(255, 255, 255, .55),
    inset 0 -2px 3px rgba(0, 0, 0, .5),
    0 0 0 1px rgba(0, 0, 0, .55);
}
.sq-crest-coin::before {
  content: "";
  position: absolute;
  z-index: 2;
  inset: 4px;
  border-radius: 50%;
  box-shadow:
    inset 0 2px 3px rgba(0, 0, 0, .72),
    inset 0 -1px 1px rgba(255, 255, 255, .28),
    0 1px 0 rgba(255, 255, 255, .2);
  pointer-events: none;
}
.sq-crest-coin::after {
  content: "";
  position: absolute;
  z-index: 3;
  inset: 5px;
  border-radius: 50%;
  background: linear-gradient(122deg, rgba(255, 255, 255, .3) 0%, rgba(255, 255, 255, 0) 38% 64%, rgba(255, 255, 255, .12) 100%);
  pointer-events: none;
}
.sq-crest-face {
  position: absolute;
  inset: 8px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: radial-gradient(82% 82% at 34% 20%, #26344B 0%, #111826 66%, #0A0F18 100%);
  box-shadow:
    inset 0 0 0 1.5px rgba(0, 0, 0, .6),
    inset 0 3px 8px rgba(0, 0, 0, .72),
    0 1px 0 rgba(255, 255, 255, .14);
  color: var(--sqc-hi);
}
.sq-crest-t {
  font-size: 19px;
  font-weight: 900;
  letter-spacing: -.02em;
  line-height: 1;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .6), 0 0 14px var(--sqc-aura);
}
/* One metal for every crest: the arena divisions no longer tint it, because the
   league badges were removed from the design. */
@keyframes sq-crest-breathe {
  0%, 100% { opacity: .72; transform: scale(.96); }
  50% { opacity: 1; transform: scale(1.06); }
}
html.reduced-motion .sq-crest-aura { animation: none; }
/* Hero identity: a 52px channel squircle with a luminous gold rim, the metallic rank
   medallion pinned to the card's top-right, a two-line name that owns its column, and one
   quiet handle line. Roles stay on the roster rows, so nothing competes with the name. */
.sq-hero-av {
  grid-area: av;
  position: relative;
  flex: none;
  width: 52px;
  height: 52px;
  isolation: isolate;
}
.sq-hero-frame {
  position: relative;
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: 15px;
  background:
    radial-gradient(120% 120% at 28% 10%, rgba(252, 211, 77, .2) 0%, rgba(252, 211, 77, 0) 62%),
    linear-gradient(180deg, #2A2A30 0%, #10141B 100%);
  box-shadow:
    0 0 0 1px rgba(252, 211, 77, .4),
    0 0 0 3px rgba(252, 211, 77, .05),
    inset 0 1px 0 rgba(255, 244, 205, .22),
    0 8px 18px -12px rgba(0, 0, 0, .95);
}
.sq-hero-frame::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  border-radius: inherit;
  box-shadow:
    inset 0 0 0 1px rgba(255, 238, 190, .14),
    inset 0 -10px 14px -12px rgba(0, 0, 0, .7);
  pointer-events: none;
}
.sq-hero-mark {
  font-size: 21px;
  font-weight: 900;
  letter-spacing: -.02em;
  line-height: 1;
  color: #F7E7BB;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .55), 0 0 16px rgba(252, 211, 77, .22);
}
.sq-hero-photo {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  transition: opacity .2s ease;
}
.sq-hero-frame.has-photo .sq-hero-photo { opacity: 1; }
.sq-hero-rank {
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 3;
  min-width: 26px;
  height: 20px;
  padding: 0 6px;
  display: grid;
  place-items: center;
  border-radius: 7px;
  background: linear-gradient(160deg, #3A352B 0%, #1B1C22 100%);
  box-shadow:
    0 0 0 1px rgba(252, 211, 77, .22),
    inset 0 1px 0 rgba(255, 241, 198, .2),
    0 3px 8px -3px rgba(0, 0, 0, .85);
  color: #F0D79A;
  font-size: 9.5px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -.01em;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.sq-hero-rank[data-rank="gold"] {
  background:
    linear-gradient(135deg, rgba(255, 255, 255, .55) 0%, rgba(255, 255, 255, 0) 48%),
    linear-gradient(160deg, #FFE9A8 0%, #F2BE4C 48%, #B7791F 100%);
  color: #3B2400;
  box-shadow:
    0 0 0 1px rgba(252, 211, 77, .34),
    inset 0 1px 0 rgba(255, 255, 255, .8),
    inset 0 -1px 0 rgba(87, 52, 8, .4),
    0 3px 10px -4px rgba(245, 158, 11, .8);
}
.sq-hero-rank[data-rank="silver"] {
  background:
    linear-gradient(135deg, rgba(255, 255, 255, .8) 0%, rgba(255, 255, 255, 0) 48%),
    linear-gradient(160deg, #F8FAFC 0%, #CBD5E1 48%, #8798AB 100%);
  color: #1E293B;
  box-shadow:
    0 0 0 1px rgba(252, 211, 77, .24),
    inset 0 1px 0 rgba(255, 255, 255, .85),
    inset 0 -1px 0 rgba(30, 41, 59, .35),
    0 3px 10px -4px rgba(148, 163, 184, .7);
}
.sq-hero-rank[data-rank="bronze"] {
  background:
    linear-gradient(135deg, rgba(255, 237, 213, .7) 0%, rgba(255, 255, 255, 0) 48%),
    linear-gradient(160deg, #F5CFA6 0%, #E8B48A 46%, #9A4A1B 100%);
  color: #3B1D06;
  box-shadow:
    0 0 0 1px rgba(252, 211, 77, .22),
    inset 0 1px 0 rgba(255, 255, 255, .7),
    inset 0 -1px 0 rgba(59, 29, 6, .4),
    0 3px 10px -4px rgba(217, 119, 6, .7);
}
.sq-banner-id {
  grid-area: id;
  min-width: 0;
  /* The rank medallion owns the card's top-right corner; the identity keeps that slot
     clear instead of letting the badge clip or overlap the channel name. */
  padding-right: 32px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.sq-banner-name {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  min-width: 0;
  overflow: hidden;
  overflow-wrap: anywhere;
  font-size: 15.5px;
  font-weight: 800;
  letter-spacing: -.015em;
  line-height: 1.22;
  color: #FFFFFF;
  text-shadow: 0 0 18px rgba(255, 246, 215, .08);
}
.sq-meta {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  font-size: 12px;
  line-height: 1.2;
  color: #94A3B8;
  white-space: nowrap;
}
.sq-meta-handle {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  font-weight: 700;
  letter-spacing: -.01em;
  color: #94A3B8;
}
.sq-verified {
  flex: none;
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: linear-gradient(160deg, #FFE9A8 0%, #DDAE45 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .65),
    0 0 8px -3px rgba(245, 158, 11, .55);
  color: #2C1D04;
}
.sq-verified .ico { width: 9px; height: 9px; }
.sq-verified[hidden] { display: none; }
.sq-banner-stats {
  grid-area: stats;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  min-width: 0;
}
.sq-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  min-width: 0;
  padding: 7px 4px 6px;
  border-radius: 11px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .06) 0%, rgba(255, 255, 255, .015) 100%);
  box-shadow:
    inset 0 0 0 1px rgba(252, 211, 77, .13),
    inset 0 1px 0 rgba(255, 255, 255, .06);
  text-align: center;
}
.sq-stat-v {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-width: 0;
  max-width: 100%;
}
.sq-stat .ico { flex: none; width: 11px; height: 11px; }
.sq-stat small {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: .09em;
  line-height: 1;
  text-transform: uppercase;
  color: rgba(203, 213, 225, .66);
}
.sq-stat b {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12.5px;
  font-weight: 900;
  line-height: 1;
  color: #FDE9AE;
  font-variant-numeric: tabular-nums;
  direction: ltr;
  unicode-bidi: isolate;
}
.sq-stat-subs .ico { color: rgba(148, 163, 184, .9); }
.sq-stat-mem .ico { color: rgba(252, 211, 77, .78); }
.sq-stat-tiq .ico {
  color: var(--tiq);
  filter: drop-shadow(0 0 4px rgba(252, 211, 77, .45));
}

.sq-scroll {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  touch-action: pan-y;
  -webkit-overflow-scrolling: touch;
  padding-bottom: 26px;
  -webkit-mask-image: linear-gradient(180deg, #000 0, #000 calc(100% - 20px), transparent 100%);
  mask-image: linear-gradient(180deg, #000 0, #000 calc(100% - 20px), transparent 100%);
}
.sq-av-flag {
  position: absolute;
  left: -3px;
  bottom: -3px;
  --fp-d: 16px;
  width: 16px;
  height: 16px;
  border-radius: 5px;
  overflow: hidden;
  box-shadow: 0 0 0 2px #11151C, 0 2px 5px rgba(0, 0, 0, .5);
}
.sq-av-flag .fp-chip {
  border-radius: 5px;
  font-size: 6px;
  box-shadow: none;
}
.sq-av-flag .fp-img {
  border-radius: 4px;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .45);
}

.sq-role {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  height: 15px;
  padding: 0 6px 0 5px;
  border-radius: var(--radius-pill);
  font-size: 7.5px;
  font-weight: 900;
  letter-spacing: .06em;
  line-height: 1;
  text-transform: uppercase;
  white-space: nowrap;
}
.sq-role .ico {
  flex: none;
  width: 9px;
  height: 9px;
}
.sq-role[data-role="leader"] {
  background: linear-gradient(180deg, rgba(245, 158, 11, .26) 0%, rgba(245, 158, 11, .1) 100%);
  box-shadow:
    inset 0 0 0 1px rgba(252, 211, 77, .36),
    inset 0 1px 0 rgba(255, 255, 255, .12);
  color: var(--gold-ink);
}
.sq-role[data-role="leader"] .ico { filter: drop-shadow(0 0 3px rgba(252, 211, 77, .55)); }
.sq-role[data-role="admin"] {
  background: linear-gradient(180deg, rgba(252, 211, 77, .12) 0%, rgba(252, 211, 77, .05) 100%);
  box-shadow:
    inset 0 0 0 1px rgba(252, 211, 77, .22),
    inset 0 1px 0 rgba(255, 255, 255, .08);
  color: #E8D59A;
}
/* The local player's own row says so in a whisper; the cyan rail is gone. */
.sq-you-tag {
  flex: none;
  display: inline-flex;
  align-items: center;
  height: 15px;
  padding: 0 5px;
  border-radius: var(--radius-pill);
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .08em;
  line-height: 1;
  text-transform: uppercase;
  white-space: nowrap;
  color: #E9D9AC;
  background: rgba(252, 211, 77, .08);
  box-shadow: inset 0 0 0 1px rgba(252, 211, 77, .18);
}
.sq-roster-head {
  flex: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0 0 6px;
}
.sq-roster-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}
.sq-roster-title {
  min-width: 0;
  margin: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 9.5px;
  font-weight: 900;
  letter-spacing: .13em;
  line-height: 1.2;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.sq-count {
  flex: none;
  min-width: 34px;
  height: 19px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 8px;
  border-radius: var(--radius-pill);
  background: linear-gradient(180deg, rgba(255, 255, 255, .07) 0%, rgba(255, 255, 255, .02) 100%);
  box-shadow:
    inset 0 0 0 1px rgba(252, 211, 77, .18),
    inset 0 1px 0 rgba(255, 255, 255, .1);
  color: #F5E5B8;
  font-size: 9.5px;
  font-weight: 900;
  letter-spacing: .01em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.sq-tools {
  display: flex;
  align-items: stretch;
  gap: 6px;
  min-width: 0;
}
.sq-tools[hidden] { display: none; }
.sq-search {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  height: 40px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 9px;
  border-radius: 11px;
  background: var(--field);
  box-shadow:
    inset 0 0 0 1px var(--hair-off),
    inset 0 2px 4px rgba(0, 0, 0, .3);
  transition: box-shadow var(--motion-fast);
}
.sq-search::after {
  content: "";
  position: absolute;
  inset: -2px 0;
  border-radius: 13px;
  pointer-events: none;
}
.sq-search:focus-within {
  box-shadow:
    inset 0 0 0 1.5px rgba(252, 211, 77, .46),
    inset 0 2px 4px rgba(0, 0, 0, .3);
}
.sq-search .ico {
  flex: none;
  width: 13px;
  height: 13px;
  color: var(--ink-soft);
}
.sq-search input {
  flex: 1 1 auto;
  min-width: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--ink);
  font-family: inherit;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: .01em;
}
.sq-search input::placeholder { color: var(--ink-soft); opacity: .82; }
.sq-search input::-webkit-search-cancel-button,
.sq-search input::-webkit-search-decoration { appearance: none; -webkit-appearance: none; }

.sq-roster {
  --sq-row-h: 54px;
  --sq-row-gap: 8px;
  --sq-row-pitch: 62px;
  position: relative;
  min-height: var(--sq-row-h);
  margin: 0;
  padding: 0;
  list-style: none;
  border: 0;
  background: transparent;
}
.sq-row {
  position: absolute;
  left: 0;
  right: 0;
  height: var(--sq-row-h);
  display: grid;
  grid-template-columns: 30px 34px minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 9px;
  padding: 0 12px;
  border: 1px solid rgba(255, 238, 190, .05);
  border-top-color: rgba(255, 241, 198, .09);
  border-radius: 14px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .025) 0%, rgba(255, 255, 255, 0) 42%),
    rgba(13, 17, 24, .62);
  box-shadow:
    inset 0 1px 0 rgba(255, 245, 215, .045),
    0 1px 0 rgba(4, 7, 12, .55),
    0 10px 18px -16px rgba(0, 0, 0, .95);
  contain: layout paint;
  transition: background var(--motion-fast), border-color var(--motion-fast);
}
.sq-row:hover { background: rgba(29, 31, 38, .78); border-top-color: rgba(255, 241, 198, .16); }
.sq-row:active { background: rgba(252, 211, 77, .08); }
.sq-row[data-rank="1"] { background: linear-gradient(90deg, rgba(245, 158, 11, .13) 0%, rgba(13, 17, 24, .66) 58%); border-top-color: rgba(252, 211, 77, .26); }
.sq-row[data-rank="2"] { background: linear-gradient(90deg, rgba(226, 232, 240, .09) 0%, rgba(13, 17, 24, .66) 58%); border-top-color: rgba(226, 232, 240, .22); }
.sq-row[data-rank="3"] { background: linear-gradient(90deg, rgba(217, 119, 6, .1) 0%, rgba(13, 17, 24, .66) 58%); border-top-color: rgba(232, 180, 138, .22); }
.sq-row.is-you {
  background: linear-gradient(90deg, rgba(252, 211, 77, .14) 0%, rgba(13, 17, 24, .7) 64%);
  border-color: rgba(252, 211, 77, .22);
  border-top-color: rgba(255, 241, 198, .3);
  box-shadow:
    inset 2px 0 0 rgba(252, 211, 77, .78),
    inset 0 1px 0 rgba(255, 255, 255, .05);
}
.sq-row[data-rank="1"]:hover { background: linear-gradient(90deg, rgba(245, 158, 11, .18) 0%, rgba(29, 31, 38, .78) 58%); }
.sq-row[data-rank="2"]:hover { background: linear-gradient(90deg, rgba(226, 232, 240, .14) 0%, rgba(29, 31, 38, .78) 58%); }
.sq-row[data-rank="3"]:hover { background: linear-gradient(90deg, rgba(217, 119, 6, .16) 0%, rgba(29, 31, 38, .78) 58%); }
.sq-row.is-you:hover { background: linear-gradient(90deg, rgba(252, 211, 77, .2) 0%, rgba(29, 31, 38, .78) 64%); }
.sq-rank {
  width: 30px;
  height: 28px;
  display: grid;
  place-items: center;
  justify-self: start;
  color: #64748B;
  font-family: var(--ml-mono, ui-monospace, Menlo, Consolas, monospace);
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: -.02em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.sq-rank.is-wide {
  font-size: 8.5px;
  letter-spacing: -.04em;
}
/* Rows borrow the discovery cards' metal, but only the podium gets a filled key —
   1,200 chips would turn a list into a wall. Scoped so the card rank stays intact. */
.sq-row .sq-rank {
  height: 26px;
  border-radius: 8px;
  background: rgba(255, 238, 190, .04);
  box-shadow: inset 0 0 0 1px rgba(255, 238, 190, .06);
  color: #8B8065;
  font-size: 9.5px;
  font-weight: 900;
}
.sq-row .sq-rank.is-wide {
  font-size: 8.5px;
  letter-spacing: -.045em;
}
.sq-row[data-rank="1"] .sq-rank {
  background:
    linear-gradient(135deg, rgba(255, 255, 255, .62) 0%, rgba(255, 255, 255, 0) 48%),
    linear-gradient(160deg, #FFE9A8 0%, #F2BE4C 48%, #B7791F 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .8),
    inset 0 -1px 0 rgba(87, 52, 8, .4),
    0 2px 8px -5px rgba(245, 158, 11, .8);
  color: #3B2400;
  text-shadow: none;
}
.sq-row[data-rank="2"] .sq-rank {
  background:
    linear-gradient(135deg, rgba(255, 255, 255, .8) 0%, rgba(255, 255, 255, 0) 48%),
    linear-gradient(160deg, #F8FAFC 0%, #CBD5E1 48%, #8798AB 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .85),
    inset 0 -1px 0 rgba(30, 41, 59, .35),
    0 2px 8px -5px rgba(148, 163, 184, .7);
  color: #1E293B;
  text-shadow: none;
}
.sq-row[data-rank="3"] .sq-rank {
  background:
    linear-gradient(135deg, rgba(255, 237, 213, .7) 0%, rgba(255, 255, 255, 0) 48%),
    linear-gradient(160deg, #F5CFA6 0%, #E8B48A 46%, #9A4A1B 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .7),
    inset 0 -1px 0 rgba(59, 29, 6, .4),
    0 2px 8px -5px rgba(217, 119, 6, .7);
  color: #3B1D06;
  text-shadow: none;
}
.sq-avwrap {
  position: relative;
  flex: none;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
}
.sq-av {
  position: relative;
  isolation: isolate;
  flex: none;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  overflow: hidden;
  border: 1px solid rgba(255, 238, 190, .08);
  border-radius: 10px;
  background:
    radial-gradient(120% 120% at 28% 10%, rgba(252, 211, 77, .14) 0%, rgba(252, 211, 77, 0) 58%),
    linear-gradient(180deg, #2A2B31 0%, #11151C 100%);
  box-shadow:
    inset 0 0 0 1px rgba(252, 211, 77, .16),
    inset 0 1px 1px rgba(255, 255, 255, .1);
  color: #F1DFAD;
  font-size: 9.5px;
  font-weight: 900;
  letter-spacing: .01em;
  line-height: 1;
}
.sq-av-photo {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  transition: opacity .18s ease;
}
.sq-av.has-photo .sq-av-photo { opacity: 1; }
html.reduced-motion .sq-av-photo { transition: none; }
.sq-row[data-rank="1"] .sq-av { box-shadow: inset 0 0 0 1px rgba(252, 211, 77, .34), inset 0 1px 1px rgba(255, 255, 255, .14); }
.sq-row[data-rank="2"] .sq-av { box-shadow: inset 0 0 0 1px rgba(203, 213, 225, .3), inset 0 1px 1px rgba(255, 255, 255, .14); }
.sq-row[data-rank="3"] .sq-av { box-shadow: inset 0 0 0 1px rgba(217, 119, 6, .34), inset 0 1px 1px rgba(255, 255, 255, .14); }
.sq-medal {
  right: -3px;
  bottom: -3px;
  width: 16px;
  height: 16px;
}
.sq-medal .medal-coin,
.sq-medal .medal-coin.badge-crest-art {
  width: 13px;
  height: 13px;
}
.sq-id {
  min-width: 0;
  display: flex;
  align-items: center;
}
.sq-name-line {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  max-width: 100%;
}
.sq-name {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: -.01em;
  line-height: 1.15;
  color: #FFFFFF;
}
.sq-row-right {
  justify-self: end;
  display: flex;
  align-items: center;
  min-width: 0;
}
.sq-score {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  color: var(--tiq);
  font-size: 13.5px;
  font-weight: 900;
  letter-spacing: -.015em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  text-shadow: 0 0 12px rgba(252, 211, 77, .3);
}
.sq-score .ico {
  align-self: center;
  width: 11px;
  height: 11px;
  opacity: .95;
  filter: drop-shadow(0 0 4px rgba(252, 211, 77, .45));
}
.sq-score b {
  font-size: inherit;
  font-weight: inherit;
  line-height: inherit;
}
.sq-score small {
  align-self: center;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .08em;
  color: rgba(252, 211, 77, .62);
}
.sq-score.is-zero { color: var(--ink-soft); text-shadow: none; }
.sq-score.is-zero .ico { opacity: .5; }
.sq-score.is-zero small { color: var(--ink-soft); }

/* The leader's per-row remove key. It rides the score column, so a member row keeps the same
   grid whether or not an admin is looking at it. */
.sq-kick {
  flex: none;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  margin-inline-start: 6px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: rgba(248, 113, 113, .1);
  box-shadow: inset 0 0 0 1px rgba(248, 113, 113, .26);
  color: #FCA5A5;
  cursor: pointer;
  transition: background .16s ease, color .16s ease, transform .16s ease;
}
.sq-kick .ico { width: 11px; height: 11px; }
.sq-kick:hover { background: rgba(248, 113, 113, .2); color: #FECACA; }
.sq-kick:active { transform: scale(.92); }
.sq-kick:focus-visible { outline: 2px solid #FCA5A5; outline-offset: 2px; }
.sq-kick.is-busy { opacity: .45; pointer-events: none; }

/* One invite row: the gold Telegram key and a compact glass copy pill. */
.sq-invite {
  flex: none;
  /* The hub's 8px flex gap plus this margin puts the action row 12px under the hero. */
  margin-top: 4px;
  display: flex;
  align-items: stretch;
  gap: 8px;
  min-width: 0;
}
.sq-invite[hidden] { display: none !important; }
.sq-invite-share {
  flex: 1 1 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 0;
  height: 42px;
  padding: 0 14px;
  border: 0;
  border-radius: 12px;
  cursor: pointer;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .42) 0%, rgba(255, 255, 255, 0) 46%),
    linear-gradient(160deg, #FFE8A3 0%, #F2C14E 48%, #C58A1D 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .75),
    inset 0 -1px 0 rgba(87, 52, 8, .5),
    0 7px 16px -10px rgba(0, 0, 0, .9),
    0 0 20px -12px rgba(252, 211, 77, .65);
  color: #2A1B02;
  font-family: inherit;
  font-size: 10.5px;
  font-weight: 900;
  letter-spacing: .03em;
  line-height: 1;
  white-space: nowrap;
  transition: filter .16s ease, transform .12s ease;
}
.sq-invite-share .ico { flex: none; width: 15px; height: 15px; }
.sq-invite-share:hover { filter: brightness(1.04); }
.sq-invite-share:active { transform: translateY(1px); filter: brightness(.98); }
.sq-invite-share:focus-visible { outline: 2px solid #FCD34D; outline-offset: 2px; }
.sq-invite-copy {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  height: 42px;
  padding: 0 12px;
  border: 0;
  border-radius: 12px;
  cursor: pointer;
  background: rgba(255, 255, 255, .035);
  box-shadow:
    inset 0 0 0 1px rgba(252, 211, 77, .18),
    inset 0 1px 0 rgba(255, 255, 255, .06);
  color: #E8D59A;
  font-family: inherit;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: .01em;
  line-height: 1;
  white-space: nowrap;
  transition: background .16s ease, color .16s ease, transform .12s ease;
}
.sq-invite-copy .ico { flex: none; width: 13px; height: 13px; color: rgba(252, 211, 77, .8); }
.sq-invite-copy-t {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.sq-invite-copy:hover { background: rgba(252, 211, 77, .09); color: #FEF3C7; }
.sq-invite-copy:active { transform: translateY(1px); }
.sq-invite-copy:focus-visible { outline: 2px solid #FCD34D; outline-offset: 2px; }
.sq-invite-copy.is-copied {
  background: rgba(52, 211, 153, .14);
  box-shadow: inset 0 0 0 1px rgba(52, 211, 153, .35);
  color: #A7F3D0;
}
.sq-invite-copy.is-copied .ico { color: #A7F3D0; }
.sq-invite-share[aria-disabled="true"],
.sq-invite-copy[aria-disabled="true"] { opacity: .45; pointer-events: none; }

.sq-roster-empty {
  margin: 2px 0 0;
  padding: 20px 12px;
  border-radius: 14px;
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair);
  text-align: center;
  font-size: 11px;
  font-weight: 700;
  color: var(--ink-soft);
}

.sq-foot {
  position: relative;
  flex: none;
  display: flex;
  justify-content: center;
  padding-top: 2px;
}
.sq-foot::before {
  content: "";
  position: absolute;
  left: 8%;
  right: 8%;
  top: -4px;
  height: 1px;
  background: linear-gradient(90deg, transparent 0%, rgba(252, 211, 77, .1) 50%, transparent 100%);
}
.sq-leave {
  position: relative;
  width: auto;
  min-width: 150px;
  max-width: 100%;
  height: 34px;
  margin: 0 auto;
  padding: 0 18px;
  border: 1px solid rgba(248, 113, 113, .16);
  border-radius: 999px;
  background: transparent;
  color: rgba(252, 165, 165, .62);
  font-family: inherit;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
  cursor: pointer;
  white-space: nowrap;
  transition:
    color var(--motion-fast),
    background var(--motion-fast),
    border-color var(--motion-fast),
    transform var(--motion-fast),
    box-shadow var(--motion-fast);
}
.sq-leave::after {
  content: "";
  position: absolute;
  inset: -6px 0;
}
.sq-leave:hover {
  color: #FCA5A5;
  background: rgba(239, 68, 68, .055);
  border-color: rgba(248, 113, 113, .28);
}
.sq-leave:active {
  color: #FFFFFF;
  background: #B91C1C;
  border-color: #EF4444;
  box-shadow: 0 0 18px -8px rgba(239, 68, 68, .75);
  transform: translateY(1px);
}
.sq-leave:focus-visible {
  outline: 2px solid rgba(248, 113, 113, .65);
  outline-offset: 2px;
}
.sq-leave.is-armed {
  color: #FFFFFF;
  background: rgba(185, 28, 28, .92);
  border-color: rgba(248, 113, 113, .7);
  box-shadow: 0 0 18px -8px rgba(239, 68, 68, .8);
}

@media (max-width: 360px) {
  .sq-banner { grid-template-columns: 50px minmax(0, 1fr); padding: 10px; column-gap: 9px; row-gap: 9px; }
  .sq-hero-av { width: 50px; height: 50px; }
  .sq-hero-frame { border-radius: 14px; }
  .sq-hero-mark { font-size: 19px; }
  .sq-hero-rank { top: 9px; right: 9px; min-width: 24px; height: 19px; padding: 0 5px; font-size: 9px; }
  .sq-banner-id { padding-right: 32px; }
  .sq-banner-name { font-size: 15px; }
  .sq-meta { font-size: 11.5px; }
  .sq-stat { padding: 6px 3px 5px; }
  .sq-stat small { font-size: 6px; letter-spacing: .07em; }
  .sq-stat b { font-size: 12px; }
  .sq-stat .ico { width: 10px; height: 10px; }
  .sq-name-line { gap: 5px; }
  .sq-row { column-gap: 7px; padding: 0 10px; }
  .sq-invite-share { height: 40px; padding: 0 10px; gap: 6px; font-size: 10px; }
  .sq-invite-copy { height: 40px; padding: 0 10px; font-size: 9px; }
  .sq-leave { font-size: 8px; letter-spacing: .1em; }
}

@media (max-width: 340px) {
  .sq-banner { grid-template-columns: 48px minmax(0, 1fr); padding: 9px; column-gap: 8px; row-gap: 9px; }
  .sq-hero-av { width: 48px; height: 48px; }
  .sq-hero-frame { border-radius: 13px; }
  .sq-hero-mark { font-size: 18px; }
  .sq-hero-rank { top: 8px; right: 8px; min-width: 23px; height: 18px; padding: 0 5px; font-size: 8.5px; }
  .sq-banner-id { gap: 3px; padding-right: 30px; }
  .sq-banner-name { font-size: 14.5px; line-height: 1.2; }
  .sq-meta { font-size: 11px; gap: 4px; }
  .sq-verified { width: 13px; height: 13px; }
  .sq-stat { padding: 6px 2px 5px; }
  .sq-stat small { font-size: 5.8px; letter-spacing: .05em; }
  .sq-stat b { font-size: 11.5px; }
  .sq-stat .ico { width: 9px; height: 9px; }
  .sq-banner-stats { gap: 5px; }
  .sq-name-line { gap: 4px; }
  .sq-row { grid-template-columns: 26px 32px minmax(0, 1fr) auto; column-gap: 6px; padding: 0 8px; }
  .sq-rank { width: 26px; }
  .sq-avwrap, .sq-av { width: 30px; height: 30px; }
  .sq-av-flag { --fp-d: 14px; width: 14px; height: 14px; }
  .sq-name { font-size: 12px; }
  .sq-role { font-size: 7px; padding: 0 5px 0 4px; }
  .sq-you-tag { padding: 0 4px; font-size: 6.5px; }
  .sq-score { font-size: 13px; }
  .sq-invite { gap: 6px; }
  .sq-invite-share { padding: 0 9px; font-size: 9.5px; }
  .sq-invite-copy { width: 40px; padding: 0; }
  .sq-invite-copy-t { display: none; }
}

/* ==========================================================================
   SQUAD LEADER ADMIN — join-approval lock, segmented roster/requests tabs,
   pending applicant rows and the in-modal broadcast composer.
   Opaque obsidian slabs with gold hairlines; every flex/grid child carries
   min-width:0 so a 320px shell can never be pushed sideways.
   ========================================================================== */
#sheet-squad { overflow-x: clip; }

.sq-admin {
  flex: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  max-width: 100%;
}
.sq-admin[hidden],
.sq-tabs[hidden],
.sq-roster-title-row[hidden],
.sq-roster[hidden],
.sq-roster-empty[hidden],
.sq-requests[hidden],
.sq-requests-empty[hidden],
.sq-tab-badge[hidden],
.sq-cast[hidden] { display: none !important; }

/* ---- the lock: one obsidian setting row, one switch ---- */
.sq-lock-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  max-width: 100%;
  min-height: 42px;
  padding: 6px 9px;
  border: 1px solid rgba(252, 211, 77, .15);
  border-radius: 13px;
  background:
    radial-gradient(120% 180% at 0% 0%, rgba(252, 211, 77, .055) 0%, rgba(252, 211, 77, 0) 62%),
    linear-gradient(165deg, rgba(28, 32, 42, .98) 0%, rgba(9, 12, 19, .99) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 244, 205, .07),
    inset 0 -1px 0 rgba(0, 0, 0, .6),
    0 10px 24px -22px rgba(0, 0, 0, .95);
}
.sq-lock-glyph {
  flex: none;
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 9px;
  background: rgba(252, 211, 77, .08);
  box-shadow: inset 0 0 0 1px rgba(252, 211, 77, .2);
  font-size: 12px;
  line-height: 1;
}
.sq-lock-copy {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.sq-lock-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 10.5px;
  font-weight: 900;
  letter-spacing: .02em;
  line-height: 1.2;
  color: #F5E5B8;
}
.sq-lock-sub {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 8.5px;
  font-weight: 600;
  line-height: 1.3;
  color: var(--text-dim);
}
.sq-switch {
  position: relative;
  flex: none;
  width: 42px;
  height: 24px;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, .1);
  border-radius: var(--radius-pill);
  background: linear-gradient(180deg, #141A25 0%, #0A0E16 100%);
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, .75),
    inset 0 0 0 1px rgba(0, 0, 0, .5);
  cursor: pointer;
  transition: background var(--motion-fast), border-color var(--motion-fast), box-shadow var(--motion-fast);
}
.sq-switch-knob {
  position: absolute;
  inset-block-start: 2px;
  inset-inline-start: 2px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: linear-gradient(180deg, #94A3B8 0%, #64748B 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .45),
    0 2px 5px rgba(0, 0, 0, .7);
  transition: inset-inline-start .2s ease, background .2s ease, box-shadow .2s ease;
}
.sq-switch[aria-checked="true"] {
  border-color: rgba(252, 211, 77, .48);
  background: linear-gradient(180deg, rgba(180, 124, 20, .7) 0%, rgba(96, 63, 6, .8) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 232, 160, .28),
    0 0 14px -6px rgba(252, 211, 77, .7);
}
.sq-switch[aria-checked="true"] .sq-switch-knob {
  inset-inline-start: 20px;
  background: linear-gradient(180deg, #FFF1C2 0%, #F2C14E 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .85),
    0 0 10px -2px rgba(252, 211, 77, .65);
}
.sq-switch:hover { border-color: rgba(252, 211, 77, .4); }
.sq-switch:focus-visible { outline: 2px solid #FCD34D; outline-offset: 2px; }
.sq-switch[aria-busy="true"] { opacity: .55; pointer-events: none; }

/* ---- the broadcast key: obsidian slate, gold rim, a restrained glow ---- */
.sq-broadcast-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
  max-width: 100%;
  height: 38px;
  padding: 0 12px;
  border: 1px solid rgba(252, 211, 77, .38);
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .05) 0%, rgba(255, 255, 255, 0) 55%),
    linear-gradient(165deg, rgba(33, 37, 48, .98) 0%, rgba(12, 15, 23, .99) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 244, 205, .1),
    inset 0 -1px 0 rgba(0, 0, 0, .6),
    0 0 20px -12px rgba(252, 211, 77, .75);
  color: #F5E5B8;
  font-family: inherit;
  font-size: 10.5px;
  font-weight: 900;
  letter-spacing: .02em;
  line-height: 1;
  cursor: pointer;
  transition: background var(--motion-fast), box-shadow var(--motion-fast), transform .12s ease;
}
.sq-broadcast-t {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: start;
}
.sq-broadcast-btn .ico { flex: none; width: 13px; height: 13px; color: rgba(252, 211, 77, .8); }
.sq-broadcast-btn:hover {
  background: linear-gradient(165deg, rgba(45, 42, 40, .99) 0%, rgba(17, 18, 24, .99) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 244, 205, .16),
    0 0 24px -10px rgba(252, 211, 77, .85);
}
.sq-broadcast-btn:active { transform: translateY(1px); }
.sq-broadcast-btn:focus-visible { outline: 2px solid #FCD34D; outline-offset: 2px; }
.sq-broadcast-btn[aria-disabled="true"] { opacity: .5; pointer-events: none; }

/* ---- segmented tabs: leaders only, a notification badge when N > 0 ---- */
.sq-tabs {
  display: flex;
  align-items: stretch;
  gap: 4px;
  min-width: 0;
  max-width: 100%;
  padding: 3px;
  border: 1px solid rgba(255, 255, 255, .07);
  border-radius: 12px;
  background: linear-gradient(180deg, rgba(15, 19, 28, .95) 0%, rgba(8, 11, 17, .98) 100%);
  box-shadow: inset 0 2px 5px rgba(0, 0, 0, .6);
}
.sq-tab {
  flex: 1 1 0;
  min-width: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  height: 30px;
  padding: 0 6px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: var(--ink-soft);
  font-family: inherit;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .07em;
  line-height: 1;
  text-transform: uppercase;
  white-space: nowrap;
  cursor: pointer;
  transition: background var(--motion-fast), color var(--motion-fast), box-shadow var(--motion-fast);
}
.sq-tab-t { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sq-tab-n {
  flex: none;
  min-width: 18px;
  height: 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 4px;
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, .07);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .1);
  color: #D7C79C;
  font-size: 8.5px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  direction: ltr;
  unicode-bidi: isolate;
}
.sq-tab.is-active {
  background:
    linear-gradient(180deg, rgba(252, 211, 77, .2) 0%, rgba(252, 211, 77, .07) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 244, 205, .18),
    inset 0 0 0 1px rgba(252, 211, 77, .36);
  color: #FDE9AE;
}
.sq-tab:focus-visible { outline: 2px solid #FCD34D; outline-offset: 1px; }
.sq-tab-badge {
  background: linear-gradient(180deg, rgba(248, 113, 113, .95) 0%, rgba(153, 27, 27, .95) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 220, 220, .4),
    0 0 10px -3px rgba(239, 68, 68, .85);
  color: #FFF5F5;
}
.sq-tab:not(.is-active) .sq-tab-badge { box-shadow: 0 0 12px -3px rgba(245, 158, 11, .85); }

/* ---- pending applicants: one row, face + name + TIQ + two decisions ---- */
.sq-requests {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}
.sq-req {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  max-width: 100%;
  padding: 8px;
  border: 1px solid rgba(255, 255, 255, .07);
  border-radius: 14px;
  background: linear-gradient(165deg, rgba(28, 32, 42, .96) 0%, rgba(10, 13, 20, .98) 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .05), 0 8px 20px -18px rgba(0, 0, 0, .95);
}
.sq-req-av {
  position: relative;
  flex: none;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: 11px;
  background: linear-gradient(150deg, rgba(252, 211, 77, .22) 0%, rgba(252, 211, 77, .04) 100%);
  box-shadow: inset 0 0 0 1px rgba(252, 211, 77, .25);
  color: #FDE9AE;
  font-size: 11px;
  font-weight: 900;
  line-height: 1;
}
.sq-req-av img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.sq-req-id {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.sq-req-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11px;
  font-weight: 800;
  line-height: 1.2;
  color: var(--ink);
}
.sq-req-tiq {
  min-width: 0;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .04em;
  line-height: 1.2;
  color: var(--text-dim);
  font-variant-numeric: tabular-nums;
}
.sq-req-actions { flex: none; display: flex; align-items: center; gap: 6px; }
.sq-req-btn {
  flex: none;
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  padding: 0;
  border-radius: 10px;
  background: rgba(255, 255, 255, .04);
  font-family: inherit;
  font-size: 14px;
  font-weight: 900;
  line-height: 1;
  cursor: pointer;
  transition: background var(--motion-fast), transform .12s ease, box-shadow var(--motion-fast);
}
.sq-req-btn.yes {
  border: 1px solid rgba(52, 211, 153, .42);
  box-shadow: inset 0 1px 0 rgba(167, 243, 208, .14), 0 0 12px -7px rgba(16, 185, 129, .9);
  color: #6EE7B7;
}
.sq-req-btn.no {
  border: 1px solid rgba(248, 113, 113, .4);
  box-shadow: inset 0 1px 0 rgba(254, 202, 202, .12), 0 0 12px -7px rgba(239, 68, 68, .9);
  color: #FCA5A5;
}
.sq-req-btn.yes:hover { background: rgba(16, 185, 129, .18); }
.sq-req-btn.no:hover { background: rgba(239, 68, 68, .18); }
.sq-req-btn:active { transform: scale(.9); }
.sq-req-btn:focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
.sq-req-btn[aria-disabled="true"] { opacity: .45; pointer-events: none; }
.sq-requests-empty {
  margin: 0;
  padding: 22px 12px;
  border-radius: 14px;
  background: var(--field);
  box-shadow: var(--inset), inset 0 0 0 1px var(--hair);
  text-align: center;
  font-size: 10.5px;
  font-weight: 700;
  color: var(--ink-soft);
}

/* ---- the composer: a drawer inside the sheet, never a second sheet ---- */
.sq-cast {
  position: absolute;
  inset: 0;
  z-index: 6;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  min-width: 0;
  max-width: 100%;
}
.sq-cast-scrim {
  position: absolute;
  inset: 0;
  background: rgba(4, 6, 10, .78);
}
.sq-cast-panel {
  position: relative;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px 14px calc(14px + env(safe-area-inset-bottom));
  border: 1px solid rgba(252, 211, 77, .22);
  border-bottom: 0;
  border-radius: 20px 20px 0 0;
  background:
    radial-gradient(120% 90% at 0% 0%, rgba(252, 211, 77, .07) 0%, rgba(252, 211, 77, 0) 62%),
    linear-gradient(180deg, #1B202B 0%, #090C13 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 244, 205, .12),
    0 -18px 46px -28px rgba(0, 0, 0, .98),
    0 -14px 34px -26px rgba(252, 211, 77, .5);
  animation: sq-cast-in .2s ease both;
}
@keyframes sq-cast-in {
  from { opacity: 0; transform: translate3d(0, 14px, 0); }
  to { opacity: 1; transform: none; }
}
html.reduced-motion .sq-cast-panel { animation: none; }
.sq-cast-top { display: flex; align-items: flex-start; gap: 8px; min-width: 0; }
.sq-cast-head { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.sq-cast-title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 13px;
  font-weight: 900;
  letter-spacing: .01em;
  line-height: 1.2;
  color: #FDE9AE;
}
.sq-cast-sub {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 9px;
  font-weight: 600;
  line-height: 1.3;
  color: var(--text-dim);
}
.sq-cast-x {
  flex: none;
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, .1);
  border-radius: 50%;
  background: rgba(255, 255, 255, .04);
  color: var(--ink-soft);
  font-family: inherit;
  font-size: 17px;
  line-height: 1;
  cursor: pointer;
}
.sq-cast-x:hover { color: var(--ink); background: rgba(255, 255, 255, .1); }
.sq-cast-x:focus-visible { outline: 2px solid #FCD34D; outline-offset: 2px; }
.sq-cast-field { position: relative; display: block; min-width: 0; max-width: 100%; }
.sq-cast-field textarea {
  display: block;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  height: 92px;
  margin: 0;
  padding: 10px 10px 25px;
  border: 1px solid rgba(255, 255, 255, .09);
  border-radius: 12px;
  outline: none;
  resize: none;
  background: var(--field);
  box-shadow: inset 0 2px 5px rgba(0, 0, 0, .55);
  color: var(--ink);
  font-family: inherit;
  font-size: 11.5px;
  font-weight: 600;
  line-height: 1.55;
  transition: border-color var(--motion-fast), box-shadow var(--motion-fast);
}
.sq-cast-field textarea::placeholder { color: var(--text-dim); }
.sq-cast-field textarea:focus {
  border-color: rgba(252, 211, 77, .5);
  box-shadow: inset 0 2px 5px rgba(0, 0, 0, .55), 0 0 14px -8px rgba(252, 211, 77, .8);
}
.sq-cast-count {
  position: absolute;
  inset-inline-end: 10px;
  bottom: 8px;
  font-size: 8.5px;
  font-weight: 800;
  color: var(--text-dim);
  font-variant-numeric: tabular-nums;
  direction: ltr;
  unicode-bidi: isolate;
  pointer-events: none;
}
.sq-cast-note {
  margin: 0;
  min-width: 0;
  font-size: 8.5px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--text-dim);
}
.sq-cast-actions { display: flex; gap: 8px; min-width: 0; }
.sq-cast-actions button {
  flex: 1 1 0;
  min-width: 0;
  height: 40px;
  padding: 0 8px;
  border-radius: 11px;
  font-family: inherit;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .03em;
  line-height: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: pointer;
  transition: filter var(--motion-fast), transform .12s ease;
}
.sq-cast-cancel {
  border: 1px solid rgba(255, 255, 255, .12);
  background: rgba(255, 255, 255, .04);
  color: var(--ink-soft);
}
.sq-cast-cancel:hover { color: var(--ink); background: rgba(255, 255, 255, .09); }
.sq-cast-send {
  border: 1px solid rgba(255, 232, 160, .55);
  background: linear-gradient(180deg, #FFE8A3 0%, #F2C14E 48%, #C58A1D 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .7), 0 0 20px -12px rgba(252, 211, 77, .85);
  color: #2A1B02;
}
.sq-cast-send:hover { filter: brightness(1.05); }
.sq-cast-actions button:active { transform: translateY(1px); }
.sq-cast-actions button:focus-visible { outline: 2px solid #FCD34D; outline-offset: 2px; }
.sq-cast-send[aria-busy="true"] { opacity: .6; pointer-events: none; }

/* ---- RTL: joined script needs no tracking, and logical insets flip the chrome ---- */
html[data-lang="fa"] :is(.sq-lock-row, .sq-tabs, .sq-req, .sq-broadcast-btn, .sq-cast-top, .sq-cast-actions, .sq-cast-panel, .sq-cast-field, .sq-requests-empty),
html[data-lang="ar"] :is(.sq-lock-row, .sq-tabs, .sq-req, .sq-broadcast-btn, .sq-cast-top, .sq-cast-actions, .sq-cast-panel, .sq-cast-field, .sq-requests-empty) { direction: rtl; }
html[data-lang="fa"] :is(.sq-lock-label, .sq-lock-sub, .sq-broadcast-t, .sq-tab, .sq-tab-t, .sq-cast-title, .sq-cast-sub, .sq-cast-note, .sq-req-name, .sq-req-tiq, .sq-cast-actions button, .sq-requests-empty),
html[data-lang="ar"] :is(.sq-lock-label, .sq-lock-sub, .sq-broadcast-t, .sq-tab, .sq-tab-t, .sq-cast-title, .sq-cast-sub, .sq-cast-note, .sq-req-name, .sq-req-tiq, .sq-cast-actions button, .sq-requests-empty) {
  letter-spacing: 0;
  text-transform: none;
}
html[data-lang="fa"] .sq-broadcast-btn .ico,
html[data-lang="ar"] .sq-broadcast-btn .ico { transform: scaleX(-1); }

@media (max-width: 360px) {
  .sq-admin { gap: 5px; }
  .sq-lock-row { min-height: 38px; padding: 5px 8px; gap: 6px; }
  .sq-lock-glyph { width: 23px; height: 23px; font-size: 11px; }
  .sq-lock-sub { display: none; }
  .sq-lock-label { font-size: 10px; }
  .sq-broadcast-btn { height: 36px; padding: 0 10px; font-size: 10px; }
  .sq-tab { font-size: 8.5px; gap: 4px; height: 28px; padding: 0 4px; }
  .sq-req { gap: 6px; padding: 7px; }
  .sq-req-av { width: 30px; height: 30px; }
  .sq-req-btn { width: 28px; height: 28px; }
  .sq-cast-panel { gap: 8px; padding: 12px; }
  .sq-cast-field textarea { height: 84px; }
}
@media (max-width: 340px) {
  .sq-switch { width: 38px; height: 22px; }
  .sq-switch-knob { width: 16px; height: 16px; inset-block-start: 2px; }
  .sq-switch[aria-checked="true"] .sq-switch-knob { inset-inline-start: 18px; }
  .sq-lock-row { padding: 5px 7px; }
  .sq-broadcast-btn { padding: 0 9px; }
  .sq-broadcast-btn .ico { display: none; }
  .sq-tab-t { font-size: 8px; }
  .sq-tab-n { min-width: 16px; padding: 0 3px; font-size: 8px; }
  .sq-cast-actions button { font-size: 9.5px; padding: 0 5px; }
}

.sq-scroll:focus { outline: none; }
.sq-scroll:focus-visible {
  outline: 3px solid rgba(252, 211, 77, .7);
  outline-offset: -2px;
  border-radius: 14px;
}

/* ==========================================================================
   NATION PRESTIGE ROSTER — the Nations IQ drill-down (2026-10-21).
   Every country row and podium pillar opens #sheet-nation-detail: a frosted
   Dark-Clay panel whose minted flag medallion takes its aura from the standing
   (#1 gold, #2 silver, #3 bronze, the rest cobalt), then lists that nation's
   top players. The list is sliced to the same 20-50 head-count the row prints,
   so the sheet can never promise more players than the ladder named.
   ========================================================================== */

/* ---- the sheet: 20px corners, one razor rim, frosted over the scrim ---- */
.sheet.nation-sheet {
  --nd-aura: rgba(56, 189, 248, .44);
  --nd-glow: rgba(14, 165, 233, .3);
  --nd-ring: rgba(56, 189, 248, .62);
  --nd-metal-hi: #E0F2FE;
  --nd-metal: #38BDF8;
  --nd-metal-lo: #0369A1;
  --nd-deep: #082F49;
  gap: var(--s2);
  max-height: 85vh;
  max-height: 85dvh;
  padding-top: var(--s3);
  border: 1px solid rgba(255, 255, 255, .08);
  border-bottom: 0;
  border-radius: 20px 20px 0 0;
  background: rgba(13, 19, 31, .95);
  -webkit-backdrop-filter: blur(16px) saturate(1.05);
  backdrop-filter: blur(16px) saturate(1.05);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .12),
    0 -24px 54px -22px rgba(0, 0, 0, .9);
  overflow: hidden;
}
.nation-sheet[data-aura="gold"] {
  --nd-aura: rgba(245, 158, 11, .48);
  --nd-glow: rgba(245, 158, 11, .32);
  --nd-ring: rgba(251, 191, 36, .72);
  --nd-metal-hi: #FEF3C7;
  --nd-metal: #FBBF24;
  --nd-metal-lo: #B45309;
  --nd-deep: #3B1D06;
}
.nation-sheet[data-aura="silver"] {
  --nd-aura: rgba(203, 213, 225, .36);
  --nd-glow: rgba(148, 163, 184, .28);
  --nd-ring: rgba(226, 232, 240, .66);
  --nd-metal-hi: #F8FAFC;
  --nd-metal: #CBD5E1;
  --nd-metal-lo: #64748B;
  --nd-deep: #1E293B;
}
.nation-sheet[data-aura="bronze"] {
  --nd-aura: rgba(217, 119, 6, .42);
  --nd-glow: rgba(217, 119, 6, .3);
  --nd-ring: rgba(253, 186, 116, .64);
  --nd-metal-hi: #FFEDD5;
  --nd-metal: #FDBA74;
  --nd-metal-lo: #C2410C;
  --nd-deep: #431407;
}

/* ---- fixed header: rank key, identity, 48px dismiss ---- */
.nd-head {
  flex: none;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  touch-action: none;            /* the header is the swipe-down handle */
  cursor: grab;
}
.nd-rank {
  flex: none;
  display: grid;
  place-items: center;
  min-width: 42px;
  height: 34px;
  padding: 0 7px;
  border: 1px solid var(--nd-ring);
  border-radius: 10px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .16) 0%, rgba(255, 255, 255, 0) 52%),
    linear-gradient(180deg, #222E44 0%, var(--nd-deep) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .3),
    0 2px 0 rgba(5, 9, 15, .9),
    0 0 18px -7px var(--nd-aura);
  color: var(--nd-metal-hi);
  font-size: 13px;
  font-weight: 900;
  letter-spacing: -.02em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .55);
}
.nd-head-id {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.nd-title {
  margin: 0;
  font-size: 18px;
  font-weight: 900;
  letter-spacing: -.015em;
  line-height: 1.15;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.nd-kicker {
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .14em;
  text-transform: uppercase;
  line-height: 1.2;
  color: var(--nd-metal-hi);
  text-shadow: 0 0 10px var(--nd-aura);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.nd-x { margin-left: auto; }

/* ---- scrolling body ---- */
.sheet-body.nd-body { gap: 14px; padding-right: 2px; }

/* ---- hero: a flag minted inside a bevelled ring, floating on a glass rim ---- */
.nd-hero {
  position: relative;
  flex: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 4px 0 2px;
}
.nd-aura {
  position: absolute;
  top: -10px;
  left: 50%;
  width: 230px;
  height: 158px;
  border-radius: 50%;
  background: radial-gradient(closest-side at 50% 46%, var(--nd-glow) 0%, rgba(0, 0, 0, 0) 74%);
  filter: blur(10px);
  transform: translateX(-50%);
  animation: nd-breathe 5.2s ease-in-out infinite;
  pointer-events: none;
}
.nd-mark {
  position: relative;
  display: grid;
  place-items: center;
  width: 118px;
  height: 118px;
  animation: nd-float 6.4s ease-in-out infinite alternate;
}
.nd-coin {
  position: relative;
  width: 100%;
  height: 100%;
  padding: 8px;
  border-radius: 50%;
  background:
    radial-gradient(58% 58% at 32% 24%, rgba(255, 255, 255, .55) 0%, rgba(255, 255, 255, 0) 54%),
    conic-gradient(from 205deg,
      var(--nd-deep) 0deg,
      var(--nd-metal-lo) 26deg,
      var(--nd-metal) 74deg,
      var(--nd-metal-hi) 112deg,
      var(--nd-metal) 150deg,
      var(--nd-metal-lo) 196deg,
      var(--nd-deep) 232deg,
      var(--nd-metal-lo) 274deg,
      var(--nd-metal-hi) 314deg,
      var(--nd-metal) 344deg,
      var(--nd-deep) 360deg);
  box-shadow:
    0 7px 0 var(--nd-deep),
    0 16px 28px -10px rgba(0, 0, 0, .82),
    0 0 32px -2px var(--nd-aura),
    inset 0 1px 1px rgba(255, 255, 255, .55),
    inset 0 -2px 3px rgba(0, 0, 0, .5),
    0 0 0 1px rgba(0, 0, 0, .55);
}
/* the recessed groove between the metal ring and the flag well */
.nd-coin::before {
  content: "";
  position: absolute;
  z-index: 2;
  inset: 7px;
  border-radius: 50%;
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, .72),
    inset 0 -1px 1px rgba(255, 255, 255, .3),
    0 1px 0 rgba(255, 255, 255, .24);
  pointer-events: none;
}
.nd-coin-face {
  position: absolute;
  inset: 12px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  overflow: hidden;
  background: #0B1019;
  box-shadow:
    inset 0 0 0 2px rgba(0, 0, 0, .62),
    inset 0 3px 9px rgba(0, 0, 0, .72);
}
.nd-coin-face .fp { width: 100%; height: 100%; }
.nd-coin-face .fp-img { box-shadow: none; }
.nd-coin-face .fp-chip { border-radius: 50%; font-size: 18px; }
.nd-gleam {
  position: absolute;
  z-index: 1;
  inset: 12px;
  border-radius: 50%;
  overflow: hidden;
  pointer-events: none;
}
.nd-gleam::before {
  content: "";
  position: absolute;
  top: -30%;
  bottom: -30%;
  left: -70%;
  width: 46%;
  background: linear-gradient(90deg, rgba(255, 255, 255, 0) 0%, rgba(255, 255, 255, .52) 48%, rgba(255, 255, 255, 0) 100%);
  transform: rotate(18deg);
  animation: nd-sheen 4.8s ease-in-out infinite;
}
.nd-pedestal {
  width: 146px;
  height: 14px;
  margin-top: -12px;
  border: 1px solid rgba(255, 255, 255, .1);
  border-radius: 50%;
  background: linear-gradient(180deg, rgba(255, 255, 255, .16) 0%, rgba(255, 255, 255, .04) 48%, rgba(0, 0, 0, .4) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .26),
    0 12px 20px -12px var(--nd-aura);
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);
}
@keyframes nd-sheen {
  0%, 58% { transform: translate3d(0, 0, 0) rotate(18deg); }
  100% { transform: translate3d(300%, 0, 0) rotate(18deg); }
}
@keyframes nd-float {
  from { transform: translate3d(0, 1px, 0); }
  to { transform: translate3d(0, -4px, 0); }
}
@keyframes nd-breathe {
  0%, 100% { opacity: .75; transform: translateX(-50%) scale(.96); }
  50% { opacity: 1; transform: translateX(-50%) scale(1.05); }
}

/* ---- the counter pill: nation TIQ · active players ---- */
.nd-totals {
  position: relative;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid rgba(255, 255, 255, .08);
  border-radius: 999px;
  background: rgba(255, 255, 255, .045);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .1),
    0 8px 18px -12px rgba(0, 0, 0, .8);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.nd-total { display: inline-flex; align-items: baseline; gap: 4px; min-width: 0; }
.nd-total b { font-size: 14px; font-weight: 900; line-height: 1; color: var(--ink); }
.nd-total small {
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  line-height: 1;
  color: #94A3B8;
}
.nd-total.is-tiq b { color: var(--tiq); }
.nd-total-ico { flex: none; align-self: center; width: 13px; height: 13px; color: var(--nd-metal-hi); }
.nd-total-tiq { color: var(--tiq); filter: drop-shadow(0 0 4px rgba(245, 158, 11, .55)); }
.nd-split { width: 1px; height: 14px; background: rgba(255, 255, 255, .14); }
.nd-caption {
  margin: 0;
  text-align: center;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: .04em;
  color: #94A3B8;
}

/* ---- roster ---- */
.nd-roster { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.nd-rhead {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding: 0 2px;
}
.nd-rh {
  margin: 0;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: #CBD5E1;
}
.nd-rh-count { flex: none; font-size: 10px; font-weight: 800; color: #94A3B8; font-variant-numeric: tabular-nums; }
.nd-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.nd-row {
  display: grid;
  grid-template-columns: 30px 34px minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 8px;
  min-height: 48px;
  min-width: 0;
  padding: 5px 9px;
  border: 1px solid rgba(255, 255, 255, .06);
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, .045) 0%, rgba(255, 255, 255, 0) 48%),
    #1C2433;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .08),
    inset 0 -1px 0 rgba(0, 0, 0, .3),
    0 1px 0 #0A0F1A;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.nd-row.is-you {
  border-color: rgba(56, 189, 248, .45);
  background:
    linear-gradient(180deg, rgba(56, 189, 248, .14) 0%, rgba(56, 189, 248, .03) 62%),
    #172131;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 -1px 0 rgba(0, 0, 0, .32),
    0 0 18px -10px rgba(56, 189, 248, .85);
}
.nd-row.is-skel { grid-template-columns: 30px minmax(0, 1fr) 60px; }
.nd-row.is-skel .skel { height: 12px; border-radius: 6px; }
.nd-rk {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 9px;
  background: linear-gradient(180deg, #28334C 0%, #1A2233 100%);
  box-shadow:
    0 2px 0 #0A0F1A,
    inset 0 1px 0 rgba(255, 255, 255, .15),
    inset 0 0 0 1px rgba(255, 255, 255, .05);
  color: #CBD5E1;
  font-size: 12px;
  font-weight: 900;
  line-height: 1;
}
.nd-rk.t1 {
  background: linear-gradient(180deg, #4A3A15 0%, #2A2312 56%, #171510 100%);
  box-shadow:
    inset 0 1px 0 rgba(251, 191, 36, .7),
    inset 0 0 0 1px rgba(245, 158, 11, .45),
    0 2px 0 #0A0F1A,
    0 0 12px -4px rgba(245, 158, 11, .8);
  color: #FCD34D;
  text-shadow: 0 0 8px rgba(245, 158, 11, .6);
}
.nd-rk.t2 {
  background: linear-gradient(180deg, #3B4658 0%, #222A38 56%, #121721 100%);
  box-shadow:
    inset 0 1px 0 rgba(248, 250, 252, .6),
    inset 0 0 0 1px rgba(203, 213, 225, .4),
    0 2px 0 #0A0F1A,
    0 0 12px -4px rgba(203, 213, 225, .6);
  color: #F1F5F9;
}
.nd-rk.t3 {
  background: linear-gradient(180deg, #4A2A15 0%, #2C1810 56%, #180D08 100%);
  box-shadow:
    inset 0 1px 0 rgba(253, 186, 116, .62),
    inset 0 0 0 1px rgba(217, 119, 6, .42),
    0 2px 0 #0A0F1A,
    0 0 12px -4px rgba(217, 119, 6, .65);
  color: #FDBA74;
}
.nd-avwrap {
  position: relative;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
}
.nd-av {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background:
    radial-gradient(70% 70% at 32% 24%, rgba(255, 255, 255, .22), rgba(255, 255, 255, 0) 58%),
    linear-gradient(180deg, hsl(var(--nd-hue, 198) 42% 30%) 0%, hsl(var(--nd-hue, 198) 48% 15%) 100%);
  box-shadow:
    inset 0 0 0 1.5px rgba(148, 163, 184, .38),
    inset 0 1px 1px rgba(255, 255, 255, .16),
    0 2px 0 #0A0F1A;
  color: #F8FAFC;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .02em;
  line-height: 1;
}
.nd-medal { width: 18px; height: 18px; right: -4px; bottom: -4px; }
.nd-medal .medal-coin,
.nd-medal .medal-coin.badge-crest-art { width: 15px; height: 15px; }
.nd-id { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.nd-nm { display: flex; align-items: center; gap: 5px; min-width: 0; }
.nd-pname {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--ink);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: -.01em;
  line-height: 1.2;
}
.nd-you-tag {
  flex: none;
  height: 14px;
  padding: 0 5px;
  border-radius: 5px;
  background: rgba(56, 189, 248, .16);
  box-shadow: inset 0 0 0 1px rgba(125, 211, 252, .35);
  color: #BAE6FD;
  font-size: 7.5px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
  line-height: 14px;
}
.nd-sub {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-family: var(--ml-mono, ui-monospace, Menlo, Consolas, monospace);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: .01em;
  line-height: 1.2;
  color: #94A3B8;
}
.nd-score {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  color: var(--tiq);
  font-weight: 900;
}
.nd-score b {
  font-size: 13px;
  font-weight: 900;
  letter-spacing: -.01em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.nd-score-ico { flex: none; width: 13px; height: 13px; color: var(--honey); filter: drop-shadow(0 0 4px rgba(245, 158, 11, .6)); }

/* ---- your standing card, pinned above the roster ---- */
.nd-you {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 9px;
  min-height: 54px;
  padding: 7px 10px;
  border: 1px solid rgba(56, 189, 248, .4);
  border-radius: 14px;
  background:
    linear-gradient(180deg, rgba(56, 189, 248, .14) 0%, rgba(56, 189, 248, .02) 72%),
    #172131;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .14),
    0 8px 20px -14px rgba(56, 189, 248, .8);
}
.nd-you-txt { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.nd-you-k {
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #7DD3FC;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.nd-you-line {
  font-size: 13px;
  font-weight: 900;
  letter-spacing: -.01em;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.nd-you-score b { color: var(--tiq); }

.nd-empty {
  display: grid;
  place-items: center;
  min-height: 96px;
  padding: 16px;
  border: 1px dashed rgba(255, 255, 255, .12);
  border-radius: 12px;
  text-align: center;
  color: #94A3B8;
  font-size: 12px;
  font-weight: 600;
}

/* ---- 320px: shrink the medal and the fixed columns, never the name ---- */
@media (max-width: 359px) {
  .nd-head { gap: 8px; }
  .nd-rank { min-width: 38px; height: 32px; font-size: 12px; }
  .nd-title { font-size: 16px; }
  .nd-mark { width: 100px; height: 100px; }
  .nd-coin-face, .nd-gleam { inset: 10px; }
  .nd-pedestal { width: 126px; }
  .nd-totals { gap: 7px; padding: 0 10px; }
  .nd-row { grid-template-columns: 28px 32px minmax(0, 1fr) auto; column-gap: 6px; padding: 5px 7px; }
  .nd-rk { width: 28px; height: 28px; border-radius: 8px; font-size: 11px; }
  .nd-avwrap, .nd-av { width: 32px; height: 32px; }
  .nd-you { grid-template-columns: 32px minmax(0, 1fr) auto; column-gap: 7px; }
  .nd-pname { font-size: 12.5px; }
}

html.reduced-motion .nd-mark,
html.reduced-motion .nd-aura,
html.reduced-motion .nd-gleam::before { animation: none; }
@media (prefers-reduced-motion: reduce) {
  .nd-mark, .nd-aura, .nd-gleam::before { animation: none; }
}

/* ============================================================================================
   FINISH SWITCH + LIGHT MODE — the pearl chessboard stage.

   Dark Mode is untouched: every rule below keys off `html[data-theme="light"]`, and the page wash
   only joins in while the race screen is live (`html.light-game`, set by main.ts). The shell, the
   menus and every sheet keep their midnight clay. Inside the race, the canvas swaps to the pearl
   board theme and the chrome turns into warm porcelain + cool platinum: pearl/ivory panels, a
   champagne light from above, and team inks deepened so red and blue still clear the pale surfaces.
   ============================================================================================ */

/* ---- the head: menu | centred round | sun-moon switch ---- */
.g-head { position: relative; justify-content: space-between; }
.g-head .g-round {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  max-width: calc(100% - 156px);
}

.theme-toggle {
  position: relative;
  flex: none;
  margin-left: auto;
  width: 64px;
  height: 32px;
  padding: 3px;
  border: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  justify-items: center;
  border-radius: 999px;
  cursor: pointer;
  isolation: isolate;
  background: linear-gradient(180deg, #0B111B 0%, #1D2839 100%);
  color: #94A3B8;
  box-shadow:
    inset 0 1px 2px rgba(255, 255, 255, .13),
    inset 0 -2px 3px rgba(0, 0, 0, .6),
    inset 0 0 0 1px rgba(255, 255, 255, .06),
    0 3px 8px -4px rgba(0, 0, 0, .75);
  transition: background .3s ease, box-shadow .3s ease;
}
.theme-toggle::after { content: ""; position: absolute; inset: -6px; border-radius: inherit; }
.theme-toggle .ico {
  position: relative;
  z-index: 1;
  width: 15px;
  height: 15px;
  flex: none;
  transition: color .28s ease, opacity .28s ease, filter .28s ease;
}
.theme-toggle .tt-sun { color: #64748B; opacity: .72; }
.theme-toggle .tt-moon { color: #EEF2F8; opacity: 1; filter: drop-shadow(0 0 4px rgba(186, 208, 255, .6)); }
.theme-toggle-thumb {
  position: absolute;
  z-index: 0;
  top: 3px;
  left: 3px;
  width: 28px;
  height: 26px;
  border-radius: 999px;
  background: radial-gradient(circle at 34% 24%, #6C7B95 0%, #334158 46%, #101824 100%);
  box-shadow:
    0 1px 3px rgba(0, 0, 0, .65),
    inset 0 1px 1px rgba(255, 255, 255, .3);
  transform: translateX(30px);
  transition:
    transform .32s cubic-bezier(.34, 1.4, .64, 1),
    background .3s ease, box-shadow .3s ease;
}
.theme-toggle[aria-checked="true"] .theme-toggle-thumb {
  transform: translateX(0);
  background: radial-gradient(circle at 34% 24%, #FFFDF7 0%, #F1E7D3 48%, #D8C39A 100%);
  box-shadow:
    0 1px 3px rgba(88, 70, 36, .45),
    inset 0 1px 1px rgba(255, 255, 255, .95);
}
.theme-toggle[aria-checked="true"] .tt-sun { color: #A4690A; opacity: 1; filter: drop-shadow(0 0 5px rgba(245, 187, 66, .65)); }
.theme-toggle[aria-checked="true"] .tt-moon { color: #7A8492; opacity: .62; filter: none; }
.theme-toggle:active .theme-toggle-thumb { transform: translateX(30px) scale(.92); }
