/* ---- mandatory channel gate: obsidian & gold -------------------------------------------------
   A full-viewport sheet between a signed Telegram session and the arena. It sits over every app
   surface, so on a cold launch the gate is what the player meets first — there is no boot screen
   in front of it. An unanswered check never raises it. */
.fj-gate {
  position: fixed;
  inset: 0;
  z-index: 2600;
  display: grid;
  place-items: center;
  padding: calc(18px + env(safe-area-inset-top)) 16px calc(18px + env(safe-area-inset-bottom));
  background:
    radial-gradient(72% 46% at 50% 8%, rgba(212, 175, 55, .16) 0%, rgba(212, 175, 55, 0) 64%),
    radial-gradient(120% 80% at 50% 110%, rgba(120, 85, 18, .12) 0%, rgba(0, 0, 0, 0) 60%),
    linear-gradient(180deg, #0B0906 0%, #050506 62%, #030303 100%);
  color: #F4EFE6;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  animation: fj-veil .32s ease both;
}
.fj-gate[hidden] { display: none; }
.fj-gate[data-state="closing"] { opacity: 0; pointer-events: none; transition: opacity .24s ease; }
@keyframes fj-veil { from { opacity: 0; } to { opacity: 1; } }

.fj-card {
  width: min(100%, 372px);
  max-width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 26px 20px 20px;
  border-radius: 24px;
  background:
    radial-gradient(120% 70% at 50% -10%, rgba(212, 175, 55, .1) 0%, rgba(212, 175, 55, 0) 58%),
    linear-gradient(180deg, #14110C 0%, #0A0908 58%, #070707 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 236, 179, .18),
    inset 0 0 0 1px rgba(212, 175, 55, .16),
    0 34px 70px -30px rgba(0, 0, 0, .95);
  text-align: center;
  animation: fj-card .42s cubic-bezier(.2, .8, .2, 1) both;
}
@keyframes fj-card {
  from { opacity: 0; transform: translateY(14px) scale(.985); }
  to { opacity: 1; transform: none; }
}

/* 48px round crest: a Telegram plane on obsidian with a gold lock pinned to its edge. */
.fj-crest {
  position: relative;
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #F6D87A;
  background: radial-gradient(circle at 32% 28%, #2A2314 0%, #14100A 62%, #0A0805 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 239, 189, .3),
    inset 0 0 0 1px rgba(212, 175, 55, .45),
    0 0 0 5px rgba(212, 175, 55, .06),
    0 10px 30px -10px rgba(212, 175, 55, .55);
}
.fj-crest::after {
  content: '';
  position: absolute;
  inset: -9px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(212, 175, 55, .22) 0%, rgba(212, 175, 55, 0) 68%);
  pointer-events: none;
}
.fj-crest-plane { width: 22px; height: 22px; filter: drop-shadow(0 0 6px rgba(246, 216, 122, .55)); }
.fj-crest-lock {
  position: absolute;
  right: -2px;
  bottom: -2px;
  width: 18px;
  height: 18px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #0A0805;
  color: #F6D87A;
  box-shadow: 0 0 0 1px rgba(212, 175, 55, .55), 0 4px 10px -4px #000;
}
.fj-crest-lock .ico { width: 9px; height: 9px; }

.fj-kicker {
  margin: 8px 0 0;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: #C8A552;
}
.fj-title {
  margin: 0;
  font-size: 20px;
  font-weight: 900;
  line-height: 1.25;
  letter-spacing: 0;
  color: #F8F4EA;
}
.fj-body {
  margin: 0;
  max-width: 32ch;
  font-size: 12.5px;
  font-weight: 500;
  line-height: 1.65;
  letter-spacing: 0;
  color: #A9A296;
}
.fj-hair {
  width: 100%;
  height: 1px;
  margin: 4px 0 2px;
  background: linear-gradient(90deg, transparent, rgba(212, 175, 55, .32), transparent);
}

.fj-cta,
.fj-verify {
  width: 100%;
  min-width: 0;
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  appearance: none;
  border: 0;
  border-radius: 15px;
  font: inherit;
  font-size: 13px;
  font-weight: 900;
  letter-spacing: .01em;
  cursor: pointer;
  transition: transform .16s ease, filter .16s ease, box-shadow .16s ease;
}
.fj-cta:active,
.fj-verify:active { transform: translateY(1px); }
.fj-cta:focus-visible,
.fj-verify:focus-visible { outline: 2px solid #F6D87A; outline-offset: 2px; }
.fj-cta {
  color: #1B1405;
  background: linear-gradient(180deg, #F7DC86 0%, #E7BE55 45%, #C99A32 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 252, 230, .8),
    0 3px 0 #7E5F14,
    0 14px 30px -14px rgba(212, 175, 55, .8);
}
.fj-cta .ico { width: 16px; height: 16px; flex: none; }
.fj-verify {
  color: #E8DFCB;
  background: linear-gradient(180deg, rgba(38, 32, 21, .9) 0%, rgba(20, 17, 12, .95) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 240, 200, .1),
    inset 0 0 0 1px rgba(212, 175, 55, .28);
}
.fj-verify:disabled { cursor: default; opacity: .72; }
.fj-verify-ico { width: 15px; height: 15px; flex: none; color: #C8A552; }
.fj-verify[aria-busy="true"] .fj-verify-ico { display: none; }

.fj-spin {
  display: none;
  width: 14px;
  height: 14px;
  flex: none;
  border-radius: 50%;
  border: 2px solid rgba(200, 165, 82, .28);
  border-top-color: #F6D87A;
  animation: fj-spin .75s linear infinite;
}
.fj-verify[aria-busy="true"] .fj-spin { display: block; }
@keyframes fj-spin { to { transform: rotate(360deg); } }

.fj-status {
  min-height: 15px;
  margin: 0;
  font-size: 10.5px;
  font-weight: 700;
  line-height: 1.5;
  letter-spacing: 0;
  color: #9A9284;
}
.fj-status[data-state="error"] { color: #F0A6A0; }

.fj-toast {
  position: fixed;
  left: 50%;
  bottom: calc(96px + env(safe-area-inset-bottom));
  z-index: 2700;
  max-width: min(340px, calc(100vw - 32px));
  padding: 11px 16px;
  border-radius: 15px;
  background: linear-gradient(180deg, #1B1710 0%, #100D09 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 236, 179, .16),
    inset 0 0 0 1px rgba(212, 175, 55, .26),
    0 18px 40px -20px #000;
  color: #F6D87A;
  font-size: 11px;
  font-weight: 800;
  line-height: 1.5;
  text-align: center;
  transform: translate(-50%, 10px);
  opacity: 0;
  transition: opacity .22s ease, transform .22s ease;
  pointer-events: none;
}
.fj-toast[hidden] { display: none; }
.fj-toast.show { opacity: 1; transform: translate(-50%, 0); }

/* Persian gets its direction and air surgically; the document itself is never mirrored. */
html[data-lang="fa"] .fj-card,
html[data-lang="ar"] .fj-card { direction: rtl; }
html[data-lang="fa"] :is(.fj-kicker, .fj-title, .fj-body, .fj-status, .fj-cta-t, .fj-verify-t),
html[data-lang="ar"] :is(.fj-kicker, .fj-title, .fj-body, .fj-status, .fj-cta-t, .fj-verify-t) {
  letter-spacing: 0;
}
html[data-lang="fa"] .fj-title,
html[data-lang="ar"] .fj-title { font-size: 19px; line-height: 1.45; }
html[data-lang="fa"] .fj-body,
html[data-lang="ar"] .fj-body { line-height: 1.65; }
html[data-lang="fa"] .fj-kicker,
html[data-lang="ar"] .fj-kicker { letter-spacing: 0; }
html[data-lang="fa"] .fj-cta .ico { transform: scaleX(-1); }
html[data-lang="fa"] .fj-crest-lock { right: auto; left: -2px; }

@media (max-width: 359px) {
  .fj-card { padding: 22px 16px 17px; border-radius: 21px; gap: 9px; }
  .fj-title { font-size: 18.5px; }
  .fj-body { font-size: 12px; }
  .fj-cta, .fj-verify { font-size: 12px; min-height: 46px; }
}
@media (max-height: 560px) {
  .fj-gate { align-items: start; padding-top: calc(12px + env(safe-area-inset-top)); }
  .fj-card { padding: 18px 16px 14px; gap: 8px; }
  .fj-kicker { margin-top: 4px; }
  .fj-body { line-height: 1.5; }
  .fj-cta, .fj-verify { min-height: 44px; }
}
@media (prefers-reduced-motion: reduce) {
  .fj-gate, .fj-card { animation: none; }
  .fj-gate[data-state="closing"] { transition: none; }
  .fj-spin { animation: none; }
  .fj-cta, .fj-verify { transition: none; }
}

/* ==========================================================================
   SQUAD ALLIANCE HUB — the Join Squad search view.
   One loud key (Create Squad) owns the top of the sheet; search sits in a
   recessed groove below it; every squad is a bento card whose only gesture is
   a quiet inspect chevron. The list is the sole scroller and keeps a slim cyan
   rail, so the hero, CTA and search stay pinned while squads move under them.
   ========================================================================== */
#sheet-squad .sq-search-view {
  gap: 10px;
  min-height: 0;
}

/* A compact frosted command bar: obsidian glass, a cyan rim and one ambient
   bloom. It reads as the sheet's primary action without shouting. */
.sq-create {
  flex: none;
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  min-height: 46px;
  padding: 0 14px;
  border: 1px solid rgba(0, 210, 255, .35);
  border-radius: 16px;
  background: linear-gradient(135deg, rgba(0, 210, 255, .16), rgba(0, 102, 255, .08));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .1),
    0 12px 30px -20px rgba(0, 210, 255, .85);
  -webkit-backdrop-filter: blur(14px) saturate(1.15);
  backdrop-filter: blur(14px) saturate(1.15);
  color: #E6F7FF;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    background var(--motion-fast),
    border-color var(--motion-fast),
    box-shadow var(--motion-fast),
    transform var(--motion-fast);
}
.sq-create:hover:not(:active) {
  border-color: rgba(0, 210, 255, .52);
  background: linear-gradient(135deg, rgba(0, 210, 255, .23), rgba(0, 102, 255, .12));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .14),
    0 14px 34px -20px rgba(0, 210, 255, 1);
}
.sq-create:active {
  transform: translateY(1px);
  box-shadow:
    inset 0 2px 8px rgba(2, 8, 18, .4),
    0 6px 16px -14px rgba(0, 210, 255, .7);
}
.sq-create:focus-visible { outline: 3px solid var(--brand-3); outline-offset: 2px; }
.sq-create-plus {
  flex: none;
  width: 16px;
  height: 16px;
  color: #4FD8FF;
  filter: drop-shadow(0 0 6px rgba(0, 210, 255, .55));
}
.sq-create-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  font-size: 12.5px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: .09em;
  text-transform: uppercase;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: #F2FBFF;
}
.sq-create-go { flex: none; width: 15px; height: 15px; color: rgba(198, 236, 255, .68); }

/* Recessed groove: the field reads as a slot cut into the clay, not a card on it. */
#sheet-squad .sq-field {
  flex: none;
  min-height: 46px;
  border-radius: 14px;
  background: rgba(6, 11, 20, .62);
  box-shadow:
    inset 0 2px 7px rgba(0, 0, 0, .58),
    inset 0 0 0 1px rgba(255, 255, 255, .07),
    0 1px 0 rgba(255, 255, 255, .04);
  color: var(--ink-soft);
  transition: box-shadow var(--motion-fast), background var(--motion-fast), color var(--motion-fast);
}
#sheet-squad .sq-field:focus-within {
  background: rgba(6, 11, 20, .8);
  box-shadow:
    inset 0 2px 8px rgba(0, 0, 0, .62),
    inset 0 0 0 1px rgba(56, 189, 248, .58),
    0 0 0 3px rgba(56, 189, 248, .13);
  color: var(--brand-ink);
}
#sheet-squad .sq-field .ico { width: 17px; height: 17px; }
#sheet-squad .sq-field .input::placeholder { color: var(--text-dim); }

/* The list owns the gesture; the rail is a thin cyan→violet seam. */
#sheet-squad .sq-bento {
  flex: 1 1 auto;
  min-height: 96px;
  max-height: calc(100vh - 280px);
  max-height: calc(100dvh - 280px);
  margin: 0;
  padding: 2px 2px 4px;
  list-style: none;
  overflow-y: auto;
  overscroll-behavior: contain;
  touch-action: pan-y;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: rgba(56, 189, 248, .5) transparent;
}
#sheet-squad .sq-bento::-webkit-scrollbar { display: block; width: 6px; height: 6px; }
#sheet-squad .sq-bento::-webkit-scrollbar-track { background: transparent; }
#sheet-squad .sq-bento::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(56, 189, 248, .6) 0%, rgba(167, 139, 250, .55) 100%);
}
#sheet-squad .sq-bento::-webkit-scrollbar-thumb:hover { background: rgba(56, 189, 248, .75); }
#sheet-squad .sq-bento:empty { display: none; }
#sheet-squad .sq-bento:focus-visible { outline: 2px solid rgba(56, 189, 248, .55); outline-offset: 2px; }

/* Bento squad card: rank key · crest · identity + chips · inspect chevron.
   The whole row is the door; joining is committed only inside the preview sheet. */
.sq-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-width: 0;
  min-height: 84px;
  margin: 0 0 10px;
  padding: 13px 14px;
  border: 1px solid rgba(255, 255, 255, .08);
  border-radius: 16px;
  background: rgba(255, 255, 255, .03);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .05),
    0 12px 20px -20px rgba(0, 0, 0, .95);
  cursor: pointer;
  transition: background var(--motion-fast), border-color var(--motion-fast), transform var(--motion-fast);
}
.sq-card:last-child { margin-bottom: 0; }
.sq-card:hover { background: rgba(255, 255, 255, .045); border-color: rgba(255, 255, 255, .14); }
.sq-card:active { transform: translateY(1px); }
.sq-card:focus-visible { outline: 3px solid var(--brand-3); outline-offset: 2px; border-color: rgba(56, 189, 248, .4); }
.sq-card.is-bound { border-color: rgba(56, 189, 248, .34); background: rgba(56, 189, 248, .06); }

/* Rank: podium metal on 1–3, quiet clay key from 4 down. */
.sq-rank {
  flex: none;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 10px;
  background: linear-gradient(180deg, #28334C 0%, #1A2233 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .14),
    inset 0 0 0 1px rgba(255, 255, 255, .06),
    0 1px 0 #0A0F1A;
  color: var(--chip-ink);
  font-size: 12px;
  font-weight: 900;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.sq-rank .ico { width: 14px; height: 14px; color: var(--brand-ink); }
.sq-rank[data-rank="gold"] {
  background:
    linear-gradient(135deg, rgba(255, 255, 255, .7) 0%, rgba(255, 255, 255, 0) 48%),
    linear-gradient(160deg, #FFE9A8 0%, #F2BE4C 48%, #B7791F 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .8),
    inset 0 -1px 0 rgba(87, 52, 8, .45),
    0 2px 7px -3px rgba(245, 158, 11, .8);
  color: #3B2400;
}
.sq-rank[data-rank="silver"] {
  background:
    linear-gradient(135deg, rgba(255, 255, 255, .85) 0%, rgba(255, 255, 255, 0) 48%),
    linear-gradient(160deg, #F8FAFC 0%, #CBD5E1 48%, #8798AB 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .9),
    inset 0 -1px 0 rgba(30, 41, 59, .4),
    0 2px 7px -3px rgba(148, 163, 184, .7);
  color: #1E293B;
}
.sq-rank[data-rank="bronze"] {
  background:
    linear-gradient(135deg, rgba(255, 255, 255, .6) 0%, rgba(255, 255, 255, 0) 48%),
    linear-gradient(160deg, #F8D3AC 0%, #DE9A57 50%, #A15A22 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .65),
    inset 0 -1px 0 rgba(66, 30, 6, .45),
    0 2px 7px -3px rgba(180, 83, 9, .7);
  color: #2B1203;
}
.sq-rank[data-rank="new"] { box-shadow: inset 0 0 0 1px rgba(56, 189, 248, .35); }

/* Crest: squircle token. The real Telegram profile photo layers over the
   monogram, so a channel without a public picture keeps the polished crest. */
.sq-card-av {
  position: relative;
  flex: none;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, .14);
  border-radius: 14px;
  background:
    radial-gradient(100% 100% at 30% 0%, rgba(56, 189, 248, .2) 0%, rgba(56, 189, 248, 0) 62%),
    linear-gradient(180deg, #1A2334 0%, #141B29 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .1),
    0 4px 10px -6px rgba(56, 189, 248, .55);
  color: #E0F2FE;
}
.sq-card-av b {
  font-size: 13px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: .04em;
}
.sq-card-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  transition: opacity .18s ease;
}
.sq-card-av.has-photo .sq-card-img { opacity: 1; }

.sq-card-id {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.sq-card-name {
  overflow: hidden;
  font-size: 14.5px;
  font-weight: 800;
  line-height: 1.25;
  color: var(--ink);
  unicode-bidi: isolate;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.sq-card-handle {
  overflow: hidden;
  font-size: 11px;
  font-weight: 700;
  line-height: 1.3;
  color: var(--brand-ink);
  white-space: nowrap;
  text-overflow: ellipsis;
}
.sq-card-metrics {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 4px;
  min-width: 0;
  font-variant-numeric: tabular-nums;
}
/* Stats read as quiet inline metadata, not stacked pills. */
.sq-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
  white-space: nowrap;
}
.sq-chip .ico { flex: none; width: 12px; height: 12px; }
.sq-chip-mem { color: var(--ink-soft); }
.sq-chip-tiq { color: var(--honey-ink); }
.sq-chip-tiq .ico {
  color: var(--violet);
  filter: drop-shadow(0 0 4px rgba(167, 139, 250, .75));
}
.sq-chip-tiq b { font-weight: 900; }
.sq-card-note { font-size: 10.5px; font-weight: 600; line-height: 1; color: var(--text-dim); }

/* Inspect chevron: a translucent pill, quiet until the row is hovered. */
.sq-card-go {
  flex: none;
  display: grid;
  place-items: center;
  width: 30px;
  height: 38px;
  border-radius: 12px;
  background: rgba(255, 255, 255, .05);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .06),
    inset 0 0 0 1px rgba(255, 255, 255, .08);
  color: var(--brand-ink);
  transition: background var(--motion-fast), box-shadow var(--motion-fast), color var(--motion-fast);
}
.sq-card-go .ico { width: 15px; height: 15px; }
.sq-card:hover .sq-card-go {
  background: rgba(56, 189, 248, .13);
  box-shadow: inset 0 0 0 1px rgba(56, 189, 248, .35);
  color: #BAE6FD;
}

@media (max-width: 380px) {
  .sq-card { gap: 9px; min-height: 76px; padding: 11px; }
  .sq-rank { width: 27px; height: 27px; border-radius: 9px; font-size: 11px; }
  .sq-card-name { font-size: 13.5px; }
  .sq-card-handle { font-size: 10.5px; }
  .sq-card-go { width: 28px; height: 34px; }
  .sq-create-label { font-size: 12px; }
}
@media (max-width: 340px) {
  .sq-card { gap: 7px; }
  .sq-chip { gap: 3px; font-size: 10px; }
  .sq-chip .ico { width: 10px; height: 10px; }
  .sq-card-metrics { gap: 8px; margin-top: 3px; }
}

/* ==========================================================================
   SQUAD PREVIEW SHEET — the inspection step between discovery and joining.
   The crest and verified identity lead, three bento tiles carry rank / TIQ /
   members, and one full-width esports key owns the commitment. Only the body
   scrolls; the top bar and the key stay inside the 360x640 viewport.
   ========================================================================== */
#sheet-squad-preview {
  padding-top: 12px;
  padding-bottom: calc(12px + env(safe-area-inset-bottom));
  max-height: calc(90vh - env(safe-area-inset-top));
  max-height: calc(90dvh - env(safe-area-inset-top));
  gap: 8px;
  border: 1px solid rgba(148, 197, 255, .12);
  border-bottom: 0;
  background:
    radial-gradient(110% 70% at 4% 0%, rgba(56, 189, 248, .11) 0%, rgba(56, 189, 248, 0) 58%),
    radial-gradient(90% 60% at 100% 0%, rgba(167, 139, 250, .1) 0%, rgba(167, 139, 250, 0) 62%),
    linear-gradient(180deg, rgba(22, 31, 46, .985) 0%, rgba(11, 16, 26, .998) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .1),
    0 -26px 60px -34px rgba(56, 189, 248, .42);
  -webkit-backdrop-filter: blur(18px) saturate(1.06);
  backdrop-filter: blur(18px) saturate(1.06);
}

.sqp-top {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 42px;
}
.sqp-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 42px;
  padding: 0 13px 0 9px;
  border: 1px solid rgba(255, 255, 255, .08);
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, .04);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .06),
    inset 0 0 0 1px rgba(255, 255, 255, .015);
  color: var(--ink-soft);
  font: inherit;
  font-size: 9.5px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: .09em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background var(--motion-fast), border-color var(--motion-fast), color var(--motion-fast), transform var(--motion-fast);
}
.sqp-back .ico { flex: none; width: 15px; height: 15px; color: var(--brand-ink); }
.sqp-back:hover:not(:active) {
  border-color: rgba(56, 189, 248, .3);
  background: rgba(56, 189, 248, .1);
  color: var(--ink);
}
.sqp-back:active { transform: translateY(1px); }
.sqp-back:focus-visible { outline: 3px solid var(--brand-3); outline-offset: 2px; }
.sqp-x { width: 42px; height: 42px; }
.sqp-x .ms-x-g { font-size: 22px; }

.sqp-body {
  flex: 1 1 auto;
  min-height: 0;
  gap: 10px;
  overflow-y: auto;
  overscroll-behavior: contain;
  touch-action: pan-y;
}

/* Hero: the crest's ambient breathing room, the official title, the channel. */
.sqp-hero {
  position: relative;
  flex: none;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 14px 14px 16px;
  border: 1px solid rgba(255, 255, 255, .08);
  border-radius: 20px;
  background:
    radial-gradient(120% 170% at 0% 0%, rgba(56, 189, 248, .14) 0%, rgba(56, 189, 248, 0) 58%),
    radial-gradient(100% 150% at 100% 0%, rgba(167, 139, 250, .1) 0%, rgba(167, 139, 250, 0) 62%),
    rgba(15, 23, 42, .68);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .08),
    0 18px 36px -34px rgba(0, 0, 0, .95);
}
.sqp-crest { width: 66px; height: 66px; }
.sqp-crest .sq-crest-t { font-size: 22px; }
.sqp-id {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.sqp-eyebrow {
  font-size: 8px;
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--brand-ink);
}
.sqp-name {
  min-width: 0;
  overflow: hidden;
  font-size: 20px;
  font-weight: 900;
  line-height: 1.12;
  letter-spacing: -.02em;
  color: #FFFFFF;
  text-shadow: 0 0 20px rgba(255, 255, 255, .1);
  white-space: nowrap;
  text-overflow: ellipsis;
}
.sqp-handle-row {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
}
.sqp-verified {
  flex: none;
  display: grid;
  place-items: center;
  width: 15px;
  height: 15px;
  border-radius: 50%;
  background: linear-gradient(180deg, #38BDF8 0%, #2563EB 100%);
  box-shadow:
    0 0 8px -1px rgba(56, 189, 248, .6),
    inset 0 1px 0 rgba(255, 255, 255, .4);
  color: #FFFFFF;
}
.sqp-verified .ico { width: 9px; height: 9px; }
.sqp-handle {
  min-width: 0;
  overflow: hidden;
  font-size: 12px;
  font-weight: 800;
  line-height: 1.2;
  color: #7DD3FC;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.sqp-kind {
  overflow: hidden;
  font-size: 8.5px;
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--text-dim);
  white-space: nowrap;
  text-overflow: ellipsis;
}

/* Bento stat tiles: one metal for rank, one violet brain, one cyan headcount. */
.sqp-tiles {
  flex: none;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}
.sqp-tile {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 3px;
  min-width: 0;
  min-height: 80px;
  padding: 10px 11px;
  border: 1px solid rgba(255, 255, 255, .07);
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(30, 41, 59, .76) 0%, rgba(15, 23, 42, .66) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .06),
    0 12px 22px -24px rgba(0, 0, 0, .95);
}
.sqp-tile-k {
  display: flex;
  align-items: center;
  gap: 4px;
  width: 100%;
  min-width: 0;
  overflow: hidden;
  font-size: 7.5px;
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: .09em;
  text-transform: uppercase;
  color: var(--ink-soft);
  white-space: nowrap;
  text-overflow: ellipsis;
}
.sqp-tile-k .ico { flex: none; width: 11px; height: 11px; }
.sqp-tile-v {
  max-width: 100%;
  overflow: hidden;
  font-family: var(--font-numeric);
  font-size: clamp(16px, 4.8vw, 20px);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: -.03em;
  font-variant-numeric: tabular-nums;
  color: #FFFFFF;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.sqp-tile-s {
  width: 100%;
  overflow: hidden;
  font-size: 7.5px;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--text-dim);
  white-space: nowrap;
  text-overflow: ellipsis;
}
.sqp-tile-rank {
  --sqp-metal: 56, 189, 248;
  border-color: rgba(var(--sqp-metal), .3);
  background:
    radial-gradient(140% 160% at 0% 0%, rgba(var(--sqp-metal), .14) 0%, rgba(15, 23, 42, .66) 68%),
    linear-gradient(180deg, rgba(30, 41, 59, .7) 0%, rgba(15, 23, 42, .66) 100%);
}
.sqp-tile-rank[data-rank="gold"] { --sqp-metal: 252, 211, 77; }
.sqp-tile-rank[data-rank="silver"] { --sqp-metal: 203, 213, 225; }
.sqp-tile-rank[data-rank="bronze"] { --sqp-metal: 251, 146, 60; }
.sqp-tile-rank[data-rank="new"] { --sqp-metal: 56, 189, 248; }
.sqp-tile-rank .sqp-tile-k .ico {
  color: rgb(var(--sqp-metal));
  filter: drop-shadow(0 0 5px rgba(var(--sqp-metal), .55));
}
.sqp-tile-rank .sqp-tile-v {
  color: rgb(var(--sqp-metal));
  text-shadow: 0 0 16px rgba(var(--sqp-metal), .4);
}
.sqp-tile-tiq {
  border-color: rgba(167, 139, 250, .22);
  background:
    radial-gradient(140% 160% at 0% 0%, rgba(167, 139, 250, .13) 0%, rgba(15, 23, 42, .66) 68%),
    linear-gradient(180deg, rgba(30, 41, 59, .7) 0%, rgba(15, 23, 42, .66) 100%);
}
.sqp-tile-tiq .sqp-tile-k .ico {
  color: #C4B5FD;
  filter: drop-shadow(0 0 6px rgba(167, 139, 250, .95));
}
.sqp-tile-mem {
  border-color: rgba(56, 189, 248, .18);
  background:
    radial-gradient(140% 160% at 0% 0%, rgba(56, 189, 248, .1) 0%, rgba(15, 23, 42, .66) 68%),
    linear-gradient(180deg, rgba(30, 41, 59, .7) 0%, rgba(15, 23, 42, .66) 100%);
}
.sqp-tile-mem .sqp-tile-k .ico { color: #7DD3FC; }

/* The brief lane: one line of clan incentive, never a wall of copy. */
.sqp-lore {
  flex: none;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid rgba(125, 211, 252, .13);
  border-radius: 14px;
  background: linear-gradient(100deg, rgba(56, 189, 248, .08) 0%, rgba(167, 139, 250, .07) 100%);
}
.sqp-lore-ico {
  flex: none;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 10px;
  background: rgba(56, 189, 248, .12);
  box-shadow:
    inset 0 0 0 1px rgba(125, 211, 252, .2),
    inset 0 1px 0 rgba(255, 255, 255, .08);
  color: #7DD3FC;
}
.sqp-lore-ico .ico { width: 16px; height: 16px; }
.sqp-lore p {
  min-width: 0;
  margin: 0;
  font-size: 11px;
  font-weight: 700;
  line-height: 1.35;
  color: #CBD5E1;
}

/* The one commitment in the flow: full-width cyan → violet, lit rim, edge bloom. */
.sqp-foot {
  flex: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: auto;
  padding-top: 2px;
}
.sqp-join {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  width: 100%;
  min-height: 56px;
  padding: 0 18px;
  overflow: hidden;
  border: 1px solid rgba(165, 243, 252, .58);
  border-radius: 16px;
  background:
    linear-gradient(120deg, rgba(255, 255, 255, .2) 0%, rgba(255, 255, 255, 0) 44%),
    linear-gradient(100deg, #06B6D4 0%, #3B82F6 46%, #8B5CF6 100%);
  box-shadow:
    0 12px 30px -12px rgba(34, 211, 238, .8),
    0 0 26px -8px rgba(139, 92, 246, .8),
    inset 0 1px 0 rgba(255, 255, 255, .38),
    inset 0 -1px 0 rgba(6, 11, 20, .42);
  color: #FFFFFF;
  font: inherit;
  cursor: pointer;
  transition: filter var(--motion-fast), transform var(--motion-fast), box-shadow var(--motion-fast);
}
.sqp-join::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(115deg, rgba(255, 255, 255, .22) 0%, rgba(255, 255, 255, 0) 42%, rgba(255, 255, 255, .08) 100%);
  pointer-events: none;
}
.sqp-join-ico {
  position: relative;
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 9px;
  background: rgba(255, 255, 255, .16);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .35),
    inset 0 0 0 1px rgba(255, 255, 255, .12);
}
.sqp-join-ico .ico { width: 16px; height: 16px; }
.sqp-join-t {
