  box-shadow:
    0 4px 14px -10px rgba(34, 211, 238, .7),
    0 0 18px -8px rgba(139, 92, 246, .7),
    inset 0 2px 6px rgba(6, 11, 20, .32);
}
.sqp-join:focus-visible { outline: 3px solid #A5F3FC; outline-offset: 3px; }
.sqp-join.is-joined {
  border-color: rgba(167, 243, 208, .6);
  background:
    linear-gradient(120deg, rgba(255, 255, 255, .2) 0%, rgba(255, 255, 255, 0) 44%),
    linear-gradient(100deg, #10B981 0%, #0EA5E9 52%, #3B82F6 100%);
  box-shadow:
    0 12px 30px -12px rgba(52, 211, 153, .7),
    0 0 26px -8px rgba(14, 165, 233, .7),
