/* 360px-class phones: keep every tile legible and the key fully visible. */
@media (max-width: 380px) {
  .sqp-hero { gap: 12px; padding: 12px; }
  .sqp-crest { width: 60px; height: 60px; }
  .sqp-crest .sq-crest-t { font-size: 20px; }
