  .sqp-tile-k { font-size: 7px; letter-spacing: .05em; }
  .sqp-tile-k .ico { width: 10px; height: 10px; }
  .sqp-tile-v { font-size: 16px; }
  .sqp-tile-s { font-size: 7px; letter-spacing: .04em; }
  .sqp-lore { gap: 8px; padding: 9px 10px; }
  .sqp-lore p { font-size: 10.5px; }
  .sqp-join { min-height: 52px; }
