}
html[data-lang="fa"] #s-profile :is(.pf-sec-sub, .pf-chip-k, .pf-xp-lvl, .pf-quest-kicker),
html[data-lang="ar"] #s-profile :is(.pf-sec-sub, .pf-chip-k, .pf-xp-lvl, .pf-quest-kicker) {
  font-family: 'Vazirmatn', system-ui, -apple-system, sans-serif;
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
