.vf-back:hover:not(:active) { color: var(--ink); }
.vf-back:active { transform: translateY(var(--press-y)); box-shadow: 0 1px 0 #0A0E15, inset 0 1px 0 rgba(255, 255, 255, .07), inset 0 0 0 1px var(--hair-off); }
