/* the sheets mirror for fa/ar; every numeral and every fill keeps its own LTR direction */
html:lang(fa) .vault-modal-sheet, html:lang(ar) .vault-modal-sheet { direction: rtl; }
html:lang(fa) .vm-foot-chev, html:lang(ar) .vm-foot-chev { transform: scaleX(-1); }
html:lang(fa) :is(.vm-foot-l, .vg-t, .vg-b, .vg-fine-t, .vg-done, .vf-back),
html:lang(ar) :is(.vm-foot-l, .vg-t, .vg-b, .vg-fine-t, .vg-done, .vf-back) {
